INSERT INTO question_translations (question_id, lang, text, explanation, choices) VALUES
(1, 'en', $text$What does the date of 14 July correspond to?$text$, $expl$14 July commemorates the storming of the Bastille in 1789, a symbol of the end of royal arbitrary rule. It is the French national day, celebrated every year with a military parade and fireworks.$expl$, $choices$[{"id":"a","text":"The storming of the Bastille and the national day"},{"id":"b","text":"The signing of the Constitution"},{"id":"c","text":"The end of the Second World War"},{"id":"d","text":"The abolition of the monarchy"}]$choices$),
(1, 'tr', $text$14 Temmuz tarihi neye karşılık gelir?$text$, $expl$14 Temmuz, 1789'da Bastille'in alınışını anar; bu, kraliyetin keyfi yönetiminin sona ermesinin simgesidir. Fransa'nın ulusal bayramıdır ve her yıl askeri geçit töreni ve havai fişeklerle kutlanır.$expl$, $choices$[{"id":"a","text":"Bastille'in alınışı ve ulusal bayram"},{"id":"b","text":"Anayasa'nın imzalanması"},{"id":"c","text":"İkinci Dünya Savaşı'nın sonu"},{"id":"d","text":"Monarşinin kaldırılması"}]$choices$),
(2, 'en', $text$What is one of the symbols of the République française (French Republic)?$text$, $expl$Marianne is one of the official symbols of the République française. She represents liberty and the Republic, and her bust is present in every town hall in France.$expl$, $choices$[{"id":"a","text":"Marianne"},{"id":"b","text":"The imperial eagle"},{"id":"c","text":"The royal crown"},{"id":"d","text":"The lion"}]$choices$),
(2, 'tr', $text$République française'in (Fransız Cumhuriyeti) sembollerinden biri nedir?$text$, $expl$Marianne, République française'in resmi sembollerinden biridir. Özgürlüğü ve Cumhuriyeti temsil eder ve büstü Fransa'daki tüm belediye binalarında bulunur.$expl$, $choices$[{"id":"a","text":"Marianne"},{"id":"b","text":"İmparatorluk kartalı"},{"id":"c","text":"Kraliyet tacı"},{"id":"d","text":"Aslan"}]$choices$),
(3, 'en', $text$The principle of equality means that:$text$, $expl$The principle of equality, enshrined in the republican motto, means that all citizens have the same rights and the same duties before the law, without distinction of origin, race or religion.$expl$, $choices$[{"id":"a","text":"All citizens have the same rights and the same duties"},{"id":"b","text":"Everyone must earn the same salary"},{"id":"c","text":"Men have more rights than women"},{"id":"d","text":"Only French people have rights"}]$choices$),
(3, 'tr', $text$Eşitlik ilkesi şu anlama gelir:$text$, $expl$Cumhuriyet sloganında yer alan eşitlik ilkesi, tüm vatandaşların köken, ırk veya din ayrımı yapılmaksızın yasa önünde aynı haklara ve aynı görevlere sahip olması anlamına gelir.$expl$, $choices$[{"id":"a","text":"Tüm vatandaşların aynı haklara ve aynı görevlere sahip olması"},{"id":"b","text":"Herkesin aynı maaşı kazanması gerektiği"},{"id":"c","text":"Erkeklerin kadınlardan daha fazla hakka sahip olduğu"},{"id":"d","text":"Yalnızca Fransızların haklara sahip olduğu"}]$choices$),
(4, 'en', $text$"Liberté, égalité, fraternité" (Liberty, equality, fraternity) is:$text$, $expl$"Liberté, égalité, fraternité" is the motto of the République française. It is enshrined in the Constitution and appears on public buildings and official documents.$expl$, $choices$[{"id":"a","text":"The motto of the République française"},{"id":"b","text":"The title of the national anthem"},{"id":"c","text":"The name of a French law"},{"id":"d","text":"An advertising slogan"}]$choices$),
(4, 'tr', $text$"Liberté, égalité, fraternité" (Özgürlük, eşitlik, kardeşlik) nedir?$text$, $expl$"Liberté, égalité, fraternité", République française'in sloganıdır. Anayasa'da yer alır ve kamu binalarında ve resmi belgelerde görünür.$expl$, $choices$[{"id":"a","text":"République française'in sloganı"},{"id":"b","text":"Ulusal marşın başlığı"},{"id":"c","text":"Bir Fransız yasasının adı"},{"id":"d","text":"Bir reklam sloganı"}]$choices$),
(5, 'en', $text$Does one have the right to publicly insult someone because they are different (disability, physical appearance, sex, etc.)?$text$, $expl$No, publicly insulting someone because of their difference is prohibited by law. It is discrimination punishable under criminal law. The law protects everyone against insults related to disability, sex or physical appearance.$expl$, $choices$[{"id":"a","text":"No, it is forbidden by law"},{"id":"b","text":"Yes, thanks to freedom of expression"},{"id":"c","text":"Yes, if it is humour"},{"id":"d","text":"Only in private"}]$choices$),
(5, 'tr', $text$Birini farklı olduğu için (engellilik, fiziksel görünüm, cinsiyet vb.) alenen aşağılama hakkı var mıdır?$text$, $expl$Hayır, birini farklılığı nedeniyle alenen aşağılamak yasalarca yasaklanmıştır. Bu, cezai olarak cezalandırılan bir ayrımcılıktır. Yasa, engellilik, cinsiyet veya fiziksel görünümle ilgili hakaretlere karşı her bireyi korur.$expl$, $choices$[{"id":"a","text":"Hayır, yasalarca yasaktır"},{"id":"b","text":"Evet, ifade özgürlüğü sayesinde"},{"id":"c","text":"Evet, eğer mizah ise"},{"id":"d","text":"Yalnızca özel bir ortamda"}]$choices$),
(6, 'en', $text$Can certain professions be reserved for men?$text$, $expl$No, in France, all professions are open to women and men alike. The principle of equality between the sexes prohibits any sex-based discrimination in hiring.$expl$, $choices$[{"id":"a","text":"No, all professions are open to women and men"},{"id":"b","text":"Yes, certain professions are forbidden to women"},{"id":"c","text":"Yes, physical jobs are reserved for men"},{"id":"d","text":"It depends on the employer"}]$choices$),
(6, 'tr', $text$Bazı meslekler yalnızca erkeklere ayrılabilir mi?$text$, $expl$Hayır, Fransa'da tüm meslekler hem kadınlara hem de erkeklere açıktır. Cinsiyetler arası eşitlik ilkesi, işe alımda cinsiyete dayalı her türlü ayrımcılığı yasaklar.$expl$, $choices$[{"id":"a","text":"Hayır, tüm meslekler kadınlara ve erkeklere açıktır"},{"id":"b","text":"Evet, bazı meslekler kadınlara yasaktır"},{"id":"c","text":"Evet, fiziksel meslekler erkeklere ayrılmıştır"},{"id":"d","text":"İşverene bağlıdır"}]$choices$),
(7, 'en', $text$When does the Constitution of the Fifth Republic date from?$text$, $expl$The Constitution of the Fifth Republic was adopted by referendum on 28 September 1958 and promulgated on 4 October 1958. It establishes the current political regime of France.$expl$, $choices$[{"id":"a","text":"1958"},{"id":"b","text":"1789"},{"id":"c","text":"1945"},{"id":"d","text":"1968"}]$choices$),
(7, 'tr', $text$Beşinci Cumhuriyet'in Anayasası hangi tarihe aittir?$text$, $expl$Beşinci Cumhuriyet'in Anayasası 28 Eylül 1958'de referandumla kabul edilmiş ve 4 Ekim 1958'de yürürlüğe girmiştir. Fransa'nın mevcut siyasi rejimini kurar.$expl$, $choices$[{"id":"a","text":"1958"},{"id":"b","text":"1789"},{"id":"c","text":"1945"},{"id":"d","text":"1968"}]$choices$),
(8, 'en', $text$The regime of France is:$text$, $expl$France is a democratic republic. Article 1 of the Constitution defines France as an indivisible, secular, democratic and social Republic.$expl$, $choices$[{"id":"a","text":"A democratic republic"},{"id":"b","text":"A constitutional monarchy"},{"id":"c","text":"A dictatorship"},{"id":"d","text":"An empire"}]$choices$),
(8, 'tr', $text$Fransa'nın rejimi:$text$, $expl$Fransa demokratik bir cumhuriyettir. Anayasa'nın 1. maddesi Fransa'yı bölünmez, laik, demokratik ve sosyal bir Cumhuriyet olarak tanımlar.$expl$, $choices$[{"id":"a","text":"Demokratik bir cumhuriyet"},{"id":"b","text":"Anayasal bir monarşi"},{"id":"c","text":"Bir diktatörlük"},{"id":"d","text":"Bir imparatorluk"}]$choices$),
(9, 'en', $text$Which of these symbols officially represents the République française?$text$, $expl$Marianne is the official symbol of the République française. She embodies the values of liberty and democracy. Her bust is present in town halls and on postage stamps.$expl$, $choices$[{"id":"a","text":"Marianne"},{"id":"b","text":"The fleur-de-lis"},{"id":"c","text":"The eagle"},{"id":"d","text":"The ram"}]$choices$),
(9, 'tr', $text$Bu sembollerden hangisi République française'i resmi olarak temsil eder?$text$, $expl$Marianne, République française'in resmi sembolüdür. Özgürlük ve demokrasi değerlerini somutlaştırır. Büstü belediye binalarında ve posta pullarında yer alır.$expl$, $choices$[{"id":"a","text":"Marianne"},{"id":"b","text":"Zambak çiçeği (fleur-de-lis)"},{"id":"c","text":"Kartal"},{"id":"d","text":"Koç"}]$choices$),
(10, 'en', $text$Where can one see the motto of the Republic?$text$, $expl$The motto "Liberté, Égalité, Fraternité" is inscribed on the pediments of public buildings, such as town halls, schools and courts. It also appears on coins.$expl$, $choices$[{"id":"a","text":"On public buildings (town halls, schools, courts)"},{"id":"b","text":"Only on banknotes"},{"id":"c","text":"On road signs"},{"id":"d","text":"Only in the Constitution"}]$choices$),
(10, 'tr', $text$Cumhuriyet'in sloganını nerede görebiliriz?$text$, $expl$"Liberté, Égalité, Fraternité" sloganı, belediye binaları, okullar ve mahkemeler gibi kamu binalarının alınlıklarında yazılıdır. Madeni paralarda da yer alır.$expl$, $choices$[{"id":"a","text":"Kamu binalarında (belediye binaları, okullar, mahkemeler)"},{"id":"b","text":"Yalnızca banknotlarda"},{"id":"c","text":"Yol levhalarında"},{"id":"d","text":"Yalnızca Anayasa'da"}]$choices$),
(11, 'en', $text$What are official symbols of the République française?$text$, $expl$The tricolour flag, the Marseillaise and Marianne are official symbols of the République française. They represent the values and identity of the nation.$expl$, $choices$[{"id":"a","text":"The tricolour flag, the Marseillaise and Marianne"},{"id":"b","text":"The Eiffel Tower, the beret and the baguette"},{"id":"c","text":"The fleur-de-lis, the crown and the sceptre"},{"id":"d","text":"The croissant, wine and cheese"}]$choices$),
(11, 'tr', $text$République française'in resmi sembolleri nelerdir?$text$, $expl$Üç renkli bayrak, Marseillaise ve Marianne, République française'in resmi sembolleridir. Ulusun değerlerini ve kimliğini temsil ederler.$expl$, $choices$[{"id":"a","text":"Üç renkli bayrak, Marseillaise ve Marianne"},{"id":"b","text":"Eyfel Kulesi, bere ve baget"},{"id":"c","text":"Zambak çiçeği, taç ve asa"},{"id":"d","text":"Kruvasan, şarap ve peynir"}]$choices$),
(12, 'en', $text$What is equality?$text$, $expl$Equality is a fundamental principle of the Republic: all citizens are equal before the law, without distinction of origin, race or religion. This principle is enshrined in the Declaration of the Rights of Man and of the Citizen of 1789.$expl$, $choices$[{"id":"a","text":"The fact that all citizens have the same rights before the law"},{"id":"b","text":"The fact that everyone has the same salary"},{"id":"c","text":"The right to do whatever one wants"},{"id":"d","text":"The obligation to think the same thing"}]$choices$),
(12, 'tr', $text$Eşitlik nedir?$text$, $expl$Eşitlik, Cumhuriyet'in temel ilkelerinden biridir: tüm vatandaşlar köken, ırk veya din ayrımı yapılmaksızın yasa önünde eşittir. Bu ilke, 1789 İnsan ve Yurttaş Hakları Bildirgesi'nde yer alır.$expl$, $choices$[{"id":"a","text":"Tüm vatandaşların yasa önünde aynı haklara sahip olması"},{"id":"b","text":"Herkesin aynı maaşa sahip olması"},{"id":"c","text":"İstediğini yapma hakkı"},{"id":"d","text":"Aynı şeyi düşünme zorunluluğu"}]$choices$),
(13, 'en', $text$What does liberty mean?$text$, $expl$Liberty consists of being able to do anything that does not harm others. It is framed by the law to guarantee respect for everyone's rights, in accordance with the Declaration of the Rights of Man of 1789.$expl$, $choices$[{"id":"a","text":"Being able to do anything that does not harm others"},{"id":"b","text":"Doing whatever one wants without limit"},{"id":"c","text":"Obeying only the laws one approves of"},{"id":"d","text":"Having no responsibilities"}]$choices$),
(13, 'tr', $text$Özgürlük ne anlama gelir?$text$, $expl$Özgürlük, başkalarına zarar vermeyen her şeyi yapabilme yeteneğidir. 1789 İnsan Hakları Bildirgesi'ne uygun olarak, herkesin haklarına saygıyı güvence altına almak için yasa ile çerçevelenir.$expl$, $choices$[{"id":"a","text":"Başkalarına zarar vermeyen her şeyi yapabilmek"},{"id":"b","text":"Sınırsız bir şekilde istediğini yapmak"},{"id":"c","text":"Yalnızca onayladığı yasalara uymak"},{"id":"d","text":"Sorumluluk taşımamak"}]$choices$),
(14, 'en', $text$What does the word "fraternity" mean in the French motto?$text$, $expl$Fraternity expresses solidarity between citizens and the duty of mutual assistance. This principle implies that members of society support one another.$expl$, $choices$[{"id":"a","text":"Solidarity and mutual help between citizens"},{"id":"b","text":"The obligation to have brothers and sisters"},{"id":"c","text":"The right to live as a family"},{"id":"d","text":"The freedom to choose one's friends"}]$choices$),
(14, 'tr', $text$Fransız sloganında "kardeşlik" kelimesi ne anlama gelir?$text$, $expl$Kardeşlik, vatandaşlar arasındaki dayanışmayı ve karşılıklı yardımlaşma görevini ifade eder. Bu ilke, toplum üyelerinin birbirlerine destek olmasını gerektirir.$expl$, $choices$[{"id":"a","text":"Vatandaşlar arasında dayanışma ve karşılıklı yardımlaşma"},{"id":"b","text":"Erkek ve kız kardeşlere sahip olma zorunluluğu"},{"id":"c","text":"Aile olarak yaşama hakkı"},{"id":"d","text":"Arkadaşlarını seçme özgürlüğü"}]$choices$),
(15, 'en', $text$Which animal is a symbol of France?$text$, $expl$The rooster is a symbol of France. It represents vigilance and pride. It is found in particular on the gates of the Élysée Palace and on the jerseys of French sports teams.$expl$, $choices$[{"id":"a","text":"The rooster"},{"id":"b","text":"The eagle"},{"id":"c","text":"The lion"},{"id":"d","text":"The bear"}]$choices$),
(15, 'tr', $text$Hangi hayvan Fransa'nın simgesidir?$text$, $expl$Horoz, Fransa'nın simgesidir. Tetikte olmayı ve gururu temsil eder. Özellikle Élysée Sarayı'nın parmaklıklarında ve Fransız spor takımlarının formalarında görülür.$expl$, $choices$[{"id":"a","text":"Horoz"},{"id":"b","text":"Kartal"},{"id":"c","text":"Aslan"},{"id":"d","text":"Ayı"}]$choices$),
(16, 'en', $text$What is one of the roles of associations?$text$, $expl$Associations play an essential role in civic life by allowing people to come together to defend a cause, practise an activity or help others. They contribute to solidarity and citizen participation.$expl$, $choices$[{"id":"a","text":"Allowing citizens to come together to defend a cause or help one another"},{"id":"b","text":"Replacing the government"},{"id":"c","text":"Voting on laws"},{"id":"d","text":"Collecting taxes"}]$choices$),
(16, 'tr', $text$Derneklerin rollerinden biri nedir?$text$, $expl$Dernekler, insanların bir davayı savunmak, bir etkinlik yapmak veya başkalarına yardım etmek için bir araya gelmesine olanak tanıyarak yurttaşlık yaşamında önemli bir rol oynarlar. Dayanışmaya ve yurttaş katılımına katkıda bulunurlar.$expl$, $choices$[{"id":"a","text":"Vatandaşların bir davayı savunmak veya birbirine yardım etmek için bir araya gelmesini sağlamak"},{"id":"b","text":"Hükümetin yerini almak"},{"id":"c","text":"Yasaları oylamak"},{"id":"d","text":"Vergi toplamak"}]$choices$),
(17, 'en', $text$What is the name of the national anthem?$text$, $expl$The French national anthem is the Marseillaise. Composed by Rouget de Lisle in 1792, it was declared the national anthem in 1795.$expl$, $choices$[{"id":"a","text":"The Marseillaise"},{"id":"b","text":"The Parisienne"},{"id":"c","text":"The Chant du départ"},{"id":"d","text":"The Carmagnole"}]$choices$),
(17, 'tr', $text$Ulusal marşın adı nedir?$text$, $expl$Fransız ulusal marşı Marseillaise'dir. 1792'de Rouget de Lisle tarafından bestelenmiş ve 1795'te ulusal marş ilan edilmiştir.$expl$, $choices$[{"id":"a","text":"Marseillaise"},{"id":"b","text":"Parisienne"},{"id":"c","text":"Chant du départ"},{"id":"d","text":"Carmagnole"}]$choices$),
(18, 'en', $text$Which symbol of the République française is tricolour?$text$, $expl$The French flag is tricolour: blue, white, red. It has been the symbol of the Republic since the French Revolution and flies over all public buildings.$expl$, $choices$[{"id":"a","text":"The flag"},{"id":"b","text":"Marianne"},{"id":"c","text":"The rooster"},{"id":"d","text":"The motto"}]$choices$),
(18, 'tr', $text$République française'in hangi sembolü üç renklidir?$text$, $expl$Fransız bayrağı üç renklidir: mavi, beyaz, kırmızı. Fransız Devrimi'nden bu yana Cumhuriyet'in simgesidir ve tüm kamu binalarında dalgalanır.$expl$, $choices$[{"id":"a","text":"Bayrak"},{"id":"b","text":"Marianne"},{"id":"c","text":"Horoz"},{"id":"d","text":"Slogan"}]$choices$),
(19, 'en', $text$What is the date of the French national day?$text$, $expl$The French national day is 14 July. It commemorates the storming of the Bastille (1789) and the Fête de la Fédération (1790), symbols of liberty and national unity.$expl$, $choices$[{"id":"a","text":"14 July"},{"id":"b","text":"1 May"},{"id":"c","text":"11 November"},{"id":"d","text":"8 May"}]$choices$),
(19, 'tr', $text$Fransa'nın ulusal bayramının tarihi nedir?$text$, $expl$Fransa'nın ulusal bayramı 14 Temmuz'dur. Bastille'in alınışını (1789) ve Fête de la Fédération'u (1790) anar; bunlar özgürlük ve ulusal birliğin simgeleridir.$expl$, $choices$[{"id":"a","text":"14 Temmuz"},{"id":"b","text":"1 Mayıs"},{"id":"c","text":"11 Kasım"},{"id":"d","text":"8 Mayıs"}]$choices$),
(20, 'en', $text$What is the motto of the République française?$text$, $expl$The motto of the République française is "Liberté, Égalité, Fraternité". It is enshrined in the Constitution and appears on public buildings, coins and official documents.$expl$, $choices$[{"id":"a","text":"Liberté, Égalité, Fraternité"},{"id":"b","text":"Liberty, Justice, Peace"},{"id":"c","text":"Honour, Homeland, Valour"},{"id":"d","text":"Equality, Solidarity, Fraternity"}]$choices$),
(20, 'tr', $text$République française'in sloganı nedir?$text$, $expl$République française'in sloganı "Liberté, Égalité, Fraternité"dir. Anayasa'da yer alır ve kamu binalarında, madeni paralarda ve resmi belgelerde görünür.$expl$, $choices$[{"id":"a","text":"Liberté, Égalité, Fraternité"},{"id":"b","text":"Özgürlük, Adalet, Barış"},{"id":"c","text":"Onur, Vatan, Cesaret"},{"id":"d","text":"Eşitlik, Dayanışma, Kardeşlik"}]$choices$),
(21, 'en', $text$What is the official language of the République française?$text$, $expl$French is the official language of the République française, as stated in Article 2 of the Constitution. It is the language used in administration, justice and education.$expl$, $choices$[{"id":"a","text":"French"},{"id":"b","text":"French and English"},{"id":"c","text":"There is no official language"},{"id":"d","text":"French and regional languages"}]$choices$),
(21, 'tr', $text$République française'in resmi dili nedir?$text$, $expl$Fransızca, Anayasa'nın 2. maddesinde belirtildiği üzere République française'in resmi dilidir. Yönetim, adalet ve eğitimde kullanılan dildir.$expl$, $choices$[{"id":"a","text":"Fransızca"},{"id":"b","text":"Fransızca ve İngilizce"},{"id":"c","text":"Resmi bir dil yoktur"},{"id":"d","text":"Fransızca ve bölgesel diller"}]$choices$),
(22, 'en', $text$What is the place of the French language in the Republic?$text$, $expl$French is the language of the Republic according to Article 2 of the Constitution. It is mandatory in public services, education and administrative acts.$expl$, $choices$[{"id":"a","text":"It is the language of the Republic, enshrined in the Constitution"},{"id":"b","text":"It is one language among others, with no special status"},{"id":"c","text":"It is mandatory only in schools"},{"id":"d","text":"It is official only in Paris"}]$choices$),
(22, 'tr', $text$Fransızca'nın Cumhuriyet içindeki yeri nedir?$text$, $expl$Fransızca, Anayasa'nın 2. maddesine göre Cumhuriyet'in dilidir. Kamu hizmetlerinde, eğitimde ve idari işlemlerde zorunludur.$expl$, $choices$[{"id":"a","text":"Anayasa'da yer alan, Cumhuriyet'in dilidir"},{"id":"b","text":"Özel bir statüsü olmayan, diğerleri arasında bir dildir"},{"id":"c","text":"Yalnızca okullarda zorunludur"},{"id":"d","text":"Yalnızca Paris'te resmidir"}]$choices$),
(23, 'en', $text$Which freedom allows everyone to express their ideas?$text$, $expl$Freedom of expression allows everyone to express their ideas and opinions. It is guaranteed by the Declaration of the Rights of Man and of the Citizen of 1789, but it is limited by respect for others and the prohibition of defamation.$expl$, $choices$[{"id":"a","text":"Freedom of expression"},{"id":"b","text":"Freedom of movement"},{"id":"c","text":"Freedom of association"},{"id":"d","text":"Freedom of commerce"}]$choices$),
(23, 'tr', $text$Hangi özgürlük herkesin fikirlerini ifade etmesine olanak tanır?$text$, $expl$İfade özgürlüğü, herkesin fikirlerini ve görüşlerini ifade etmesine olanak tanır. 1789 İnsan ve Yurttaş Hakları Bildirgesi tarafından güvence altına alınmıştır, ancak başkalarına saygı ve hakaret yasağı ile sınırlanmıştır.$expl$, $choices$[{"id":"a","text":"İfade özgürlüğü"},{"id":"b","text":"Dolaşım özgürlüğü"},{"id":"c","text":"Dernek kurma özgürlüğü"},{"id":"d","text":"Ticaret özgürlüğü"}]$choices$),
(24, 'en', $text$Which statement is correct? Freedom of expression:$text$, $expl$Freedom of expression allows one to give one's opinion, but it has limits. Racist, defamatory or hate-inciting statements are prohibited by law.$expl$, $choices$[{"id":"a","text":"Allows giving one's opinion while respecting the law"},{"id":"b","text":"Allows saying anything without any limit"},{"id":"c","text":"Does not exist in France"},{"id":"d","text":"Is reserved for journalists"}]$choices$),
(24, 'tr', $text$Hangi önerme doğrudur? İfade özgürlüğü:$text$, $expl$İfade özgürlüğü, kişinin görüşünü ifade etmesine olanak tanır, ancak sınırları vardır. Irkçı, iftira niteliğinde veya nefreti kışkırtan söylemler yasalarca yasaktır.$expl$, $choices$[{"id":"a","text":"Yasaya saygı çerçevesinde görüş bildirmeye olanak tanır"},{"id":"b","text":"Hiçbir sınır olmadan her şeyi söylemeye olanak tanır"},{"id":"c","text":"Fransa'da mevcut değildir"},{"id":"d","text":"Yalnızca gazetecilere ayrılmıştır"}]$choices$),
(25, 'en', $text$What are the colours of the French flag?$text$, $expl$The French flag is composed of three vertical bands: blue, white and red. Blue and red are the colours of Paris, and white represents the monarchy.$expl$, $choices$[{"id":"a","text":"Blue, white, red"},{"id":"b","text":"Blue, yellow, red"},{"id":"c","text":"Red, white, green"},{"id":"d","text":"White, red, black"}]$choices$),
(25, 'tr', $text$Fransız bayrağının renkleri nelerdir?$text$, $expl$Fransız bayrağı üç dikey banttan oluşur: mavi, beyaz ve kırmızı. Mavi ve kırmızı Paris'in renkleridir ve beyaz monarşiyi temsil eder.$expl$, $choices$[{"id":"a","text":"Mavi, beyaz, kırmızı"},{"id":"b","text":"Mavi, sarı, kırmızı"},{"id":"c","text":"Kırmızı, beyaz, yeşil"},{"id":"d","text":"Beyaz, kırmızı, siyah"}]$choices$),
(26, 'en', $text$What is the Marseillaise?$text$, $expl$The Marseillaise is the national anthem of France. Composed by Rouget de Lisle in 1792, it became the national anthem in 1795 and is played at official ceremonies.$expl$, $choices$[{"id":"a","text":"The national anthem of France"},{"id":"b","text":"A popular song from the south of France"},{"id":"c","text":"The name of the French flag"},{"id":"d","text":"A traditional dance"}]$choices$),
(26, 'tr', $text$Marseillaise nedir?$text$, $expl$Marseillaise, Fransa'nın ulusal marşıdır. 1792'de Rouget de Lisle tarafından bestelenmiş, 1795'te ulusal marş olmuş ve resmi törenlerde çalınır.$expl$, $choices$[{"id":"a","text":"Fransa'nın ulusal marşı"},{"id":"b","text":"Fransa'nın güneyinden bir halk şarkısı"},{"id":"c","text":"Fransız bayrağının adı"},{"id":"d","text":"Geleneksel bir dans"}]$choices$),
(27, 'en', $text$What is traditionally organised on the Champs-Élysées on 14 July to celebrate the national day?$text$, $expl$A military parade is traditionally organised on the Champs-Élysées on 14 July. It brings together the French armed forces before the President of the Republic.$expl$, $choices$[{"id":"a","text":"A military parade"},{"id":"b","text":"A marathon"},{"id":"c","text":"A rock concert"},{"id":"d","text":"A Christmas market"}]$choices$),
(27, 'tr', $text$Ulusal bayramı kutlamak için 14 Temmuz'da Champs-Élysées'de geleneksel olarak ne düzenlenir?$text$, $expl$14 Temmuz'da geleneksel olarak Champs-Élysées'de bir askeri geçit töreni düzenlenir. Fransız silahlı kuvvetlerini Cumhuriyet Cumhurbaşkanı'nın önünde bir araya getirir.$expl$, $choices$[{"id":"a","text":"Bir askeri geçit töreni"},{"id":"b","text":"Bir maraton"},{"id":"c","text":"Bir rock konseri"},{"id":"d","text":"Bir Noel pazarı"}]$choices$),
(28, 'en', $text$Who is Marianne?$text$, $expl$Marianne is the allegorical figure of the République française. She represents the values of liberty and democracy. Her bust is present in town halls and she appears on postage stamps.$expl$, $choices$[{"id":"a","text":"The figure who represents the République française"},{"id":"b","text":"A queen of France"},{"id":"c","text":"Napoleon's wife"},{"id":"d","text":"A heroine of the Resistance"}]$choices$),
(28, 'tr', $text$Marianne kimdir?$text$, $expl$Marianne, République française'in alegorik figürüdür. Özgürlük ve demokrasi değerlerini temsil eder. Büstü belediye binalarında bulunur ve posta pullarında görünür.$expl$, $choices$[{"id":"a","text":"République française'i temsil eden figür"},{"id":"b","text":"Bir Fransa kraliçesi"},{"id":"c","text":"Napolyon'un eşi"},{"id":"d","text":"Direniş'in bir kadın kahramanı"}]$choices$),
(29, 'en', $text$Can a person freely change religion?$text$, $expl$Yes, in France, every person is free to change religion or to have no religion. Freedom of conscience and worship is guaranteed by the 1905 law and by the Constitution.$expl$, $choices$[{"id":"a","text":"Yes, everyone is free to change religion"},{"id":"b","text":"No, one must keep the religion of one's parents"},{"id":"c","text":"Only with the authorisation of the State"},{"id":"d","text":"No, it is forbidden in France"}]$choices$),
(29, 'tr', $text$Bir kişi serbestçe dinini değiştirebilir mi?$text$, $expl$Evet, Fransa'da her kişi dinini değiştirmekte veya dinsiz olmakta serbesttir. Vicdan ve ibadet özgürlüğü 1905 yasası ve Anayasa tarafından güvence altına alınmıştır.$expl$, $choices$[{"id":"a","text":"Evet, herkes dinini değiştirmekte serbesttir"},{"id":"b","text":"Hayır, anne babasının dinini korumak zorundadır"},{"id":"c","text":"Yalnızca Devlet'in izniyle"},{"id":"d","text":"Hayır, Fransa'da yasaktır"}]$choices$),
(30, 'en', $text$"France is an indivisible, ..., democratic and social Republic." Complete this sentence from Article 1 of the Constitution:$text$, $expl$Article 1 of the Constitution states that "France is an indivisible, secular, democratic and social Republic". Laïcité (secularism) is therefore a fundamental constitutional principle.$expl$, $choices$[{"id":"a","text":"Secular (laïque)"},{"id":"b","text":"Christian"},{"id":"c","text":"Liberal"},{"id":"d","text":"Federal"}]$choices$),
(30, 'tr', $text$"Fransa, bölünmez, ..., demokratik ve sosyal bir Cumhuriyettir." Anayasa'nın 1. maddesinden alınan bu cümleyi tamamlayın:$text$, $expl$Anayasa'nın 1. maddesi "Fransa, bölünmez, laik, demokratik ve sosyal bir Cumhuriyettir" der. Laïcité (laiklik) bu nedenle temel bir anayasal ilkedir.$expl$, $choices$[{"id":"a","text":"Laik (laïque)"},{"id":"b","text":"Hristiyan"},{"id":"c","text":"Liberal"},{"id":"d","text":"Federal"}]$choices$),
(31, 'en', $text$In what year was the law on the separation of the Churches and the State passed?$text$, $expl$The law on the separation of the Churches and the State was passed on 9 December 1905. It guarantees freedom of conscience and establishes the principle of the secularism of the State.$expl$, $choices$[{"id":"a","text":"1905"},{"id":"b","text":"1789"},{"id":"c","text":"1958"},{"id":"d","text":"1848"}]$choices$),
(31, 'tr', $text$Kiliseler ve Devlet'in ayrılması yasası hangi yılda kabul edildi?$text$, $expl$Kiliseler ve Devlet'in ayrılması yasası 9 Aralık 1905'te kabul edildi. Vicdan özgürlüğünü güvence altına alır ve Devlet'in laiklik ilkesini ortaya koyar.$expl$, $choices$[{"id":"a","text":"1905"},{"id":"b","text":"1789"},{"id":"c","text":"1958"},{"id":"d","text":"1848"}]$choices$),
(32, 'en', $text$What does the principle of laïcité (secularism) allow?$text$, $expl$The principle of laïcité allows everyone to freely practise their religion or to have none, while ensuring the neutrality of the State in religious matters. The State does not favour any religion.$expl$, $choices$[{"id":"a","text":"Freely practising one's religion or having none"},{"id":"b","text":"Banning all religions"},{"id":"c","text":"Imposing an official religion"},{"id":"d","text":"Practising one's religion only at home"}]$choices$),
(32, 'tr', $text$Laïcité (laiklik) ilkesi neye olanak tanır?$text$, $expl$Laïcité ilkesi, herkesin dinini özgürce uygulamasına veya hiç din taşımamasına olanak tanırken, Devlet'in dini konulardaki tarafsızlığını da güvence altına alır. Devlet hiçbir dini kayırmaz.$expl$, $choices$[{"id":"a","text":"Kişinin dinini özgürce uygulamasına veya hiç dinsiz olmasına"},{"id":"b","text":"Tüm dinleri yasaklamaya"},{"id":"c","text":"Resmi bir din dayatmaya"},{"id":"d","text":"Kişinin dinini yalnızca evinde uygulamasına"}]$choices$),
(33, 'en', $text$Which right is guaranteed by laïcité?$text$, $expl$Laïcité guarantees freedom of conscience: everyone is free to believe or not to believe. The State ensures freedom of worship while remaining neutral towards all religions.$expl$, $choices$[{"id":"a","text":"Freedom of conscience and freedom of worship"},{"id":"b","text":"The right to vote"},{"id":"c","text":"The right to work"},{"id":"d","text":"The right to property"}]$choices$),
(33, 'tr', $text$Laïcité (laiklik) tarafından hangi hak güvence altına alınır?$text$, $expl$Laïcité vicdan özgürlüğünü güvence altına alır: herkes inanmakta veya inanmamakta serbesttir. Devlet, tüm dinlere karşı tarafsız kalarak ibadet özgürlüğünü sağlar.$expl$, $choices$[{"id":"a","text":"Vicdan özgürlüğü ve ibadet özgürlüğü"},{"id":"b","text":"Oy hakkı"},{"id":"c","text":"Çalışma hakkı"},{"id":"d","text":"Mülkiyet hakkı"}]$choices$),
(34, 'en', $text$Why must the principle of laïcité be respected at school?$text$, $expl$Laïcité must be respected at school to guarantee the neutrality of the public education service and to enable all pupils to study together without religious pressure.$expl$, $choices$[{"id":"a","text":"To guarantee the neutrality of teaching and living together"},{"id":"b","text":"To prohibit any discussion of religion"},{"id":"c","text":"To force pupils to be atheists"},{"id":"d","text":"To favour a particular religion"}]$choices$),
(34, 'tr', $text$Laïcité (laiklik) ilkesi neden okulda saygı görmelidir?$text$, $expl$Laïcité, kamu eğitim hizmetinin tarafsızlığını güvence altına almak ve tüm öğrencilerin dini baskı olmadan birlikte öğrenim görmesini sağlamak için okulda saygı görmelidir.$expl$, $choices$[{"id":"a","text":"Öğretimin tarafsızlığını ve birlikte yaşamayı güvence altına almak için"},{"id":"b","text":"Din hakkında her türlü tartışmayı yasaklamak için"},{"id":"c","text":"Öğrencileri ateist olmaya zorlamak için"},{"id":"d","text":"Belirli bir dini kayırmak için"}]$choices$),
(35, 'en', $text$What is laïcité (secularism)?$text$, $expl$Laïcité is the principle of separation of the Churches and the State. The State does not recognise, pay or subsidise any religion, while guaranteeing freedom of conscience and the free exercise of worship.$expl$, $choices$[{"id":"a","text":"The principle of separation of religions and the State"},{"id":"b","text":"The prohibition of all religions"},{"id":"c","text":"The obligation to be an atheist"},{"id":"d","text":"The official religion of France"}]$choices$),
(35, 'tr', $text$Laïcité (laiklik) nedir?$text$, $expl$Laïcité, Kiliseler ve Devlet'in ayrılması ilkesidir. Devlet hiçbir dini tanımaz, maaş ödemez veya sübvanse etmezken, vicdan özgürlüğünü ve ibadetin serbest yapılmasını güvence altına alır.$expl$, $choices$[{"id":"a","text":"Dinler ile Devlet'in ayrılması ilkesi"},{"id":"b","text":"Tüm dinlerin yasaklanması"},{"id":"c","text":"Ateist olma zorunluluğu"},{"id":"d","text":"Fransa'nın resmi dini"}]$choices$),
(36, 'en', $text$Can a child refuse to go to school for religious reasons?$text$, $expl$No, schooling is compulsory in France for all children from 3 to 16 years old. No religious reason can justify refusing this obligation. Laïcité guarantees neutral education accessible to all.$expl$, $choices$[{"id":"a","text":"No, schooling is compulsory for all children"},{"id":"b","text":"Yes, if his or her parents agree"},{"id":"c","text":"Yes, religious freedom allows it"},{"id":"d","text":"Yes, only during religious holidays"}]$choices$),
(36, 'tr', $text$Bir çocuk dini bir nedenle okula gitmeyi reddedebilir mi?$text$, $expl$Hayır, Fransa'da 3 ila 16 yaş arasındaki tüm çocuklar için eğitim zorunludur. Hiçbir dini sebep bu zorunluluğun reddedilmesini meşrulaştıramaz. Laïcité, herkes için erişilebilir tarafsız bir öğretimi güvence altına alır.$expl$, $choices$[{"id":"a","text":"Hayır, eğitim tüm çocuklar için zorunludur"},{"id":"b","text":"Evet, ebeveynleri onay verirse"},{"id":"c","text":"Evet, dini özgürlük buna izin verir"},{"id":"d","text":"Evet, yalnızca dini bayramlar sırasında"}]$choices$),
(37, 'en', $text$Does a person have the right not to believe in a religion?$text$, $expl$Yes, freedom of conscience guarantees everyone the right to believe or not to believe. In France, one can be atheist, agnostic or believer; it is a personal choice protected by law.$expl$, $choices$[{"id":"a","text":"Yes, this is freedom of conscience"},{"id":"b","text":"No, everyone must have a religion"},{"id":"c","text":"Only if the State authorises it"},{"id":"d","text":"No, it is forbidden in France"}]$choices$),
(37, 'tr', $text$Bir kişinin bir dine inanmama hakkı var mıdır?$text$, $expl$Evet, vicdan özgürlüğü herkese inanma veya inanmama hakkı sağlar. Fransa'da kişi ateist, agnostik veya inançlı olabilir; bu, yasa tarafından korunan kişisel bir tercihtir.$expl$, $choices$[{"id":"a","text":"Evet, bu vicdan özgürlüğüdür"},{"id":"b","text":"Hayır, herkesin bir dini olmalıdır"},{"id":"c","text":"Yalnızca Devlet izin verirse"},{"id":"d","text":"Hayır, Fransa'da yasaktır"}]$choices$),
(38, 'en', $text$Among the following options, which constitutes citizen participation?$text$, $expl$Voting is one of the fundamental acts of citizen participation. It is the means by which citizens exercise their sovereignty and take part in democratic life.$expl$, $choices$[{"id":"a","text":"Voting in elections"},{"id":"b","text":"Watching the news on television"},{"id":"c","text":"Going on holiday"},{"id":"d","text":"Doing the shopping"}]$choices$),
(38, 'tr', $text$Aşağıdaki seçeneklerden hangisi yurttaş katılımını oluşturur?$text$, $expl$Oy vermek, yurttaş katılımının temel eylemlerinden biridir. Vatandaşların egemenliklerini kullanmasının ve demokratik yaşama katılmasının bir yoludur.$expl$, $choices$[{"id":"a","text":"Seçimlerde oy vermek"},{"id":"b","text":"Televizyonda haberleri izlemek"},{"id":"c","text":"Tatile gitmek"},{"id":"d","text":"Alışveriş yapmak"}]$choices$),
(39, 'en', $text$What does freedom of expression guarantee?$text$, $expl$Freedom of expression guarantees everyone's right to express their opinions and ideas freely. It is a pillar of democracy, but it is framed by law to prevent abuses such as defamation or incitement to hatred.$expl$, $choices$[{"id":"a","text":"The right to express one's opinions freely while respecting the law"},{"id":"b","text":"The right to say anything without consequence"},{"id":"c","text":"The right not to speak French"},{"id":"d","text":"The right to refuse to answer the police"}]$choices$),
(39, 'tr', $text$İfade özgürlüğü neyi güvence altına alır?$text$, $expl$İfade özgürlüğü, herkesin görüşlerini ve fikirlerini özgürce ifade etme hakkını güvence altına alır. Demokrasinin temel direklerinden biridir, ancak iftira veya nefreti kışkırtma gibi suistimallerin önlenmesi için yasa ile çerçevelenmiştir.$expl$, $choices$[{"id":"a","text":"Yasaya saygı çerçevesinde görüşlerini özgürce ifade etme hakkı"},{"id":"b","text":"Sonuçsuz olarak her şeyi söyleme hakkı"},{"id":"c","text":"Fransızca konuşmama hakkı"},{"id":"d","text":"Polise cevap vermeyi reddetme hakkı"}]$choices$),
(40, 'en', $text$What is the purpose of a residence permit (titre de séjour)?$text$, $expl$A residence permit is an official document that authorises a foreigner to legally reside in France. It can be temporary or permanent and conditions access to work and social rights.$expl$, $choices$[{"id":"a","text":"To authorise a foreigner to legally reside in France"},{"id":"b","text":"To automatically obtain French nationality"},{"id":"c","text":"To travel for free in France"},{"id":"d","text":"To vote in elections"}]$choices$),
(40, 'tr', $text$İkamet izninin (titre de séjour) amacı nedir?$text$, $expl$İkamet izni, bir yabancının Fransa'da yasal olarak ikamet etmesine izin veren resmi bir belgedir. Geçici veya kalıcı olabilir ve çalışmaya ve sosyal haklara erişimi şartlandırır.$expl$, $choices$[{"id":"a","text":"Bir yabancının Fransa'da yasal olarak ikamet etmesine izin vermek"},{"id":"b","text":"Otomatik olarak Fransız vatandaşlığı elde etmek"},{"id":"c","text":"Fransa'da ücretsiz seyahat etmek"},{"id":"d","text":"Seçimlerde oy vermek"}]$choices$),
(41, 'en', $text$Freedom of movement allows every person to:$text$, $expl$Freedom of movement is a fundamental right that allows every person to move freely on French territory and to choose their place of residence.$expl$, $choices$[{"id":"a","text":"Move freely and choose one's place of residence"},{"id":"b","text":"Drive without a licence"},{"id":"c","text":"Enter all public buildings without restriction"},{"id":"d","text":"Travel abroad without a passport"}]$choices$),
(41, 'tr', $text$Dolaşım özgürlüğü her bireye neyi sağlar?$text$, $expl$Dolaşım özgürlüğü, her bireyin Fransa topraklarında serbestçe dolaşmasını ve ikamet yerini seçmesini sağlayan temel bir haktır.$expl$, $choices$[{"id":"a","text":"Serbestçe dolaşmak ve ikamet yerini seçmek"},{"id":"b","text":"Ehliyetsiz araç kullanmak"},{"id":"c","text":"Tüm kamu binalarına kısıtlama olmaksızın girmek"},{"id":"d","text":"Pasaportsuz olarak yurtdışına seyahat etmek"}]$choices$),
(42, 'en', $text$On which website can one find the symbol of the République française?$text$, $expl$The symbol of the République française (Marianne, the tricolour flag, the motto) appears on official government websites, in particular service-public.fr and sites ending in .gouv.fr.$expl$, $choices$[{"id":"a","text":"On official government websites (ending in .gouv.fr)"},{"id":"b","text":"Only on social media"},{"id":"c","text":"On Wikipedia"},{"id":"d","text":"On online shopping sites"}]$choices$),
(42, 'tr', $text$République française'in sembolünü hangi internet sitesinde bulabiliriz?$text$, $expl$République française'in sembolü (Marianne, üç renkli bayrak, slogan) resmi hükümet sitelerinde, özellikle service-public.fr ve .gouv.fr ile biten sitelerde yer alır.$expl$, $choices$[{"id":"a","text":"Resmi hükümet sitelerinde (.gouv.fr ile bitenler)"},{"id":"b","text":"Yalnızca sosyal medyada"},{"id":"c","text":"Wikipedia'da"},{"id":"d","text":"Online alışveriş sitelerinde"}]$choices$),
(43, 'en', $text$Complete these lyrics of the Marseillaise: "To arms [...]! Form your battalions"$text$, $expl$The exact lyrics of the refrain of the Marseillaise are: "Aux armes, citoyens ! Formez vos bataillons" (To arms, citizens! Form your battalions). This revolutionary song calls on citizens to defend the nation.$expl$, $choices$[{"id":"a","text":"Citizens (Citoyens)"},{"id":"b","text":"Soldiers (Soldats)"},{"id":"c","text":"French people (Français)"},{"id":"d","text":"Comrades (Camarades)"}]$choices$),
(43, 'tr', $text$Marseillaise'in şu sözlerini tamamlayın: "Silah başına [...]! Taburlarınızı oluşturun"$text$, $expl$Marseillaise'in nakaratının kesin sözleri şöyledir: "Aux armes, citoyens ! Formez vos bataillons" (Silah başına, vatandaşlar! Taburlarınızı oluşturun). Bu devrimci şarkı, vatandaşları ulusu savunmaya çağırır.$expl$, $choices$[{"id":"a","text":"Vatandaşlar (Citoyens)"},{"id":"b","text":"Askerler (Soldats)"},{"id":"c","text":"Fransızlar (Français)"},{"id":"d","text":"Yoldaşlar (Camarades)"}]$choices$),
(44, 'en', $text$Complete the lyrics of the Marseillaise: "Arise, children of the homeland [...]"$text$, $expl$The opening lyrics of the Marseillaise are: "Allons enfants de la patrie, le jour de gloire est arrivé" (Arise, children of the homeland, the day of glory has arrived). This song was composed by Rouget de Lisle in 1792.$expl$, $choices$[{"id":"a","text":"The day of glory has arrived"},{"id":"b","text":"Victory is ours"},{"id":"c","text":"Let us defend our liberty"},{"id":"d","text":"Let us march to victory"}]$choices$),
(44, 'tr', $text$Marseillaise'in sözlerini tamamlayın: "Vatanın çocukları, ileri [...]"$text$, $expl$Marseillaise'in ilk sözleri şöyledir: "Allons enfants de la patrie, le jour de gloire est arrivé" (Vatanın çocukları, ileri, zafer günü geldi). Bu şarkı 1792'de Rouget de Lisle tarafından bestelenmiştir.$expl$, $choices$[{"id":"a","text":"Zafer günü geldi"},{"id":"b","text":"Zafer bizimdir"},{"id":"c","text":"Özgürlüğümüzü savunalım"},{"id":"d","text":"Zafere yürüyelim"}]$choices$),
(45, 'en', $text$In application of individual liberty, which statement is correct? A person can:$text$, $expl$Individual liberty allows everyone to dress as they wish in public space, while respecting the law. It is an expression of personal freedom guaranteed by the Constitution.$expl$, $choices$[{"id":"a","text":"Dress as they wish while respecting the law"},{"id":"b","text":"Refuse to pay their taxes"},{"id":"c","text":"Not respect the highway code"},{"id":"d","text":"Ignore court decisions"}]$choices$),
(45, 'tr', $text$Bireysel özgürlüğün uygulanmasında hangi önerme doğrudur? Bir kişi:$text$, $expl$Bireysel özgürlük, herkesin yasalara saygı duyarak kamusal alanda istediği gibi giyinmesine olanak tanır. Anayasa tarafından güvence altına alınan kişisel özgürlüğün bir ifadesidir.$expl$, $choices$[{"id":"a","text":"Yasaya saygı duyarak istediği gibi giyinebilir"},{"id":"b","text":"Vergilerini ödemeyi reddedebilir"},{"id":"c","text":"Trafik kurallarına uymayabilir"},{"id":"d","text":"Mahkeme kararlarını yok sayabilir"}]$choices$),
(46, 'en', $text$Regarding the practice of religion, which statement is correct?$text$, $expl$In France, everyone is free to practise the religion of their choice or to practise none. Laïcité guarantees this freedom while imposing the neutrality of the State.$expl$, $choices$[{"id":"a","text":"Everyone is free to practise the religion of their choice or to have none"},{"id":"b","text":"One must necessarily practise a religion"},{"id":"c","text":"Only certain religions are authorised"},{"id":"d","text":"Religion must remain secret"}]$choices$),
(46, 'tr', $text$Dinin uygulanmasına ilişkin olarak hangi önerme doğrudur?$text$, $expl$Fransa'da herkes seçtiği dini uygulamakta veya hiç bir din uygulamamakta serbesttir. Laïcité, Devlet'in tarafsızlığını dayatırken bu özgürlüğü güvence altına alır.$expl$, $choices$[{"id":"a","text":"Herkes seçtiği dini uygulamakta veya hiç bir dini uygulamamakta serbesttir"},{"id":"b","text":"Mutlaka bir din uygulanmalıdır"},{"id":"c","text":"Yalnızca bazı dinlere izin verilir"},{"id":"d","text":"Din gizli kalmalıdır"}]$choices$),
(47, 'en', $text$As a parent, can one refuse to have one's child take part in sport classes at school because they are mixed?$text$, $expl$No, sport classes are compulsory at school and co-education (mixité) is a fundamental principle of public schooling. No religious or personal reason can justify refusing co-education at school.$expl$, $choices$[{"id":"a","text":"No, sport classes are compulsory and co-education is a principle of the school"},{"id":"b","text":"Yes, for religious reasons"},{"id":"c","text":"Yes, if the child agrees"},{"id":"d","text":"Yes, with a medical certificate"}]$choices$),
(47, 'tr', $text$Bir veli olarak, çocuğunuzun okuldaki spor derslerine karma oldukları için katılmasını reddedebilir misiniz?$text$, $expl$Hayır, okulda spor dersleri zorunludur ve karmalık (mixité) kamu okulunun temel ilkelerinden biridir. Hiçbir dini veya kişisel sebep okulda karmalığın reddini meşrulaştıramaz.$expl$, $choices$[{"id":"a","text":"Hayır, spor dersleri zorunludur ve karmalık okulun bir ilkesidir"},{"id":"b","text":"Evet, dini nedenlerle"},{"id":"c","text":"Evet, çocuk razı olursa"},{"id":"d","text":"Evet, tıbbi raporla"}]$choices$),
(48, 'en', $text$Repudiating one's wife (répudiation) is:$text$, $expl$Repudiation is forbidden in France. French law does not recognise unilateral repudiation. Only divorce, pronounced by a judge, can end a marriage, in respect of equality between the spouses.$expl$, $choices$[{"id":"a","text":"Forbidden in France"},{"id":"b","text":"Authorised under certain conditions"},{"id":"c","text":"Possible with the mayor's agreement"},{"id":"d","text":"Authorised if both spouses agree"}]$choices$),
(48, 'tr', $text$Eşini boşaması (répudiation):$text$, $expl$Répudiation (tek taraflı boşama) Fransa'da yasaktır. Fransız hukuku tek taraflı boşamayı tanımaz. Yalnızca bir hâkim tarafından verilen boşanma, eşler arasındaki eşitliğe saygı içinde bir evliliği sona erdirebilir.$expl$, $choices$[{"id":"a","text":"Fransa'da yasaktır"},{"id":"b","text":"Belirli koşullar altında izinlidir"},{"id":"c","text":"Belediye başkanının onayıyla mümkündür"},{"id":"d","text":"İki eş de razıysa izinlidir"}]$choices$),
(49, 'en', $text$Taxes are used to finance public spending. Which statement is correct?$text$, $expl$Taxes fund public services such as education, health, security and infrastructure. Each citizen contributes according to their means to the functioning of the State and local authorities.$expl$, $choices$[{"id":"a","text":"Taxes finance public services (schools, hospitals, roads, security)"},{"id":"b","text":"Taxes are only used to pay elected officials"},{"id":"c","text":"Only the rich pay taxes"},{"id":"d","text":"Taxes are optional"}]$choices$),
(49, 'tr', $text$Vergiler kamu harcamalarını finanse etmek için kullanılır. Hangi önerme doğrudur?$text$, $expl$Vergiler eğitim, sağlık, güvenlik ve altyapı gibi kamu hizmetlerini finanse eder. Her vatandaş, Devlet'in ve yerel yönetimlerin işleyişine olanakları ölçüsünde katkıda bulunur.$expl$, $choices$[{"id":"a","text":"Vergiler kamu hizmetlerini (okullar, hastaneler, yollar, güvenlik) finanse eder"},{"id":"b","text":"Vergiler yalnızca seçilmişleri ödemek için kullanılır"},{"id":"c","text":"Yalnızca zenginler vergi öder"},{"id":"d","text":"Vergiler isteğe bağlıdır"}]$choices$),
(50, 'en', $text$Can one publicly burn a French flag?$text$, $expl$No, contempt of the tricolour flag (outrage au drapeau) at a public event is an offence punishable by law. The flag is a symbol of the Republic and its public destruction is forbidden.$expl$, $choices$[{"id":"a","text":"No, it is an offence punishable by law"},{"id":"b","text":"Yes, thanks to freedom of expression"},{"id":"c","text":"Yes, if it is during a demonstration"},{"id":"d","text":"Yes, if the flag belongs to you"}]$choices$),
(50, 'tr', $text$Bir Fransız bayrağı alenen yakılabilir mi?$text$, $expl$Hayır, üç renkli bayrağa kamuya açık bir etkinlik sırasında hakaret (outrage au drapeau) yasalarca cezalandırılan bir suçtur. Bayrak Cumhuriyet'in simgesidir ve aleni olarak imha edilmesi yasaktır.$expl$, $choices$[{"id":"a","text":"Hayır, yasalarca cezalandırılan bir suçtur"},{"id":"b","text":"Evet, ifade özgürlüğü sayesinde"},{"id":"c","text":"Evet, bir gösteri sırasında ise"},{"id":"d","text":"Evet, bayrak size aitse"}]$choices$),
(51, 'en', $text$What does the State do to combat discrimination?$text$, $expl$The State has put in place laws that prohibit and punish discrimination. The Défenseur des droits (the Defender of Rights, an independent authority) can be petitioned by any victim of discrimination.$expl$, $choices$[{"id":"a","text":"It passes laws that prohibit and punish discrimination"},{"id":"b","text":"It does nothing; it is up to citizens to act"},{"id":"c","text":"It authorises certain discriminations"},{"id":"d","text":"It lets companies decide"}]$choices$),
(51, 'tr', $text$Devlet ayrımcılıkla mücadele için ne yapar?$text$, $expl$Devlet, ayrımcılıkları yasaklayan ve cezalandıran yasalar çıkarmıştır. Défenseur des droits (Haklar Savunucusu, bağımsız bir kurum) ayrımcılığa uğrayan herkes tarafından başvurulabilen bağımsız bir kurumdur.$expl$, $choices$[{"id":"a","text":"Ayrımcılığı yasaklayan ve cezalandıran yasalar çıkarır"},{"id":"b","text":"Hiçbir şey yapmaz; harekete geçmek vatandaşlara düşer"},{"id":"c","text":"Bazı ayrımcılıklara izin verir"},{"id":"d","text":"Karar vermeyi şirketlere bırakır"}]$choices$),
(52, 'en', $text$What does Marianne represent?$text$, $expl$Marianne is the allegory of the République française. She embodies the values of liberty and the Republic. Wearing the Phrygian cap, she symbolises the triumph of the Republic.$expl$, $choices$[{"id":"a","text":"The République française"},{"id":"b","text":"The queen of France"},{"id":"c","text":"Europe"},{"id":"d","text":"The city of Paris"}]$choices$),
(52, 'tr', $text$Marianne neyi temsil eder?$text$, $expl$Marianne, République française'in alegorisidir. Özgürlük ve Cumhuriyet değerlerini somutlaştırır. Frigya başlığı takarak Cumhuriyet'in zaferini simgeler.$expl$, $choices$[{"id":"a","text":"République française"},{"id":"b","text":"Fransa kraliçesi"},{"id":"c","text":"Avrupa"},{"id":"d","text":"Paris şehri"}]$choices$),
(53, 'en', $text$What is freedom of association?$text$, $expl$Freedom of association is the right to create or join an association without prior authorisation. It is guaranteed by the law of 1 July 1901 and allows citizens to group together to defend a common cause.$expl$, $choices$[{"id":"a","text":"The right to freely create or join an association"},{"id":"b","text":"The obligation to belong to an association"},{"id":"c","text":"The right to start a business"},{"id":"d","text":"The right to start a political party only"}]$choices$),
(53, 'tr', $text$Dernek kurma özgürlüğü nedir?$text$, $expl$Dernek kurma özgürlüğü, önceden izin almadan bir dernek kurma veya bir derneğe katılma hakkıdır. 1 Temmuz 1901 yasası tarafından güvence altına alınır ve vatandaşların ortak bir davayı savunmak için bir araya gelmesini sağlar.$expl$, $choices$[{"id":"a","text":"Bir dernek kurma veya bir derneğe katılma hakkı"},{"id":"b","text":"Bir derneğe ait olma zorunluluğu"},{"id":"c","text":"Bir şirket kurma hakkı"},{"id":"d","text":"Yalnızca siyasi parti kurma hakkı"}]$choices$),
(54, 'en', $text$What is liberty?$text$, $expl$Liberty consists of being able to do anything that does not harm others, according to Article 4 of the Declaration of the Rights of Man and of the Citizen of 1789. It is limited by law to protect the rights of others.$expl$, $choices$[{"id":"a","text":"The right to do anything that does not harm others, while respecting the law"},{"id":"b","text":"The right to do absolutely anything one wants"},{"id":"c","text":"The right not to respect the law"},{"id":"d","text":"The right to do nothing"}]$choices$),
(54, 'tr', $text$Özgürlük nedir?$text$, $expl$Özgürlük, 1789 İnsan ve Yurttaş Hakları Bildirgesi'nin 4. maddesine göre başkalarına zarar vermeyen her şeyi yapabilme olanağıdır. Başkalarının haklarını korumak için yasa tarafından sınırlanmıştır.$expl$, $choices$[{"id":"a","text":"Yasaya saygı çerçevesinde başkalarına zarar vermeyen her şeyi yapma hakkı"},{"id":"b","text":"Kesinlikle istediği her şeyi yapma hakkı"},{"id":"c","text":"Yasaya uymama hakkı"},{"id":"d","text":"Hiçbir şey yapmama hakkı"}]$choices$),
(55, 'en', $text$On which document can one see Marianne?$text$, $expl$Marianne appears on French postage stamps. She can also be found on coins, in town halls and on official documents of the Republic.$expl$, $choices$[{"id":"a","text":"On postage stamps"},{"id":"b","text":"On the driving licence"},{"id":"c","text":"On train tickets"},{"id":"d","text":"On medical prescriptions"}]$choices$),
(55, 'tr', $text$Marianne'i hangi belgede görebiliriz?$text$, $expl$Marianne, Fransız posta pullarında görünür. Madeni paralarda, belediye binalarında ve Cumhuriyet'in resmi belgelerinde de bulunur.$expl$, $choices$[{"id":"a","text":"Posta pullarında"},{"id":"b","text":"Ehliyette"},{"id":"c","text":"Tren biletlerinde"},{"id":"d","text":"Tıbbi reçetelerde"}]$choices$),
(56, 'en', $text$An employer refuses to hire women in his company. What does the law say?$text$, $expl$The law prohibits any discrimination in hiring based on sex. Refusing to hire women is an offence punishable under criminal law. The principle of equality between women and men is guaranteed by the Constitution.$expl$, $choices$[{"id":"a","text":"It is forbidden; it is discrimination punishable by law"},{"id":"b","text":"It is allowed if the company is small"},{"id":"c","text":"It is allowed in certain sectors"},{"id":"d","text":"It is the employer's right"}]$choices$),
(56, 'tr', $text$Bir işveren şirketinde kadınları işe almayı reddediyor. Yasa ne der?$text$, $expl$Yasa, cinsiyete dayalı işe alımda her türlü ayrımcılığı yasaklar. Kadınları işe almayı reddetmek, cezai yaptırımlara tabi bir suçtur. Kadınlar ve erkekler arasında eşitlik ilkesi Anayasa tarafından güvence altına alınmıştır.$expl$, $choices$[{"id":"a","text":"Yasaktır, yasalarca cezalandırılan bir ayrımcılıktır"},{"id":"b","text":"Şirket küçükse izinlidir"},{"id":"c","text":"Belirli sektörlerde izinlidir"},{"id":"d","text":"Bu işverenin hakkıdır"}]$choices$),
(57, 'en', $text$One of the values of the republican motto is equality. What does this mean?$text$, $expl$Equality in the republican motto means that all citizens are equal before the law, without distinction of origin, race or religion, in accordance with Article 1 of the Constitution.$expl$, $choices$[{"id":"a","text":"All citizens are equal before the law"},{"id":"b","text":"All citizens must have the same income"},{"id":"c","text":"All citizens must think the same way"},{"id":"d","text":"All citizens must have the same job"}]$choices$),
(57, 'tr', $text$Cumhuriyet sloganının değerlerinden biri eşitliktir. Bu ne anlama gelir?$text$, $expl$Cumhuriyet sloganında eşitlik, Anayasa'nın 1. maddesi uyarınca tüm vatandaşların köken, ırk veya din ayrımı yapılmaksızın yasa önünde eşit olması anlamına gelir.$expl$, $choices$[{"id":"a","text":"Tüm vatandaşlar yasa önünde eşittir"},{"id":"b","text":"Tüm vatandaşların aynı gelire sahip olması gerekir"},{"id":"c","text":"Tüm vatandaşların aynı şekilde düşünmesi gerekir"},{"id":"d","text":"Tüm vatandaşların aynı işe sahip olması gerekir"}]$choices$),
(58, 'en', $text$At public school, who can wear very visible religious signs?$text$, $expl$Since the law of 15 March 2004, wearing ostensible religious signs is prohibited for pupils in public schools, middle schools and high schools. No one (neither pupils nor staff) can wear very visible religious signs.$expl$, $choices$[{"id":"a","text":"No one; it is forbidden by the 2004 law"},{"id":"b","text":"Everyone"},{"id":"c","text":"Only teachers"},{"id":"d","text":"Only adult pupils"}]$choices$),
(58, 'tr', $text$Kamu okulunda, çok belirgin dini işaretleri kim takabilir?$text$, $expl$15 Mart 2004 yasasından bu yana, kamu okullarında, ortaokullarda ve liselerde öğrencilerin gösterişli dini işaretler takması yasaktır. Hiç kimse (ne öğrenciler ne de personel) çok belirgin dini işaretler takamaz.$expl$, $choices$[{"id":"a","text":"Kimse, 2004 yasasıyla yasaklanmıştır"},{"id":"b","text":"Herkes"},{"id":"c","text":"Yalnızca öğretmenler"},{"id":"d","text":"Yalnızca reşit öğrenciler"}]$choices$),
(59, 'en', $text$According to the principle of laïcité, what does the neutrality of the State mean?$text$, $expl$The neutrality of the State means that the State neither favours nor disfavours any religion. It does not recognise, pay or subsidise any religion, in accordance with the 1905 law.$expl$, $choices$[{"id":"a","text":"The State neither favours nor disfavours any religion"},{"id":"b","text":"The State prohibits all religions"},{"id":"c","text":"The State chooses an official religion"},{"id":"d","text":"The State controls religious practices"}]$choices$),
(59, 'tr', $text$Laïcité ilkesine göre, Devlet'in tarafsızlığı ne anlama gelir?$text$, $expl$Devlet'in tarafsızlığı, Devlet'in hiçbir dini kayırmadığı ve hiçbirine karşı olmadığı anlamına gelir. 1905 yasasına uygun olarak hiçbir dini tanımaz, maaş ödemez veya sübvanse etmez.$expl$, $choices$[{"id":"a","text":"Devlet hiçbir dini kayırmaz ve hiçbirine karşı olmaz"},{"id":"b","text":"Devlet tüm dinleri yasaklar"},{"id":"c","text":"Devlet resmi bir din seçer"},{"id":"d","text":"Devlet dini uygulamaları kontrol eder"}]$choices$),
(60, 'en', $text$What can a user of a public service do in a town hall?$text$, $expl$A user of a public service can wear a religious sign in a town hall because neutrality applies to staff, not to users. However, the user must respect public order.$expl$, $choices$[{"id":"a","text":"Wear a religious sign, because neutrality applies to staff, not to users"},{"id":"b","text":"Impose their religious convictions on staff"},{"id":"c","text":"Refuse to be served by a staff member of another religion"},{"id":"d","text":"Demand opening hours adapted to their religion"}]$choices$),
(60, 'tr', $text$Bir belediye binasında kamu hizmetinden yararlanan kişi ne yapabilir?$text$, $expl$Kamu hizmetinden yararlanan bir kişi belediye binasında dini bir işaret takabilir çünkü tarafsızlık çalışanlara uygulanır, hizmetten yararlananlara değil. Ancak kullanıcı kamu düzenine saygı göstermelidir.$expl$, $choices$[{"id":"a","text":"Dini bir işaret takabilir; tarafsızlık çalışanlara uygulanır, kullanıcılara değil"},{"id":"b","text":"Dini inançlarını çalışanlara dayatabilir"},{"id":"c","text":"Başka bir dinden bir çalışan tarafından hizmet almayı reddedebilir"},{"id":"d","text":"Dinine uygun çalışma saatleri talep edebilir"}]$choices$),
(61, 'en', $text$Who must respect the principle of religious neutrality in a préfecture (prefecture)?$text$, $expl$The principle of religious neutrality applies to staff of the public service. They must not manifest their religious convictions in the exercise of their functions, unlike users who remain free.$expl$, $choices$[{"id":"a","text":"The staff of the public service"},{"id":"b","text":"Users only"},{"id":"c","text":"Everyone without exception"},{"id":"d","text":"No one; the prefecture is a free space"}]$choices$),
(61, 'tr', $text$Bir préfecture'de (valilik) dini tarafsızlık ilkesine kim uymalıdır?$text$, $expl$Dini tarafsızlık ilkesi kamu hizmeti çalışanlarına uygulanır. Görevlerinin ifası sırasında dini inançlarını ifade etmemelidirler; hizmetten yararlananlar ise serbest kalır.$expl$, $choices$[{"id":"a","text":"Kamu hizmeti çalışanları"},{"id":"b","text":"Yalnızca hizmetten yararlananlar"},{"id":"c","text":"İstisnasız herkes"},{"id":"d","text":"Hiç kimse; valilik özgür bir yerdir"}]$choices$),
(62, 'en', $text$Does laïcité impose neutrality on public officials towards users?$text$, $expl$Yes, laïcité requires public officials to treat all users equally, without distinction of religion. Officials must not manifest their religious convictions in the context of their functions.$expl$, $choices$[{"id":"a","text":"Yes, public officials must treat all users equally"},{"id":"b","text":"No, officials are free to show their preferences"},{"id":"c","text":"Only in schools"},{"id":"d","text":"No, laïcité concerns only users"}]$choices$),
(62, 'tr', $text$Laïcité kamu çalışanlarına hizmetten yararlananlara karşı tarafsızlık dayatır mı?$text$, $expl$Evet, laïcité kamu çalışanlarının tüm kullanıcılara din ayrımı yapmaksızın eşit muamele yapmasını gerektirir. Çalışanlar görevleri kapsamında dini inançlarını ifade etmemelidir.$expl$, $choices$[{"id":"a","text":"Evet, kamu çalışanları tüm kullanıcılara eşit muamele yapmalıdır"},{"id":"b","text":"Hayır, çalışanlar tercihlerini göstermekte serbesttir"},{"id":"c","text":"Yalnızca okullarda"},{"id":"d","text":"Hayır, laïcité yalnızca hizmetten yararlananları ilgilendirir"}]$choices$),
(63, 'en', $text$What does the principle of laïcité guarantee?$text$, $expl$The principle of laïcité guarantees freedom of conscience and freedom of worship for all. It ensures the neutrality of the State and the equality of all citizens before the law, regardless of their religion.$expl$, $choices$[{"id":"a","text":"Freedom of conscience, freedom of worship and the neutrality of the State"},{"id":"b","text":"The prohibition of all religious practices"},{"id":"c","text":"The funding of religions by the State"},{"id":"d","text":"The superiority of one religion over others"}]$choices$),
(63, 'tr', $text$Laïcité ilkesi neyi güvence altına alır?$text$, $expl$Laïcité ilkesi herkes için vicdan özgürlüğünü ve ibadet özgürlüğünü güvence altına alır. Devlet'in tarafsızlığını ve tüm vatandaşların dinlerine bakılmaksızın yasa önünde eşitliğini sağlar.$expl$, $choices$[{"id":"a","text":"Vicdan özgürlüğü, ibadet özgürlüğü ve Devlet'in tarafsızlığı"},{"id":"b","text":"Tüm dini uygulamaların yasaklanması"},{"id":"c","text":"Dinlerin Devlet tarafından finanse edilmesi"},{"id":"d","text":"Bir dinin diğerlerine üstünlüğü"}]$choices$),
(64, 'en', $text$Does one have the right to change religion?$text$, $expl$Yes, freedom of conscience allows each person to change religion, adopt one, or have none. This right is guaranteed by the Constitution and the Declaration of the Rights of Man.$expl$, $choices$[{"id":"a","text":"Yes, it is a right guaranteed by freedom of conscience"},{"id":"b","text":"No, one must keep the religion of one's birth"},{"id":"c","text":"Only with the agreement of a judge"},{"id":"d","text":"Only if one becomes atheist"}]$choices$),
(64, 'tr', $text$Din değiştirme hakkı var mıdır?$text$, $expl$Evet, vicdan özgürlüğü her kişiye din değiştirme, bir din kabul etme veya hiç din taşımama olanağı tanır. Bu hak, Anayasa ve İnsan Hakları Bildirgesi tarafından güvence altına alınmıştır.$expl$, $choices$[{"id":"a","text":"Evet, vicdan özgürlüğü tarafından güvence altına alınan bir haktır"},{"id":"b","text":"Hayır, doğuştan gelen dini korumak gerekir"},{"id":"c","text":"Yalnızca bir hâkim onayıyla"},{"id":"d","text":"Yalnızca ateist olunursa"}]$choices$),
(65, 'en', $text$What does laïcité represent?$text$, $expl$Laïcité represents the separation of religions and the State, the neutrality of the State towards religions, and the guarantee of freedom of conscience for all citizens.$expl$, $choices$[{"id":"a","text":"The separation of religions and the State and freedom of conscience"},{"id":"b","text":"The prohibition of practising a religion"},{"id":"c","text":"The promotion of atheism"},{"id":"d","text":"The control of religions by the State"}]$choices$),
(65, 'tr', $text$Laïcité neyi temsil eder?$text$, $expl$Laïcité, dinler ve Devlet'in ayrılmasını, Devlet'in dinlere karşı tarafsızlığını ve tüm vatandaşlar için vicdan özgürlüğünün güvencesini temsil eder.$expl$, $choices$[{"id":"a","text":"Dinler ile Devlet'in ayrılması ve vicdan özgürlüğü"},{"id":"b","text":"Din uygulama yasağı"},{"id":"c","text":"Ateizmin teşvik edilmesi"},{"id":"d","text":"Dinlerin Devlet tarafından kontrol edilmesi"}]$choices$),
(66, 'en', $text$What is prohibited by the Charter of Laïcité at school?$text$, $expl$The Charter of Laïcité prohibits wearing signs or clothing ostensibly manifesting a religious affiliation in public schools. It aims to guarantee the neutrality of the school space.$expl$, $choices$[{"id":"a","text":"Wearing ostensible religious signs by pupils"},{"id":"b","text":"The study of the history of religions"},{"id":"c","text":"Discussions between pupils about religion"},{"id":"d","text":"The school canteen"}]$choices$),
(66, 'tr', $text$Okuldaki Laïcité Sözleşmesi tarafından ne yasaklanmıştır?$text$, $expl$Laïcité Sözleşmesi, kamu okullarında dini aidiyeti gösterişli bir şekilde ifade eden işaretlerin veya giysilerin takılmasını yasaklar. Okul alanının tarafsızlığını güvence altına almayı amaçlar.$expl$, $choices$[{"id":"a","text":"Öğrenciler tarafından gösterişli dini işaretlerin takılması"},{"id":"b","text":"Dinler tarihinin incelenmesi"},{"id":"c","text":"Öğrenciler arasında din hakkında tartışmalar"},{"id":"d","text":"Okul yemekhanesi"}]$choices$),
(68, 'en', $text$In a job interview, what can be asked of the candidate?$text$, $expl$During a job interview, questions must concern only the candidate's professional skills. It is forbidden to ask questions about religion, origin, family situation or political opinions.$expl$, $choices$[{"id":"a","text":"Questions about their skills and professional experience"},{"id":"b","text":"Their religion and religious practices"},{"id":"c","text":"Their political opinions"},{"id":"d","text":"Their plan to have children"}]$choices$),
(68, 'tr', $text$Bir iş görüşmesi sırasında, adaya neler sorulabilir?$text$, $expl$Bir iş görüşmesi sırasında sorular yalnızca adayın mesleki becerileriyle ilgili olmalıdır. Din, köken, aile durumu veya siyasi görüşler hakkında soru sormak yasaktır.$expl$, $choices$[{"id":"a","text":"Beceriler ve mesleki deneyim hakkında sorular"},{"id":"b","text":"Dini ve dini uygulamaları"},{"id":"c","text":"Siyasi görüşleri"},{"id":"d","text":"Çocuk sahibi olma planı"}]$choices$),
(69, 'en', $text$Declaring one's income to the tax authorities is:$text$, $expl$Declaring one's income is a legal obligation for every taxpayer in France. It is a civic duty that helps fund public services and ensure national solidarity.$expl$, $choices$[{"id":"a","text":"A legal obligation"},{"id":"b","text":"A personal choice"},{"id":"c","text":"Mandatory only for the wealthy"},{"id":"d","text":"Optional for foreigners"}]$choices$),
(69, 'tr', $text$Gelirini vergi dairesine beyan etmek:$text$, $expl$Gelirini beyan etmek Fransa'daki her vergi mükellefi için yasal bir zorunluluktur. Kamu hizmetlerinin finansmanını ve ulusal dayanışmayı sağlamaya yardımcı olan yurttaşlık görevidir.$expl$, $choices$[{"id":"a","text":"Yasal bir yükümlülüktür"},{"id":"b","text":"Kişisel bir tercihtir"},{"id":"c","text":"Yalnızca zenginler için zorunludur"},{"id":"d","text":"Yabancılar için isteğe bağlıdır"}]$choices$),
(70, 'en', $text$Freedom of association is:$text$, $expl$Freedom of association is a fundamental right guaranteed by the law of 1 July 1901. It allows any person to create or join an association without prior authorisation from the State.$expl$, $choices$[{"id":"a","text":"A fundamental right guaranteed by the 1901 law"},{"id":"b","text":"A right reserved for French citizens"},{"id":"c","text":"Subject to the authorisation of the préfet (prefect)"},{"id":"d","text":"Forbidden for foreigners"}]$choices$),
(70, 'tr', $text$Dernek kurma özgürlüğü:$text$, $expl$Dernek kurma özgürlüğü, 1 Temmuz 1901 yasası tarafından güvence altına alınan temel bir haktır. Herkesin Devlet'in önceden iznine gerek olmaksızın bir dernek kurmasına veya bir derneğe katılmasına olanak tanır.$expl$, $choices$[{"id":"a","text":"1901 yasasıyla güvence altına alınmış temel bir haktır"},{"id":"b","text":"Yalnızca Fransız vatandaşlarına özgü bir haktır"},{"id":"c","text":"Préfet'nin (vali) iznine tabidir"},{"id":"d","text":"Yabancılar için yasaktır"}]$choices$),
(71, 'en', $text$Freedom of expression on social media in France is:$text$, $expl$Freedom of expression on social media exists, but it is framed by law. Racist, defamatory remarks, incitement to hatred or cyberbullying are forbidden and punished.$expl$, $choices$[{"id":"a","text":"Framed by law; certain statements are forbidden"},{"id":"b","text":"Total and without any limit"},{"id":"c","text":"Forbidden in France"},{"id":"d","text":"Reserved for journalists and influencers"}]$choices$),
(71, 'tr', $text$Fransa'da sosyal medyada ifade özgürlüğü:$text$, $expl$Sosyal medyada ifade özgürlüğü vardır, ancak yasayla çerçevelenmiştir. Irkçı, iftira niteliğinde ifadeler, nefreti kışkırtma veya siber zorbalık yasaktır ve cezalandırılır.$expl$, $choices$[{"id":"a","text":"Yasayla çerçevelenmiştir; bazı ifadeler yasaktır"},{"id":"b","text":"Tam ve hiçbir sınırı yoktur"},{"id":"c","text":"Fransa'da yasaktır"},{"id":"d","text":"Yalnızca gazetecilere ve influencerlara ayrılmıştır"}]$choices$),
(72, 'en', $text$Which of these first names evokes a symbol of the Republic?$text$, $expl$Marianne is the first name that evokes a symbol of the République française. She is the allegorical figure of the Republic, representing liberty and democracy.$expl$, $choices$[{"id":"a","text":"Marianne"},{"id":"b","text":"Jeanne"},{"id":"c","text":"Marie"},{"id":"d","text":"Catherine"}]$choices$),
(72, 'tr', $text$Bu adlardan hangisi Cumhuriyet'in bir sembolünü çağrıştırır?$text$, $expl$Marianne, République française'in bir sembolünü çağrıştıran addır. Cumhuriyet'in alegorik figürüdür ve özgürlüğü ve demokrasiyi temsil eder.$expl$, $choices$[{"id":"a","text":"Marianne"},{"id":"b","text":"Jeanne"},{"id":"c","text":"Marie"},{"id":"d","text":"Catherine"}]$choices$),
(73, 'en', $text$When was the Sécurité sociale (the French social security system) established in France?$text$, $expl$The Sécurité sociale was created in 1945 by the ordinances of 4 and 19 October 1945. It is based on the principle of national solidarity and covers the risks of illness, old age, family and work accidents.$expl$, $choices$[{"id":"a","text":"In 1945"},{"id":"b","text":"In 1789"},{"id":"c","text":"In 1905"},{"id":"d","text":"In 1968"}]$choices$),
(73, 'tr', $text$Sécurité sociale (Fransız sosyal güvenlik sistemi) Fransa'da ne zaman kuruldu?$text$, $expl$Sécurité sociale, 4 ve 19 Ekim 1945 kararnameleriyle 1945'te kurulmuştur. Ulusal dayanışma ilkesine dayanır ve hastalık, yaşlılık, aile ve iş kazaları risklerini kapsar.$expl$, $choices$[{"id":"a","text":"1945'te"},{"id":"b","text":"1789'da"},{"id":"c","text":"1905'te"},{"id":"d","text":"1968'de"}]$choices$),
(74, 'en', $text$What does the national day commemorate?$text$, $expl$The national day of 14 July commemorates the storming of the Bastille on 14 July 1789 and the Fête de la Fédération of 14 July 1790. These events symbolise liberty and national unity.$expl$, $choices$[{"id":"a","text":"The storming of the Bastille (1789) and the Fête de la Fédération (1790)"},{"id":"b","text":"The end of the Second World War"},{"id":"c","text":"The election of the first President of the Republic"},{"id":"d","text":"The signing of the Treaty of Versailles"}]$choices$),
(74, 'tr', $text$Ulusal bayram neyi anar?$text$, $expl$14 Temmuz ulusal bayramı, 14 Temmuz 1789'da Bastille'in alınışını ve 14 Temmuz 1790'daki Fête de la Fédération'u anar. Bu olaylar özgürlüğü ve ulusal birliği simgeler.$expl$, $choices$[{"id":"a","text":"Bastille'in alınışı (1789) ve Fête de la Fédération (1790)"},{"id":"b","text":"İkinci Dünya Savaşı'nın sonu"},{"id":"c","text":"Cumhuriyet'in ilk Cumhurbaşkanı'nın seçimi"},{"id":"d","text":"Versailles Antlaşması'nın imzalanması"}]$choices$),
(75, 'en', $text$What does Marianne wear on her head?$text$, $expl$Marianne wears a Phrygian cap, a symbol of liberty inherited from Roman antiquity. This cap was worn by freed slaves and has become an emblem of the French Revolution.$expl$, $choices$[{"id":"a","text":"A Phrygian cap"},{"id":"b","text":"A crown"},{"id":"c","text":"A beret"},{"id":"d","text":"A feathered hat"}]$choices$),
(75, 'tr', $text$Marianne başında ne taşır?$text$, $expl$Marianne, Roma antik çağından miras kalan bir özgürlük sembolü olan Frigya başlığı takar. Bu başlık özgürlüğüne kavuşmuş köleler tarafından takılırdı ve Fransız Devrimi'nin bir amblemi olmuştur.$expl$, $choices$[{"id":"a","text":"Bir Frigya başlığı"},{"id":"b","text":"Bir taç"},{"id":"c","text":"Bir bere"},{"id":"d","text":"Tüylü bir şapka"}]$choices$),
(76, 'en', $text$Which symbol of the Republic can be seen on the jerseys of the French football team?$text$, $expl$The rooster is the symbol found on the jerseys of the French football team. This animal, associated with France since antiquity, represents pride and combativeness.$expl$, $choices$[{"id":"a","text":"The rooster"},{"id":"b","text":"Marianne"},{"id":"c","text":"The Eiffel Tower"},{"id":"d","text":"The tricolour flag"}]$choices$),
(76, 'tr', $text$Cumhuriyet'in hangi sembolü Fransa futbol takımının formalarında görülür?$text$, $expl$Horoz, Fransa futbol takımının formalarında bulunan semboldür. Antik çağdan beri Fransa ile ilişkilendirilen bu hayvan, gururu ve mücadeleciliği temsil eder.$expl$, $choices$[{"id":"a","text":"Horoz"},{"id":"b","text":"Marianne"},{"id":"c","text":"Eyfel Kulesi"},{"id":"d","text":"Üç renkli bayrak"}]$choices$),
(77, 'en', $text$What is a freedom (liberté)?$text$, $expl$A freedom is a fundamental right that allows each individual to act according to their will within the framework of the law. Freedoms are framed by law to guarantee respect for the rights of others.$expl$, $choices$[{"id":"a","text":"A right to act according to one's will within the framework set by law"},{"id":"b","text":"The right to do anything at all"},{"id":"c","text":"A privilege reserved for French citizens"},{"id":"d","text":"The total absence of rules"}]$choices$),
(77, 'tr', $text$Bir özgürlük (liberté) nedir?$text$, $expl$Bir özgürlük, her bireyin yasa çerçevesinde kendi iradesine göre hareket etmesine olanak tanıyan temel bir haktır. Özgürlükler, başkalarının haklarına saygıyı güvence altına almak için yasa ile çerçevelenmiştir.$expl$, $choices$[{"id":"a","text":"Yasanın belirlediği çerçevede iradeye göre hareket etme hakkı"},{"id":"b","text":"Her şeyi yapma hakkı"},{"id":"c","text":"Yalnızca Fransız vatandaşlarına özgü bir ayrıcalık"},{"id":"d","text":"Kuralların tamamen yokluğu"}]$choices$),
(78, 'en', $text$In France, the State may finance:$text$, $expl$The State may finance the maintenance of religious buildings built before 1905, since the law of separation transferred ownership of these buildings to the municipalities. However, the State does not finance the religions themselves.$expl$, $choices$[{"id":"a","text":"The maintenance of religious buildings built before 1905"},{"id":"b","text":"The construction of new churches"},{"id":"c","text":"The salaries of priests and imams"},{"id":"d","text":"Religious proselytising activities"}]$choices$),
(78, 'tr', $text$Fransa'da Devlet'in finanse etmesi mümkündür:$text$, $expl$Devlet 1905'ten önce inşa edilen dini binaların bakımını finanse edebilir, çünkü ayrılma yasası bu binaların mülkiyetini belediyelere devretmiştir. Bununla birlikte, Devlet dinlerin kendisini finanse etmez.$expl$, $choices$[{"id":"a","text":"1905'ten önce inşa edilen dini binaların bakımı"},{"id":"b","text":"Yeni kiliselerin inşası"},{"id":"c","text":"Rahiplerin ve imamların maaşları"},{"id":"d","text":"Dini propaganda faaliyetleri"}]$choices$),
(79, 'en', $text$What does the 1905 law say?$text$, $expl$The law of 9 December 1905 establishes the separation of the Churches and the State. It guarantees freedom of conscience and the free exercise of worship, while affirming that the Republic does not recognise, pay or subsidise any religion.$expl$, $choices$[{"id":"a","text":"It establishes the separation of the Churches and the State"},{"id":"b","text":"It prohibits all religions"},{"id":"c","text":"It establishes the right to vote for women"},{"id":"d","text":"It creates compulsory schooling"}]$choices$),
(79, 'tr', $text$1905 yasası ne der?$text$, $expl$9 Aralık 1905 yasası, Kiliseler ve Devlet'in ayrılmasını sağlar. Vicdan özgürlüğünü ve ibadetin serbestçe yapılmasını güvence altına alırken, Cumhuriyet'in hiçbir dini tanımadığını, maaş ödemediğini ve sübvanse etmediğini açıkça belirtir.$expl$, $choices$[{"id":"a","text":"Kiliseler ile Devlet'in ayrılmasını sağlar"},{"id":"b","text":"Tüm dinleri yasaklar"},{"id":"c","text":"Kadınların oy hakkını kurar"},{"id":"d","text":"Zorunlu eğitimi oluşturur"}]$choices$),
(80, 'en', $text$On which day is laïcité officially celebrated in France?$text$, $expl$The Day of Laïcité is celebrated on 9 December, the anniversary of the promulgation of the law on the separation of the Churches and the State in 1905. Events are organised, in particular in schools.$expl$, $choices$[{"id":"a","text":"9 December"},{"id":"b","text":"14 July"},{"id":"c","text":"1 January"},{"id":"d","text":"11 November"}]$choices$),
(80, 'tr', $text$Fransa'da laïcité resmi olarak hangi günde kutlanır?$text$, $expl$Laïcité Günü, 1905'te Kiliseler ve Devlet'in ayrılması yasasının ilan edildiği günün yıldönümü olan 9 Aralık'ta kutlanır. Özellikle okullarda etkinlikler düzenlenir.$expl$, $choices$[{"id":"a","text":"9 Aralık"},{"id":"b","text":"14 Temmuz"},{"id":"c","text":"1 Ocak"},{"id":"d","text":"11 Kasım"}]$choices$),
(81, 'en', $text$Which religious symbol can be worn in a public school in accordance with laïcité?$text$, $expl$Only discreet religious signs are allowed in public schools. The 2004 law forbids ostensible signs, but a small discreet pendant remains tolerated if it is not ostentatious.$expl$, $choices$[{"id":"a","text":"A discreet, non-ostensible sign"},{"id":"b","text":"A full veil"},{"id":"c","text":"A large visible cross"},{"id":"d","text":"No religious symbol is tolerated"}]$choices$),
(81, 'tr', $text$Kamu okulunda laïcité'ye saygı içinde hangi dini sembol takılabilir?$text$, $expl$Kamu okullarında yalnızca dikkat çekmeyen dini işaretlere izin verilir. 2004 yasası gösterişli işaretleri yasaklar, ancak küçük ve dikkat çekmeyen bir kolye gösterişli olmadığı sürece hoş görülür.$expl$, $choices$[{"id":"a","text":"Belirgin olmayan, dikkat çekmeyen bir işaret"},{"id":"b","text":"Tam bir peçe"},{"id":"c","text":"Belirgin büyük bir haç"},{"id":"d","text":"Hiçbir dini sembole tolerans gösterilmez"}]$choices$),
(82, 'en', $text$Which term specifically refers to hatred or prejudice against Jews?$text$, $expl$Antisemitism refers to hatred, prejudice or discrimination against Jewish people. France combats antisemitism by law, and the Republic condemns any form of racism.$expl$, $choices$[{"id":"a","text":"Antisemitism"},{"id":"b","text":"Xenophobia"},{"id":"c","text":"Islamophobia"},{"id":"d","text":"Racism"}]$choices$),
(82, 'tr', $text$Hangi terim özellikle Yahudilere yönelik nefret veya önyargıyı ifade eder?$text$, $expl$Antisemitizm, Yahudi insanlara yönelik nefret, önyargı veya ayrımcılığı ifade eder. Fransa antisemitizmle yasa yoluyla mücadele eder ve Cumhuriyet her türlü ırkçılığı kınar.$expl$, $choices$[{"id":"a","text":"Antisemitizm"},{"id":"b","text":"Yabancı düşmanlığı"},{"id":"c","text":"İslamofobi"},{"id":"d","text":"Irkçılık"}]$choices$),
(83, 'en', $text$Which text is considered the founding text of laïcité?$text$, $expl$The law of 9 December 1905 on the separation of the Churches and the State is the founding text of laïcité in France. It sets out the principles of freedom of conscience and the neutrality of the State.$expl$, $choices$[{"id":"a","text":"The 1905 law on the separation of the Churches and the State"},{"id":"b","text":"The Declaration of the Rights of Man of 1789"},{"id":"c","text":"The Constitution of 1958"},{"id":"d","text":"The Civil Code of 1804"}]$choices$),
(83, 'tr', $text$Hangi metin laïcité'nin kurucu metni olarak kabul edilir?$text$, $expl$9 Aralık 1905 tarihli Kiliseler ve Devlet'in ayrılması yasası, Fransa'da laïcité'nin kurucu metnidir. Vicdan özgürlüğü ve Devlet'in tarafsızlığı ilkelerini ortaya koyar.$expl$, $choices$[{"id":"a","text":"1905 Kiliseler ve Devlet'in ayrılması yasası"},{"id":"b","text":"1789 İnsan Hakları Bildirgesi"},{"id":"c","text":"1958 Anayasası"},{"id":"d","text":"1804 Medeni Kanun"}]$choices$),
(84, 'en', $text$Which French institution must remain neutral on religious matters?$text$, $expl$The State and all public institutions (schools, hospitals, courts, town halls) must remain neutral on religious matters. This is a fundamental principle of laïcité enshrined in the Constitution.$expl$, $choices$[{"id":"a","text":"The State and all public institutions"},{"id":"b","text":"Only schools"},{"id":"c","text":"Only the courts"},{"id":"d","text":"Private companies"}]$choices$),
(84, 'tr', $text$Hangi Fransız kurumu dini konularda tarafsız kalmalıdır?$text$, $expl$Devlet ve tüm kamu kurumları (okullar, hastaneler, mahkemeler, belediye binaları) dini konularda tarafsız kalmalıdır. Bu, Anayasa'da yer alan laïcité'nin temel bir ilkesidir.$expl$, $choices$[{"id":"a","text":"Devlet ve tüm kamu kurumları"},{"id":"b","text":"Yalnızca okullar"},{"id":"c","text":"Yalnızca mahkemeler"},{"id":"d","text":"Özel şirketler"}]$choices$),
(85, 'en', $text$At school, the Charter of Laïcité makes it possible to:$text$, $expl$The Charter of Laïcité at school, displayed in all public schools, makes it possible to recall the rules of living together and the secular framework of public education.$expl$, $choices$[{"id":"a","text":"Recall the rules of living together and the secular framework"},{"id":"b","text":"Prohibit the teaching of the history of religions"},{"id":"c","text":"Force pupils to be atheists"},{"id":"d","text":"Prevent parents from entering the school"}]$choices$),
(85, 'tr', $text$Okulda Laïcité Sözleşmesi şunu mümkün kılar:$text$, $expl$Tüm kamu okullarında asılı olan okuldaki Laïcité Sözleşmesi, birlikte yaşama kurallarını ve kamu öğretiminin laik çerçevesini hatırlatmayı sağlar.$expl$, $choices$[{"id":"a","text":"Birlikte yaşama kurallarını ve laik çerçeveyi hatırlatmak"},{"id":"b","text":"Dinler tarihinin öğretimini yasaklamak"},{"id":"c","text":"Öğrencileri ateist olmaya zorlamak"},{"id":"d","text":"Velilerin okula girmesini engellemek"}]$choices$),
(86, 'en', $text$Who must respect and ensure religious neutrality in public services?$text$, $expl$Public service officials must respect and ensure religious neutrality. They cannot manifest their religious beliefs in the exercise of their functions.$expl$, $choices$[{"id":"a","text":"Public service officials"},{"id":"b","text":"Users only"},{"id":"c","text":"Elected officials only"},{"id":"d","text":"Religious associations"}]$choices$),
(86, 'tr', $text$Kamu hizmetlerinde dini tarafsızlığa kim saygı göstermeli ve onu kim sağlamalıdır?$text$, $expl$Kamu hizmeti çalışanları dini tarafsızlığa saygı göstermeli ve onu sağlamalıdır. Görevlerinin ifası sırasında dini inançlarını ifade edemezler.$expl$, $choices$[{"id":"a","text":"Kamu hizmeti çalışanları"},{"id":"b","text":"Yalnızca hizmetten yararlananlar"},{"id":"c","text":"Yalnızca seçilmişler"},{"id":"d","text":"Dini dernekler"}]$choices$),
(87, 'en', $text$A person declares they do not believe in any god. One can say:$text$, $expl$A person who does not believe in any god is atheist. In France, freedom of conscience guarantees the right not to believe, to believe or to change one's beliefs. Atheism is fully respected by law.$expl$, $choices$[{"id":"a","text":"That they are atheist, which is a right guaranteed by freedom of conscience"},{"id":"b","text":"That they are breaking the law"},{"id":"c","text":"That they must leave France"},{"id":"d","text":"That they must choose a religion"}]$choices$),
(87, 'tr', $text$Bir kişi hiçbir tanrıya inanmadığını beyan ediyor. Şöyle denebilir:$text$, $expl$Hiçbir tanrıya inanmayan bir kişi ateisttir. Fransa'da vicdan özgürlüğü inanmama, inanma veya inancını değiştirme hakkını güvence altına alır. Ateizm yasalarca tamamen saygıyla karşılanır.$expl$, $choices$[{"id":"a","text":"Ateist olduğu söylenebilir; bu vicdan özgürlüğü tarafından güvence altına alınan bir haktır"},{"id":"b","text":"Yasayı çiğnediği söylenebilir"},{"id":"c","text":"Fransa'yı terk etmesi gerektiği söylenebilir"},{"id":"d","text":"Bir din seçmesi gerektiği söylenebilir"}]$choices$),
(492, 'en', $text$You are a pupil's parent. Your 14-year-old daughter wishes to wear an Islamic veil at her public middle school. The principal informs you that this is forbidden. What is the right attitude?$text$, $expl$The law of 15 March 2004 prohibits the wearing of ostensible religious signs in public schools, middle schools and high schools. This law applies to all pupils and to all religions.$expl$, $choices$[{"id":"a","text":"You accept the rule because the law forbids ostensible religious signs in public schools"},{"id":"b","text":"You file a complaint against the principal for religious discrimination"},{"id":"c","text":"You enrol your daughter in another public middle school where it will be allowed"},{"id":"d","text":"You request a waiver from the rectorat (education authority) on religious grounds"}]$choices$),
(492, 'tr', $text$Bir öğrencinin velisisiniz. 14 yaşındaki kızınız kamu ortaokulunda İslami başörtü takmak istiyor. Müdür bunun yasak olduğunu bildiriyor. Doğru tutum nedir?$text$, $expl$15 Mart 2004 yasası, kamu okullarında, ortaokullarda ve liselerde gösterişli dini işaretler takılmasını yasaklar. Bu yasa tüm öğrencilere ve tüm dinlere uygulanır.$expl$, $choices$[{"id":"a","text":"Kuralı kabul edersiniz çünkü yasa kamu okullarında gösterişli dini işaretleri yasaklar"},{"id":"b","text":"Müdüre karşı dini ayrımcılıktan şikayette bulunursunuz"},{"id":"c","text":"Kızınızı bunun izinli olacağı başka bir kamu ortaokuluna kaydedersiniz"},{"id":"d","text":"Dini gerekçeyle rectorat'tan (eğitim makamı) bir muafiyet talep edersiniz"}]$choices$),
(493, 'en', $text$At work, you are a reception officer in a town hall. A colleague asks you to cover for him for 15 minutes so that he can perform his prayer in an empty office. What do you do?$text$, $expl$Public service officials are bound by an obligation of religious neutrality. Religious practice cannot be exercised during working hours. Your colleague must wait for his personal break.$expl$, $choices$[{"id":"a","text":"You accept out of solidarity between colleagues; it is normal"},{"id":"b","text":"You refuse because it disrupts the service, but you remind him that he can pray during his break"},{"id":"c","text":"You accept on condition that he is quick about it"},{"id":"d","text":"You immediately report your colleague to the police"}]$choices$),
(493, 'tr', $text$İşte, bir belediye binasında karşılama görevlisisiniz. Bir meslektaşınız boş bir ofiste namazını kılabilmesi için 15 dakika yerine bakmanızı istiyor. Ne yaparsınız?$text$, $expl$Kamu hizmeti çalışanları dini tarafsızlık yükümlülüğüne tabidir. Dini uygulama mesai saatleri içinde yerine getirilemez. Meslektaşınız kişisel molasını beklemelidir.$expl$, $choices$[{"id":"a","text":"Meslektaşlar arası dayanışma adına kabul edersiniz; bu normaldir"},{"id":"b","text":"Hizmeti aksattığı için reddedersiniz, ancak molasında dua edebileceğini hatırlatırsınız"},{"id":"c","text":"Hızlı olması şartıyla kabul edersiniz"},{"id":"d","text":"Meslektaşınızı derhal polise bildirirsiniz"}]$choices$),
(494, 'en', $text$You accompany your mother to the emergency room of a public hospital. She refuses to be examined by a male doctor for religious reasons. What should you understand?$text$, $expl$In a public hospital service, the patient cannot demand a doctor of a particular sex on religious grounds. The hospital is organised according to its resources, and medical urgency takes precedence over personal convictions.$expl$, $choices$[{"id":"a","text":"The hospital must necessarily provide a female doctor if the patient requests it"},{"id":"b","text":"Your mother has an absolute right to refuse all care"},{"id":"c","text":"The hospital is not obliged to comply with this request; medical care takes precedence over personal convictions"},{"id":"d","text":"You can file a complaint against the hospital for failing to respect religious freedom"}]$choices$),
(494, 'tr', $text$Annenizi bir kamu hastanesinin acil servisine götürüyorsunuz. Dini nedenlerle erkek bir doktor tarafından muayene edilmeyi reddediyor. Ne anlamalısınız?$text$, $expl$Kamu hastane hizmetinde hasta, dini gerekçelerle belirli bir cinsiyetten doktor talep edemez. Hastane olanaklarına göre düzenlenir ve tıbbi aciliyet kişisel inançlardan önce gelir.$expl$, $choices$[{"id":"a","text":"Hasta talep ederse hastane zorunlu olarak bir kadın doktor sağlamalıdır"},{"id":"b","text":"Anneniz tüm bakımı reddetme konusunda mutlak bir hakka sahiptir"},{"id":"c","text":"Hastane bu talebi karşılamak zorunda değildir; tıbbi bakım kişisel inançlardan önce gelir"},{"id":"d","text":"Hastaneye karşı dini özgürlüğe saygı göstermediği için şikayette bulunabilirsiniz"}]$choices$),
(495, 'en', $text$At your child's public school canteen, you ask that a halal menu be systematically offered. The principal refuses. Does he have the right?$text$, $expl$A public school canteen has no legal obligation to offer confessional menus. The principle of laïcité means that the public service does not adapt to religious requirements, even though some municipalities offer substitute menus by choice.$expl$, $choices$[{"id":"a","text":"No, it is discrimination against your religion"},{"id":"b","text":"No, the school must respect all religions by offering all menus"},{"id":"c","text":"Yes, but only if the school already offers a vegetarian menu"},{"id":"d","text":"Yes, the public canteen has no obligation to offer confessional menus"}]$choices$),
(495, 'tr', $text$Çocuğunuzun kamu okul yemekhanesinde, sistematik olarak helal bir menü sunulmasını talep ediyorsunuz. Müdür reddediyor. Bu hakka sahip mi?$text$, $expl$Kamu okul yemekhanesinin dini menüler sunma konusunda yasal bir yükümlülüğü yoktur. Laïcité ilkesi, kamu hizmetinin dini gereksinimlere uyum sağlamaması anlamına gelir; bazı belediyeler kendi tercihleriyle alternatif menüler sunsa bile.$expl$, $choices$[{"id":"a","text":"Hayır, bu sizin dininize karşı bir ayrımcılıktır"},{"id":"b","text":"Hayır, okul tüm menüleri sunarak tüm dinlere saygı göstermelidir"},{"id":"c","text":"Evet, ancak yalnızca okul zaten vejetaryen bir menü sunuyorsa"},{"id":"d","text":"Evet, kamu yemekhanesinin dini menüler sunma yükümlülüğü yoktur"}]$choices$),
(496, 'en', $text$You are a municipal employee. The mayor wishes to install a Nativity scene (crèche de Noël) in the hall of the town hall. A resident protests. What does the law say?$text$, $expl$According to the case law of the Conseil d'État (Council of State, 2016), a Nativity scene may be installed in a public building provided that it has a cultural, artistic or festive character, and is not an act of religious proselytising. The local context is decisive.$expl$, $choices$[{"id":"a","text":"It is always forbidden because it violates laïcité"},{"id":"b","text":"It is always authorised because Christmas is part of French culture"},{"id":"c","text":"It is possible if the Nativity scene has a cultural or festive character and does not constitute an act of proselytising"},{"id":"d","text":"It is authorised only if all religions are equally represented"}]$choices$),
(496, 'tr', $text$Bir belediye çalışanısınız. Belediye başkanı belediye binasının lobisine bir Noel doğuşu sahnesi (crèche de Noël) kurmak istiyor. Bir vatandaş itiraz ediyor. Yasa ne der?$text$, $expl$Conseil d'État'nın (Danıştay, 2016) içtihadına göre, bir doğuş sahnesi kamu binasına kültürel, sanatsal veya bayram niteliği taşıması ve dini propaganda eylemi olmaması koşuluyla kurulabilir. Yerel bağlam belirleyicidir.$expl$, $choices$[{"id":"a","text":"Laïcité'yi ihlal ettiği için her zaman yasaktır"},{"id":"b","text":"Noel Fransız kültürünün bir parçası olduğundan her zaman izinlidir"},{"id":"c","text":"Doğuş sahnesinin kültürel veya bayram niteliği varsa ve propaganda eylemi oluşturmuyorsa mümkündür"},{"id":"d","text":"Yalnızca tüm dinler eşit şekilde temsil ediliyorsa izinlidir"}]$choices$),
(497, 'en', $text$You are a pupil's mother and you wear the veil. You wish to accompany your son's class on a school outing. Can the school refuse you?$text$, $expl$Parents accompanying school outings are not public service officials. The Conseil d'État has specified that wearing a veil by an accompanying parent is not in itself a ground for refusal, unless it disrupts public order or the smooth running of the activity.$expl$, $choices$[{"id":"a","text":"Yes, the 2004 law forbids any religious sign in the school context, including for parents"},{"id":"b","text":"No, because as an accompanying parent you are not subject to the public officials' duty of neutrality"},{"id":"c","text":"Yes, because you represent the school during the outing"},{"id":"d","text":"No, because religious freedom is absolute and without any limit in France"}]$choices$),
(497, 'tr', $text$Bir öğrencinin annesisiniz ve başörtü takıyorsunuz. Oğlunuzun sınıfına bir okul gezisinde eşlik etmek istiyorsunuz. Okul sizi reddedebilir mi?$text$, $expl$Okul gezilerine eşlik eden veliler kamu hizmeti çalışanı değildir. Conseil d'État, refakatçinin başörtü takmasının başlı başına bir reddetme gerekçesi olmadığını, ancak kamu düzenini veya etkinliğin sorunsuz yürütülmesini bozmadığı sürece geçerli olduğunu belirtmiştir.$expl$, $choices$[{"id":"a","text":"Evet, 2004 yasası velilere dahil olmak üzere okul ortamında her türlü dini işareti yasaklar"},{"id":"b","text":"Hayır, çünkü refakatçi veli olarak kamu çalışanlarının tarafsızlık yükümlülüğüne tabi değilsiniz"},{"id":"c","text":"Evet, çünkü gezi sırasında okulu temsil edersiniz"},{"id":"d","text":"Hayır, çünkü Fransa'da dini özgürlük mutlaktır ve hiçbir sınırı yoktur"}]$choices$),
(498, 'en', $text$You have just been recruited as a civil servant in a tax office. You usually wear a large cross around your neck. Your superior asks you to remove it during your shift. Is he right?$text$, $expl$Public service officials are bound by strict religious neutrality. They must not wear any ostensible religious sign during the exercise of their functions, regardless of their religion.$expl$, $choices$[{"id":"a","text":"No, it is an infringement of your religious freedom"},{"id":"b","text":"Yes, but only if users complain"},{"id":"c","text":"No, because the cross is a cultural symbol and not a religious one"},{"id":"d","text":"Yes, public officials must respect the principle of religious neutrality"}]$choices$),
(498, 'tr', $text$Bir vergi dairesinde memur olarak işe alındınız. Genellikle boynunuzda büyük bir haç takarsınız. Amiriniz çalışma sırasında onu çıkarmanızı istiyor. Haklı mı?$text$, $expl$Kamu hizmeti çalışanları sıkı bir dini tarafsızlığa tabidir. Görevlerinin ifası sırasında dinleri ne olursa olsun hiçbir gösterişli dini işaret takmamalıdırlar.$expl$, $choices$[{"id":"a","text":"Hayır, bu dini özgürlüğünüze bir saldırıdır"},{"id":"b","text":"Evet, ancak yalnızca kullanıcılar şikayet ederse"},{"id":"c","text":"Hayır, çünkü haç dini değil kültürel bir semboldür"},{"id":"d","text":"Evet, kamu çalışanları dini tarafsızlık ilkesine uymak zorundadır"}]$choices$),
(499, 'en', $text$You work in a private company. You wish to take a day off for a religious holiday that is not an official public holiday. Your employer refuses. Is this legal?$text$, $expl$In the private sector, the employer may authorise an absence on religious grounds, but is not obliged to, unless the collective agreement provides for it. The refusal is not discriminatory if it is based on the needs of the service.$expl$, $choices$[{"id":"a","text":"No, it is religious discrimination forbidden by law"},{"id":"b","text":"Yes, the employer may refuse if it is justified by the needs of the service"},{"id":"c","text":"No, the employer must necessarily accept all religious holidays"},{"id":"d","text":"Yes, but only if the company is a public institution"}]$choices$),
(499, 'tr', $text$Özel bir şirkette çalışıyorsunuz. Resmi tatil olmayan bir dini bayram için bir gün izin almak istiyorsunuz. İşvereniniz reddediyor. Bu yasal mı?$text$, $expl$Özel sektörde, toplu sözleşmede öngörülmedikçe işveren dini gerekçelerle bir devamsızlığa izin verebilir ancak zorunlu değildir. Hizmetin ihtiyaçlarına dayanıyorsa ret ayrımcı değildir.$expl$, $choices$[{"id":"a","text":"Hayır, yasanın yasakladığı bir dini ayrımcılıktır"},{"id":"b","text":"Evet, işveren hizmetin gerekleriyle haklı çıkarsa reddedebilir"},{"id":"c","text":"Hayır, işveren zorunlu olarak tüm dini bayramları kabul etmelidir"},{"id":"d","text":"Evet, ancak yalnızca şirket bir kamu kurumuysa"}]$choices$),
(500, 'en', $text$Several employees of your company ask management to set aside a prayer room on the premises. Management refuses. The employees consider this discriminatory. Who is right?$text$, $expl$A private employer has no obligation to set aside a place of worship within the company. They may do so if they wish, but their refusal does not constitute discrimination. The employee's religious freedom is exercised outside working hours.$expl$, $choices$[{"id":"a","text":"The employees, because the employer must respect religious freedom"},{"id":"b","text":"Management, because nothing obliges an employer to provide a place of worship"},{"id":"c","text":"The employees, if there are enough of them requesting it"},{"id":"d","text":"Management, but it must offer an alternative outside the premises"}]$choices$),
(500, 'tr', $text$Şirketinizin birkaç çalışanı yönetimden tesislerde bir ibadet odası ayrılmasını talep ediyor. Yönetim reddediyor. Çalışanlar bunun ayrımcı olduğunu düşünüyor. Kim haklı?$text$, $expl$Özel bir işveren şirket içinde bir ibadet yeri ayırma yükümlülüğüne sahip değildir. İsterse yapabilir, ancak reddi ayrımcılık oluşturmaz. Çalışanın dini özgürlüğü çalışma saatleri dışında uygulanır.$expl$, $choices$[{"id":"a","text":"Çalışanlar, çünkü işveren dini özgürlüğe saygı göstermelidir"},{"id":"b","text":"Yönetim, çünkü hiçbir şey işvereni bir ibadet yeri sağlamaya zorlamaz"},{"id":"c","text":"Çalışanlar, eğer bunu talep edenler yeterince çoksa"},{"id":"d","text":"Yönetim, ancak dışarıda bir alternatif önermelidir"}]$choices$),
(501, 'en', $text$Your child comes home from school and tells you that the teacher explained the history of the major religions in class. You consider this a violation of laïcité. Are you right?$text$, $expl$Laïcité does not prohibit teaching about the religious phenomenon at school. Teaching the history of religions as a matter of knowledge and culture is perfectly compatible with the principle of laïcité. What is forbidden is proselytising.$expl$, $choices$[{"id":"a","text":"Yes, the public school must never speak of religion"},{"id":"b","text":"Yes, unless the teacher speaks of all religions equally"},{"id":"c","text":"No, teaching the history of religions is an approach to knowledge, not proselytising"},{"id":"d","text":"Yes, only parents can discuss religions with their children"}]$choices$),
(501, 'tr', $text$Çocuğunuz okuldan döndüğünde size öğretmeninin sınıfta büyük dinlerin tarihini anlattığını söylüyor. Bunun laïcité'yi ihlal ettiğini düşünüyorsunuz. Haklı mısınız?$text$, $expl$Laïcité, okulda dini olgunun öğretilmesini yasaklamaz. Bilgi ve kültür yaklaşımı içinde dinler tarihini öğretmek laïcité ilkesiyle tamamen uyumludur. Yasak olan, propagandadır.$expl$, $choices$[{"id":"a","text":"Evet, kamu okulu asla dinden söz etmemelidir"},{"id":"b","text":"Evet, öğretmen tüm dinlerden eşit şekilde söz etmedikçe"},{"id":"c","text":"Hayır, dinler tarihini öğretmek bir bilgi yaklaşımıdır, propaganda değildir"},{"id":"d","text":"Evet, dinlerden yalnızca veliler çocuklarıyla söz edebilir"}]$choices$),
(502, 'en', $text$You apply for a job as a waiter. During the interview, the recruiter tells you: "We do not hire people of foreign origin in our establishment." What can you do?$text$, $expl$This is discrimination in hiring based on origin, forbidden by the Code du travail (Labour Code) and the Code pénal (Penal Code). You can petition the Défenseur des droits (the Defender of Rights) or file a complaint.$expl$, $choices$[{"id":"a","text":"Nothing; it is the employer's right to choose his employees freely"},{"id":"b","text":"You can petition the Défenseur des droits or file a complaint because it is a forbidden discrimination"},{"id":"c","text":"You can only write a negative review on the Internet"},{"id":"d","text":"You must first obtain French nationality to be able to act"}]$choices$),
(502, 'tr', $text$Garson olarak bir işe başvuruyorsunuz. Görüşme sırasında işe alım görevlisi size şöyle diyor: «İşletmemizde yabancı kökenli insanları işe almıyoruz.» Ne yapabilirsiniz?$text$, $expl$Bu, kökene dayalı işe alımda bir ayrımcılıktır ve Code du travail (İş Kanunu) ile Code pénal (Ceza Kanunu) tarafından yasaklanmıştır. Défenseur des droits'a (Haklar Savunucusu) başvurabilir veya şikayette bulunabilirsiniz.$expl$, $choices$[{"id":"a","text":"Hiçbir şey, çalışanlarını özgürce seçmek işverenin hakkıdır"},{"id":"b","text":"Yasak bir ayrımcılık olduğu için Défenseur des droits'a başvurabilir veya şikayette bulunabilirsiniz"},{"id":"c","text":"Yalnızca İnternette olumsuz bir yorum yazabilirsiniz"},{"id":"d","text":"Harekete geçebilmek için önce Fransız vatandaşlığı almalısınız"}]$choices$),
(503, 'en', $text$You are looking for an apartment. A landlord refuses to rent his property to you upon learning that you are a single mother with three children. Is this legal?$text$, $expl$Refusing a rental on grounds of family situation constitutes discrimination forbidden by law. Family situation is among the criteria of discrimination prohibited by the Code pénal (article 225-1).$expl$, $choices$[{"id":"a","text":"Yes, the landlord is free to choose his tenant according to his criteria"},{"id":"b","text":"Yes, because he has the right to protect his property"},{"id":"c","text":"No, it is discrimination based on family situation, forbidden by law"},{"id":"d","text":"No, but only if you have French nationality"}]$choices$),
(503, 'tr', $text$Bir daire arıyorsunuz. Bir ev sahibi, üç çocuklu bekar bir anne olduğunuzu öğrendikten sonra mülkünü size kiralamayı reddediyor. Bu yasal mı?$text$, $expl$Aile durumu nedeniyle bir kiralamayı reddetmek yasanın yasakladığı bir ayrımcılık oluşturur. Aile durumu, Code pénal'in (Ceza Kanunu) 225-1. maddesi tarafından yasaklanan ayrımcılık kriterleri arasında yer alır.$expl$, $choices$[{"id":"a","text":"Evet, ev sahibi kiracısını kendi kriterlerine göre seçmekte serbesttir"},{"id":"b","text":"Evet, çünkü mülkünü koruma hakkı vardır"},{"id":"c","text":"Hayır, aile durumuna dayalı bir ayrımcılıktır, yasayla yasaklanmıştır"},{"id":"d","text":"Hayır, ancak yalnızca Fransız vatandaşıysanız"}]$choices$),
(504, 'en', $text$Your elderly neighbour is isolated and has difficulty doing her shopping, especially in winter. Which attitude best illustrates the republican value of fraternity?$text$, $expl$Fraternity, enshrined in the motto of the Republic, implies solidarity between citizens. Offering help to a vulnerable person is a concrete act of fraternity.$expl$, $choices$[{"id":"a","text":"You do nothing because it is not your responsibility"},{"id":"b","text":"You offer to accompany her or to do her shopping from time to time"},{"id":"c","text":"You call the social services so that they take care of it in your place"},{"id":"d","text":"You advise her to move to a retirement home"}]$choices$),
(504, 'tr', $text$Yaşlı komşunuz yalnız ve özellikle kışın alışveriş yapmakta güçlük çekiyor. Hangi tutum cumhuriyetçi kardeşlik değerini en iyi şekilde örnekler?$text$, $expl$Cumhuriyet sloganında yer alan kardeşlik, vatandaşlar arasındaki dayanışmayı ifade eder. Savunmasız bir kişiye yardım önermek somut bir kardeşlik eylemidir.$expl$, $choices$[{"id":"a","text":"Sorumluluğunuz olmadığı için hiçbir şey yapmazsınız"},{"id":"b","text":"Ona eşlik etmeyi veya zaman zaman alışverişini yapmayı önerirsiniz"},{"id":"c","text":"Sizin yerinize ilgilenmeleri için sosyal hizmetleri ararsınız"},{"id":"d","text":"Ona huzurevine taşınmasını tavsiye edersiniz"}]$choices$),
(505, 'en', $text$At work, you discover that a female colleague holding the same position as you, with the same seniority and the same qualifications, earns 15% less than you. What does the law say?$text$, $expl$The principle of "equal pay for equal work" is enshrined in the Code du travail (Labour Code). The pay gap between women and men for the same position and equivalent qualifications is illegal.$expl$, $choices$[{"id":"a","text":"It is normal; the employer is free to set salaries as he wishes"},{"id":"b","text":"It is illegal only if the gap exceeds 20%"},{"id":"c","text":"The law requires equal pay for equal work; this gap is illegal"},{"id":"d","text":"It is legal if the employer can prove that the man is more productive"}]$choices$),
(505, 'tr', $text$İşte, sizinle aynı pozisyonda, aynı kıdem ve aynı niteliklere sahip bir kadın meslektaşınızın sizden %15 daha az kazandığını keşfediyorsunuz. Yasa ne der?$text$, $expl$«Eşit işe eşit ücret» ilkesi Code du travail'da (İş Kanunu) yer alır. Aynı pozisyon ve eşdeğer nitelikler için kadınlar ve erkekler arasındaki ücret farkı yasa dışıdır.$expl$, $choices$[{"id":"a","text":"Bu normaldir, işveren maaşları istediği gibi belirlemekte serbesttir"},{"id":"b","text":"Yalnızca fark %20'yi aşarsa yasa dışıdır"},{"id":"c","text":"Yasa eşit işe eşit ücreti zorunlu kılar, bu fark yasa dışıdır"},{"id":"d","text":"İşveren erkeğin daha üretken olduğunu kanıtlayabilirse yasaldır"}]$choices$),
(506, 'en', $text$Your friend, a foreigner with regular status in France, is refused enrolment for his child at a public school by the principal, who says that "one must be French". What should you know?$text$, $expl$Education is compulsory for all children residing in France, regardless of their nationality or that of their parents. The refusal to enrol is illegal.$expl$, $choices$[{"id":"a","text":"The principal is right; the public school is reserved for French children"},{"id":"b","text":"The principal is wrong; every child residing in France is entitled to education, regardless of nationality"},{"id":"c","text":"The principal is right, but the child can go to a private school"},{"id":"d","text":"The child must first obtain a personal residence permit"}]$choices$),
(506, 'tr', $text$Fransa'da yasal statüye sahip yabancı bir arkadaşınızın çocuğu, müdür tarafından «Fransız olmak gerekir» denilerek kamu okuluna kaydedilmesi reddediliyor. Ne bilmeniz gerekiyor?$text$, $expl$Eğitim, kendisinin veya ebeveynlerinin uyruğu ne olursa olsun Fransa'da ikamet eden tüm çocuklar için zorunludur. Kayıt reddi yasa dışıdır.$expl$, $choices$[{"id":"a","text":"Müdür haklı, kamu okulu Fransız çocuklara ayrılmıştır"},{"id":"b","text":"Müdür haksız, Fransa'da ikamet eden her çocuğun uyruğu ne olursa olsun eğitim hakkı vardır"},{"id":"c","text":"Müdür haklı, ancak çocuk özel bir okula gidebilir"},{"id":"d","text":"Çocuğun önce kişisel bir ikamet izni alması gerekir"}]$choices$),
(507, 'en', $text$You are in a wheelchair. A restaurant refuses to admit you on the grounds that it has no access ramp and that "it would be complicated". What does the law say?$text$, $expl$The law of 11 February 2005 requires accessibility of establishments open to the public. Refusing access to a disabled person constitutes discrimination punishable by law.$expl$, $choices$[{"id":"a","text":"The restaurant owner is within his rights; he has no obligation to adapt"},{"id":"b","text":"The restaurant owner commits discrimination; the law requires accessibility of places open to the public"},{"id":"c","text":"The restaurant owner is within his rights if the building is old"},{"id":"d","text":"You cannot do anything because there is no law on accessibility"}]$choices$),
(507, 'tr', $text$Tekerlekli sandalye kullanıyorsunuz. Bir restoran erişim rampası olmadığı ve «bunun karmaşık olacağı» gerekçesiyle sizi kabul etmeyi reddediyor. Yasa ne der?$text$, $expl$11 Şubat 2005 yasası halka açık kuruluşların erişilebilirliğini zorunlu kılar. Engelli bir kişinin erişimini reddetmek, yasalarca cezalandırılan bir ayrımcılık oluşturur.$expl$, $choices$[{"id":"a","text":"Restoran sahibi haklarını kullanıyor; uyum sağlama zorunluluğu yoktur"},{"id":"b","text":"Restoran sahibi bir ayrımcılık yapıyor; yasa halka açık yerlerin erişilebilirliğini zorunlu kılar"},{"id":"c","text":"Bina eski ise restoran sahibi haklarını kullanıyor"},{"id":"d","text":"Hiçbir şey yapamazsınız çünkü erişilebilirlik hakkında bir yasa yoktur"}]$choices$),
(508, 'en', $text$Your colleague is dismissed after his employer learned of his homosexuality. Can your colleague contest this dismissal?$text$, $expl$Dismissal based on sexual orientation is discrimination forbidden by the Code du travail (Labour Code) and the Code pénal (Penal Code). This dismissal is void, and the employee can refer the matter to the prud'hommes (labour tribunal).$expl$, $choices$[{"id":"a","text":"No, the employer may dismiss for the reason of his choice"},{"id":"b","text":"Yes, but only if he has more than two years of seniority"},{"id":"c","text":"No, sexual orientation is not a criterion protected by law"},{"id":"d","text":"Yes, it is a discriminatory dismissal forbidden by law; he can refer the matter to the prud'hommes (labour tribunal)"}]$choices$),
(508, 'tr', $text$Meslektaşınız, işvereninin onun eşcinselliğini öğrenmesinden sonra işten çıkarılıyor. Meslektaşınız bu işten çıkarmaya itiraz edebilir mi?$text$, $expl$Cinsel yönelime dayalı işten çıkarma, Code du travail (İş Kanunu) ve Code pénal (Ceza Kanunu) tarafından yasaklanmış bir ayrımcılıktır. Bu işten çıkarma geçersizdir ve çalışan prud'hommes'a (iş mahkemesi) başvurabilir.$expl$, $choices$[{"id":"a","text":"Hayır, işveren istediği gerekçeyle işten çıkarabilir"},{"id":"b","text":"Evet, ancak yalnızca iki yıldan fazla kıdemi varsa"},{"id":"c","text":"Hayır, cinsel yönelim yasa tarafından korunan bir kriter değildir"},{"id":"d","text":"Evet, bu yasanın yasakladığı ayrımcı bir işten çıkarmadır; prud'hommes'a (iş mahkemesi) başvurabilir"}]$choices$),
(509, 'en', $text$In the street, you see a person having a fit. Passers-by ignore them. What is your legal obligation?$text$, $expl$In France, failing to assist a person in danger (non-assistance à personne en danger) is an offence punishable by the Code pénal (article 223-6). Every citizen has the obligation to provide assistance or at the very least to call the emergency services.$expl$, $choices$[{"id":"a","text":"You have no obligation; it is a personal choice"},{"id":"b","text":"You must intervene only if you are a doctor"},{"id":"c","text":"You have the obligation to provide assistance or to call the emergency services (15 or 112)"},{"id":"d","text":"You must wait for someone else to intervene first"}]$choices$),
(509, 'tr', $text$Sokakta, fenalık geçiren bir kişi görüyorsunuz. Yoldan geçenler onu görmezden geliyor. Yasal yükümlülüğünüz nedir?$text$, $expl$Fransa'da, tehlikedeki bir kişiye yardım etmemek (non-assistance à personne en danger), Code pénal (Ceza Kanunu) madde 223-6 tarafından cezalandırılan bir suçtur. Her vatandaşın yardım etme veya en azından acil servisleri arama yükümlülüğü vardır.$expl$, $choices$[{"id":"a","text":"Hiçbir yükümlülüğünüz yoktur; bu kişisel bir tercihtir"},{"id":"b","text":"Yalnızca doktorsanız müdahale etmelisiniz"},{"id":"c","text":"Yardım etme veya acil servisleri (15 veya 112) arama yükümlülüğünüz vardır"},{"id":"d","text":"Önce başka birinin müdahale etmesini beklemelisiniz"}]$choices$),
(510, 'en', $text$Your 19-year-old son wishes to commit to a public-interest mission to help others. He is hesitating between several schemes. Which scheme best corresponds to the republican value of fraternity?$text$, $expl$The Service Civique allows young people aged 16 to 25 to commit to public-interest missions (solidarity, education, environment). It is a concrete form of citizen engagement linked to fraternity.$expl$, $choices$[{"id":"a","text":"The Service Civique (civic service), which allows undertaking public-interest missions"},{"id":"b","text":"A job in a private company, because working is a form of solidarity"},{"id":"c","text":"A trip abroad to discover other cultures"},{"id":"d","text":"Joining a political party"}]$choices$),
(510, 'tr', $text$19 yaşındaki oğlunuz başkalarına yardım etmek için bir kamu yararı görevine kendini adamak istiyor. Birkaç program arasında karar veremiyor. Hangi program cumhuriyetçi kardeşlik değerine en iyi karşılık gelir?$text$, $expl$Service Civique, 16 ila 25 yaş arasındaki gençlerin kamu yararı görevlerine (dayanışma, eğitim, çevre) kendilerini adamasına olanak tanır. Kardeşlikle bağlantılı somut bir yurttaşlık angajmanı biçimidir.$expl$, $choices$[{"id":"a","text":"Kamu yararı görevleri yapmaya olanak tanıyan Service Civique (sivil hizmet)"},{"id":"b","text":"Özel bir şirkette bir iş, çünkü çalışmak bir dayanışma biçimidir"},{"id":"c","text":"Diğer kültürleri keşfetmek için yurt dışında bir yolculuk"},{"id":"d","text":"Bir siyasi partiye katılım"}]$choices$),
(511, 'en', $text$You are summoned to court but you cannot afford to pay for a lawyer. What does the Republic provide to guarantee equality before justice?$text$, $expl$Legal aid (aide juridictionnelle) allows people with low incomes to benefit from full or partial coverage of legal costs, including lawyer's fees. It is a concrete application of the principle of equality.$expl$, $choices$[{"id":"a","text":"Nothing; you must pay a lawyer or defend yourself alone"},{"id":"b","text":"Legal aid (aide juridictionnelle) allows people with low incomes to have a free lawyer"},{"id":"c","text":"You can ask the judge to dismiss the case"},{"id":"d","text":"Only French citizens can benefit from a free lawyer"}]$choices$),
(511, 'tr', $text$Mahkemeye çağrılıyorsunuz ancak bir avukat ödemeye gücünüz yetmiyor. Cumhuriyet adalet önünde eşitliği güvence altına almak için ne öngörür?$text$, $expl$Adli yardım (aide juridictionnelle), düşük gelirli kişilerin avukat ücretleri dahil yargılama masraflarının tamamen veya kısmen karşılanmasından yararlanmasını sağlar. Eşitlik ilkesinin somut bir uygulamasıdır.$expl$, $choices$[{"id":"a","text":"Hiçbir şey, bir avukat ödemeniz veya kendinizi savunmanız gerekir"},{"id":"b","text":"Adli yardım (aide juridictionnelle), düşük gelirli kişilerin ücretsiz bir avukata sahip olmasını sağlar"},{"id":"c","text":"Hâkimden davayı düşürmesini isteyebilirsiniz"},{"id":"d","text":"Yalnızca Fransız vatandaşları ücretsiz bir avukattan yararlanabilir"}]$choices$),
(512, 'en', $text$On social media, a user posts an insulting and threatening message against a religious community. He defends himself by invoking freedom of expression. Is he right?$text$, $expl$Freedom of expression has limits in France. Incitement to hatred, threats and racial or religious insults are offences punishable by law (law of 29 July 1881 and the Code pénal).$expl$, $choices$[{"id":"a","text":"Yes, freedom of expression is absolute in France"},{"id":"b","text":"Yes, because on the Internet one can say whatever one wants"},{"id":"c","text":"No, freedom of expression does not protect incitement to hatred or threats"},{"id":"d","text":"No, but only if the victim files a complaint"}]$choices$),
(512, 'tr', $text$Sosyal medyada, bir internet kullanıcısı bir dini topluluğa karşı hakaret içeren ve tehdit edici bir mesaj paylaşıyor. İfade özgürlüğünü öne sürerek kendini savunuyor. Haklı mı?$text$, $expl$Fransa'da ifade özgürlüğünün sınırları vardır. Nefreti kışkırtma, tehditler ve ırkçı veya dini hakaretler yasalarca cezalandırılan suçlardır (29 Temmuz 1881 yasası ve Code pénal).$expl$, $choices$[{"id":"a","text":"Evet, Fransa'da ifade özgürlüğü mutlaktır"},{"id":"b","text":"Evet, çünkü İnternette istediğini söyleyebilirsin"},{"id":"c","text":"Hayır, ifade özgürlüğü nefreti kışkırtmayı ve tehditleri korumaz"},{"id":"d","text":"Hayır, ancak yalnızca mağdur şikayetçi olursa"}]$choices$),
(513, 'en', $text$You wish to take part in a peaceful demonstration against a government reform. Your employer threatens to dismiss you if you go on your day off. Does he have the right?$text$, $expl$The right to demonstrate peacefully is a fundamental freedom in France. The employer cannot sanction an employee for participating in a demonstration outside working hours.$expl$, $choices$[{"id":"a","text":"Yes, the employer can forbid his employees from demonstrating"},{"id":"b","text":"No, the right to demonstrate is a fundamental freedom and your employer cannot sanction you for it"},{"id":"c","text":"Yes, if the demonstration is against the government"},{"id":"d","text":"No, but only if the demonstration is declared at the prefecture"}]$choices$),
(513, 'tr', $text$Bir hükümet reformuna karşı barışçıl bir gösteriye katılmak istiyorsunuz. İşvereniniz izin gününüzde giderseniz sizi işten çıkarmakla tehdit ediyor. Bu hakka sahip mi?$text$, $expl$Barışçıl gösteri hakkı, Fransa'da temel bir özgürlüktür. İşveren, mesai saatleri dışında bir gösteriye katılan bir çalışanı cezalandıramaz.$expl$, $choices$[{"id":"a","text":"Evet, işveren çalışanlarının gösteriye katılmasını yasaklayabilir"},{"id":"b","text":"Hayır, gösteri hakkı temel bir özgürlüktür ve işvereniniz sizi bunun için cezalandıramaz"},{"id":"c","text":"Evet, gösteri hükümete karşıysa"},{"id":"d","text":"Hayır, ancak yalnızca gösteri valiliğe bildirildiyse"}]$choices$),
(514, 'en', $text$A newspaper publishes a critical article about the President of the Republic. A friend tells you that the newspaper should be banned for disrespect. What do you reply?$text$, $expl$Freedom of the press, guaranteed by the law of 29 July 1881, allows critiquing political figures and institutions. It is a pillar of democracy, as long as it does not amount to defamation.$expl$, $choices$[{"id":"a","text":"Your friend is right; one must not criticise the President"},{"id":"b","text":"The newspaper can be prosecuted for offence to the head of State"},{"id":"c","text":"The press is free to criticise political officials; it is a fundamental right of democracy"},{"id":"d","text":"The newspaper can criticise, but only with the agreement of the government"}]$choices$),
(514, 'tr', $text$Bir gazete Cumhuriyet Cumhurbaşkanı hakkında eleştirel bir makale yayınlıyor. Bir arkadaşınız size, gazetenin saygısızlık nedeniyle yasaklanması gerektiğini söylüyor. Ne cevap verirsiniz?$text$, $expl$29 Temmuz 1881 yasasıyla güvence altına alınan basın özgürlüğü, siyasi kişilikleri ve kurumları eleştirmeye olanak tanır. İftira teşkil etmediği sürece demokrasinin temel bir direğidir.$expl$, $choices$[{"id":"a","text":"Arkadaşınız haklı, Cumhurbaşkanı eleştirilmemelidir"},{"id":"b","text":"Gazete devlet başkanına hakaretten kovuşturulabilir"},{"id":"c","text":"Basın siyasi sorumluları eleştirmekte serbesttir, bu demokrasinin temel bir hakkıdır"},{"id":"d","text":"Gazete eleştirebilir, ancak yalnızca hükümetin onayıyla"}]$choices$),
(515, 'en', $text$Your neighbour writes on social media that the local baker "sells poisoned food" without any proof. The baker wants to file a complaint. Does he have grounds?$text$, $expl$Publicly asserting false facts that harm a person's honour constitutes defamation, an offence under the 1881 law. It is not protected by freedom of expression.$expl$, $choices$[{"id":"a","text":"No, it is your neighbour's freedom of expression"},{"id":"b","text":"Yes, it is defamation because he asserts false facts that harm the baker's honour"},{"id":"c","text":"No, because social media is not subject to the law"},{"id":"d","text":"Yes, but only if the baker can prove that his food is good"}]$choices$),
(515, 'tr', $text$Komşunuz sosyal medyada mahalledeki fırıncının «zehirli yiyecek sattığını» hiçbir kanıt olmadan yazıyor. Fırıncı şikayetçi olmak istiyor. Gerekçesi var mı?$text$, $expl$Bir kişinin onuruna zarar veren yanlış olguları alenen ileri sürmek, 1881 yasası uyarınca bir suç olan iftirayı oluşturur. İfade özgürlüğü tarafından korunmaz.$expl$, $choices$[{"id":"a","text":"Hayır, bu komşunuzun ifade özgürlüğüdür"},{"id":"b","text":"Evet, bu iftiradır çünkü fırıncının onuruna zarar veren yanlış olguları öne sürüyor"},{"id":"c","text":"Hayır, çünkü sosyal medya yasaya tabi değildir"},{"id":"d","text":"Evet, ancak yalnızca fırıncı yiyeceğinin iyi olduğunu kanıtlayabilirse"}]$choices$),
(516, 'en', $text$You wish to create a cultural association in your neighbourhood to organise events. What are the conditions in France?$text$, $expl$Freedom of association is guaranteed by the law of 1 July 1901. Any person can create an association by filing a declaration at the prefecture. At least two people are needed and the statutes must be drafted.$expl$, $choices$[{"id":"a","text":"You must obtain prior authorisation from the mayor"},{"id":"b","text":"It is enough to file a declaration at the prefecture; creation is free"},{"id":"c","text":"You must have French nationality to create an association"},{"id":"d","text":"You must gather at least ten people and obtain the agreement of the préfet (prefect)"}]$choices$),
(516, 'tr', $text$Mahallenizde etkinlikler düzenlemek için bir kültür derneği kurmak istiyorsunuz. Fransa'da koşullar nelerdir?$text$, $expl$Dernek kurma özgürlüğü 1 Temmuz 1901 yasasıyla güvence altına alınmıştır. Herhangi bir kişi, valiliğe bir beyanname vererek bir dernek kurabilir. En az iki kişi gereklidir ve tüzüklerin hazırlanması gerekir.$expl$, $choices$[{"id":"a","text":"Belediye başkanından önceden izin almak gerekir"},{"id":"b","text":"Valilikte bir beyanname vermek yeterlidir, kuruluş serbesttir"},{"id":"c","text":"Bir dernek kurmak için Fransız vatandaşı olmak gerekir"},{"id":"d","text":"En az on kişiyi bir araya getirmek ve préfet'nin (vali) onayını almak gerekir"}]$choices$),
(517, 'en', $text$During a police check in the street, an officer asks you for your identity papers. You have no documents on you. What happens?$text$, $expl$In France, it is not compulsory to carry an identity document at all times. However, during a check, if you cannot prove your identity, you may be held for up to 4 hours for verification.$expl$, $choices$[{"id":"a","text":"You are immediately arrested and placed in police custody (garde à vue)"},{"id":"b","text":"You automatically receive a fine"},{"id":"c","text":"You may be held for an identity check, but not having one's papers is not an offence"},{"id":"d","text":"The police officer has no right to check you without a reason"}]$choices$),
(517, 'tr', $text$Sokakta bir polis kontrolü sırasında, bir memur sizden kimlik belgelerinizi istiyor. Üzerinizde hiçbir belge yok. Ne olur?$text$, $expl$Fransa'da, sürekli bir kimlik belgesi taşımak zorunlu değildir. Ancak bir kontrol sırasında kimliğinizi kanıtlayamazsanız, doğrulama için 4 saate kadar tutulabilirsiniz.$expl$, $choices$[{"id":"a","text":"Derhal tutuklanırsınız ve garde à vue (polis nezareti) altına alınırsınız"},{"id":"b","text":"Otomatik olarak bir para cezası alırsınız"},{"id":"c","text":"Kimlik doğrulaması için tutulabilirsiniz, ancak kimlik belgesi taşımamak bir suç değildir"},{"id":"d","text":"Polis memurunun sebep olmadan sizi kontrol etme hakkı yoktur"}]$choices$),
(518, 'en', $text$The employees of your company decide to go on strike to protest against dangerous working conditions. Your employer threatens to dismiss all the strikers. Is this legal?$text$, $expl$The right to strike is a constitutional right in France. An employer cannot dismiss an employee for having gone on strike, except in case of gross misconduct (faute lourde) committed during the strike (violence, damage).$expl$, $choices$[{"id":"a","text":"Yes, the employer can dismiss the strikers because they are not working"},{"id":"b","text":"No, the right to strike is constitutional and dismissal for striking is forbidden"},{"id":"c","text":"Yes, if the strike lasts more than 48 hours"},{"id":"d","text":"No, but he may permanently reduce their salary"}]$choices$),
(518, 'tr', $text$Şirketinizin çalışanları tehlikeli çalışma koşullarını protesto etmek için greve gitmeye karar veriyor. İşvereniniz tüm grevcileri işten çıkarmakla tehdit ediyor. Bu yasal mı?$text$, $expl$Grev hakkı Fransa'da anayasal bir haktır. Bir işveren, grev sırasında işlenen ağır kusur (faute lourde) hariç (şiddet, hasar), grev yapması nedeniyle bir çalışanı işten çıkaramaz.$expl$, $choices$[{"id":"a","text":"Evet, çalışmadıkları için işveren grevcileri işten çıkarabilir"},{"id":"b","text":"Hayır, grev hakkı anayasaldır ve grev nedeniyle işten çıkarma yasaktır"},{"id":"c","text":"Evet, grev 48 saatten uzun sürerse"},{"id":"d","text":"Hayır, ancak maaşlarını kalıcı olarak azaltabilir"}]$choices$),
(519, 'en', $text$Your neighbour installs a surveillance camera that films directly the entrance to your flat and your landing. Do you have any recourse?$text$, $expl$The right to respect for private life is guaranteed by Article 9 of the Code civil (Civil Code). Filming common areas or the entrance to another person's home without consent is an infringement of privacy. You can demand the removal of the camera and take the matter to court.$expl$, $choices$[{"id":"a","text":"No, your neighbour has the right to film the common areas"},{"id":"b","text":"No, because the camera is on his property"},{"id":"c","text":"Yes, but only if you are the owner and not a tenant"},{"id":"d","text":"Yes, it is an infringement of your private life and you can demand the removal of the camera"}]$choices$),
(519, 'tr', $text$Komşunuz dairenizin girişini ve katınızı doğrudan filme alan bir gözetim kamerası kuruyor. Bir başvuru yolunuz var mı?$text$, $expl$Özel yaşama saygı hakkı, Code civil'in (Medeni Kanun) 9. maddesiyle güvence altına alınmıştır. Ortak alanları veya başka bir kişinin evinin girişini onay olmadan filme almak, özel yaşama yönelik bir ihlaldir. Kameranın kaldırılmasını talep edebilir ve adalete başvurabilirsiniz.$expl$, $choices$[{"id":"a","text":"Hayır, komşunuzun ortak alanları filme alma hakkı vardır"},{"id":"b","text":"Hayır, çünkü kamera onun mülkündedir"},{"id":"c","text":"Evet, ancak yalnızca kiracı değil mülk sahibi iseniz"},{"id":"d","text":"Evet, bu özel yaşamınıza bir saldırıdır ve kameranın kaldırılmasını talep edebilirsiniz"}]$choices$),
(520, 'en', $text$You are invited to a meal among colleagues. A colleague reproaches you for not drinking alcohol, saying that "in France, we toast together". What do you reply?$text$, $expl$Freedom of conscience, protected by the Constitution, includes the right not to consume alcohol, whether for personal, religious or health reasons. No one can be forced to drink alcohol.$expl$, $choices$[{"id":"a","text":"He is right; one must adapt to French traditions"},{"id":"b","text":"You are free not to drink alcohol; it is a personal choice protected by freedom of conscience"},{"id":"c","text":"You must drink a little out of politeness so as not to offend your colleagues"},{"id":"d","text":"You must explain your religious reasons to be excused"}]$choices$),
(520, 'tr', $text$Meslektaşlar arasında bir yemeğe davetlisiniz. Bir meslektaşınız «Fransa'da birlikte kadeh kaldırırız» diyerek alkol içmediğiniz için sizi kınıyor. Ne cevap verirsiniz?$text$, $expl$Anayasa tarafından korunan vicdan özgürlüğü, kişisel, dini veya sağlık nedenleriyle alkol tüketmemenin hakkını da içerir. Hiç kimse alkol içmeye zorlanamaz.$expl$, $choices$[{"id":"a","text":"Haklı, Fransız geleneklerine uyum sağlamak gerekir"},{"id":"b","text":"Alkol içmemekte serbestsiniz, bu vicdan özgürlüğü tarafından korunan kişisel bir tercihtir"},{"id":"c","text":"Meslektaşlarınızı incitmemek için nezaketen biraz içmelisiniz"},{"id":"d","text":"Muaf tutulmak için dini nedenlerinizi açıklamalısınız"}]$choices$),
(521, 'en', $text$During a debate, a person publicly asserts that the Shoah (Holocaust) never existed, invoking their freedom of expression. What does French law say?$text$, $expl$The Gayssot law of 1990 prohibits negationism, that is, contesting the existence of crimes against humanity. It is not covered by freedom of expression and constitutes a criminal offence.$expl$, $choices$[{"id":"a","text":"It is covered by freedom of expression, even if it is shocking"},{"id":"b","text":"It is forbidden only in the media, not in a private discussion"},{"id":"c","text":"Holocaust denial (négationnisme) is a criminal offence in France; it is not protected by freedom of expression"},{"id":"d","text":"It is allowed if the person presents it as an opinion and not as a fact"}]$choices$),
(521, 'tr', $text$Bir tartışma sırasında bir kişi ifade özgürlüğünü öne sürerek Şoah'ın (Holokost) hiç var olmadığını alenen ileri sürüyor. Fransız yasası ne der?$text$, $expl$1990 tarihli Gayssot yasası, insanlığa karşı suçların varlığına itiraz etmeyi yani negasyonizmi yasaklar. İfade özgürlüğü kapsamında değildir ve cezai bir suç oluşturur.$expl$, $choices$[{"id":"a","text":"Sarsıcı olsa bile ifade özgürlüğü kapsamındadır"},{"id":"b","text":"Yalnızca medyada yasaktır, özel bir tartışmada değil"},{"id":"c","text":"Holokost inkârı (négationnisme) Fransa'da cezai bir suçtur; ifade özgürlüğü tarafından korunmaz"},{"id":"d","text":"Kişi bunu bir görüş olarak sunarsa ve bir olgu olarak sunmazsa izinlidir"}]$choices$)
INSERT INTO question_translations (question_id, lang, text, explanation, choices) VALUES
(88, 'en', $text$Who appoints the Prime Minister?$text$, $expl$The Prime Minister is appointed by the President of the Republic. This is a constitutional prerogative defined by article 8 of the 1958 Constitution.$expl$, $choices$[{"id":"a","text":"The President of the Republic"},{"id":"b","text":"The Assemblée nationale (the French National Assembly)"},{"id":"c","text":"The Sénat (the French Senate)"},{"id":"d","text":"The Conseil constitutionnel (the Constitutional Council)"}]$choices$),
(88, 'tr', $text$Başbakanı kim atar?$text$, $expl$Başbakan, Cumhurbaşkanı tarafından atanır. Bu, 1958 Anayasası'nın 8. maddesiyle tanımlanan anayasal bir yetkidir.$expl$, $choices$[{"id":"a","text":"Cumhurbaşkanı"},{"id":"b","text":"Assemblée nationale (Fransız Ulusal Meclisi)"},{"id":"c","text":"Sénat (Fransız Senatosu)"},{"id":"d","text":"Conseil constitutionnel (Anayasa Konseyi)"}]$choices$),
(89, 'en', $text$Parliament is composed of:$text$, $expl$The French Parliament is bicameral. It is composed of the Assemblée nationale (the French National Assembly) and the Sénat (the French Senate), which vote on laws and oversee the action of the Government.$expl$, $choices$[{"id":"a","text":"The Assemblée nationale (the French National Assembly) and the Sénat (the French Senate)"},{"id":"b","text":"The Sénat and the Conseil constitutionnel (the Constitutional Council)"},{"id":"c","text":"The Assemblée nationale and the Government"},{"id":"d","text":"The Conseil d'État (the Council of State) and the Assemblée nationale"}]$choices$),
(89, 'tr', $text$Parlamento şunlardan oluşur:$text$, $expl$Fransız Parlamentosu iki meclislidir. Yasaları oylayan ve Hükümetin eylemlerini denetleyen Assemblée nationale (Fransız Ulusal Meclisi) ve Sénat'tan (Fransız Senatosu) oluşur.$expl$, $choices$[{"id":"a","text":"Assemblée nationale (Fransız Ulusal Meclisi) ve Sénat (Fransız Senatosu)"},{"id":"b","text":"Sénat ve Conseil constitutionnel (Anayasa Konseyi)"},{"id":"c","text":"Assemblée nationale ve Hükümet"},{"id":"d","text":"Conseil d'État (Danıştay) ve Assemblée nationale"}]$choices$),
(90, 'en', $text$What is the executive power? The power:$text$, $expl$The executive power is the power to enforce the laws. In France, it is exercised by the President of the Republic and the Government.$expl$, $choices$[{"id":"a","text":"To enforce the laws"},{"id":"b","text":"To vote on the laws"},{"id":"c","text":"To judge offences"},{"id":"d","text":"To amend the Constitution"}]$choices$),
(90, 'tr', $text$Yürütme yetkisi nedir? Şu yetkidir:$text$, $expl$Yürütme yetkisi, yasaları uygulama yetkisidir. Fransa'da bu yetki, Cumhurbaşkanı ve Hükümet tarafından kullanılır.$expl$, $choices$[{"id":"a","text":"Yasaları uygulama"},{"id":"b","text":"Yasaları oylama"},{"id":"c","text":"Suçları yargılama"},{"id":"d","text":"Anayasayı değiştirme"}]$choices$),
(91, 'en', $text$Leaders are elected by citizens in:$text$, $expl$In a democracy, leaders are elected by citizens through free elections. This is the fundamental principle of a democratic regime.$expl$, $choices$[{"id":"a","text":"A democracy"},{"id":"b","text":"A dictatorship"},{"id":"c","text":"An absolute monarchy"},{"id":"d","text":"An oligarchy"}]$choices$),
(91, 'tr', $text$Liderler vatandaşlar tarafından şu rejimde seçilir:$text$, $expl$Bir demokraside liderler, özgür seçimler yoluyla vatandaşlar tarafından seçilir. Bu, demokratik rejimin temel ilkesidir.$expl$, $choices$[{"id":"a","text":"Demokraside"},{"id":"b","text":"Diktatörlükte"},{"id":"c","text":"Mutlak monarşide"},{"id":"d","text":"Oligarşide"}]$choices$),
(92, 'en', $text$Does one have the right not to comply with a law?$text$, $expl$No, no one has the right not to comply with the law. The law applies equally to everyone. No one is supposed to be unaware of the law.$expl$, $choices$[{"id":"a","text":"No, never"},{"id":"b","text":"Yes, if one disagrees with the law"},{"id":"c","text":"Yes, if one is a foreigner"},{"id":"d","text":"Yes, in certain personal circumstances"}]$choices$),
(92, 'tr', $text$Bir yasaya uymama hakkı var mıdır?$text$, $expl$Hayır, hiç kimsenin yasaya uymama hakkı yoktur. Yasa herkese eşit şekilde uygulanır. Kimse yasayı bilmediğini ileri süremez.$expl$, $choices$[{"id":"a","text":"Hayır, asla"},{"id":"b","text":"Evet, yasayla aynı fikirde değilseniz"},{"id":"c","text":"Evet, yabancıysanız"},{"id":"d","text":"Evet, bazı kişisel durumlarda"}]$choices$),
(93, 'en', $text$Who must comply with the law?$text$, $expl$Everyone must comply with the law in France, without exception. This principle applies to citizens, foreigners, elected officials and leaders.$expl$, $choices$[{"id":"a","text":"Everyone"},{"id":"b","text":"Only French citizens"},{"id":"c","text":"Only adults"},{"id":"d","text":"Only people living in France"}]$choices$),
(93, 'tr', $text$Yasalara kim uymak zorundadır?$text$, $expl$Fransa'da herkes istisnasız yasalara uymak zorundadır. Bu ilke vatandaşlar, yabancılar, seçilmiş yetkililer ve liderler için geçerlidir.$expl$, $choices$[{"id":"a","text":"Herkes"},{"id":"b","text":"Yalnızca Fransız vatandaşları"},{"id":"c","text":"Yalnızca yetişkinler"},{"id":"d","text":"Yalnızca Fransa'da yaşayan kişiler"}]$choices$),
(94, 'en', $text$What is the role of the judicial authority?$text$, $expl$The role of the judicial authority is to ensure compliance with the laws and to sanction non-compliance. It protects individual freedoms.$expl$, $choices$[{"id":"a","text":"To ensure compliance with the laws and to sanction non-compliance"},{"id":"b","text":"To vote on the laws"},{"id":"c","text":"To propose new laws"},{"id":"d","text":"To appoint ministers"}]$choices$),
(94, 'tr', $text$Yargı erkinin rolü nedir?$text$, $expl$Yargı erkinin rolü, yasalara uyulmasını sağlamak ve uyulmamasını yaptırıma bağlamaktır. Bireysel özgürlükleri korur.$expl$, $choices$[{"id":"a","text":"Yasalara uyulmasını sağlamak ve uyulmamasını yaptırıma bağlamak"},{"id":"b","text":"Yasaları oylamak"},{"id":"c","text":"Yeni yasalar önermek"},{"id":"d","text":"Bakanları atamak"}]$choices$),
(95, 'en', $text$What power does a judge hold? The power:$text$, $expl$The judge holds the judicial power. They administer justice by applying the laws and sanctioning offences.$expl$, $choices$[{"id":"a","text":"Judicial"},{"id":"b","text":"Executive"},{"id":"c","text":"Legislative"},{"id":"d","text":"Administrative"}]$choices$),
(95, 'tr', $text$Bir hâkim hangi yetkiyi elinde tutar? Şu yetkiyi:$text$, $expl$Hâkim, yargı yetkisini elinde tutar. Yasaları uygulayarak ve suçları yaptırıma bağlayarak adaleti tesis eder.$expl$, $choices$[{"id":"a","text":"Yargı"},{"id":"b","text":"Yürütme"},{"id":"c","text":"Yasama"},{"id":"d","text":"İdari"}]$choices$),
(96, 'en', $text$The judicial authority is exercised by:$text$, $expl$The judicial authority is exercised by magistrates and judges. They are independent of the executive and legislative powers.$expl$, $choices$[{"id":"a","text":"Magistrates and judges"},{"id":"b","text":"Members of Parliament (députés)"},{"id":"c","text":"Ministers"},{"id":"d","text":"Prefects"}]$choices$),
(96, 'tr', $text$Yargı erki şunlar tarafından kullanılır:$text$, $expl$Yargı erki, magistralar ve hâkimler tarafından kullanılır. Yürütme ve yasama erklerinden bağımsızdırlar.$expl$, $choices$[{"id":"a","text":"Magistralar ve hâkimler"},{"id":"b","text":"Milletvekilleri (députés)"},{"id":"c","text":"Bakanlar"},{"id":"d","text":"Valiler (préfets)"}]$choices$),
(97, 'en', $text$What happens if a minister does not comply with the law?$text$, $expl$A minister who does not comply with the law may be judged like any citizen. No one is above the law, including members of the Government.$expl$, $choices$[{"id":"a","text":"They may be judged like any citizen"},{"id":"b","text":"They cannot be judged because they are a minister"},{"id":"c","text":"They are merely dismissed from the Government"},{"id":"d","text":"They are protected by ministerial immunity for life"}]$choices$),
(97, 'tr', $text$Bir bakan yasaya uymazsa ne olur?$text$, $expl$Yasaya uymayan bir bakan, herhangi bir vatandaş gibi yargılanabilir. Hükümet üyeleri dahil hiç kimse yasaların üstünde değildir.$expl$, $choices$[{"id":"a","text":"Herhangi bir vatandaş gibi yargılanabilir"},{"id":"b","text":"Bakan olduğu için yargılanamaz"},{"id":"c","text":"Yalnızca Hükümetten ihraç edilir"},{"id":"d","text":"Ömür boyu bakanlık dokunulmazlığı ile korunur"}]$choices$),
(98, 'en', $text$Who is elected during the legislative elections?$text$, $expl$Members of Parliament (députés) are elected during the legislative elections. They sit in the Assemblée nationale (the French National Assembly) and vote on the laws.$expl$, $choices$[{"id":"a","text":"Members of Parliament (députés)"},{"id":"b","text":"Senators"},{"id":"c","text":"Mayors"},{"id":"d","text":"Regional councillors"}]$choices$),
(98, 'tr', $text$Yasama seçimlerinde kim seçilir?$text$, $expl$Yasama seçimlerinde milletvekilleri (députés) seçilir. Assemblée nationale'de (Fransız Ulusal Meclisi) görev yaparlar ve yasaları oylarlar.$expl$, $choices$[{"id":"a","text":"Milletvekilleri (députés)"},{"id":"b","text":"Senatörler"},{"id":"c","text":"Belediye başkanları"},{"id":"d","text":"Bölge meclisi üyeleri"}]$choices$),
(99, 'en', $text$How many members of Parliament (députés) make up the Assemblée nationale (the French National Assembly)?$text$, $expl$The Assemblée nationale is composed of 577 members of Parliament (députés). They are elected by direct universal suffrage for a 5-year term.$expl$, $choices$[{"id":"a","text":"577"},{"id":"b","text":"348"},{"id":"c","text":"500"},{"id":"d","text":"650"}]$choices$),
(99, 'tr', $text$Assemblée nationale (Fransız Ulusal Meclisi) kaç milletvekilinden oluşur?$text$, $expl$Assemblée nationale 577 milletvekilinden (députés) oluşur. 5 yıllık bir görev süresi için doğrudan genel oyla seçilirler.$expl$, $choices$[{"id":"a","text":"577"},{"id":"b","text":"348"},{"id":"c","text":"500"},{"id":"d","text":"650"}]$choices$),
(100, 'en', $text$When are senators elected?$text$, $expl$Senators are elected by indirect universal suffrage by the grands électeurs (electoral college). The Sénat (the French Senate) is renewed by half every 3 years.$expl$, $choices$[{"id":"a","text":"They are elected by indirect universal suffrage"},{"id":"b","text":"They are elected by direct universal suffrage"},{"id":"c","text":"They are appointed by the President of the Republic"},{"id":"d","text":"They are designated by the members of Parliament (députés)"}]$choices$),
(100, 'tr', $text$Senatörler ne zaman seçilir?$text$, $expl$Senatörler, grands électeurs (büyük seçmenler) tarafından dolaylı genel oyla seçilir. Sénat (Fransız Senatosu) her 3 yılda bir yarısı yenilenir.$expl$, $choices$[{"id":"a","text":"Dolaylı genel oyla seçilirler"},{"id":"b","text":"Doğrudan genel oyla seçilirler"},{"id":"c","text":"Cumhurbaşkanı tarafından atanırlar"},{"id":"d","text":"Milletvekilleri (députés) tarafından belirlenirler"}]$choices$),
(101, 'en', $text$Who is elected during the municipal elections?$text$, $expl$Municipal councillors are elected during the municipal elections. They then elect the mayor from among themselves.$expl$, $choices$[{"id":"a","text":"Municipal councillors"},{"id":"b","text":"The mayor directly"},{"id":"c","text":"Departmental councillors"},{"id":"d","text":"Members of Parliament (députés)"}]$choices$),
(101, 'tr', $text$Belediye seçimlerinde kim seçilir?$text$, $expl$Belediye seçimlerinde belediye meclisi üyeleri seçilir. Daha sonra aralarından belediye başkanını seçerler.$expl$, $choices$[{"id":"a","text":"Belediye meclisi üyeleri"},{"id":"b","text":"Belediye başkanı doğrudan"},{"id":"c","text":"İl meclisi üyeleri"},{"id":"d","text":"Milletvekilleri (députés)"}]$choices$),
(102, 'en', $text$Who is elected during the presidential elections?$text$, $expl$The President of the Republic is elected during the presidential elections, by direct universal suffrage since 1962.$expl$, $choices$[{"id":"a","text":"The President of the Republic"},{"id":"b","text":"The Prime Minister"},{"id":"c","text":"Members of Parliament (députés)"},{"id":"d","text":"Senators"}]$choices$),
(102, 'tr', $text$Cumhurbaşkanlığı seçimlerinde kim seçilir?$text$, $expl$Cumhurbaşkanı, 1962'den beri doğrudan genel oyla, cumhurbaşkanlığı seçimlerinde seçilir.$expl$, $choices$[{"id":"a","text":"Cumhurbaşkanı"},{"id":"b","text":"Başbakan"},{"id":"c","text":"Milletvekilleri (députés)"},{"id":"d","text":"Senatörler"}]$choices$),
(103, 'en', $text$From what age does one have the right to vote?$text$, $expl$In France, the right to vote is granted from the age of 18. This is the age of civil and political majority.$expl$, $choices$[{"id":"a","text":"18 years old"},{"id":"b","text":"16 years old"},{"id":"c","text":"21 years old"},{"id":"d","text":"25 years old"}]$choices$),
(103, 'tr', $text$Hangi yaştan itibaren oy kullanma hakkı vardır?$text$, $expl$Fransa'da oy kullanma hakkı 18 yaşından itibaren tanınır. Bu, medeni ve siyasi reşitlik yaşıdır.$expl$, $choices$[{"id":"a","text":"18 yaş"},{"id":"b","text":"16 yaş"},{"id":"c","text":"21 yaş"},{"id":"d","text":"25 yaş"}]$choices$),
(104, 'en', $text$For how long is the President of the French Republic elected?$text$, $expl$The President of the Republic is elected for a 5-year term (quinquennat) since the constitutional reform of 2000.$expl$, $choices$[{"id":"a","text":"5 years"},{"id":"b","text":"7 years"},{"id":"c","text":"4 years"},{"id":"d","text":"6 years"}]$choices$),
(104, 'tr', $text$Fransa Cumhurbaşkanı ne kadar süre için seçilir?$text$, $expl$Cumhurbaşkanı, 2000 anayasa reformundan bu yana 5 yıllık (quinquennat) bir görev süresi için seçilir.$expl$, $choices$[{"id":"a","text":"5 yıl"},{"id":"b","text":"7 yıl"},{"id":"c","text":"4 yıl"},{"id":"d","text":"6 yıl"}]$choices$),
(105, 'en', $text$For how long are members of Parliament (députés) elected?$text$, $expl$Members of Parliament (députés) are elected for a 5-year term. The Assemblée nationale (the French National Assembly) may be dissolved before the end of the term by the President of the Republic.$expl$, $choices$[{"id":"a","text":"5 years"},{"id":"b","text":"6 years"},{"id":"c","text":"4 years"},{"id":"d","text":"7 years"}]$choices$),
(105, 'tr', $text$Milletvekilleri (députés) ne kadar süre için seçilir?$text$, $expl$Milletvekilleri (députés) 5 yıllık bir görev süresi için seçilir. Assemblée nationale (Fransız Ulusal Meclisi), görev süresi sona ermeden Cumhurbaşkanı tarafından feshedilebilir.$expl$, $choices$[{"id":"a","text":"5 yıl"},{"id":"b","text":"6 yıl"},{"id":"c","text":"4 yıl"},{"id":"d","text":"7 yıl"}]$choices$),
(106, 'en', $text$For how long are senators elected?$text$, $expl$Senators are elected for a 6-year term. The Sénat (the French Senate) is renewed by half every 3 years.$expl$, $choices$[{"id":"a","text":"6 years"},{"id":"b","text":"5 years"},{"id":"c","text":"4 years"},{"id":"d","text":"7 years"}]$choices$),
(106, 'tr', $text$Senatörler ne kadar süre için seçilir?$text$, $expl$Senatörler 6 yıllık bir görev süresi için seçilir. Sénat (Fransız Senatosu) her 3 yılda bir yarısı yenilenir.$expl$, $choices$[{"id":"a","text":"6 yıl"},{"id":"b","text":"5 yıl"},{"id":"c","text":"4 yıl"},{"id":"d","text":"7 yıl"}]$choices$),
(107, 'en', $text$Who holds the executive power?$text$, $expl$The executive power is held by the President of the Republic and the Government. They enforce the laws passed by Parliament.$expl$, $choices$[{"id":"a","text":"The President of the Republic and the Government"},{"id":"b","text":"Parliament"},{"id":"c","text":"Judges"},{"id":"d","text":"The Conseil constitutionnel (the Constitutional Council)"}]$choices$),
(107, 'tr', $text$Yürütme yetkisini kim elinde tutar?$text$, $expl$Yürütme yetkisi, Cumhurbaşkanı ve Hükümet tarafından elinde tutulur. Parlamento tarafından oylanan yasaları uygularlar.$expl$, $choices$[{"id":"a","text":"Cumhurbaşkanı ve Hükümet"},{"id":"b","text":"Parlamento"},{"id":"c","text":"Hâkimler"},{"id":"d","text":"Conseil constitutionnel (Anayasa Konseyi)"}]$choices$),
(108, 'en', $text$What condition is required to vote in elections?$text$, $expl$To vote in elections in France, one must be registered on the electoral rolls. Registration is an essential prerequisite.$expl$, $choices$[{"id":"a","text":"To be registered on the electoral rolls"},{"id":"b","text":"To have a job in France"},{"id":"c","text":"To own real estate"},{"id":"d","text":"To have a French diploma"}]$choices$),
(108, 'tr', $text$Seçimlerde oy kullanmak için hangi koşul gereklidir?$text$, $expl$Fransa'da seçimlerde oy kullanmak için seçmen kütüğüne kayıtlı olmak gerekir. Kayıt, vazgeçilmez bir ön koşuldur.$expl$, $choices$[{"id":"a","text":"Seçmen kütüğüne kayıtlı olmak"},{"id":"b","text":"Fransa'da bir işe sahip olmak"},{"id":"c","text":"Bir gayrimenkule sahip olmak"},{"id":"d","text":"Bir Fransız diplomasına sahip olmak"}]$choices$),
(109, 'en', $text$Who can vote in elections in France?$text$, $expl$French citizens of legal age (18 and over) enjoying their civil and political rights may vote in elections in France.$expl$, $choices$[{"id":"a","text":"French citizens of legal age"},{"id":"b","text":"Any person residing in France"},{"id":"c","text":"People holding a residence permit"},{"id":"d","text":"People over 21 years old"}]$choices$),
(109, 'tr', $text$Fransa'da seçimlerde kim oy kullanabilir?$text$, $expl$Reşit (18 yaş ve üzeri) ve medeni ile siyasi haklarını kullanan Fransız vatandaşları Fransa'da seçimlerde oy kullanabilir.$expl$, $choices$[{"id":"a","text":"Reşit Fransız vatandaşları"},{"id":"b","text":"Fransa'da ikamet eden herhangi bir kişi"},{"id":"c","text":"Oturma izni olan kişiler"},{"id":"d","text":"21 yaşından büyük kişiler"}]$choices$),
(110, 'en', $text$What does "universal suffrage" mean?$text$, $expl$Universal suffrage means that all citizens of legal age have the right to vote, without distinction of sex, wealth or origin.$expl$, $choices$[{"id":"a","text":"All citizens of legal age have the right to vote"},{"id":"b","text":"Only men have the right to vote"},{"id":"c","text":"Voting is compulsory for all"},{"id":"d","text":"Only property owners may vote"}]$choices$),
(110, 'tr', $text$"Genel oy" ne anlama gelir?$text$, $expl$Genel oy, cinsiyet, zenginlik veya köken ayrımı yapılmaksızın tüm reşit vatandaşların oy kullanma hakkına sahip olduğu anlamına gelir.$expl$, $choices$[{"id":"a","text":"Tüm reşit vatandaşlar oy kullanma hakkına sahiptir"},{"id":"b","text":"Yalnızca erkekler oy kullanma hakkına sahiptir"},{"id":"c","text":"Oy kullanmak herkes için zorunludur"},{"id":"d","text":"Yalnızca mülk sahipleri oy kullanabilir"}]$choices$),
(111, 'en', $text$Regarding political parties, which statement is correct?$text$, $expl$In France, there are several political parties and one may freely join the party of one's choice. Multipartism is a fundamental principle of democracy.$expl$, $choices$[{"id":"a","text":"Several political parties exist and one may join the party of one's choice"},{"id":"b","text":"There is only one political party in France"},{"id":"c","text":"Political parties are prohibited"},{"id":"d","text":"Only civil servants may join a party"}]$choices$),
(111, 'tr', $text$Siyasi partilerle ilgili olarak hangi ifade doğrudur?$text$, $expl$Fransa'da birçok siyasi parti vardır ve kişi tercih ettiği partiye özgürce katılabilir. Çok partililik, demokrasinin temel ilkesidir.$expl$, $choices$[{"id":"a","text":"Birçok siyasi parti vardır ve kişi tercih ettiği partiye katılabilir"},{"id":"b","text":"Fransa'da yalnızca tek bir siyasi parti vardır"},{"id":"c","text":"Siyasi partiler yasaktır"},{"id":"d","text":"Yalnızca memurlar bir partiye katılabilir"}]$choices$),
(112, 'en', $text$What is the role of members of Parliament (députés)?$text$, $expl$Members of Parliament (députés) vote on the laws and oversee the action of the Government. They represent the people in the Assemblée nationale (the French National Assembly).$expl$, $choices$[{"id":"a","text":"To vote on the laws and oversee the action of the Government"},{"id":"b","text":"To lead the Government"},{"id":"c","text":"To appoint judges"},{"id":"d","text":"To manage the communes (smallest administrative units)"}]$choices$),
(112, 'tr', $text$Milletvekillerinin (députés) rolü nedir?$text$, $expl$Milletvekilleri (députés) yasaları oylar ve Hükümetin eylemlerini denetler. Assemblée nationale'de (Fransız Ulusal Meclisi) halkı temsil ederler.$expl$, $choices$[{"id":"a","text":"Yasaları oylamak ve Hükümetin eylemlerini denetlemek"},{"id":"b","text":"Hükümeti yönetmek"},{"id":"c","text":"Hâkimleri atamak"},{"id":"d","text":"Belediyeleri (en küçük idari birimler) yönetmek"}]$choices$),
(113, 'en', $text$The separation of powers is a fundamental principle. What are the three powers concerned?$text$, $expl$The three powers are: the legislative power (making the laws), the executive power (enforcing the laws) and the judicial power (judging). This principle guarantees democracy.$expl$, $choices$[{"id":"a","text":"Legislative, executive, judicial"},{"id":"b","text":"Presidential, parliamentary, judicial"},{"id":"c","text":"Municipal, departmental, regional"},{"id":"d","text":"Military, civil, religious"}]$choices$),
(113, 'tr', $text$Kuvvetler ayrılığı temel bir ilkedir. Söz konusu üç güç nedir?$text$, $expl$Üç güç şunlardır: yasama (yasaları yapma), yürütme (yasaları uygulama) ve yargı (yargılama). Bu ilke demokrasiyi güvence altına alır.$expl$, $choices$[{"id":"a","text":"Yasama, yürütme, yargı"},{"id":"b","text":"Cumhurbaşkanlığı, parlamento, yargı"},{"id":"c","text":"Belediye, il, bölge"},{"id":"d","text":"Askeri, sivil, dini"}]$choices$),
(114, 'en', $text$Who holds the legislative power?$text$, $expl$The legislative power is held by Parliament, composed of the Assemblée nationale (the French National Assembly) and the Sénat (the French Senate). It votes on the laws.$expl$, $choices$[{"id":"a","text":"Parliament (Assemblée nationale and Sénat)"},{"id":"b","text":"The President of the Republic"},{"id":"c","text":"The Government"},{"id":"d","text":"Judges"}]$choices$),
(114, 'tr', $text$Yasama yetkisini kim elinde tutar?$text$, $expl$Yasama yetkisi, Assemblée nationale (Fransız Ulusal Meclisi) ve Sénat'tan (Fransız Senatosu) oluşan Parlamento tarafından elinde tutulur. Yasaları oylar.$expl$, $choices$[{"id":"a","text":"Parlamento (Assemblée nationale ve Sénat)"},{"id":"b","text":"Cumhurbaşkanı"},{"id":"c","text":"Hükümet"},{"id":"d","text":"Hâkimler"}]$choices$),
(115, 'en', $text$Who sanctions the perpetrator of a theft?$text$, $expl$It is the justice system (a judge) that sanctions the perpetrator of a theft. The judicial power alone is competent to pronounce criminal penalties.$expl$, $choices$[{"id":"a","text":"The justice system (a judge)"},{"id":"b","text":"The police"},{"id":"c","text":"The mayor"},{"id":"d","text":"The victim themselves"}]$choices$),
(115, 'tr', $text$Bir hırsızlık failini kim yaptırıma bağlar?$text$, $expl$Bir hırsızlık failini adalet (bir hâkim) yaptırıma bağlar. Cezai yaptırımları yalnızca yargı erki belirlemekle yetkilidir.$expl$, $choices$[{"id":"a","text":"Adalet (bir hâkim)"},{"id":"b","text":"Polis"},{"id":"c","text":"Belediye başkanı"},{"id":"d","text":"Mağdurun kendisi"}]$choices$),
(116, 'en', $text$Who elects the members of Parliament (députés)?$text$, $expl$Members of Parliament (députés) are elected by French citizens by direct universal suffrage. Each député represents a constituency.$expl$, $choices$[{"id":"a","text":"French citizens by direct universal suffrage"},{"id":"b","text":"Senators"},{"id":"c","text":"The President of the Republic"},{"id":"d","text":"The grands électeurs (electoral college)"}]$choices$),
(116, 'tr', $text$Milletvekillerini (députés) kim seçer?$text$, $expl$Milletvekilleri (députés), Fransız vatandaşları tarafından doğrudan genel oyla seçilir. Her milletvekili bir seçim bölgesini temsil eder.$expl$, $choices$[{"id":"a","text":"Fransız vatandaşları doğrudan genel oyla"},{"id":"b","text":"Senatörler"},{"id":"c","text":"Cumhurbaşkanı"},{"id":"d","text":"Grands électeurs (büyük seçmenler)"}]$choices$),
(117, 'en', $text$Who votes on the laws?$text$, $expl$Parliament (the Assemblée nationale and the Sénat) votes on the laws. This is the main function of the legislative power.$expl$, $choices$[{"id":"a","text":"Parliament (Assemblée nationale and Sénat)"},{"id":"b","text":"The President of the Republic"},{"id":"c","text":"The Government"},{"id":"d","text":"The Conseil constitutionnel (the Constitutional Council)"}]$choices$),
(117, 'tr', $text$Yasaları kim oylar?$text$, $expl$Parlamento (Assemblée nationale ve Sénat) yasaları oylar. Bu, yasama erkinin temel işlevidir.$expl$, $choices$[{"id":"a","text":"Parlamento (Assemblée nationale ve Sénat)"},{"id":"b","text":"Cumhurbaşkanı"},{"id":"c","text":"Hükümet"},{"id":"d","text":"Conseil constitutionnel (Anayasa Konseyi)"}]$choices$),
(118, 'en', $text$Who resides at the Palais de l'Élysée?$text$, $expl$The Palais de l'Élysée is the official residence of the President of the French Republic, located in Paris.$expl$, $choices$[{"id":"a","text":"The President of the Republic"},{"id":"b","text":"The Prime Minister"},{"id":"c","text":"The president of the Assemblée nationale (the French National Assembly)"},{"id":"d","text":"The president of the Sénat (the French Senate)"}]$choices$),
(118, 'tr', $text$Palais de l'Élysée'de kim ikamet eder?$text$, $expl$Palais de l'Élysée, Paris'te bulunan Fransa Cumhurbaşkanı'nın resmi konutudur.$expl$, $choices$[{"id":"a","text":"Cumhurbaşkanı"},{"id":"b","text":"Başbakan"},{"id":"c","text":"Assemblée nationale (Fransız Ulusal Meclisi) başkanı"},{"id":"d","text":"Sénat (Fransız Senatosu) başkanı"}]$choices$),
(119, 'en', $text$How many départements (administrative units) are there in France?$text$, $expl$France has 101 départements: 96 metropolitan départements and 5 overseas départements (Guadeloupe, Martinique, French Guiana, Réunion, Mayotte).$expl$, $choices$[{"id":"a","text":"101"},{"id":"b","text":"96"},{"id":"c","text":"95"},{"id":"d","text":"110"}]$choices$),
(119, 'tr', $text$Fransa'da kaç département (idari birim) vardır?$text$, $expl$Fransa'nın 101 département'ı vardır: 96 anakara département'ı ve 5 deniz aşırı département (Guadeloupe, Martinique, Fransız Guyanası, Réunion, Mayotte).$expl$, $choices$[{"id":"a","text":"101"},{"id":"b","text":"96"},{"id":"c","text":"95"},{"id":"d","text":"110"}]$choices$),
(120, 'en', $text$Who represents the State in a département?$text$, $expl$The préfet (prefect) represents the State in the département. They are appointed by the President of the Republic and ensure the application of the laws.$expl$, $choices$[{"id":"a","text":"The préfet (prefect)"},{"id":"b","text":"The mayor"},{"id":"c","text":"The member of Parliament (député)"},{"id":"d","text":"The senator"}]$choices$),
(120, 'tr', $text$Bir département'ta Devleti kim temsil eder?$text$, $expl$Préfet (vali) département'ta Devleti temsil eder. Cumhurbaşkanı tarafından atanır ve yasaların uygulanmasını sağlar.$expl$, $choices$[{"id":"a","text":"Préfet (vali)"},{"id":"b","text":"Belediye başkanı"},{"id":"c","text":"Milletvekili (député)"},{"id":"d","text":"Senatör"}]$choices$),
(121, 'en', $text$Who heads the commune (the smallest administrative unit)?$text$, $expl$The mayor heads the commune. They are elected by the municipal councillors and exercise functions both on behalf of the commune and on behalf of the State.$expl$, $choices$[{"id":"a","text":"The mayor"},{"id":"b","text":"The préfet (prefect)"},{"id":"c","text":"The member of Parliament (député)"},{"id":"d","text":"The president of the departmental council"}]$choices$),
(121, 'tr', $text$Commune'ü (en küçük idari birim) kim yönetir?$text$, $expl$Belediye başkanı commune'ü yönetir. Belediye meclis üyeleri tarafından seçilir ve hem commune adına hem de Devlet adına görevleri yerine getirir.$expl$, $choices$[{"id":"a","text":"Belediye başkanı"},{"id":"b","text":"Préfet (vali)"},{"id":"c","text":"Milletvekili (député)"},{"id":"d","text":"İl meclisi başkanı"}]$choices$),
(122, 'en', $text$Does the President of the Republic have all the powers?$text$, $expl$No, the President of the Republic does not have all the powers. The separation of powers (legislative, executive, judicial) guarantees that no single person holds all the powers.$expl$, $choices$[{"id":"a","text":"No, the powers are separated"},{"id":"b","text":"Yes, they have all the powers"},{"id":"c","text":"Yes, except the judicial power"},{"id":"d","text":"Yes, in times of crisis"}]$choices$),
(122, 'tr', $text$Cumhurbaşkanı tüm yetkilere sahip midir?$text$, $expl$Hayır, Cumhurbaşkanı tüm yetkilere sahip değildir. Kuvvetler ayrılığı (yasama, yürütme, yargı) hiçbir kişinin tüm yetkilere sahip olmamasını güvence altına alır.$expl$, $choices$[{"id":"a","text":"Hayır, yetkiler ayrılmıştır"},{"id":"b","text":"Evet, tüm yetkilere sahiptir"},{"id":"c","text":"Evet, yargı yetkisi hariç"},{"id":"d","text":"Evet, kriz dönemlerinde"}]$choices$),
(123, 'en', $text$Who is the préfet (prefect)?$text$, $expl$The préfet is the representative of the State in the département. They are appointed by the President of the Republic in the Council of Ministers.$expl$, $choices$[{"id":"a","text":"The representative of the State in the département"},{"id":"b","text":"The head of the municipal police"},{"id":"c","text":"A local elected official"},{"id":"d","text":"The director of the public hospital"}]$choices$),
(123, 'tr', $text$Préfet (vali) kimdir?$text$, $expl$Préfet, département'ta Devletin temsilcisidir. Bakanlar Kurulu'nda Cumhurbaşkanı tarafından atanır.$expl$, $choices$[{"id":"a","text":"Département'ta Devletin temsilcisi"},{"id":"b","text":"Belediye polisi şefi"},{"id":"c","text":"Yerel seçilmiş bir yetkili"},{"id":"d","text":"Devlet hastanesinin müdürü"}]$choices$),
(124, 'en', $text$What is the role of Parliament?$text$, $expl$Parliament votes on the laws and oversees the action of the Government. It exercises the legislative power in France.$expl$, $choices$[{"id":"a","text":"To vote on the laws and oversee the action of the Government"},{"id":"b","text":"To lead the army"},{"id":"c","text":"To appoint judges"},{"id":"d","text":"To manage local taxes"}]$choices$),
(124, 'tr', $text$Parlamentonun rolü nedir?$text$, $expl$Parlamento yasaları oylar ve Hükümetin eylemlerini denetler. Fransa'da yasama yetkisini kullanır.$expl$, $choices$[{"id":"a","text":"Yasaları oylamak ve Hükümetin eylemlerini denetlemek"},{"id":"b","text":"Orduyu yönetmek"},{"id":"c","text":"Hâkimleri atamak"},{"id":"d","text":"Yerel vergileri yönetmek"}]$choices$),
(125, 'en', $text$What is the political regime of France today?$text$, $expl$France is a democratic republic. Its regime is a representative democracy in which citizens elect their representatives.$expl$, $choices$[{"id":"a","text":"A democratic republic"},{"id":"b","text":"A constitutional monarchy"},{"id":"c","text":"A dictatorship"},{"id":"d","text":"An empire"}]$choices$),
(125, 'tr', $text$Bugün Fransa'nın siyasi rejimi nedir?$text$, $expl$Fransa demokratik bir cumhuriyettir. Rejimi, vatandaşların temsilcilerini seçtiği temsili bir demokrasidir.$expl$, $choices$[{"id":"a","text":"Demokratik bir cumhuriyet"},{"id":"b","text":"Anayasal bir monarşi"},{"id":"c","text":"Bir diktatörlük"},{"id":"d","text":"Bir imparatorluk"}]$choices$),
(126, 'en', $text$How many States are part of the European Union as of 1 January 2025?$text$, $expl$The European Union has 27 member States as of 1 January 2025, since the departure of the United Kingdom in 2020.$expl$, $choices$[{"id":"a","text":"27"},{"id":"b","text":"28"},{"id":"c","text":"25"},{"id":"d","text":"30"}]$choices$),
(126, 'tr', $text$1 Ocak 2025 itibarıyla Avrupa Birliği'ne kaç Devlet üyedir?$text$, $expl$Birleşik Krallık'ın 2020'de ayrılmasından bu yana, 1 Ocak 2025 itibarıyla Avrupa Birliği'nin 27 üye Devleti vardır.$expl$, $choices$[{"id":"a","text":"27"},{"id":"b","text":"28"},{"id":"c","text":"25"},{"id":"d","text":"30"}]$choices$),
(127, 'en', $text$Which State is not a member of the European Union?$text$, $expl$Switzerland is not a member of the European Union. It chose to remain outside the EU while maintaining bilateral agreements.$expl$, $choices$[{"id":"a","text":"Switzerland"},{"id":"b","text":"Germany"},{"id":"c","text":"Italy"},{"id":"d","text":"Spain"}]$choices$),
(127, 'tr', $text$Hangi Devlet Avrupa Birliği üyesi değildir?$text$, $expl$İsviçre, Avrupa Birliği üyesi değildir. İkili anlaşmaları sürdürürken AB'nin dışında kalmayı tercih etmiştir.$expl$, $choices$[{"id":"a","text":"İsviçre"},{"id":"b","text":"Almanya"},{"id":"c","text":"İtalya"},{"id":"d","text":"İspanya"}]$choices$),
(128, 'en', $text$What condition is required to vote in the European elections?$text$, $expl$To vote in the European elections, one must be a citizen of a member State of the European Union and be registered on the electoral rolls.$expl$, $choices$[{"id":"a","text":"To be a citizen of a member State of the European Union"},{"id":"b","text":"To be a French citizen only"},{"id":"c","text":"To reside in France for more than 10 years"},{"id":"d","text":"To be over 21 years old"}]$choices$),
(128, 'tr', $text$Avrupa seçimlerinde oy kullanmak için hangi koşul gereklidir?$text$, $expl$Avrupa seçimlerinde oy kullanmak için Avrupa Birliği üye Devletlerinden birinin vatandaşı olmak ve seçmen kütüğüne kayıtlı olmak gerekir.$expl$, $choices$[{"id":"a","text":"Avrupa Birliği üye Devletlerinden birinin vatandaşı olmak"},{"id":"b","text":"Yalnızca Fransız vatandaşı olmak"},{"id":"c","text":"Fransa'da 10 yıldan uzun süredir ikamet etmek"},{"id":"d","text":"21 yaşından büyük olmak"}]$choices$),
(129, 'en', $text$How often are the European elections held?$text$, $expl$The European elections are held every 5 years. EU citizens elect the members of the European Parliament (MEPs) who sit in the European Parliament.$expl$, $choices$[{"id":"a","text":"Every 5 years"},{"id":"b","text":"Every 4 years"},{"id":"c","text":"Every 6 years"},{"id":"d","text":"Every 3 years"}]$choices$),
(129, 'tr', $text$Avrupa seçimleri ne sıklıkla düzenlenir?$text$, $expl$Avrupa seçimleri her 5 yılda bir düzenlenir. AB vatandaşları, Avrupa Parlamentosu'nda görev yapan Avrupa Parlamentosu milletvekillerini seçer.$expl$, $choices$[{"id":"a","text":"Her 5 yılda bir"},{"id":"b","text":"Her 4 yılda bir"},{"id":"c","text":"Her 6 yılda bir"},{"id":"d","text":"Her 3 yılda bir"}]$choices$),
(130, 'en', $text$Which country is a founding country of the European Union?$text$, $expl$France is one of the six founding countries of European construction (along with Germany, Italy, Belgium, the Netherlands and Luxembourg), signatories of the Treaty of Rome in 1957.$expl$, $choices$[{"id":"a","text":"France"},{"id":"b","text":"Spain"},{"id":"c","text":"The United Kingdom"},{"id":"d","text":"Poland"}]$choices$),
(130, 'tr', $text$Hangi ülke Avrupa Birliği'nin kurucu ülkelerinden biridir?$text$, $expl$Fransa, 1957'de Roma Antlaşması'nı imzalayan Avrupa inşasının altı kurucu ülkesinden biridir (Almanya, İtalya, Belçika, Hollanda ve Lüksemburg ile birlikte).$expl$, $choices$[{"id":"a","text":"Fransa"},{"id":"b","text":"İspanya"},{"id":"c","text":"Birleşik Krallık"},{"id":"d","text":"Polonya"}]$choices$),
(131, 'en', $text$What is the currency used in France?$text$, $expl$The euro is the currency used in France since 1 January 2002. It is the common currency of many countries of the European Union.$expl$, $choices$[{"id":"a","text":"The euro"},{"id":"b","text":"The franc"},{"id":"c","text":"The pound"},{"id":"d","text":"The dollar"}]$choices$),
(131, 'tr', $text$Fransa'da kullanılan para birimi nedir?$text$, $expl$Avro, 1 Ocak 2002'den beri Fransa'da kullanılan para birimidir. Avrupa Birliği'nin birçok ülkesinin ortak para birimidir.$expl$, $choices$[{"id":"a","text":"Avro"},{"id":"b","text":"Frank"},{"id":"c","text":"Sterlin"},{"id":"d","text":"Dolar"}]$choices$),
(132, 'en', $text$Who elects the members of the European Parliament?$text$, $expl$The members of the European Parliament are elected by the citizens of the member States of the European Union by direct universal suffrage.$expl$, $choices$[{"id":"a","text":"The citizens of the member States of the European Union"},{"id":"b","text":"The heads of State of the member countries"},{"id":"c","text":"The European Commission"},{"id":"d","text":"The national parliaments"}]$choices$),
(132, 'tr', $text$Avrupa Parlamentosu milletvekillerini kim seçer?$text$, $expl$Avrupa Parlamentosu milletvekilleri, Avrupa Birliği üye Devletlerinin vatandaşları tarafından doğrudan genel oyla seçilir.$expl$, $choices$[{"id":"a","text":"Avrupa Birliği üye Devletlerinin vatandaşları"},{"id":"b","text":"Üye ülkelerin Devlet başkanları"},{"id":"c","text":"Avrupa Komisyonu"},{"id":"d","text":"Ulusal parlamentolar"}]$choices$),
(133, 'en', $text$When is Europe Day celebrated?$text$, $expl$Europe Day is celebrated on 9 May. It commemorates the Schuman Declaration of 9 May 1950, considered to be the founding act of European construction.$expl$, $choices$[{"id":"a","text":"9 May"},{"id":"b","text":"14 July"},{"id":"c","text":"1 January"},{"id":"d","text":"25 March"}]$choices$),
(133, 'tr', $text$Avrupa Günü ne zaman kutlanır?$text$, $expl$Avrupa Günü 9 Mayıs'ta kutlanır. Avrupa inşasının kurucu eylemi olarak kabul edilen 9 Mayıs 1950 tarihli Schuman Bildirgesi'ni anmaktadır.$expl$, $choices$[{"id":"a","text":"9 Mayıs"},{"id":"b","text":"14 Temmuz"},{"id":"c","text":"1 Ocak"},{"id":"d","text":"25 Mart"}]$choices$),
(134, 'en', $text$What is the rule of law (État de droit)?$text$, $expl$The rule of law is a system in which public authorities are subject to compliance with the law. Every person, including the State, must comply with the laws.$expl$, $choices$[{"id":"a","text":"A State in which public authorities are subject to compliance with the law"},{"id":"b","text":"A State in which only the president decides on the laws"},{"id":"c","text":"A State without a Constitution"},{"id":"d","text":"A State in which judges make the laws"}]$choices$),
(134, 'tr', $text$Hukuk devleti (État de droit) nedir?$text$, $expl$Hukuk devleti, kamu otoritelerinin hukuka uymakla yükümlü olduğu bir sistemdir. Devlet dahil herkes yasalara uymak zorundadır.$expl$, $choices$[{"id":"a","text":"Kamu otoritelerinin hukuka uymakla yükümlü olduğu bir Devlet"},{"id":"b","text":"Yalnızca cumhurbaşkanının yasalara karar verdiği bir Devlet"},{"id":"c","text":"Anayasasız bir Devlet"},{"id":"d","text":"Hâkimlerin yasaları yaptığı bir Devlet"}]$choices$),
(135, 'en', $text$The President of the Republic has committed a crime. Which statement is correct?$text$, $expl$The President of the Republic may be judged after the end of their term. During their term, they enjoy temporary immunity, but they are not above the law.$expl$, $choices$[{"id":"a","text":"They may be judged after the end of their term"},{"id":"b","text":"They can never be judged"},{"id":"c","text":"They are immediately arrested"},{"id":"d","text":"They are judged by Parliament alone"}]$choices$),
(135, 'tr', $text$Cumhurbaşkanı bir suç işlemiştir. Hangi ifade doğrudur?$text$, $expl$Cumhurbaşkanı, görev süresinin sona ermesinden sonra yargılanabilir. Görev süresi boyunca geçici dokunulmazlığa sahiptir, ancak yasaların üstünde değildir.$expl$, $choices$[{"id":"a","text":"Görev süresinin sona ermesinden sonra yargılanabilir"},{"id":"b","text":"Asla yargılanamaz"},{"id":"c","text":"Derhal tutuklanır"},{"id":"d","text":"Yalnızca Parlamento tarafından yargılanır"}]$choices$),
(136, 'en', $text$The law is the expression of:$text$, $expl$The law is the expression of the general will, as stated in article 6 of the Declaration of the Rights of Man and of the Citizen of 1789.$expl$, $choices$[{"id":"a","text":"The general will"},{"id":"b","text":"The will of the president"},{"id":"c","text":"The will of the judges"},{"id":"d","text":"The will of the Government"}]$choices$),
(136, 'tr', $text$Yasa şunun ifadesidir:$text$, $expl$Yasa, 1789 İnsan ve Yurttaş Hakları Bildirgesi'nin 6. maddesinde belirtildiği gibi, genel iradenin ifadesidir.$expl$, $choices$[{"id":"a","text":"Genel iradenin"},{"id":"b","text":"Cumhurbaşkanının iradesinin"},{"id":"c","text":"Hâkimlerin iradesinin"},{"id":"d","text":"Hükümetin iradesinin"}]$choices$),
(137, 'en', $text$What is the duration of the term of the municipal council and the mayor?$text$, $expl$The municipal council and the mayor are elected for a 6-year term. Municipal elections take place every 6 years.$expl$, $choices$[{"id":"a","text":"6 years"},{"id":"b","text":"5 years"},{"id":"c","text":"4 years"},{"id":"d","text":"7 years"}]$choices$),
(137, 'tr', $text$Belediye meclisi ve belediye başkanının görev süresi ne kadardır?$text$, $expl$Belediye meclisi ve belediye başkanı 6 yıllık bir görev süresi için seçilir. Belediye seçimleri her 6 yılda bir yapılır.$expl$, $choices$[{"id":"a","text":"6 yıl"},{"id":"b","text":"5 yıl"},{"id":"c","text":"4 yıl"},{"id":"d","text":"7 yıl"}]$choices$),
(138, 'en', $text$What does the rule of law guarantee?$text$, $expl$The rule of law guarantees respect for fundamental rights and individual freedoms. It ensures that no one, not even the State, is above the law.$expl$, $choices$[{"id":"a","text":"Respect for fundamental rights and individual freedoms"},{"id":"b","text":"A job for every citizen"},{"id":"c","text":"Free access to all public services"},{"id":"d","text":"The complete absence of taxes"}]$choices$),
(138, 'tr', $text$Hukuk devleti neyi güvence altına alır?$text$, $expl$Hukuk devleti, temel haklara ve bireysel özgürlüklere saygıyı güvence altına alır. Devlet dahil hiç kimsenin yasaların üstünde olmamasını sağlar.$expl$, $choices$[{"id":"a","text":"Temel haklara ve bireysel özgürlüklere saygı"},{"id":"b","text":"Tüm vatandaşlar için bir iş"},{"id":"c","text":"Tüm kamu hizmetlerinin ücretsiz olması"},{"id":"d","text":"Vergilerin tamamen ortadan kalkması"}]$choices$),
(139, 'en', $text$May a person vote in place of another?$text$, $expl$Yes, it is possible to vote by proxy. A voter who is unable to vote may grant proxy to another voter registered in the same commune to vote on their behalf.$expl$, $choices$[{"id":"a","text":"Yes, by proxy"},{"id":"b","text":"No, never"},{"id":"c","text":"Yes, without any formalities"},{"id":"d","text":"Yes, only for family members"}]$choices$),
(139, 'tr', $text$Bir kişi başkasının yerine oy kullanabilir mi?$text$, $expl$Evet, vekaletle oy kullanmak mümkündür. Oy kullanamayan bir seçmen, kendisi yerine oy kullanması için aynı commune'de kayıtlı başka bir seçmene vekalet verebilir.$expl$, $choices$[{"id":"a","text":"Evet, vekaletle"},{"id":"b","text":"Hayır, asla"},{"id":"c","text":"Evet, hiçbir formalite olmadan"},{"id":"d","text":"Evet, yalnızca aile üyeleri için"}]$choices$),
(140, 'en', $text$Is voting compulsory?$text$, $expl$No, voting is not compulsory in France. It is a right and not a legal obligation, but it is a civic duty.$expl$, $choices$[{"id":"a","text":"No, it is not compulsory but it is a civic duty"},{"id":"b","text":"Yes, it is compulsory for all"},{"id":"c","text":"Yes, under penalty of a fine"},{"id":"d","text":"Yes, except for elderly people"}]$choices$),
(140, 'tr', $text$Oy kullanmak zorunlu mudur?$text$, $expl$Hayır, Fransa'da oy kullanmak zorunlu değildir. Yasal bir yükümlülük değil bir haktır, ancak medeni bir görevdir.$expl$, $choices$[{"id":"a","text":"Hayır, zorunlu değildir ancak medeni bir görevdir"},{"id":"b","text":"Evet, herkes için zorunludur"},{"id":"c","text":"Evet, para cezası tehdidiyle"},{"id":"d","text":"Evet, yaşlı kişiler hariç"}]$choices$),
(141, 'en', $text$At the end of their term, may the President of the Republic decide to remain in power?$text$, $expl$No, the president cannot decide to remain in power at the end of their term. They must stand for re-election or leave office. This is a fundamental principle of democracy.$expl$, $choices$[{"id":"a","text":"No, they must stand for re-election or leave office"},{"id":"b","text":"Yes, if they so decide"},{"id":"c","text":"Yes, with the agreement of Parliament"},{"id":"d","text":"Yes, in case of national crisis"}]$choices$),
(141, 'tr', $text$Görev süresinin sonunda Cumhurbaşkanı iktidarda kalmaya karar verebilir mi?$text$, $expl$Hayır, cumhurbaşkanı görev süresinin sonunda iktidarda kalmaya karar veremez. Yeniden seçime girmek veya görevinden ayrılmak zorundadır. Bu, demokrasinin temel bir ilkesidir.$expl$, $choices$[{"id":"a","text":"Hayır, yeniden seçime girmek veya görevinden ayrılmak zorundadır"},{"id":"b","text":"Evet, kendisi karar verirse"},{"id":"c","text":"Evet, Parlamentonun onayıyla"},{"id":"d","text":"Evet, ulusal kriz durumunda"}]$choices$),
(142, 'en', $text$Who directs the action of the Government?$text$, $expl$The Prime Minister directs the action of the Government, in accordance with article 21 of the Constitution. They coordinate the action of the ministers.$expl$, $choices$[{"id":"a","text":"The Prime Minister"},{"id":"b","text":"The President of the Republic"},{"id":"c","text":"The president of the Assemblée nationale (the French National Assembly)"},{"id":"d","text":"The Minister of the Interior"}]$choices$),
(142, 'tr', $text$Hükümetin eylemini kim yönetir?$text$, $expl$Başbakan, Anayasa'nın 21. maddesine uygun olarak Hükümetin eylemini yönetir. Bakanların eylemini koordine eder.$expl$, $choices$[{"id":"a","text":"Başbakan"},{"id":"b","text":"Cumhurbaşkanı"},{"id":"c","text":"Assemblée nationale (Fransız Ulusal Meclisi) başkanı"},{"id":"d","text":"İçişleri Bakanı"}]$choices$),
(143, 'en', $text$What is the administrative organisation of France?$text$, $expl$France is organised into communes, départements and régions. These are the three levels of territorial authorities provided for by the Constitution.$expl$, $choices$[{"id":"a","text":"Communes, départements and régions"},{"id":"b","text":"Provinces, cantons and districts"},{"id":"c","text":"Cities, counties and States"},{"id":"d","text":"Arrondissements, prefectures and metropolises"}]$choices$),
(143, 'tr', $text$Fransa'nın idari örgütlenmesi nasıldır?$text$, $expl$Fransa, communes (en küçük idari birimler), départements ve régions (bölgeler) olarak örgütlenmiştir. Bunlar, Anayasa'da öngörülen üç düzey toprak yetkili kuruluşlarıdır.$expl$, $choices$[{"id":"a","text":"Communes, départements ve régions"},{"id":"b","text":"Vilayetler, kantonlar ve ilçeler"},{"id":"c","text":"Şehirler, kontluklar ve Devletler"},{"id":"d","text":"Arrondissementler, valilikler ve metropoller"}]$choices$),
(144, 'en', $text$What is the legislative power? The power:$text$, $expl$The legislative power is the power to make the laws. In France, it is exercised by Parliament (the Assemblée nationale and the Sénat).$expl$, $choices$[{"id":"a","text":"To make the laws"},{"id":"b","text":"To enforce the laws"},{"id":"c","text":"To judge offences"},{"id":"d","text":"To appoint ministers"}]$choices$),
(144, 'tr', $text$Yasama yetkisi nedir? Şu yetkidir:$text$, $expl$Yasama yetkisi, yasaları yapma yetkisidir. Fransa'da bu yetki Parlamento (Assemblée nationale ve Sénat) tarafından kullanılır.$expl$, $choices$[{"id":"a","text":"Yasaları yapma"},{"id":"b","text":"Yasaları uygulama"},{"id":"c","text":"Suçları yargılama"},{"id":"d","text":"Bakanları atama"}]$choices$),
(145, 'en', $text$Why separate the three powers in a democracy?$text$, $expl$The separation of powers prevents a single person or institution from concentrating all the powers. It is a safeguard against the abuse of power and tyranny.$expl$, $choices$[{"id":"a","text":"To prevent the concentration of powers and protect freedoms"},{"id":"b","text":"To create more public-sector jobs"},{"id":"c","text":"To slow down decisions"},{"id":"d","text":"To increase the number of elections"}]$choices$),
(145, 'tr', $text$Bir demokraside üç gücü neden ayırmak gerekir?$text$, $expl$Kuvvetler ayrılığı, tek bir kişinin veya kurumun tüm yetkileri elinde toplamasını önler. Yetki istismarına ve tiranlığa karşı bir güvencedir.$expl$, $choices$[{"id":"a","text":"Yetkilerin toplanmasını önlemek ve özgürlükleri korumak için"},{"id":"b","text":"Daha fazla kamu sektörü işi yaratmak için"},{"id":"c","text":"Kararların daha yavaş alınması için"},{"id":"d","text":"Seçim sayısını artırmak için"}]$choices$),
(146, 'en', $text$What is the role of the Government?$text$, $expl$The Government determines and conducts the policy of the nation. It has at its disposal the administration and the armed forces (article 20 of the Constitution).$expl$, $choices$[{"id":"a","text":"To determine and conduct the policy of the nation"},{"id":"b","text":"To vote on the laws"},{"id":"c","text":"To judge criminals"},{"id":"d","text":"To elect the President of the Republic"}]$choices$),
(146, 'tr', $text$Hükümetin rolü nedir?$text$, $expl$Hükümet, ulusun politikasını belirler ve yürütür. İdareye ve silahlı kuvvetlere sahiptir (Anayasa'nın 20. maddesi).$expl$, $choices$[{"id":"a","text":"Ulusun politikasını belirlemek ve yürütmek"},{"id":"b","text":"Yasaları oylamak"},{"id":"c","text":"Suçluları yargılamak"},{"id":"d","text":"Cumhurbaşkanını seçmek"}]$choices$),
(147, 'en', $text$What is the Hôtel de Matignon?$text$, $expl$The Hôtel de Matignon is the official residence and workplace of the Prime Minister, located in Paris in the 7th arrondissement.$expl$, $choices$[{"id":"a","text":"The official residence of the Prime Minister"},{"id":"b","text":"The residence of the President of the Republic"},{"id":"c","text":"The seat of the Assemblée nationale (the French National Assembly)"},{"id":"d","text":"The seat of the Conseil constitutionnel (the Constitutional Council)"}]$choices$),
(147, 'tr', $text$Hôtel de Matignon nedir?$text$, $expl$Hôtel de Matignon, Paris'in 7. arrondissement'ında bulunan Başbakanın resmi konutu ve çalışma yeridir.$expl$, $choices$[{"id":"a","text":"Başbakanın resmi konutu"},{"id":"b","text":"Cumhurbaşkanının konutu"},{"id":"c","text":"Assemblée nationale (Fransız Ulusal Meclisi) merkezi"},{"id":"d","text":"Conseil constitutionnel (Anayasa Konseyi) merkezi"}]$choices$),
(148, 'en', $text$What is the role of the President of the Republic?$text$, $expl$The President of the Republic ensures respect for the Constitution, ensures the functioning of public authorities and the continuity of the State. They are the guarantor of national independence.$expl$, $choices$[{"id":"a","text":"To ensure respect for the Constitution and guarantee national independence"},{"id":"b","text":"To vote on the laws in Parliament"},{"id":"c","text":"To direct the courts"},{"id":"d","text":"To manage the communes"}]$choices$),
(148, 'tr', $text$Cumhurbaşkanının rolü nedir?$text$, $expl$Cumhurbaşkanı, Anayasa'ya saygıyı sağlar, kamu otoritelerinin işleyişini ve Devletin sürekliliğini güvence altına alır. Ulusal bağımsızlığın güvencesidir.$expl$, $choices$[{"id":"a","text":"Anayasa'ya saygıyı sağlamak ve ulusal bağımsızlığı güvence altına almak"},{"id":"b","text":"Parlamentoda yasaları oylamak"},{"id":"c","text":"Mahkemeleri yönetmek"},{"id":"d","text":"Communes'ları yönetmek"}]$choices$),
(149, 'en', $text$What is the role of the Prime Minister?$text$, $expl$The Prime Minister directs the action of the Government. They are accountable to the Assemblée nationale (the French National Assembly) and ensure the execution of the laws.$expl$, $choices$[{"id":"a","text":"To direct the action of the Government"},{"id":"b","text":"To preside over the Conseil constitutionnel (the Constitutional Council)"},{"id":"c","text":"To vote on the laws"},{"id":"d","text":"To command the armed forces"}]$choices$),
(149, 'tr', $text$Başbakanın rolü nedir?$text$, $expl$Başbakan, Hükümetin eylemini yönetir. Assemblée nationale'e (Fransız Ulusal Meclisi) karşı sorumludur ve yasaların uygulanmasını sağlar.$expl$, $choices$[{"id":"a","text":"Hükümetin eylemini yönetmek"},{"id":"b","text":"Conseil constitutionnel'e (Anayasa Konseyi) başkanlık etmek"},{"id":"c","text":"Yasaları oylamak"},{"id":"d","text":"Silahlı kuvvetlere komuta etmek"}]$choices$),
(150, 'en', $text$Who is the head of the Government?$text$, $expl$The Prime Minister is the head of the Government. They direct the action of the Government and coordinate the work of the ministers.$expl$, $choices$[{"id":"a","text":"The Prime Minister"},{"id":"b","text":"The President of the Republic"},{"id":"c","text":"The president of the Assemblée nationale (the French National Assembly)"},{"id":"d","text":"The Minister of the Interior"}]$choices$),
(150, 'tr', $text$Hükümetin başı kimdir?$text$, $expl$Başbakan, Hükümetin başıdır. Hükümetin eylemini yönetir ve bakanların çalışmalarını koordine eder.$expl$, $choices$[{"id":"a","text":"Başbakan"},{"id":"b","text":"Cumhurbaşkanı"},{"id":"c","text":"Assemblée nationale (Fransız Ulusal Meclisi) başkanı"},{"id":"d","text":"İçişleri Bakanı"}]$choices$),
(151, 'en', $text$How many régions (administrative regions) are there in France?$text$, $expl$France has 18 régions: 13 metropolitan régions (including Corsica) and 5 overseas régions.$expl$, $choices$[{"id":"a","text":"18"},{"id":"b","text":"13"},{"id":"c","text":"22"},{"id":"d","text":"15"}]$choices$),
(151, 'tr', $text$Fransa'da kaç région (idari bölge) vardır?$text$, $expl$Fransa'nın 18 région'u vardır: 13 anakara région'u (Korsika dahil) ve 5 deniz aşırı région.$expl$, $choices$[{"id":"a","text":"18"},{"id":"b","text":"13"},{"id":"c","text":"22"},{"id":"d","text":"15"}]$choices$),
(152, 'en', $text$What is the role of the Défenseur des droits (the Defender of Rights)?$text$, $expl$The Défenseur des droits is an independent authority responsible for ensuring respect for rights and freedoms. It may be referred to by any person who considers themselves to have been wronged by a public service.$expl$, $choices$[{"id":"a","text":"To ensure respect for the rights and freedoms of citizens"},{"id":"b","text":"To vote on the laws"},{"id":"c","text":"To command the army"},{"id":"d","text":"To manage the State budget"}]$choices$),
(152, 'tr', $text$Défenseur des droits'nın (Haklar Savunucusu) rolü nedir?$text$, $expl$Défenseur des droits, haklar ve özgürlüklere saygının sağlanmasından sorumlu bağımsız bir otoritedir. Bir kamu hizmeti tarafından zarar gördüğünü düşünen herhangi bir kişi tarafından başvurulabilir.$expl$, $choices$[{"id":"a","text":"Vatandaşların haklarına ve özgürlüklerine saygıyı sağlamak"},{"id":"b","text":"Yasaları oylamak"},{"id":"c","text":"Orduya komuta etmek"},{"id":"d","text":"Devlet bütçesini yönetmek"}]$choices$),
(153, 'en', $text$Since when has the euro been the single currency?$text$, $expl$The euro became the single currency in circulation on 1 January 2002. It had been introduced as scriptural money in 1999.$expl$, $choices$[{"id":"a","text":"1 January 2002"},{"id":"b","text":"1 January 1999"},{"id":"c","text":"1 January 1992"},{"id":"d","text":"1 January 2005"}]$choices$),
(153, 'tr', $text$Avro ne zamandan beri ortak para birimidir?$text$, $expl$Avro, 1 Ocak 2002'de dolaşımdaki ortak para birimi hâline gelmiştir. 1999'da kaydi para olarak başlatılmıştı.$expl$, $choices$[{"id":"a","text":"1 Ocak 2002"},{"id":"b","text":"1 Ocak 1999"},{"id":"c","text":"1 Ocak 1992"},{"id":"d","text":"1 Ocak 2005"}]$choices$),
(154, 'en', $text$What is the main role of the département?$text$, $expl$The département's main role is social action and solidarity (social assistance, RSA, child protection). It also manages middle schools and departmental roads.$expl$, $choices$[{"id":"a","text":"Social action and solidarity"},{"id":"b","text":"National defence"},{"id":"c","text":"Foreign policy"},{"id":"d","text":"Management of universities"}]$choices$),
(154, 'tr', $text$Département'ın temel rolü nedir?$text$, $expl$Département'ın temel rolü sosyal eylem ve dayanışmadır (sosyal yardım, RSA, çocuk koruma). Ayrıca ortaokulları ve département yollarını yönetir.$expl$, $choices$[{"id":"a","text":"Sosyal eylem ve dayanışma"},{"id":"b","text":"Ulusal savunma"},{"id":"c","text":"Dış politika"},{"id":"d","text":"Üniversitelerin yönetimi"}]$choices$),
(155, 'en', $text$What is the main role of the communes?$text$, $expl$Communes manage local services: civil registration, nursery and primary schools, urban planning, municipal road maintenance, water and sanitation.$expl$, $choices$[{"id":"a","text":"To manage local services (civil registration, schools, urban planning)"},{"id":"b","text":"To organise national defence"},{"id":"c","text":"To manage hospitals"},{"id":"d","text":"To collect national taxes"}]$choices$),
(155, 'tr', $text$Communes'ların temel rolü nedir?$text$, $expl$Communes yerel hizmetleri yönetir: nüfus kayıtları, anaokulları ve ilkokullar, şehir planlaması, belediye karayolları, su ve atık su.$expl$, $choices$[{"id":"a","text":"Yerel hizmetleri yönetmek (nüfus kayıtları, okullar, şehir planlaması)"},{"id":"b","text":"Ulusal savunmayı düzenlemek"},{"id":"c","text":"Hastaneleri yönetmek"},{"id":"d","text":"Ulusal vergileri toplamak"}]$choices$),
(156, 'en', $text$Approximately how many communes are there in France?$text$, $expl$France has approximately 35,000 communes, making it the European country with the largest number of communes.$expl$, $choices$[{"id":"a","text":"Approximately 35,000"},{"id":"b","text":"Approximately 10,000"},{"id":"c","text":"Approximately 5,000"},{"id":"d","text":"Approximately 50,000"}]$choices$),
(156, 'tr', $text$Fransa'da yaklaşık kaç commune vardır?$text$, $expl$Fransa'nın yaklaşık 35.000 commune'i vardır; bu da onu Avrupa'da en fazla commune'e sahip ülke yapar.$expl$, $choices$[{"id":"a","text":"Yaklaşık 35.000"},{"id":"b","text":"Yaklaşık 10.000"},{"id":"c","text":"Yaklaşık 5.000"},{"id":"d","text":"Yaklaşık 50.000"}]$choices$),
(157, 'en', $text$Which treaty concerns the construction of the European Union?$text$, $expl$The Treaty of Maastricht (1992) is the founding treaty of the European Union. It established European citizenship and laid the foundations for the single currency.$expl$, $choices$[{"id":"a","text":"The Treaty of Maastricht"},{"id":"b","text":"The Treaty of Versailles"},{"id":"c","text":"The Treaty of Westphalia"},{"id":"d","text":"The Treaty of Vienna"}]$choices$),
(157, 'tr', $text$Hangi antlaşma Avrupa Birliği'nin inşasıyla ilgilidir?$text$, $expl$Maastricht Antlaşması (1992), Avrupa Birliği'nin kurucu antlaşmasıdır. Avrupa vatandaşlığını oluşturmuş ve ortak para biriminin temellerini atmıştır.$expl$, $choices$[{"id":"a","text":"Maastricht Antlaşması"},{"id":"b","text":"Versailles Antlaşması"},{"id":"c","text":"Westfalya Antlaşması"},{"id":"d","text":"Viyana Antlaşması"}]$choices$),
(158, 'en', $text$Which State left the European Union in 2020?$text$, $expl$The United Kingdom left the European Union on 31 January 2020, following the Brexit referendum of 2016.$expl$, $choices$[{"id":"a","text":"The United Kingdom"},{"id":"b","text":"Norway"},{"id":"c","text":"Switzerland"},{"id":"d","text":"Iceland"}]$choices$),
(158, 'tr', $text$2020'de Avrupa Birliği'nden hangi Devlet ayrıldı?$text$, $expl$Birleşik Krallık, 2016 Brexit referandumunun ardından 31 Ocak 2020'de Avrupa Birliği'nden ayrıldı.$expl$, $choices$[{"id":"a","text":"Birleşik Krallık"},{"id":"b","text":"Norveç"},{"id":"c","text":"İsviçre"},{"id":"d","text":"İzlanda"}]$choices$),
(159, 'en', $text$What is the motto of the European Union?$text$, $expl$The motto of the European Union is "United in diversity". It symbolises the unity of the peoples of Europe in respect for their cultural differences.$expl$, $choices$[{"id":"a","text":"United in diversity"},{"id":"b","text":"Liberty, Equality, Fraternity"},{"id":"c","text":"Peace and prosperity"},{"id":"d","text":"Unity makes strength"}]$choices$),
(159, 'tr', $text$Avrupa Birliği'nin sloganı nedir?$text$, $expl$Avrupa Birliği'nin sloganı "Çeşitlilik içinde birlik"tir. Avrupa halklarının kültürel farklılıklarına saygı çerçevesinde birliğini simgeler.$expl$, $choices$[{"id":"a","text":"Çeşitlilik içinde birlik"},{"id":"b","text":"Özgürlük, Eşitlik, Kardeşlik"},{"id":"c","text":"Barış ve refah"},{"id":"d","text":"Birlikten kuvvet doğar"}]$choices$),
(160, 'en', $text$What is the anthem of the European Union?$text$, $expl$The anthem of the European Union is the Ode to Joy, taken from Ludwig van Beethoven's 9th Symphony. It was adopted by the Council of Europe in 1972.$expl$, $choices$[{"id":"a","text":"Beethoven's Ode to Joy"},{"id":"b","text":"La Marseillaise"},{"id":"c","text":"Ravel's Bolero"},{"id":"d","text":"Vivaldi's Four Seasons"}]$choices$),
(160, 'tr', $text$Avrupa Birliği'nin marşı nedir?$text$, $expl$Avrupa Birliği'nin marşı, Ludwig van Beethoven'ın 9. Senfonisinden alınan Neşeye Övgü'dür (Ode an die Freude). 1972'de Avrupa Konseyi tarafından kabul edilmiştir.$expl$, $choices$[{"id":"a","text":"Beethoven'ın Neşeye Övgü'sü"},{"id":"b","text":"La Marseillaise"},{"id":"c","text":"Ravel'in Bolero'su"},{"id":"d","text":"Vivaldi'nin Dört Mevsim'i"}]$choices$),
(161, 'en', $text$What is the composition of the European flag?$text$, $expl$The European flag is composed of 12 golden stars arranged in a circle on a blue background. The number 12 symbolises perfection and unity; it does not correspond to the number of member States.$expl$, $choices$[{"id":"a","text":"12 golden stars arranged in a circle on a blue background"},{"id":"b","text":"27 stars on a blue background"},{"id":"c","text":"Blue and white horizontal stripes"},{"id":"d","text":"15 golden stars on a red background"}]$choices$),
(161, 'tr', $text$Avrupa bayrağı neyden oluşur?$text$, $expl$Avrupa bayrağı, mavi zemin üzerine daire şeklinde dizilmiş 12 altın yıldızdan oluşur. 12 sayısı mükemmelliği ve birliği simgeler; üye Devletlerin sayısına karşılık gelmez.$expl$, $choices$[{"id":"a","text":"Mavi zemin üzerine daire şeklinde dizilmiş 12 altın yıldız"},{"id":"b","text":"Mavi zemin üzerine 27 yıldız"},{"id":"c","text":"Mavi ve beyaz yatay şeritler"},{"id":"d","text":"Kırmızı zemin üzerine 15 altın yıldız"}]$choices$),
(162, 'en', $text$What colour is the European flag?$text$, $expl$The European flag is blue with golden (yellow) stars. The blue background represents the sky and the stars symbolise the unity of the peoples of Europe.$expl$, $choices$[{"id":"a","text":"Blue with golden stars"},{"id":"b","text":"Red with white stars"},{"id":"c","text":"Green with golden stars"},{"id":"d","text":"White with blue stars"}]$choices$),
(162, 'tr', $text$Avrupa bayrağı hangi renktedir?$text$, $expl$Avrupa bayrağı, altın (sarı) yıldızlarla birlikte mavidir. Mavi zemin gökyüzünü temsil eder ve yıldızlar Avrupa halklarının birliğini simgeler.$expl$, $choices$[{"id":"a","text":"Altın yıldızlarla mavi"},{"id":"b","text":"Beyaz yıldızlarla kırmızı"},{"id":"c","text":"Altın yıldızlarla yeşil"},{"id":"d","text":"Mavi yıldızlarla beyaz"}]$choices$),
(163, 'en', $text$In which year was the Treaty of Maastricht signed?$text$, $expl$The Treaty of Maastricht was signed on 7 February 1992. It created the European Union and laid the foundations for the single currency (the euro).$expl$, $choices$[{"id":"a","text":"1992"},{"id":"b","text":"1957"},{"id":"c","text":"1989"},{"id":"d","text":"2000"}]$choices$),
(163, 'tr', $text$Maastricht Antlaşması hangi yılda imzalanmıştır?$text$, $expl$Maastricht Antlaşması 7 Şubat 1992'de imzalanmıştır. Avrupa Birliği'ni kurmuş ve ortak para biriminin (avro) temellerini atmıştır.$expl$, $choices$[{"id":"a","text":"1992"},{"id":"b","text":"1957"},{"id":"c","text":"1989"},{"id":"d","text":"2000"}]$choices$),
(164, 'en', $text$Where is the seat of the European Parliament?$text$, $expl$The seat of the European Parliament is in Strasbourg (France). Sessions also take place in Brussels (Belgium).$expl$, $choices$[{"id":"a","text":"In Strasbourg"},{"id":"b","text":"In Brussels"},{"id":"c","text":"In Luxembourg"},{"id":"d","text":"In Berlin"}]$choices$),
(164, 'tr', $text$Avrupa Parlamentosu'nun merkezi neresidir?$text$, $expl$Avrupa Parlamentosu'nun merkezi Strazburg'tadır (Fransa). Oturumlar Brüksel'de de (Belçika) yapılır.$expl$, $choices$[{"id":"a","text":"Strazburg'ta"},{"id":"b","text":"Brüksel'de"},{"id":"c","text":"Lüksemburg'ta"},{"id":"d","text":"Berlin'de"}]$choices$),
(165, 'en', $text$Where is the seat of the European Commission?$text$, $expl$The seat of the European Commission is in Brussels (Belgium). The Commission is the executive body of the European Union.$expl$, $choices$[{"id":"a","text":"In Brussels"},{"id":"b","text":"In Strasbourg"},{"id":"c","text":"In Luxembourg"},{"id":"d","text":"In Paris"}]$choices$),
(165, 'tr', $text$Avrupa Komisyonu'nun merkezi neresidir?$text$, $expl$Avrupa Komisyonu'nun merkezi Brüksel'dedir (Belçika). Komisyon, Avrupa Birliği'nin yürütme organıdır.$expl$, $choices$[{"id":"a","text":"Brüksel'de"},{"id":"b","text":"Strazburg'ta"},{"id":"c","text":"Lüksemburg'ta"},{"id":"d","text":"Paris'te"}]$choices$),
(166, 'en', $text$How is the Prime Minister designated?$text$, $expl$The Prime Minister is appointed by the President of the Republic. They are not elected directly by the citizens.$expl$, $choices$[{"id":"a","text":"They are appointed by the President of the Republic"},{"id":"b","text":"They are elected by direct universal suffrage"},{"id":"c","text":"They are elected by the members of Parliament (députés)"},{"id":"d","text":"They are designated by the Conseil constitutionnel (the Constitutional Council)"}]$choices$),
(166, 'tr', $text$Başbakan nasıl belirlenir?$text$, $expl$Başbakan, Cumhurbaşkanı tarafından atanır. Vatandaşlar tarafından doğrudan seçilmez.$expl$, $choices$[{"id":"a","text":"Cumhurbaşkanı tarafından atanır"},{"id":"b","text":"Doğrudan genel oyla seçilir"},{"id":"c","text":"Milletvekilleri (députés) tarafından seçilir"},{"id":"d","text":"Conseil constitutionnel (Anayasa Konseyi) tarafından belirlenir"}]$choices$),
(167, 'en', $text$Who may stand for the presidential elections?$text$, $expl$Any French citizen aged at least 18 and enjoying their civil and political rights may stand, provided they obtain 500 sponsorships from elected officials.$expl$, $choices$[{"id":"a","text":"Any French citizen who has obtained 500 sponsorships from elected officials"},{"id":"b","text":"Only members of a political party"},{"id":"c","text":"Only former ministers"},{"id":"d","text":"Only people over 40 years old"}]$choices$),
(167, 'tr', $text$Cumhurbaşkanlığı seçimlerine kimler aday olabilir?$text$, $expl$En az 18 yaşında olan ve medeni ile siyasi haklarını kullanan her Fransız vatandaşı, seçilmiş yetkililerden 500 destek (parrainage) almak koşuluyla aday olabilir.$expl$, $choices$[{"id":"a","text":"Seçilmiş yetkililerden 500 destek (parrainage) alan her Fransız vatandaşı"},{"id":"b","text":"Yalnızca bir siyasi partinin üyeleri"},{"id":"c","text":"Yalnızca eski bakanlar"},{"id":"d","text":"Yalnızca 40 yaşından büyük kişiler"}]$choices$),
(168, 'en', $text$To whom does national sovereignty belong?$text$, $expl$National sovereignty belongs to the people, who exercise it through their representatives and by way of referendum (article 3 of the Constitution).$expl$, $choices$[{"id":"a","text":"To the people"},{"id":"b","text":"To the President of the Republic"},{"id":"c","text":"To Parliament"},{"id":"d","text":"To the Government"}]$choices$),
(168, 'tr', $text$Ulusal egemenlik kime aittir?$text$, $expl$Ulusal egemenlik, temsilcileri ve referandum yoluyla bu egemenliği kullanan halka aittir (Anayasa'nın 3. maddesi).$expl$, $choices$[{"id":"a","text":"Halka"},{"id":"b","text":"Cumhurbaşkanına"},{"id":"c","text":"Parlamentoya"},{"id":"d","text":"Hükümete"}]$choices$),
(169, 'en', $text$Registration on the electoral rolls is:$text$, $expl$Registration on the electoral rolls is compulsory for any French citizen of legal age. Since 2019, registration has been automatic at 18.$expl$, $choices$[{"id":"a","text":"Compulsory"},{"id":"b","text":"Optional"},{"id":"c","text":"Automatic only for men"},{"id":"d","text":"Reserved for people over 21 years old"}]$choices$),
(169, 'tr', $text$Seçmen kütüğüne kayıt:$text$, $expl$Seçmen kütüğüne kayıt, her reşit Fransız vatandaşı için zorunludur. 2019'dan beri kayıt 18 yaşında otomatik olarak yapılmaktadır.$expl$, $choices$[{"id":"a","text":"Zorunludur"},{"id":"b","text":"İsteğe bağlıdır"},{"id":"c","text":"Yalnızca erkekler için otomatiktir"},{"id":"d","text":"21 yaşından büyükler için ayrılmıştır"}]$choices$),
(170, 'en', $text$What condition is required to vote in the presidential elections?$text$, $expl$To vote in the presidential elections, one must be of French nationality, at least 18 years old, enjoy one's civil and political rights, and be registered on the electoral rolls.$expl$, $choices$[{"id":"a","text":"To be of French nationality, of legal age, and registered on the electoral rolls"},{"id":"b","text":"To have been resident in France for at least 5 years"},{"id":"c","text":"To have a clean criminal record"},{"id":"d","text":"To hold a diploma"}]$choices$),
(170, 'tr', $text$Cumhurbaşkanlığı seçimlerinde oy kullanmak için hangi koşul gereklidir?$text$, $expl$Cumhurbaşkanlığı seçimlerinde oy kullanmak için Fransız vatandaşı, reşit (18 yaşını tamamlamış) olmak, medeni ve siyasi haklarını kullanmak ve seçmen kütüğüne kayıtlı olmak gerekir.$expl$, $choices$[{"id":"a","text":"Fransız vatandaşı, reşit ve seçmen kütüğüne kayıtlı olmak"},{"id":"b","text":"Fransa'da en az 5 yıldır ikamet etmek"},{"id":"c","text":"Temiz bir sabıka kaydına sahip olmak"},{"id":"d","text":"Bir diplomaya sahip olmak"}]$choices$),
(171, 'en', $text$What condition must one meet to stand as a candidate in the municipal elections?$text$, $expl$To stand as a candidate in the municipal elections, one must be at least 18 years old, be of French nationality or an EU citizen, and be registered on the electoral rolls of the commune or pay taxes there.$expl$, $choices$[{"id":"a","text":"Be 18 years old and registered on the electoral rolls of the commune"},{"id":"b","text":"Be 25 years old and have resided in the commune for 10 years"},{"id":"c","text":"Be a civil servant"},{"id":"d","text":"Be a property owner in the commune"}]$choices$),
(171, 'tr', $text$Belediye seçimlerine aday olmak için hangi koşulun karşılanması gerekir?$text$, $expl$Belediye seçimlerine aday olmak için 18 yaşını doldurmuş, Fransız vatandaşı veya AB vatandaşı olmak ve commune'ün seçmen kütüğüne kayıtlı olmak ya da orada vergi ödemek gerekir.$expl$, $choices$[{"id":"a","text":"18 yaşında ve commune'ün seçmen kütüğüne kayıtlı olmak"},{"id":"b","text":"25 yaşında ve commune'de 10 yıldır ikamet ediyor olmak"},{"id":"c","text":"Memur olmak"},{"id":"d","text":"Commune'de mülk sahibi olmak"}]$choices$),
(172, 'en', $text$Among these authorities, which one is elected?$text$, $expl$The mayor is elected by the municipal councillors. The préfet is appointed, the public prosecutor is a magistrate, and the school principal is a civil servant.$expl$, $choices$[{"id":"a","text":"The mayor"},{"id":"b","text":"The préfet (prefect)"},{"id":"c","text":"The public prosecutor"},{"id":"d","text":"The school principal"}]$choices$),
(172, 'tr', $text$Bu otoriteler arasında hangisi seçilmiştir?$text$, $expl$Belediye başkanı, belediye meclis üyeleri tarafından seçilir. Préfet atanır, savcı bir magistradır ve okul müdürü bir memurdur.$expl$, $choices$[{"id":"a","text":"Belediye başkanı"},{"id":"b","text":"Préfet (vali)"},{"id":"c","text":"Cumhuriyet savcısı"},{"id":"d","text":"Okul müdürü"}]$choices$),
(173, 'en', $text$What are the functions of the mayor?$text$, $expl$The mayor is at once a civil registrar, a representative of the State in the commune and the head of the municipal administration. They celebrate marriages and issue building permits.$expl$, $choices$[{"id":"a","text":"Civil registrar, representative of the State and head of the municipal administration"},{"id":"b","text":"Head of the national police and the fire brigade"},{"id":"c","text":"President of the commune's court"},{"id":"d","text":"Responsible for national education in the commune"}]$choices$),
(173, 'tr', $text$Belediye başkanının görevleri nelerdir?$text$, $expl$Belediye başkanı aynı anda nüfus memuru, commune'de Devletin temsilcisi ve belediye yönetiminin başıdır. Evlilikleri kıyar ve inşaat ruhsatlarını verir.$expl$, $choices$[{"id":"a","text":"Nüfus memuru, Devletin temsilcisi ve belediye yönetiminin başı"},{"id":"b","text":"Ulusal polis ve itfaiyenin başı"},{"id":"c","text":"Commune'ün mahkemesinin başkanı"},{"id":"d","text":"Commune'de ulusal eğitimden sorumlu"}]$choices$),
(174, 'en', $text$A person without access to the internet wishes to register on the electoral rolls. Where may they register?$text$, $expl$A person may register on the electoral rolls by going to the town hall (mairie) of their place of residence. Online registration is not the only option.$expl$, $choices$[{"id":"a","text":"At the town hall (mairie) of their place of residence"},{"id":"b","text":"At the prefecture only"},{"id":"c","text":"At the police station"},{"id":"d","text":"At the judicial court"}]$choices$),
(174, 'tr', $text$İnternet erişimi olmayan bir kişi seçmen kütüğüne kayıt olmak istiyor. Nerede kayıt olabilir?$text$, $expl$Bir kişi ikamet ettiği commune'ün belediyesine (mairie) giderek seçmen kütüğüne kayıt olabilir. Çevrimiçi kayıt tek seçenek değildir.$expl$, $choices$[{"id":"a","text":"İkamet ettiği commune'ün belediyesinde (mairie)"},{"id":"b","text":"Yalnızca valilikte"},{"id":"c","text":"Polis karakolunda"},{"id":"d","text":"Adli mahkemede"}]$choices$),
(175, 'en', $text$At what age can one become a voter?$text$, $expl$One can become a voter at 18 in France. This has been the age of civil and political majority since 1974.$expl$, $choices$[{"id":"a","text":"18 years old"},{"id":"b","text":"16 years old"},{"id":"c","text":"21 years old"},{"id":"d","text":"25 years old"}]$choices$),
(175, 'tr', $text$Kaç yaşında seçmen olunabilir?$text$, $expl$Fransa'da 18 yaşında seçmen olunabilir. Bu, 1974'ten beri medeni ve siyasi reşitlik yaşıdır.$expl$, $choices$[{"id":"a","text":"18 yaş"},{"id":"b","text":"16 yaş"},{"id":"c","text":"21 yaş"},{"id":"d","text":"25 yaş"}]$choices$),
(176, 'en', $text$In France, is voting compulsory?$text$, $expl$No, voting is not compulsory in France. It is a right and a civic duty, but there is no penalty for abstention.$expl$, $choices$[{"id":"a","text":"No, voting is a right but not a legal obligation"},{"id":"b","text":"Yes, under penalty of a fine"},{"id":"c","text":"Yes, under penalty of prison"},{"id":"d","text":"Yes, except for people over 70 years old"}]$choices$),
(176, 'tr', $text$Fransa'da oy kullanmak zorunlu mudur?$text$, $expl$Hayır, Fransa'da oy kullanmak zorunlu değildir. Bir hak ve medeni bir görevdir, ancak çekimser kalma durumunda hiçbir yaptırım yoktur.$expl$, $choices$[{"id":"a","text":"Hayır, oy kullanmak bir haktır ancak yasal bir zorunluluk değildir"},{"id":"b","text":"Evet, para cezası tehdidiyle"},{"id":"c","text":"Evet, hapis cezası tehdidiyle"},{"id":"d","text":"Evet, 70 yaşından büyük kişiler hariç"}]$choices$),
(177, 'en', $text$How are members of Parliament (députés) designated?$text$, $expl$Members of Parliament (députés) are elected by direct universal suffrage by French citizens. Each député represents a legislative constituency.$expl$, $choices$[{"id":"a","text":"They are elected by direct universal suffrage"},{"id":"b","text":"They are appointed by the President of the Republic"},{"id":"c","text":"They are elected by the senators"},{"id":"d","text":"They are designated by the political parties"}]$choices$),
(177, 'tr', $text$Milletvekilleri (députés) nasıl belirlenir?$text$, $expl$Milletvekilleri (députés), Fransız vatandaşları tarafından doğrudan genel oyla seçilir. Her milletvekili bir yasama seçim bölgesini temsil eder.$expl$, $choices$[{"id":"a","text":"Doğrudan genel oyla seçilirler"},{"id":"b","text":"Cumhurbaşkanı tarafından atanırlar"},{"id":"c","text":"Senatörler tarafından seçilirler"},{"id":"d","text":"Siyasi partiler tarafından belirlenirler"}]$choices$),
(178, 'en', $text$In France, is it possible to join a political party?$text$, $expl$Yes, in France, any person may freely join the political party of their choice. Freedom of association and political pluralism are guaranteed by the Constitution.$expl$, $choices$[{"id":"a","text":"Yes, one may freely join the party of one's choice"},{"id":"b","text":"No, political parties are prohibited"},{"id":"c","text":"Yes, but only if one is a French citizen"},{"id":"d","text":"No, only elected officials may join a party"}]$choices$),
(178, 'tr', $text$Fransa'da bir siyasi partiye katılmak mümkün müdür?$text$, $expl$Evet, Fransa'da herhangi bir kişi tercih ettiği siyasi partiye özgürce katılabilir. Örgütlenme özgürlüğü ve siyasi çoğulculuk Anayasa tarafından güvence altına alınmıştır.$expl$, $choices$[{"id":"a","text":"Evet, kişi tercih ettiği partiye özgürce katılabilir"},{"id":"b","text":"Hayır, siyasi partiler yasaktır"},{"id":"c","text":"Evet, ancak yalnızca Fransız vatandaşıysa"},{"id":"d","text":"Hayır, yalnızca seçilmiş yetkililer bir partiye katılabilir"}]$choices$),
(179, 'en', $text$Who manages public middle schools (collèges)?$text$, $expl$Public middle schools (collèges) are managed by the département. The construction, maintenance and operation of middle schools fall under the competence of the departmental council.$expl$, $choices$[{"id":"a","text":"The département"},{"id":"b","text":"The commune"},{"id":"c","text":"The région"},{"id":"d","text":"The State directly"}]$choices$),
(179, 'tr', $text$Devlet ortaokullarını (collèges) kim yönetir?$text$, $expl$Devlet ortaokulları (collèges) département tarafından yönetilir. Ortaokulların inşası, bakımı ve işletilmesi département konseyinin yetkisindedir.$expl$, $choices$[{"id":"a","text":"Département"},{"id":"b","text":"Commune"},{"id":"c","text":"Région"},{"id":"d","text":"Doğrudan Devlet"}]$choices$),
(180, 'en', $text$Who manages public primary and nursery schools?$text$, $expl$Public primary and nursery schools are managed by the commune. The commune is responsible for the construction, maintenance and operation of school buildings.$expl$, $choices$[{"id":"a","text":"The commune"},{"id":"b","text":"The département"},{"id":"c","text":"The région"},{"id":"d","text":"The Ministry of National Education"}]$choices$),
(180, 'tr', $text$Devlet ilkokullarını ve anaokullarını kim yönetir?$text$, $expl$Devlet ilkokulları ve anaokulları commune tarafından yönetilir. Commune, okul binalarının inşası, bakımı ve işletilmesinden sorumludur.$expl$, $choices$[{"id":"a","text":"Commune"},{"id":"b","text":"Département"},{"id":"c","text":"Région"},{"id":"d","text":"Ulusal Eğitim Bakanlığı"}]$choices$),
(181, 'en', $text$How are mayors designated?$text$, $expl$Mayors are elected by the municipal councillors during the first session of the new municipal council, after the municipal elections.$expl$, $choices$[{"id":"a","text":"They are elected by the municipal councillors"},{"id":"b","text":"They are elected directly by the citizens"},{"id":"c","text":"They are appointed by the préfet (prefect)"},{"id":"d","text":"They are designated by the President of the Republic"}]$choices$),
(181, 'tr', $text$Belediye başkanları nasıl belirlenir?$text$, $expl$Belediye başkanları, belediye seçimlerinden sonra yeni belediye meclisinin ilk oturumunda belediye meclis üyeleri tarafından seçilir.$expl$, $choices$[{"id":"a","text":"Belediye meclis üyeleri tarafından seçilirler"},{"id":"b","text":"Doğrudan vatandaşlar tarafından seçilirler"},{"id":"c","text":"Préfet (vali) tarafından atanırlar"},{"id":"d","text":"Cumhurbaşkanı tarafından belirlenirler"}]$choices$),
(182, 'en', $text$Which territorial authority is responsible for regional transport?$text$, $expl$The région is responsible for regional transport (TER). It organises and finances regional rail passenger transport services.$expl$, $choices$[{"id":"a","text":"The région"},{"id":"b","text":"The département"},{"id":"c","text":"The commune"},{"id":"d","text":"The State"}]$choices$),
(182, 'tr', $text$Bölgesel ulaşımdan hangi toprak yetkili kuruluşu sorumludur?$text$, $expl$Bölgesel ulaşımdan (TER) région sorumludur. Bölgesel demiryolu yolcu ulaşım hizmetlerini düzenler ve finanse eder.$expl$, $choices$[{"id":"a","text":"Région"},{"id":"b","text":"Département"},{"id":"c","text":"Commune"},{"id":"d","text":"Devlet"}]$choices$),
(183, 'en', $text$What is one of the possible ways to amend the Constitution?$text$, $expl$The Constitution may be amended by referendum or by the Congress (a joint meeting of the Assemblée nationale and the Sénat) by a 3/5 majority of the votes cast.$expl$, $choices$[{"id":"a","text":"By referendum or by the Congress (Assemblée nationale + Sénat)"},{"id":"b","text":"By decision of the President of the Republic alone"},{"id":"c","text":"By a vote of the mayors of France"},{"id":"d","text":"By a decision of the Conseil constitutionnel (the Constitutional Council)"}]$choices$),
(183, 'tr', $text$Anayasayı değiştirmenin olası yollarından biri nedir?$text$, $expl$Anayasa, referandum yoluyla veya Kongre (Assemblée nationale ve Sénat'ın ortak toplantısı) tarafından kullanılan oyların 3/5 çoğunluğuyla değiştirilebilir.$expl$, $choices$[{"id":"a","text":"Referandum yoluyla veya Kongre (Assemblée nationale + Sénat) tarafından"},{"id":"b","text":"Yalnızca Cumhurbaşkanının kararıyla"},{"id":"c","text":"Fransa belediye başkanlarının oyuyla"},{"id":"d","text":"Conseil constitutionnel (Anayasa Konseyi) kararıyla"}]$choices$),
(184, 'en', $text$Who acts as interim President of the Republic in the event of death?$text$, $expl$The president of the Sénat (the French Senate) acts as interim President of the Republic in the event of vacancy (death, resignation). This is provided for by article 7 of the Constitution.$expl$, $choices$[{"id":"a","text":"The president of the Sénat (the French Senate)"},{"id":"b","text":"The Prime Minister"},{"id":"c","text":"The president of the Assemblée nationale (the French National Assembly)"},{"id":"d","text":"The Minister of the Interior"}]$choices$),
(184, 'tr', $text$Cumhurbaşkanının vefatı durumunda Cumhurbaşkanlığına kim vekalet eder?$text$, $expl$Cumhurbaşkanının boşalması (vefat, istifa) durumunda Sénat (Fransız Senatosu) başkanı Cumhurbaşkanlığına vekalet eder. Bu, Anayasa'nın 7. maddesinde öngörülmüştür.$expl$, $choices$[{"id":"a","text":"Sénat (Fransız Senatosu) başkanı"},{"id":"b","text":"Başbakan"},{"id":"c","text":"Assemblée nationale (Fransız Ulusal Meclisi) başkanı"},{"id":"d","text":"İçişleri Bakanı"}]$choices$),
(185, 'en', $text$What is the role of the Conseil constitutionnel (the Constitutional Council)?$text$, $expl$The Conseil constitutionnel verifies the conformity of laws with the Constitution. It also ensures the regularity of presidential elections and referendums.$expl$, $choices$[{"id":"a","text":"To verify the conformity of laws with the Constitution"},{"id":"b","text":"To vote on the laws"},{"id":"c","text":"To lead the Government"},{"id":"d","text":"To judge criminal cases"}]$choices$),
(185, 'tr', $text$Conseil constitutionnel'in (Anayasa Konseyi) rolü nedir?$text$, $expl$Conseil constitutionnel, yasaların Anayasa'ya uygunluğunu denetler. Ayrıca cumhurbaşkanlığı seçimlerinin ve referandumların düzenli yapılmasını da güvence altına alır.$expl$, $choices$[{"id":"a","text":"Yasaların Anayasa'ya uygunluğunu denetlemek"},{"id":"b","text":"Yasaları oylamak"},{"id":"c","text":"Hükümeti yönetmek"},{"id":"d","text":"Cezai davaları yargılamak"}]$choices$),
(186, 'en', $text$Which condition is compulsory in order to stand for the presidential election?$text$, $expl$To stand for the presidential election, one must obtain 500 signatures (sponsorships) from elected officials coming from at least 30 different départements or overseas authorities.$expl$, $choices$[{"id":"a","text":"To obtain 500 sponsorships from elected officials"},{"id":"b","text":"To be a member of a political party"},{"id":"c","text":"To have been a member of Parliament or a senator"},{"id":"d","text":"To be over 40 years old"}]$choices$),
(186, 'tr', $text$Cumhurbaşkanlığı seçimine aday olmak için hangi koşul zorunludur?$text$, $expl$Cumhurbaşkanlığı seçimine aday olmak için en az 30 farklı département veya deniz aşırı yetkili kuruluştan gelen seçilmiş yetkililerden 500 imza (parrainage) almak gerekir.$expl$, $choices$[{"id":"a","text":"Seçilmiş yetkililerden 500 destek (parrainage) almak"},{"id":"b","text":"Bir siyasi partinin üyesi olmak"},{"id":"c","text":"Milletvekili veya senatör olmuş olmak"},{"id":"d","text":"40 yaşından büyük olmak"}]$choices$),
(187, 'en', $text$How is the administrative division of France organised?$text$, $expl$The administrative division of France is organised into communes, départements and régions. These three levels of territorial authorities administer themselves freely.$expl$, $choices$[{"id":"a","text":"Into communes, départements and régions"},{"id":"b","text":"Into provinces, cantons and districts"},{"id":"c","text":"Into cities, counties and federated States"},{"id":"d","text":"Into arrondissements and prefectures only"}]$choices$),
(187, 'tr', $text$Fransa'nın idari bölünüşü nasıl örgütlenmiştir?$text$, $expl$Fransa'nın idari bölünüşü communes, départements ve régions olarak örgütlenmiştir. Bu üç düzeydeki toprak yetkili kuruluşları kendi kendilerini özgürce yönetir.$expl$, $choices$[{"id":"a","text":"Communes, départements ve régions olarak"},{"id":"b","text":"Vilayetler, kantonlar ve ilçeler olarak"},{"id":"c","text":"Şehirler, kontluklar ve federe Devletler olarak"},{"id":"d","text":"Yalnızca arrondissementler ve valilikler olarak"}]$choices$),
(188, 'en', $text$In which year was European citizenship created?$text$, $expl$European citizenship was created by the Treaty of Maastricht in 1992. It grants EU citizens rights such as free movement and the right to vote in municipal and European elections in any member State.$expl$, $choices$[{"id":"a","text":"1992"},{"id":"b","text":"1957"},{"id":"c","text":"2000"},{"id":"d","text":"1985"}]$choices$),
(188, 'tr', $text$Avrupa vatandaşlığı hangi yılda oluşturulmuştur?$text$, $expl$Avrupa vatandaşlığı, 1992 Maastricht Antlaşması ile oluşturulmuştur. AB vatandaşlarına serbest dolaşım ve herhangi bir üye Devlette belediye ve Avrupa seçimlerinde oy kullanma hakkı gibi haklar tanır.$expl$, $choices$[{"id":"a","text":"1992"},{"id":"b","text":"1957"},{"id":"c","text":"2000"},{"id":"d","text":"1985"}]$choices$),
(189, 'en', $text$Who composed the anthem of the European Union?$text$, $expl$The European anthem is the Ode to Joy, composed by Ludwig van Beethoven. It is the last movement of his 9th Symphony.$expl$, $choices$[{"id":"a","text":"Ludwig van Beethoven"},{"id":"b","text":"Wolfgang Amadeus Mozart"},{"id":"c","text":"Johann Sebastian Bach"},{"id":"d","text":"Claude Debussy"}]$choices$),
(189, 'tr', $text$Avrupa Birliği marşını kim bestelemiştir?$text$, $expl$Avrupa marşı, Ludwig van Beethoven tarafından bestelenen Neşeye Övgü'dür. 9. Senfonisinin son bölümüdür.$expl$, $choices$[{"id":"a","text":"Ludwig van Beethoven"},{"id":"b","text":"Wolfgang Amadeus Mozart"},{"id":"c","text":"Johann Sebastian Bach"},{"id":"d","text":"Claude Debussy"}]$choices$),
(190, 'en', $text$Where is the seat of the European Central Bank?$text$, $expl$The seat of the European Central Bank (ECB) is in Frankfurt am Main, in Germany. The ECB is responsible for the monetary policy of the eurozone.$expl$, $choices$[{"id":"a","text":"In Frankfurt (Germany)"},{"id":"b","text":"In Brussels (Belgium)"},{"id":"c","text":"In Luxembourg"},{"id":"d","text":"In Paris (France)"}]$choices$),
(190, 'tr', $text$Avrupa Merkez Bankası'nın merkezi neresidir?$text$, $expl$Avrupa Merkez Bankası'nın (ECB) merkezi Almanya, Frankfurt am Main'dedir. ECB, avro bölgesinin para politikasından sorumludur.$expl$, $choices$[{"id":"a","text":"Frankfurt'ta (Almanya)"},{"id":"b","text":"Brüksel'de (Belçika)"},{"id":"c","text":"Lüksemburg'ta"},{"id":"d","text":"Paris'te (Fransa)"}]$choices$),
(191, 'en', $text$Who sits in the European Parliament?$text$, $expl$Members of the European Parliament (MEPs) sit in the European Parliament. They are elected by direct universal suffrage by the citizens of the member States of the EU.$expl$, $choices$[{"id":"a","text":"Members of the European Parliament elected by the citizens of the EU"},{"id":"b","text":"The heads of State of the member countries"},{"id":"c","text":"The Ministers of Foreign Affairs"},{"id":"d","text":"The ambassadors of the member countries"}]$choices$),
(191, 'tr', $text$Avrupa Parlamentosu'nda kimler görev yapar?$text$, $expl$Avrupa Parlamentosu'nda Avrupa Parlamentosu milletvekilleri görev yapar. AB üye Devletlerinin vatandaşları tarafından doğrudan genel oyla seçilirler.$expl$, $choices$[{"id":"a","text":"AB vatandaşları tarafından seçilen Avrupa Parlamentosu milletvekilleri"},{"id":"b","text":"Üye ülkelerin Devlet başkanları"},{"id":"c","text":"Dışişleri Bakanları"},{"id":"d","text":"Üye ülkelerin büyükelçileri"}]$choices$),
(522, 'en', $text$It is the day of the municipal elections and you can no longer find your voter card. May you still vote?$text$, $expl$The voter card is not compulsory in order to vote. In communes with more than 1,000 inhabitants, an identity document is sufficient. In communes with fewer than 1,000 inhabitants, no document is required.$expl$, $choices$[{"id":"a","text":"No, the voter card is essential in order to vote"},{"id":"b","text":"Yes, an identity document is sufficient in communes with more than 1,000 inhabitants"},{"id":"c","text":"Yes, but only if you make a sworn declaration"},{"id":"d","text":"No, you must request a duplicate at the town hall before voting"}]$choices$),
(522, 'tr', $text$Belediye seçimlerinin yapıldığı gündür ve seçmen kartınızı artık bulamıyorsunuz. Yine de oy kullanabilir misiniz?$text$, $expl$Seçmen kartı oy kullanmak için zorunlu değildir. 1.000'den fazla nüfuslu commune'larda bir kimlik belgesi yeterlidir. 1.000'den az nüfuslu commune'larda hiçbir belge istenmez.$expl$, $choices$[{"id":"a","text":"Hayır, oy kullanmak için seçmen kartı zorunludur"},{"id":"b","text":"Evet, 1.000'den fazla nüfuslu commune'larda bir kimlik belgesi yeterlidir"},{"id":"c","text":"Evet, ancak yalnızca yeminli beyan yaparsanız"},{"id":"d","text":"Hayır, oy kullanmadan önce belediyeden bir suret talep etmelisiniz"}]$choices$),
(523, 'en', $text$You must go on a business trip on the day of the second round of the presidential election. You do not want to miss the vote. What can you do?$text$, $expl$You may grant a proxy to a voter registered in the same commune. The procedure is carried out at the police station, gendarmerie, judicial court, or online via the maprocuration.gouv.fr website.$expl$, $choices$[{"id":"a","text":"You can vote by post by sending your ballot by mail"},{"id":"b","text":"You can do nothing, you must be physically present"},{"id":"c","text":"You can grant a proxy so that another voter votes in your place"},{"id":"d","text":"You can vote online on the government's website"}]$choices$),
(523, 'tr', $text$Cumhurbaşkanlığı seçiminin ikinci tur günü iş seyahatine çıkmanız gerekiyor. Oylamayı kaçırmak istemiyorsunuz. Ne yapabilirsiniz?$text$, $expl$Aynı commune'de kayıtlı bir seçmene vekalet verebilirsiniz. İşlem polis karakolunda, jandarmada, adli mahkemede veya maprocuration.gouv.fr sitesi üzerinden çevrimiçi olarak yapılır.$expl$, $choices$[{"id":"a","text":"Oy pusulanızı posta ile göndererek mektupla oy kullanabilirsiniz"},{"id":"b","text":"Hiçbir şey yapamazsınız, fiziksel olarak orada olmanız gerekir"},{"id":"c","text":"Başka bir seçmenin yerinize oy kullanması için vekalet verebilirsiniz"},{"id":"d","text":"Hükümetin web sitesinde çevrimiçi oy kullanabilirsiniz"}]$choices$),
(524, 'en', $text$You have just obtained French nationality and wish to vote in the next elections. What is the first compulsory step?$text$, $expl$To be able to vote in France, one must be registered on the electoral rolls. Registration may be carried out at the town hall, online, or is automatic at 18 for people born in France. New citizens must register.$expl$, $choices$[{"id":"a","text":"You are automatically registered when you obtain nationality"},{"id":"b","text":"You must register on the electoral rolls of your commune"},{"id":"c","text":"You must wait five years after naturalisation in order to be able to vote"},{"id":"d","text":"You must obtain a special authorisation from the préfet (prefect)"}]$choices$),
(524, 'tr', $text$Fransız vatandaşlığını yeni aldınız ve bir sonraki seçimlerde oy kullanmak istiyorsunuz. İlk zorunlu adım nedir?$text$, $expl$Fransa'da oy kullanabilmek için seçmen kütüğüne kayıt olmak gerekir. Kayıt belediyede, çevrimiçi olarak veya Fransa'da doğan kişiler için 18 yaşında otomatik olarak yapılabilir. Yeni vatandaşların kayıt olması gerekir.$expl$, $choices$[{"id":"a","text":"Vatandaşlığı alırken otomatik olarak kayıtlısınız"},{"id":"b","text":"Commune'ünüzün seçmen kütüğüne kayıt olmalısınız"},{"id":"c","text":"Oy kullanabilmek için vatandaşlık aldıktan sonra beş yıl beklemelisiniz"},{"id":"d","text":"Préfet'den (vali) özel izin almalısınız"}]$choices$),
(525, 'en', $text$In the polling station, you notice a voter taking a single ballot directly without going through the voting booth. The assessor asks him to go through the voting booth. Is the assessor right?$text$, $expl$Going through the voting booth is compulsory in order to guarantee the secrecy of the ballot. Even if the voter does not wish to conceal their choice, the voting booth is a compulsory step of the voting process in France.$expl$, $choices$[{"id":"a","text":"No, going through the voting booth is optional"},{"id":"b","text":"Yes, going through the voting booth is compulsory in order to guarantee the secrecy of the ballot"},{"id":"c","text":"No, only the sealed envelope guarantees the secrecy of the vote"},{"id":"d","text":"Yes, but only for the presidential elections"}]$choices$),
(525, 'tr', $text$Oy kullanma merkezinde, bir seçmenin oy kulübesine gitmeden doğrudan tek bir oy pusulası aldığını fark ediyorsunuz. Müşahit ondan oy kulübesinden geçmesini istiyor. Müşahit haklı mı?$text$, $expl$Oy gizliliğini güvence altına almak için oy kulübesinden geçmek zorunludur. Seçmen tercihini gizlemek istemese bile, oy kulübesi Fransa'da oy kullanma sürecinin zorunlu bir adımıdır.$expl$, $choices$[{"id":"a","text":"Hayır, oy kulübesinden geçmek isteğe bağlıdır"},{"id":"b","text":"Evet, oy gizliliğini güvence altına almak için oy kulübesinden geçmek zorunludur"},{"id":"c","text":"Hayır, oyun gizliliğini yalnızca kapalı zarf güvence altına alır"},{"id":"d","text":"Evet, ancak yalnızca cumhurbaşkanlığı seçimleri için"}]$choices$),
(526, 'en', $text$Your neighbour is of Portuguese nationality and has been living in France for 10 years. He wishes to vote in elections. In which elections may he participate?$text$, $expl$Citizens of the European Union residing in France may vote in the municipal and European elections, but not in the presidential, legislative or regional elections.$expl$, $choices$[{"id":"a","text":"In all elections, because he has been living in France for more than 5 years"},{"id":"b","text":"In no election, because he does not have French nationality"},{"id":"c","text":"In the municipal and European elections only"},{"id":"d","text":"Only in the European elections"}]$choices$),
(526, 'tr', $text$Komşunuz Portekiz vatandaşı ve 10 yıldır Fransa'da yaşıyor. Seçimlerde oy kullanmak istiyor. Hangi seçimlere katılabilir?$text$, $expl$Fransa'da ikamet eden Avrupa Birliği vatandaşları belediye ve Avrupa seçimlerinde oy kullanabilir, ancak cumhurbaşkanlığı, yasama veya bölgesel seçimlerde oy kullanamaz.$expl$, $choices$[{"id":"a","text":"Tüm seçimlerde, çünkü 5 yıldan uzun süredir Fransa'da yaşıyor"},{"id":"b","text":"Hiçbir seçimde, çünkü Fransız vatandaşı değil"},{"id":"c","text":"Yalnızca belediye ve Avrupa seçimlerinde"},{"id":"d","text":"Yalnızca Avrupa seçimlerinde"}]$choices$),
(527, 'en', $text$You wish to get married civilly in France. To whom must you turn in order to celebrate the marriage?$text$, $expl$In France, only the civil marriage has legal value. It is celebrated at the town hall by the mayor or a deputy. A religious marriage has no legal value if it is not preceded by the civil marriage.$expl$, $choices$[{"id":"a","text":"To a notary who officialises the marriage"},{"id":"b","text":"To the mayor or a deputy of your commune, at the town hall"},{"id":"c","text":"To the judicial court of your city"},{"id":"d","text":"To the préfet (prefect) of the département"}]$choices$),
(527, 'tr', $text$Fransa'da medeni nikahla evlenmek istiyorsunuz. Evliliği kıymak için kime başvurmalısınız?$text$, $expl$Fransa'da yalnızca medeni nikahın hukuki değeri vardır. Belediyede belediye başkanı veya bir yardımcı tarafından kıyılır. Dini nikahın, medeni nikahla önce yapılmadığı takdirde hiçbir hukuki değeri yoktur.$expl$, $choices$[{"id":"a","text":"Evliliği resmileştiren bir notere"},{"id":"b","text":"Commune'ünüzün belediye başkanına veya bir yardımcısına, belediyede"},{"id":"c","text":"Şehrinizin adli mahkemesine"},{"id":"d","text":"Département'ın préfet'ine (vali)"}]$choices$),
(528, 'en', $text$You wish to build an extension to your house. Your neighbour tells you that you must request a building permit. To whom must you apply?$text$, $expl$Applications for building permits must be filed at the town hall of the commune where the land is located. It is the mayor who issues urban planning authorisations on behalf of the commune.$expl$, $choices$[{"id":"a","text":"To the prefecture of the département"},{"id":"b","text":"To the town hall of your commune"},{"id":"c","text":"To the regional council"},{"id":"d","text":"Directly to the Ministry of Housing"}]$choices$),
(528, 'tr', $text$Evinize bir ek bina yapmak istiyorsunuz. Komşunuz inşaat ruhsatı almanız gerektiğini söylüyor. Kime başvurmalısınız?$text$, $expl$İnşaat ruhsatı başvuruları, arazinin bulunduğu commune'ün belediyesine yapılmalıdır. Şehircilik izinlerini commune adına belediye başkanı verir.$expl$, $choices$[{"id":"a","text":"Département valiliğine"},{"id":"b","text":"Commune'ünüzün belediyesine"},{"id":"c","text":"Bölge meclisine"},{"id":"d","text":"Doğrudan Konut Bakanlığı'na"}]$choices$),
(529, 'en', $text$Your child is 3 years old and you wish to enrol them in a public nursery school. What is your first step?$text$, $expl$Enrolment in a public nursery school is done first at the town hall of your commune. The town hall tells you the school for your area, then you finalise the enrolment with the school's headteacher.$expl$, $choices$[{"id":"a","text":"You go directly to the school of your choice to enrol your child"},{"id":"b","text":"You first carry out the enrolment at the town hall, which assigns you a school for your area"},{"id":"c","text":"You contact the rectorate of your académie"},{"id":"d","text":"You wait for an automatic letter from National Education"}]$choices$),
(529, 'tr', $text$Çocuğunuz 3 yaşında ve onu bir devlet anaokuluna kaydettirmek istiyorsunuz. İlk adımınız nedir?$text$, $expl$Devlet anaokuluna kayıt önce commune'ünüzün belediyesinde yapılır. Belediye size bölgenizin okulunu bildirir, ardından kaydı okul müdürüyle tamamlarsınız.$expl$, $choices$[{"id":"a","text":"Çocuğunuzu kaydettirmek için doğrudan tercih ettiğiniz okula gidersiniz"},{"id":"b","text":"Önce belediyede kayıt yaptırırsınız, belediye size bölgenizden bir okul atar"},{"id":"c","text":"Akademinizin rektörlüğüyle iletişime geçersiniz"},{"id":"d","text":"Ulusal Eğitim'den otomatik bir mektup beklersiniz"}]$choices$),
(530, 'en', $text$You wish to attend a session of the municipal council of your commune in order to find out how the budget is spent. Are you entitled to do so?$text$, $expl$Sessions of the municipal council are public (except in exceptional cases of closed session). Any citizen may attend. The deliberations may also be consulted at the town hall. This is a principle of democratic transparency.$expl$, $choices$[{"id":"a","text":"No, only elected officials and journalists may attend the sessions"},{"id":"b","text":"Yes, sessions of the municipal council are public and open to all"},{"id":"c","text":"Yes, but only if you make a written request to the mayor"},{"id":"d","text":"No, the budget is a confidential document"}]$choices$),
(530, 'tr', $text$Bütçenin nasıl harcandığını öğrenmek için commune'ünüzün belediye meclis oturumuna katılmak istiyorsunuz. Buna hakkınız var mı?$text$, $expl$Belediye meclis oturumları kamuya açıktır (istisnai kapalı oturum durumları hariç). Her vatandaş katılabilir. Müzakerelere de belediyede ulaşılabilir. Bu, demokratik şeffaflık ilkesidir.$expl$, $choices$[{"id":"a","text":"Hayır, oturumlara yalnızca seçilmiş yetkililer ve gazeteciler katılabilir"},{"id":"b","text":"Evet, belediye meclis oturumları kamuya açıktır ve herkese açıktır"},{"id":"c","text":"Evet, ancak yalnızca belediye başkanına yazılı talepte bulunursanız"},{"id":"d","text":"Hayır, bütçe gizli bir belgedir"}]$choices$),
(531, 'en', $text$Your elderly grandfather needs the Allocation Personnalisée d'Autonomie (APA, Personalised Autonomy Allowance) to finance his home care. To which authority must you apply?$text$, $expl$Social action, including the APA (Personalised Autonomy Allowance) and the RSA, falls under the competence of the département (departmental council). It is one of the main missions of the départements.$expl$, $choices$[{"id":"a","text":"To the town hall of your commune"},{"id":"b","text":"To the departmental council, because social action is a competence of the département"},{"id":"c","text":"To the Caisse d'allocations familiales (CAF, Family Allowance Fund)"},{"id":"d","text":"To the regional council"}]$choices$),
(531, 'tr', $text$Yaşlı büyükbabanızın evde bakımını finanse etmek için Allocation Personnalisée d'Autonomie (APA, Kişiselleştirilmiş Özerklik Yardımı) almaya ihtiyacı var. Hangi yetkili kuruluşa başvurmanız gerekir?$text$, $expl$Sosyal eylem, özellikle APA (Kişiselleştirilmiş Özerklik Yardımı) ve RSA, département'ın (département konseyi) yetkisindedir. Département'ların temel görevlerinden biridir.$expl$, $choices$[{"id":"a","text":"Commune'ünüzün belediyesine"},{"id":"b","text":"Département konseyine, çünkü sosyal eylem département'ın yetkisidir"},{"id":"c","text":"Aile Yardımı Fonu'na (CAF)"},{"id":"d","text":"Bölge meclisine"}]$choices$),
(532, 'en', $text$The Government wishes to increase taxes. A friend tells you that the Prime Minister may do so alone by decree. Is this correct?$text$, $expl$In France, only Parliament (the Assemblée nationale and the Sénat) has the power to vote on the laws, including those relating to taxes. This is the principle of separation of powers: the Government proposes, Parliament disposes.$expl$, $choices$[{"id":"a","text":"Yes, the Prime Minister may modify taxes by decree"},{"id":"b","text":"No, only the President of the Republic may increase taxes"},{"id":"c","text":"No, only Parliament may vote on tax laws, this is the separation of powers"},{"id":"d","text":"Yes, if the Conseil constitutionnel (the Constitutional Council) gives its agreement"}]$choices$),
(532, 'tr', $text$Hükümet vergileri artırmak istiyor. Bir arkadaşınız Başbakanın bunu kararname ile tek başına yapabileceğini söylüyor. Bu doğru mu?$text$, $expl$Fransa'da, vergilerle ilgili olanlar dahil yasaları oylama yetkisi yalnızca Parlamentoya (Assemblée nationale ve Sénat) aittir. Bu, kuvvetler ayrılığı ilkesidir: Hükümet önerir, Parlamento karar verir.$expl$, $choices$[{"id":"a","text":"Evet, Başbakan vergileri kararname ile değiştirebilir"},{"id":"b","text":"Hayır, vergileri yalnızca Cumhurbaşkanı artırabilir"},{"id":"c","text":"Hayır, vergi yasalarını yalnızca Parlamento oylayabilir, bu kuvvetler ayrılığıdır"},{"id":"d","text":"Evet, Conseil constitutionnel (Anayasa Konseyi) onay verirse"}]$choices$),
(533, 'en', $text$Parliament votes on a law which, according to some citizens, undermines freedom of expression. May citizens challenge this law, and how?$text$, $expl$Since 2010, any litigant may raise a Priority Question of Constitutionality (QPC) before a court. The Conseil constitutionnel (the Constitutional Council) then verifies that the law respects the rights and freedoms guaranteed by the Constitution.$expl$, $choices$[{"id":"a","text":"No, a law voted by Parliament can never be challenged"},{"id":"b","text":"Yes, by addressing a petition to the President of the Republic"},{"id":"c","text":"Yes, by raising a Priority Question of Constitutionality (QPC) before a court"},{"id":"d","text":"Yes, by organising a citizens' referendum"}]$choices$),
(533, 'tr', $text$Parlamento, bazı vatandaşlara göre ifade özgürlüğünü zedeleyen bir yasa oyluyor. Vatandaşlar bu yasaya itiraz edebilir mi ve nasıl?$text$, $expl$2010'dan beri herhangi bir davacı, bir mahkeme önünde Öncelikli Anayasaya Uygunluk Sorusu (QPC) ileri sürebilir. Conseil constitutionnel (Anayasa Konseyi) o zaman yasanın Anayasa tarafından güvence altına alınan hak ve özgürlüklere uyup uymadığını denetler.$expl$, $choices$[{"id":"a","text":"Hayır, Parlamento tarafından oylanan bir yasa asla itiraz edilemez"},{"id":"b","text":"Evet, Cumhurbaşkanına dilekçe göndererek"},{"id":"c","text":"Evet, bir mahkeme önünde Öncelikli Anayasaya Uygunluk Sorusu (QPC) ileri sürerek"},{"id":"d","text":"Evet, vatandaş referandumu düzenleyerek"}]$choices$),
(534, 'en', $text$On television, you learn that the President of the Republic has dissolved the Assemblée nationale (the French National Assembly) and called new elections. A friend says that this is a coup d'état. Is he right?$text$, $expl$The right to dissolve the Assemblée nationale is a personal power of the President of the Republic, provided for by article 12 of the Constitution. It is a constitutional act, not a coup d'état.$expl$, $choices$[{"id":"a","text":"Yes, the president does not have the right to dissolve the Assembly"},{"id":"b","text":"No, the dissolution is a constitutional power of the president provided for by article 12"},{"id":"c","text":"Yes, unless the Prime Minister gave his agreement"},{"id":"d","text":"No, but it requires a favourable vote of the Sénat (the French Senate)"}]$choices$),
(534, 'tr', $text$Televizyonda Cumhurbaşkanının Assemblée nationale'i (Fransız Ulusal Meclisi) feshettiğini ve yeni seçim çağrısında bulunduğunu öğrendiniz. Bir arkadaşınız bunun bir darbe olduğunu söylüyor. Haklı mı?$text$, $expl$Assemblée nationale'i fesih hakkı, Anayasa'nın 12. maddesinde öngörülen Cumhurbaşkanının kişisel bir yetkisidir. Bu, anayasal bir eylemdir, darbe değildir.$expl$, $choices$[{"id":"a","text":"Evet, cumhurbaşkanının Meclisi fesih hakkı yoktur"},{"id":"b","text":"Hayır, fesih cumhurbaşkanının 12. maddede öngörülen anayasal bir yetkisidir"},{"id":"c","text":"Evet, Başbakanın onay vermesi durumu hariç"},{"id":"d","text":"Hayır, ancak Sénat'ın (Fransız Senatosu) olumlu oyunu gerektirir"}]$choices$),
(535, 'en', $text$You are a foreigner in regular status and your residence permit is due to expire in two months. Where must you apply for renewal?$text$, $expl$The renewal of residence permits is carried out at the prefecture or sub-prefecture of the département of residence. The application must be filed before the expiry of the current permit.$expl$, $choices$[{"id":"a","text":"At the town hall of your commune"},{"id":"b","text":"At the consulate of your country of origin"},{"id":"c","text":"At the prefecture or sub-prefecture of your département of residence"},{"id":"d","text":"At the Ministry of the Interior in Paris"}]$choices$),
(535, 'tr', $text$Düzenli statüde bir yabancısınız ve oturma izniniz iki ay içinde sona erecek. Yenileme başvurunuzu nereye yapmalısınız?$text$, $expl$Oturma izinlerinin yenilenmesi, ikamet edilen département'ın valiliğinde veya alt valiliğinde yapılır. Başvurunun, mevcut iznin sona ermesinden önce yapılması gerekir.$expl$, $choices$[{"id":"a","text":"Commune'ünüzün belediyesine"},{"id":"b","text":"Anavatanınızın konsolosluğuna"},{"id":"c","text":"İkamet ettiğiniz département'ın valiliğine veya alt valiliğine"},{"id":"d","text":"Paris'teki İçişleri Bakanlığı'na"}]$choices$),
(536, 'en', $text$You believe you are the victim of discrimination by a public service and you do not know whom to turn to. Which independent institution can help you free of charge?$text$, $expl$The Défenseur des droits (the Defender of Rights) is an independent constitutional authority responsible for fighting discrimination, defending the rights of users of public services and protecting the rights of children. Referral is free of charge.$expl$, $choices$[{"id":"a","text":"The mediator of your bank"},{"id":"b","text":"The Défenseur des droits (the Defender of Rights), an independent authority that fights against discrimination"},{"id":"c","text":"The member of Parliament (député) of your constituency"},{"id":"d","text":"The public prosecutor, who has sole competence"}]$choices$),
(536, 'tr', $text$Bir kamu hizmetinden ayrımcılığa uğradığınızı düşünüyorsunuz ve kime başvuracağınızı bilmiyorsunuz. Hangi bağımsız kurum size ücretsiz yardım edebilir?$text$, $expl$Défenseur des droits (Haklar Savunucusu), ayrımcılıkla mücadele etmek, kamu hizmetleri kullanıcılarının haklarını savunmak ve çocukların haklarını korumakla görevli bağımsız anayasal bir otoritedir. Başvuru ücretsizdir.$expl$, $choices$[{"id":"a","text":"Bankanızın arabulucusu"},{"id":"b","text":"Défenseur des droits (Haklar Savunucusu), ayrımcılıkla mücadele eden bağımsız bir otorite"},{"id":"c","text":"Seçim bölgenizin milletvekili (député)"},{"id":"d","text":"Tek yetkili olan Cumhuriyet savcısı"}]$choices$)
INSERT INTO question_translations (question_id, lang, text, explanation, choices) VALUES
  (67, 'en', $text$What does Article 1 of the French Constitution state?$text$, $expl$Article 1 of the Constitution states that France is an indivisible, secular, democratic and social Republic. It ensures the equality of all citizens before the law without distinction of origin, race or religion.$expl$, $choices$[{"id":"a","text":"France is an indivisible, secular, democratic and social Republic"},{"id":"b","text":"France is a constitutional monarchy"},{"id":"c","text":"The President is elected for 7 years"},{"id":"d","text":"Catholicism is the state religion"}]$choices$),
  (67, 'tr', $text$Fransa Anayasası'nın 1. maddesi ne der?$text$, $expl$Anayasanın 1. maddesi, Fransa'nın bölünmez, laik, demokratik ve sosyal bir Cumhuriyet olduğunu belirtir. Köken, ırk veya din ayrımı gözetmeksizin tüm vatandaşların yasa önünde eşitliğini güvence altına alır.$expl$, $choices$[{"id":"a","text":"Fransa bölünmez, laik, demokratik ve sosyal bir Cumhuriyettir"},{"id":"b","text":"Fransa anayasal bir monarşidir"},{"id":"c","text":"Cumhurbaşkanı 7 yıllığına seçilir"},{"id":"d","text":"Katoliklik devlet dinidir"}]$choices$),
  (192, 'en', $text$What is the current Constitution of France called?$text$, $expl$The current Constitution of France is the Constitution of the Fifth Republic, adopted on 4 October 1958. It was drafted under the leadership of General de Gaulle and constitutes the fundamental text of French political organisation.$expl$, $choices$[{"id":"a","text":"The Constitution of the Fifth Republic"},{"id":"b","text":"The Constitution of the Fourth Republic"},{"id":"c","text":"The Constitution of the Third Republic"},{"id":"d","text":"The Constitution of the Sixth Republic"}]$choices$),
  (192, 'tr', $text$Fransa'nın mevcut Anayasası'nın adı nedir?$text$, $expl$Fransa'nın mevcut Anayasası, 4 Ekim 1958'de kabul edilen Beşinci Cumhuriyet Anayasası'dır. General de Gaulle'ün önderliğinde hazırlanmıştır ve Fransız siyasi organizasyonunun temel metnini oluşturur.$expl$, $choices$[{"id":"a","text":"Beşinci Cumhuriyet Anayasası"},{"id":"b","text":"Dördüncü Cumhuriyet Anayasası"},{"id":"c","text":"Üçüncü Cumhuriyet Anayasası"},{"id":"d","text":"Altıncı Cumhuriyet Anayasası"}]$choices$),
  (193, 'en', $text$What is the text setting out the rights and duties of persons residing in France called?$text$, $expl$The Charte des droits et devoirs du citoyen français (Charter of Rights and Duties of the French Citizen) is the text setting out the rights and duties of persons residing in France. It is given to candidates for naturalisation.$expl$, $choices$[{"id":"a","text":"The Charte des droits et devoirs du citoyen français (Charter of Rights and Duties of the French Citizen)"},{"id":"b","text":"The Penal Code"},{"id":"c","text":"The Labour Code"},{"id":"d","text":"The Universal Declaration of Human Rights"}]$choices$),
  (193, 'tr', $text$Fransa'da ikamet eden kişilerin hak ve görevlerini belirleyen metnin adı nedir?$text$, $expl$Charte des droits et devoirs du citoyen français (Fransız Vatandaşının Hak ve Görevler Bildirgesi), Fransa'da ikamet eden kişilerin hak ve görevlerini belirleyen metindir. Vatandaşlığa kabul adaylarına verilir.$expl$, $choices$[{"id":"a","text":"Charte des droits et devoirs du citoyen français (Fransız Vatandaşının Hak ve Görevler Bildirgesi)"},{"id":"b","text":"Ceza Kanunu"},{"id":"c","text":"İş Kanunu"},{"id":"d","text":"İnsan Hakları Evrensel Bildirgesi"}]$choices$),
  (194, 'en', $text$Regarding individual rights, which statement is correct?$text$, $expl$In France, every person has individual rights guaranteed by the Constitution and the Déclaration des Droits de l'Homme et du Citoyen (Declaration of the Rights of Man and of the Citizen). These rights include freedom of expression, freedom of conscience and the right to security.$expl$, $choices$[{"id":"a","text":"Every person has the right to express themselves freely, in compliance with the law"},{"id":"b","text":"Individual rights only concern French citizens"},{"id":"c","text":"Individual rights do not exist in France"},{"id":"d","text":"Only men benefit from individual rights"}]$choices$),
  (194, 'tr', $text$Bireysel haklar konusunda hangi ifade doğrudur?$text$, $expl$Fransa'da her kişi, Anayasa ve İnsan ve Vatandaş Hakları Bildirgesi tarafından güvence altına alınan bireysel haklara sahiptir. Bu haklar arasında ifade özgürlüğü, vicdan özgürlüğü ve güvenlik hakkı yer alır.$expl$, $choices$[{"id":"a","text":"Her kişi yasaya uygun olarak özgürce ifade etme hakkına sahiptir"},{"id":"b","text":"Bireysel haklar yalnızca Fransız vatandaşlarını ilgilendirir"},{"id":"c","text":"Fransa'da bireysel haklar yoktur"},{"id":"d","text":"Yalnızca erkekler bireysel haklardan yararlanır"}]$choices$),
  (195, 'en', $text$From what year does the Déclaration des Droits de l'Homme et du Citoyen (Declaration of the Rights of Man and of the Citizen) date?$text$, $expl$The Déclaration des Droits de l'Homme et du Citoyen was adopted on 26 August 1789, during the French Revolution. It is considered a founding text of freedoms in France and worldwide.$expl$, $choices$[{"id":"a","text":"1789"},{"id":"b","text":"1791"},{"id":"c","text":"1804"},{"id":"d","text":"1958"}]$choices$),
  (195, 'tr', $text$İnsan ve Vatandaş Hakları Bildirgesi (1789) hangi yıla aittir?$text$, $expl$İnsan ve Vatandaş Hakları Bildirgesi, Fransız Devrimi sırasında 26 Ağustos 1789'da kabul edilmiştir. Fransa'da ve dünyada özgürlüklerin kurucu metni olarak kabul edilir.$expl$, $choices$[{"id":"a","text":"1789"},{"id":"b","text":"1791"},{"id":"c","text":"1804"},{"id":"d","text":"1958"}]$choices$),
  (196, 'en', $text$Which of these rights is a fundamental right?$text$, $expl$Freedom of expression is a fundamental right guaranteed by the Déclaration des Droits de l'Homme et du Citoyen of 1789 and by the French Constitution. It allows everyone to freely express their ideas and opinions.$expl$, $choices$[{"id":"a","text":"Freedom of expression"},{"id":"b","text":"The right to drive without a licence"},{"id":"c","text":"The right not to pay taxes"},{"id":"d","text":"The right not to obey the law"}]$choices$),
  (196, 'tr', $text$Aşağıdaki haklardan hangisi temel bir haktır?$text$, $expl$İfade özgürlüğü, 1789 İnsan ve Vatandaş Hakları Bildirgesi ve Fransız Anayasası tarafından güvence altına alınan temel bir haktır. Herkesin fikirlerini ve görüşlerini özgürce ifade etmesine olanak tanır.$expl$, $choices$[{"id":"a","text":"İfade özgürlüğü"},{"id":"b","text":"Ehliyetsiz araç kullanma hakkı"},{"id":"c","text":"Vergi ödememe hakkı"},{"id":"d","text":"Yasaya uymama hakkı"}]$choices$),
  (197, 'en', $text$Among these texts, which one guarantees rights and freedoms in France?$text$, $expl$The Déclaration des Droits de l'Homme et du Citoyen of 1789 is the founding text that guarantees rights and freedoms in France. It is part of the bloc of constitutionality and has constitutional value.$expl$, $choices$[{"id":"a","text":"The Déclaration des Droits de l'Homme et du Citoyen of 1789"},{"id":"b","text":"The Highway Code"},{"id":"c","text":"The internal regulations of companies"},{"id":"d","text":"The Commercial Code"}]$choices$),
  (197, 'tr', $text$Aşağıdaki metinlerden hangisi Fransa'da hak ve özgürlükleri güvence altına alır?$text$, $expl$1789 İnsan ve Vatandaş Hakları Bildirgesi, Fransa'da hak ve özgürlükleri güvence altına alan kurucu metindir. Anayasallık bloğunun bir parçasıdır ve anayasal değere sahiptir.$expl$, $choices$[{"id":"a","text":"1789 İnsan ve Vatandaş Hakları Bildirgesi"},{"id":"b","text":"Karayolları Kanunu"},{"id":"c","text":"İşletmelerin iç tüzüğü"},{"id":"d","text":"Ticaret Kanunu"}]$choices$),
  (198, 'en', $text$What is freedom of expression?$text$, $expl$Freedom of expression is the right of every person to freely express their opinions and ideas, in compliance with the law. It is guaranteed by the Déclaration des Droits de l'Homme et du Citoyen of 1789.$expl$, $choices$[{"id":"a","text":"The right to freely express one's opinions in compliance with the law"},{"id":"b","text":"The right to say whatever one wants without any limit"},{"id":"c","text":"The right to publish state secrets"},{"id":"d","text":"A right reserved only for journalists"}]$choices$),
  (198, 'tr', $text$İfade özgürlüğü nedir?$text$, $expl$İfade özgürlüğü, her kişinin yasaya uygun olarak görüşlerini ve fikirlerini özgürce ifade etme hakkıdır. 1789 İnsan ve Vatandaş Hakları Bildirgesi tarafından güvence altına alınmıştır.$expl$, $choices$[{"id":"a","text":"Yasaya uygun olarak görüşlerini özgürce ifade etme hakkı"},{"id":"b","text":"Hiçbir sınır olmaksızın istediğini söyleme hakkı"},{"id":"c","text":"Devlet sırlarını yayınlama hakkı"},{"id":"d","text":"Yalnızca gazetecilere tanınan bir hak"}]$choices$),
  (199, 'en', $text$Which right allows a person to defend themselves before the courts?$text$, $expl$The right of defence allows any person to defend themselves before the courts, to be assisted by a lawyer and to benefit from a fair trial. It is a fundamental right guaranteed by the Constitution.$expl$, $choices$[{"id":"a","text":"The right of defence"},{"id":"b","text":"The right to strike"},{"id":"c","text":"The right to vote"},{"id":"d","text":"The right to demonstrate"}]$choices$),
  (199, 'tr', $text$Hangi hak bir kişinin yargı önünde kendini savunmasına olanak tanır?$text$, $expl$Savunma hakkı, herhangi bir kişinin yargı önünde kendini savunmasına, bir avukat tarafından temsil edilmesine ve adil bir yargılanma hakkından yararlanmasına olanak tanır. Anayasa tarafından güvence altına alınan temel bir haktır.$expl$, $choices$[{"id":"a","text":"Savunma hakkı"},{"id":"b","text":"Grev hakkı"},{"id":"c","text":"Oy hakkı"},{"id":"d","text":"Gösteri yapma hakkı"}]$choices$),
  (200, 'en', $text$What is the founding text establishing the rights and duties of every citizen?$text$, $expl$The Déclaration des Droits de l'Homme et du Citoyen of 1789 is the founding text that establishes the rights and duties of every citizen. It was adopted during the French Revolution and is part of the bloc of constitutionality.$expl$, $choices$[{"id":"a","text":"The Déclaration des Droits de l'Homme et du Citoyen of 1789"},{"id":"b","text":"The Civil Code of 1804"},{"id":"c","text":"The Constitution of 1958"},{"id":"d","text":"The Maastricht Treaty"}]$choices$),
  (200, 'tr', $text$Her vatandaşın hak ve görevlerini belirleyen kurucu metin hangisidir?$text$, $expl$1789 İnsan ve Vatandaş Hakları Bildirgesi, her vatandaşın hak ve görevlerini belirleyen kurucu metindir. Fransız Devrimi sırasında kabul edilmiş olup anayasallık bloğunun bir parçasıdır.$expl$, $choices$[{"id":"a","text":"1789 İnsan ve Vatandaş Hakları Bildirgesi"},{"id":"b","text":"1804 Medeni Kanun"},{"id":"c","text":"1958 Anayasası"},{"id":"d","text":"Maastricht Antlaşması"}]$choices$),
  (201, 'en', $text$Which text was adopted during the French Revolution?$text$, $expl$The Déclaration des Droits de l'Homme et du Citoyen was adopted on 26 August 1789, during the French Revolution. It proclaims the natural and imprescriptible rights of man.$expl$, $choices$[{"id":"a","text":"The Déclaration des Droits de l'Homme et du Citoyen"},{"id":"b","text":"The Constitution of the Fifth Republic"},{"id":"c","text":"The Civil Code"},{"id":"d","text":"The Treaty of Versailles"}]$choices$),
  (201, 'tr', $text$Hangi metin Fransız Devrimi sırasında kabul edilmiştir?$text$, $expl$İnsan ve Vatandaş Hakları Bildirgesi, Fransız Devrimi sırasında 26 Ağustos 1789'da kabul edilmiştir. İnsanın doğal ve zaman aşımına uğramayan haklarını ilan eder.$expl$, $choices$[{"id":"a","text":"İnsan ve Vatandaş Hakları Bildirgesi"},{"id":"b","text":"Beşinci Cumhuriyet Anayasası"},{"id":"c","text":"Medeni Kanun"},{"id":"d","text":"Versay Antlaşması"}]$choices$),
  (202, 'en', $text$Which freedom allows a person to have no religion?$text$, $expl$Freedom of conscience allows everyone to believe or not to believe in a religion. It is guaranteed by the 1905 law on the separation of Churches and the State and by the French Constitution.$expl$, $choices$[{"id":"a","text":"Freedom of conscience"},{"id":"b","text":"Freedom of expression"},{"id":"c","text":"Freedom of the press"},{"id":"d","text":"Freedom of movement"}]$choices$),
  (202, 'tr', $text$Hangi özgürlük bir kişinin hiçbir dine sahip olmamasına olanak tanır?$text$, $expl$Vicdan özgürlüğü, herkesin bir dine inanmasına veya inanmamasına olanak tanır. 1905 tarihli Kiliseler ile Devletin Ayrılması Yasası ve Fransız Anayasası tarafından güvence altına alınmıştır.$expl$, $choices$[{"id":"a","text":"Vicdan özgürlüğü"},{"id":"b","text":"İfade özgürlüğü"},{"id":"c","text":"Basın özgürlüğü"},{"id":"d","text":"Dolaşım özgürlüğü"}]$choices$),
  (203, 'en', $text$A woman may have an abortion:$text$, $expl$In France, a woman may freely have an abortion up to 14 weeks of pregnancy (since the law of 2 March 2022). This right is guaranteed by law and was constitutionalised in 2024.$expl$, $choices$[{"id":"a","text":"Freely, within the time limits provided by law"},{"id":"b","text":"Only with her husband's consent"},{"id":"c","text":"Only in case of danger to her life"},{"id":"d","text":"Abortion is forbidden in France"}]$choices$),
  (203, 'tr', $text$Bir kadın kürtaj yaptırabilir:$text$, $expl$Fransa'da bir kadın, gebeliğin 14. haftasına kadar kürtaj yaptırabilir (2 Mart 2022 yasası gereği). Bu hak yasayla güvence altına alınmış olup 2024'te anayasaya dahil edilmiştir.$expl$, $choices$[{"id":"a","text":"Yasada öngörülen süreler içinde, serbestçe"},{"id":"b","text":"Yalnızca kocasının rızasıyla"},{"id":"c","text":"Yalnızca hayati tehlike durumunda"},{"id":"d","text":"Kürtaj Fransa'da yasaktır"}]$choices$),
  (204, 'en', $text$Is it always possible to divorce?$text$, $expl$Yes, in France, it is always possible to divorce. Divorce can be requested by one or both spouses. Several procedures exist: by mutual consent, for fault, for definitive deterioration of the marital bond, etc.$expl$, $choices$[{"id":"a","text":"Yes, divorce is always possible in France"},{"id":"b","text":"No, divorce is forbidden in France"},{"id":"c","text":"Only if both spouses agree"},{"id":"d","text":"Only after 10 years of marriage"}]$choices$),
  (204, 'tr', $text$Boşanmak her zaman mümkün müdür?$text$, $expl$Evet, Fransa'da boşanmak her zaman mümkündür. Boşanma, eşlerden biri veya her ikisi tarafından talep edilebilir. Birkaç prosedür vardır: karşılıklı rıza ile, kusurlu boşanma, evlilik bağının kesin olarak kötüleşmesi vs.$expl$, $choices$[{"id":"a","text":"Evet, Fransa'da boşanmak her zaman mümkündür"},{"id":"b","text":"Hayır, Fransa'da boşanma yasaktır"},{"id":"c","text":"Yalnızca her iki eş de hemfikirse"},{"id":"d","text":"Yalnızca 10 yıllık evlilikten sonra"}]$choices$),
  (205, 'en', $text$The death penalty is:$text$, $expl$The death penalty was abolished in France on 9 October 1981, under the presidency of François Mitterrand, thanks to the action of Minister of Justice Robert Badinter. Its abolition has been enshrined in the Constitution since 2007.$expl$, $choices$[{"id":"a","text":"Abolished in France since 1981"},{"id":"b","text":"Still applied for the most serious crimes"},{"id":"c","text":"Authorised only in wartime"},{"id":"d","text":"Temporarily suspended"}]$choices$),
  (205, 'tr', $text$Ölüm cezası:$text$, $expl$Ölüm cezası, Adalet Bakanı Robert Badinter'in girişimleri sayesinde, François Mitterrand'ın cumhurbaşkanlığı döneminde 9 Ekim 1981'de Fransa'da kaldırılmıştır. Kaldırılması 2007'den bu yana Anayasa'da yer almaktadır.$expl$, $choices$[{"id":"a","text":"Fransa'da 1981'den beri kaldırılmıştır"},{"id":"b","text":"En ağır suçlar için hâlâ uygulanmaktadır"},{"id":"c","text":"Yalnızca savaş döneminde yetkilendirilmiştir"},{"id":"d","text":"Geçici olarak askıya alınmıştır"}]$choices$),
  (206, 'en', $text$Regarding the limits on individual freedoms, which statement is correct?$text$, $expl$Individual freedoms may be limited to protect public order and the rights of others. These limitations must be provided for by law and be proportionate to the aim pursued.$expl$, $choices$[{"id":"a","text":"Freedoms may be limited to protect public order and the rights of others"},{"id":"b","text":"Individual freedoms are absolute and can never be limited"},{"id":"c","text":"Only the President can limit individual freedoms"},{"id":"d","text":"Individual freedoms do not concern foreigners"}]$choices$),
  (206, 'tr', $text$Bireysel özgürlüklere getirilen sınırlamalar konusunda hangi ifade doğrudur?$text$, $expl$Bireysel özgürlükler, kamu düzenini ve başkalarının haklarını korumak için sınırlanabilir. Bu sınırlamalar yasayla öngörülmüş ve hedeflenen amaca orantılı olmalıdır.$expl$, $choices$[{"id":"a","text":"Özgürlükler, kamu düzenini ve başkalarının haklarını korumak için sınırlanabilir"},{"id":"b","text":"Bireysel özgürlükler mutlaktır ve asla sınırlanamaz"},{"id":"c","text":"Yalnızca Cumhurbaşkanı bireysel özgürlükleri sınırlayabilir"},{"id":"d","text":"Bireysel özgürlükler yabancıları ilgilendirmez"}]$choices$),
  (207, 'en', $text$In France, is it legal to be married to several people at the same time?$text$, $expl$No, polygamy is forbidden in France. The Civil Code requires monogamy: a person can only be married to one other person at a time. Bigamy is a criminal offence punished by law.$expl$, $choices$[{"id":"a","text":"No, it is forbidden by law"},{"id":"b","text":"Yes, if all persons agree"},{"id":"c","text":"Yes, but only for foreigners"},{"id":"d","text":"Yes, since the 2013 law"}]$choices$),
  (207, 'tr', $text$Fransa'da aynı anda birden fazla kişiyle evli olmak yasal mıdır?$text$, $expl$Hayır, çok eşlilik Fransa'da yasaktır. Medeni Kanun tek eşliliği zorunlu kılar: bir kişi aynı anda yalnızca bir kişiyle evli olabilir. İki eşlilik yasayla cezalandırılan bir suçtur.$expl$, $choices$[{"id":"a","text":"Hayır, yasayla yasaklanmıştır"},{"id":"b","text":"Evet, tüm kişiler hemfikirse"},{"id":"c","text":"Evet, ama yalnızca yabancılar için"},{"id":"d","text":"Evet, 2013 yasasından beri"}]$choices$),
  (208, 'en', $text$Should one reduce one's waste?$text$, $expl$Yes, reducing waste is a citizen and environmental obligation. The Charter for the Environment, integrated into the bloc of constitutionality, provides that everyone must contribute to the preservation of the environment.$expl$, $choices$[{"id":"a","text":"Yes, it is a duty of every citizen to protect the environment"},{"id":"b","text":"No, it is not an obligation"},{"id":"c","text":"Only if the town hall imposes it"},{"id":"d","text":"No, it is the exclusive role of companies"}]$choices$),
  (208, 'tr', $text$Atıklar azaltılmalı mıdır?$text$, $expl$Evet, atıkların azaltılması bir vatandaşlık ve çevre yükümlülüğüdür. Anayasallık bloğuna dahil olan Çevre Şartı, herkesin çevrenin korunmasına katkıda bulunması gerektiğini öngörür.$expl$, $choices$[{"id":"a","text":"Evet, çevreyi korumak için her vatandaşın görevidir"},{"id":"b","text":"Hayır, bu bir yükümlülük değildir"},{"id":"c","text":"Yalnızca belediye dayatıyorsa"},{"id":"d","text":"Hayır, bu sadece şirketlerin görevidir"}]$choices$),
  (209, 'en', $text$Throwing a bottle in the street is:$text$, $expl$Throwing a bottle in the street is an offence punished by law. It constitutes illegal dumping of waste, liable to a fine. Everyone must respect the cleanliness of public spaces.$expl$, $choices$[{"id":"a","text":"Forbidden and punishable by a fine"},{"id":"b","text":"Allowed if the bottle is plastic"},{"id":"c","text":"Tolerated in large cities"},{"id":"d","text":"Allowed if there is no bin nearby"}]$choices$),
  (209, 'tr', $text$Sokağa bir şişe atmak:$text$, $expl$Sokağa bir şişe atmak yasayla cezalandırılan bir suçtur. Yasadışı atık dökümü olarak kabul edilir ve para cezasıyla cezalandırılabilir. Herkes kamusal alanların temizliğine saygı göstermelidir.$expl$, $choices$[{"id":"a","text":"Yasak ve para cezası gerektirir"},{"id":"b","text":"Şişe plastikse izin verilir"},{"id":"c","text":"Büyük şehirlerde hoş görülür"},{"id":"d","text":"Yakında çöp kutusu yoksa izin verilir"}]$choices$),
  (210, 'en', $text$Why can individual freedoms be limited?$text$, $expl$Individual freedoms may be limited to preserve public order and to protect the rights and freedoms of others. The law sets these limits in a proportionate manner.$expl$, $choices$[{"id":"a","text":"To preserve public order and protect the rights of others"},{"id":"b","text":"To favour the government in place"},{"id":"c","text":"To prevent citizens from expressing themselves"},{"id":"d","text":"Individual freedoms can never be limited"}]$choices$),
  (210, 'tr', $text$Bireysel özgürlükler neden sınırlanabilir?$text$, $expl$Bireysel özgürlükler, kamu düzenini korumak ve başkalarının hak ve özgürlüklerini korumak için sınırlanabilir. Yasa bu sınırları orantılı biçimde belirler.$expl$, $choices$[{"id":"a","text":"Kamu düzenini korumak ve başkalarının haklarını korumak için"},{"id":"b","text":"Mevcut hükümeti kayırmak için"},{"id":"c","text":"Vatandaşların kendilerini ifade etmesini engellemek için"},{"id":"d","text":"Bireysel özgürlükler asla sınırlanamaz"}]$choices$),
  (211, 'en', $text$What should a person do in case of an accident?$text$, $expl$In case of an accident, every person must call the emergency services (15 for SAMU [medical emergencies], 18 for the fire brigade, or 112 for the European emergency number) and assist the victims as far as possible.$expl$, $choices$[{"id":"a","text":"Call the emergency services and assist the victims"},{"id":"b","text":"Continue on their way without stopping"},{"id":"c","text":"Film the scene and post it on social media"},{"id":"d","text":"Wait for someone else to intervene"}]$choices$),
  (211, 'tr', $text$Bir kaza durumunda bir kişi ne yapmalıdır?$text$, $expl$Kaza durumunda her kişi acil servisleri aramalı (tıbbi acil için 15 [SAMU], itfaiye için 18 veya Avrupa acil numarası için 112) ve mümkün olduğunca mağdurlara yardım etmelidir.$expl$, $choices$[{"id":"a","text":"Acil servisleri aramak ve mağdurlara yardım etmek"},{"id":"b","text":"Durmadan yoluna devam etmek"},{"id":"c","text":"Olayı filme almak ve sosyal medyada yayınlamak"},{"id":"d","text":"Başka birinin müdahale etmesini beklemek"}]$choices$),
  (212, 'en', $text$What does French citizenship allow?$text$, $expl$French citizenship allows participation in the country's political life, in particular through the right to vote and the right to be elected. It also confers civil and social rights and entails duties.$expl$, $choices$[{"id":"a","text":"To vote and participate in the country's political life"},{"id":"b","text":"Not to pay taxes"},{"id":"c","text":"Not to obey French laws"},{"id":"d","text":"To have a job guaranteed by the State"}]$choices$),
  (212, 'tr', $text$Fransız vatandaşlığı neyi sağlar?$text$, $expl$Fransız vatandaşlığı, özellikle oy hakkı ve seçilme hakkı yoluyla ülkenin siyasi yaşamına katılmayı sağlar. Ayrıca medeni ve sosyal haklar verir ve bazı görevler getirir.$expl$, $choices$[{"id":"a","text":"Oy vermek ve ülkenin siyasi yaşamına katılmak"},{"id":"b","text":"Vergi ödememek"},{"id":"c","text":"Fransız yasalarına uymamak"},{"id":"d","text":"Devlet tarafından garanti edilen bir işe sahip olmak"}]$choices$),
  (213, 'en', $text$What does a person who does not obey the law risk?$text$, $expl$A person who does not obey the law is liable to criminal sanctions ranging from a fine to imprisonment, depending on the seriousness of the offence committed (contravention, délit [misdemeanour] or crime [felony]).$expl$, $choices$[{"id":"a","text":"Sanctions ranging from a fine to imprisonment"},{"id":"b","text":"Nothing, there is no sanction in France"},{"id":"c","text":"Only a verbal warning"},{"id":"d","text":"Automatic expulsion from the territory"}]$choices$),
  (213, 'tr', $text$Yasaya uymayan bir kişi neyi göze alır?$text$, $expl$Yasaya uymayan bir kişi, işlenen suçun ağırlığına göre (kabahat, suç veya ağır suç) para cezasından hapis cezasına kadar cezai yaptırımlara maruz kalır.$expl$, $choices$[{"id":"a","text":"Para cezasından hapis cezasına kadar yaptırımlar"},{"id":"b","text":"Hiçbir şey, Fransa'da yaptırım yoktur"},{"id":"c","text":"Yalnızca sözlü uyarı"},{"id":"d","text":"Topraktan otomatik sınır dışı edilme"}]$choices$),
  (214, 'en', $text$What is the role of the gendarmerie?$text$, $expl$The national gendarmerie ensures the maintenance of public order and the security of persons, mainly in rural and peri-urban areas. It comes under the Ministry of the Interior.$expl$, $choices$[{"id":"a","text":"Ensure the security of persons and maintain order, mainly in rural areas"},{"id":"b","text":"Manage citizens' taxes"},{"id":"c","text":"Judge persons accused of crimes"},{"id":"d","text":"Draft laws"}]$choices$),
  (214, 'tr', $text$Jandarmanın rolü nedir?$text$, $expl$Ulusal jandarma, özellikle kırsal ve şehir çeperi bölgelerinde kamu düzeninin korunmasını ve kişilerin güvenliğini sağlar. İçişleri Bakanlığına bağlıdır.$expl$, $choices$[{"id":"a","text":"Kişilerin güvenliğini sağlamak ve özellikle kırsal bölgelerde düzeni korumak"},{"id":"b","text":"Vatandaşların vergilerini yönetmek"},{"id":"c","text":"Suçla itham edilen kişileri yargılamak"},{"id":"d","text":"Yasaları hazırlamak"}]$choices$),
  (215, 'en', $text$What is the role of the police?$text$, $expl$The national police ensures the maintenance of public order and the security of persons, mainly in urban areas. It watches over compliance with the laws and protects citizens.$expl$, $choices$[{"id":"a","text":"Ensure the security of persons and maintain public order"},{"id":"b","text":"Vote on laws in Parliament"},{"id":"c","text":"Collect taxes"},{"id":"d","text":"Run hospitals"}]$choices$),
  (215, 'tr', $text$Polisin rolü nedir?$text$, $expl$Ulusal polis, özellikle kentsel bölgelerde kamu düzeninin korunmasını ve kişilerin güvenliğini sağlar. Yasalara uyulmasını gözetir ve vatandaşları korur.$expl$, $choices$[{"id":"a","text":"Kişilerin güvenliğini sağlamak ve kamu düzenini korumak"},{"id":"b","text":"Parlamentoda yasalar üzerinde oy vermek"},{"id":"c","text":"Vergileri toplamak"},{"id":"d","text":"Hastaneleri yönetmek"}]$choices$),
  (216, 'en', $text$What is an offence?$text$, $expl$An offence is a behaviour forbidden by law and punished by criminal sanctions. There are three categories of offences in France: contraventions, délits [misdemeanours] and crimes [felonies], in order of seriousness.$expl$, $choices$[{"id":"a","text":"A behaviour forbidden by law and punished by criminal sanctions"},{"id":"b","text":"A rule of politeness not respected"},{"id":"c","text":"A disagreement between two people"},{"id":"d","text":"A controversial political opinion"}]$choices$),
  (216, 'tr', $text$Bir suç nedir?$text$, $expl$Suç, yasayla yasaklanmış ve cezai yaptırımlarla cezalandırılan bir davranıştır. Fransa'da ağırlık sırasına göre üç suç kategorisi vardır: kabahatler, suçlar ve ağır suçlar.$expl$, $choices$[{"id":"a","text":"Yasayla yasaklanmış ve cezai yaptırımlarla cezalandırılan bir davranış"},{"id":"b","text":"Uyulmayan bir nezaket kuralı"},{"id":"c","text":"İki kişi arasındaki bir anlaşmazlık"},{"id":"d","text":"Tartışmalı bir siyasi görüş"}]$choices$),
  (217, 'en', $text$How can one reduce one's waste?$text$, $expl$One can reduce waste by sorting, recycling, composting, avoiding food waste and choosing products with less packaging. Selective sorting is an essential civic gesture.$expl$, $choices$[{"id":"a","text":"By sorting, recycling and reducing waste"},{"id":"b","text":"By throwing everything in the same bin"},{"id":"c","text":"By burning waste in one's garden"},{"id":"d","text":"By depositing it in nature"}]$choices$),
  (217, 'tr', $text$Atıklar nasıl azaltılabilir?$text$, $expl$Atıklar; ayırma, geri dönüşüm, kompostlama, gıda israfından kaçınma ve daha az ambalajlı ürünleri tercih ederek azaltılabilir. Seçici ayrıştırma temel bir vatandaşlık davranışıdır.$expl$, $choices$[{"id":"a","text":"Ayırarak, geri dönüştürerek ve israfı azaltarak"},{"id":"b","text":"Her şeyi aynı çöp kutusuna atarak"},{"id":"c","text":"Atıkları bahçede yakarak"},{"id":"d","text":"Doğaya bırakarak"}]$choices$),
  (218, 'en', $text$Leaving a broken washing machine on the pavement is:$text$, $expl$Leaving a bulky item on the pavement is forbidden and constitutes illegal dumping punishable by a fine. Bulky items must be taken to a recycling centre or collected by the town hall's removal service.$expl$, $choices$[{"id":"a","text":"Forbidden and punishable by a fine"},{"id":"b","text":"Allowed at night"},{"id":"c","text":"Allowed in large cities"},{"id":"d","text":"Allowed if you leave an apology note"}]$choices$),
  (218, 'tr', $text$Bozuk bir çamaşır makinesini kaldırıma bırakmak:$text$, $expl$Hacimli bir eşyayı kaldırıma bırakmak yasaktır ve yasadışı atık dökümü olarak para cezasına tabidir. Hacimli atıklar geri dönüşüm merkezine götürülmeli veya belediyenin toplama hizmetine başvurulmalıdır.$expl$, $choices$[{"id":"a","text":"Yasak ve para cezası gerektirir"},{"id":"b","text":"Geceyse izin verilir"},{"id":"c","text":"Büyük şehirlerde izin verilir"},{"id":"d","text":"Bir özür notu bırakılırsa izin verilir"}]$choices$),
  (219, 'en', $text$What does human trafficking consist of?$text$, $expl$Human trafficking consists of recruiting, transporting or housing a person for the purposes of exploitation (forced labour, sexual exploitation, etc.). It is a crime severely punished by French law.$expl$, $choices$[{"id":"a","text":"Exploiting persons for purposes of forced labour, sexual exploitation or other"},{"id":"b","text":"Engaging in international trade of goods"},{"id":"c","text":"Transporting persons from one country to another legally"},{"id":"d","text":"Hiring foreign workers with an employment contract"}]$choices$),
  (219, 'tr', $text$İnsan ticareti neyi ifade eder?$text$, $expl$İnsan ticareti, bir kişiyi sömürü amaçlı (zorla çalıştırma, cinsel sömürü vb.) olarak alma, taşıma veya barındırmadan oluşur. Fransız yasalarınca ağır biçimde cezalandırılan bir ağır suçtur.$expl$, $choices$[{"id":"a","text":"Kişileri zorla çalıştırma, cinsel sömürü veya başka amaçlarla sömürmek"},{"id":"b","text":"Uluslararası mal ticareti yapmak"},{"id":"c","text":"Kişileri bir ülkeden başka bir ülkeye yasal yollarla taşımak"},{"id":"d","text":"Yabancı işçileri iş sözleşmesiyle istihdam etmek"}]$choices$),
  (220, 'en', $text$What should a victim of violence do?$text$, $expl$A victim of violence should file a complaint with the police or gendarmerie and, if necessary, call 17 (police emergency) or 3919 (domestic violence). They can also go to the emergency room to have their injuries documented.$expl$, $choices$[{"id":"a","text":"File a complaint with the police or gendarmerie"},{"id":"b","text":"Do nothing and wait for it to pass"},{"id":"c","text":"Take revenge themselves"},{"id":"d","text":"Leave the country"}]$choices$),
  (220, 'tr', $text$Şiddet mağduru ne yapmalıdır?$text$, $expl$Şiddet mağduru, polis veya jandarmaya şikayette bulunmalı ve gerekirse 17'yi (polis acil) veya 3919'u (eş içi şiddet) aramalıdır. Ayrıca yaralarını belgeletmek için acil servise de başvurabilir.$expl$, $choices$[{"id":"a","text":"Polis veya jandarmaya şikayette bulunmak"},{"id":"b","text":"Hiçbir şey yapmayıp geçmesini beklemek"},{"id":"c","text":"Kendi kendine intikam almak"},{"id":"d","text":"Ülkeyi terk etmek"}]$choices$),
  (221, 'en', $text$What is the most serious offence?$text$, $expl$The crime [felony] is the most serious offence in French criminal law. It is judged by the cour d'assises and may be punished by criminal imprisonment up to life imprisonment.$expl$, $choices$[{"id":"a","text":"The crime (felony)"},{"id":"b","text":"The délit (misdemeanour)"},{"id":"c","text":"The contravention"},{"id":"d","text":"The minor offence"}]$choices$),
  (221, 'tr', $text$En ağır suç hangisidir?$text$, $expl$Crime (ağır suç), Fransız ceza hukukundaki en ağır suçtur. Cour d'assises (ağır ceza mahkemesi) tarafından yargılanır ve müebbet hapse kadar ceza ile cezalandırılabilir.$expl$, $choices$[{"id":"a","text":"Crime (ağır suç)"},{"id":"b","text":"Délit (suç)"},{"id":"c","text":"Contravention (kabahat)"},{"id":"d","text":"Küçük suç"}]$choices$),
  (222, 'en', $text$To which freedom does PMA (medically assisted procreation) refer?$text$, $expl$Medically assisted procreation (PMA) refers to the freedom to control one's own body. Since the bioethics law of 2021, PMA is open to all women in France.$expl$, $choices$[{"id":"a","text":"The freedom to control one's own body"},{"id":"b","text":"Freedom of expression"},{"id":"c","text":"Freedom of movement"},{"id":"d","text":"Freedom of the press"}]$choices$),
  (222, 'tr', $text$PMA (tıbbi destekli üreme) hangi özgürlüğe atıfta bulunur?$text$, $expl$Tıbbi destekli üreme (PMA), kişinin kendi bedeni üzerinde tasarruf etme özgürlüğüne atıfta bulunur. 2021 biyoetik yasası ile birlikte PMA, Fransa'da tüm kadınlara açıktır.$expl$, $choices$[{"id":"a","text":"Kendi bedeni üzerinde tasarruf etme özgürlüğü"},{"id":"b","text":"İfade özgürlüğü"},{"id":"c","text":"Dolaşım özgürlüğü"},{"id":"d","text":"Basın özgürlüğü"}]$choices$),
  (223, 'en', $text$In the name of what does the State justify restricting rights?$text$, $expl$The State may restrict certain rights in the name of the general interest and public order. These restrictions must be provided for by law and proportionate to the objective pursued.$expl$, $choices$[{"id":"a","text":"In the name of the general interest and public order"},{"id":"b","text":"In the name of the President of the Republic"},{"id":"c","text":"In the name of political parties"},{"id":"d","text":"In the name of private companies"}]$choices$),
  (223, 'tr', $text$Devlet hakları kısıtlamayı neye dayandırarak haklı çıkarır?$text$, $expl$Devlet, genel çıkar ve kamu düzeni adına bazı hakları kısıtlayabilir. Bu kısıtlamalar yasayla öngörülmüş ve hedeflenen amaca orantılı olmalıdır.$expl$, $choices$[{"id":"a","text":"Genel çıkar ve kamu düzeni adına"},{"id":"b","text":"Cumhurbaşkanı adına"},{"id":"c","text":"Siyasi partiler adına"},{"id":"d","text":"Özel şirketler adına"}]$choices$),
  (224, 'en', $text$Regarding the right to marry, which statement is correct?$text$, $expl$In France, every adult person has the right to marry freely, including with a person of the same sex, since the law of 17 May 2013. Forced marriage is forbidden.$expl$, $choices$[{"id":"a","text":"Any adult person may marry freely, including with a person of the same sex"},{"id":"b","text":"Marriage is only possible between a man and a woman"},{"id":"c","text":"Marriage requires the parents' consent, even for adults"},{"id":"d","text":"Marriage is only possible from the age of 21"}]$choices$),
  (224, 'tr', $text$Evlenme hakkı konusunda hangi ifade doğrudur?$text$, $expl$Fransa'da, 17 Mayıs 2013 yasasından beri her ergin kişi, aynı cinsiyetten biriyle dahil olmak üzere serbestçe evlenme hakkına sahiptir. Zorla evlilik yasaktır.$expl$, $choices$[{"id":"a","text":"Her ergin kişi, aynı cinsiyetten biriyle de dahil olmak üzere serbestçe evlenebilir"},{"id":"b","text":"Evlilik yalnızca bir erkek ile bir kadın arasında mümkündür"},{"id":"c","text":"Evlilik, ergin kişiler için bile ebeveynlerin izni gerektirir"},{"id":"d","text":"Evlilik yalnızca 21 yaşından itibaren mümkündür"}]$choices$),
  (225, 'en', $text$Which of these quotations is inscribed in the Déclaration des Droits de l'Homme et du Citoyen of 1789?$text$, $expl$Article 1 of the Déclaration des Droits de l'Homme et du Citoyen of 1789 affirms that 'Men are born and remain free and equal in rights'. It is one of the founding principles of the French Republic.$expl$, $choices$[{"id":"a","text":"Men are born and remain free and equal in rights"},{"id":"b","text":"France is a constitutional monarchy"},{"id":"c","text":"Work is compulsory for all citizens"},{"id":"d","text":"Catholicism is the official religion of France"}]$choices$),
  (225, 'tr', $text$Aşağıdaki alıntılardan hangisi 1789 İnsan ve Vatandaş Hakları Bildirgesi'nde yer almaktadır?$text$, $expl$1789 İnsan ve Vatandaş Hakları Bildirgesi'nin 1. maddesi, 'İnsanlar haklar bakımından özgür ve eşit doğar ve öyle kalır' der. Bu Fransız Cumhuriyeti'nin kurucu ilkelerinden biridir.$expl$, $choices$[{"id":"a","text":"İnsanlar haklar bakımından özgür ve eşit doğar ve öyle kalır"},{"id":"b","text":"Fransa anayasal bir monarşidir"},{"id":"c","text":"Çalışmak tüm vatandaşlar için zorunludur"},{"id":"d","text":"Katoliklik Fransa'nın resmi dinidir"}]$choices$),
  (226, 'en', $text$Is recourse to abortion authorised?$text$, $expl$Yes, recourse to abortion is authorised in France. Voluntary termination of pregnancy (IVG) is a right guaranteed by law, available up to 14 weeks of pregnancy. This right was constitutionalised in 2024.$expl$, $choices$[{"id":"a","text":"Yes, it is a right guaranteed by law"},{"id":"b","text":"No, it is totally forbidden"},{"id":"c","text":"Only in case of danger to the mother"},{"id":"d","text":"Only with a judge's authorisation"}]$choices$),
  (226, 'tr', $text$Kürtaja başvurmak yetkili kılınmış mıdır?$text$, $expl$Evet, kürtaja başvurmak Fransa'da yetkili kılınmıştır. İsteğe bağlı gebelik sonlandırma (IVG), yasayla güvence altına alınmış bir haktır ve gebeliğin 14. haftasına kadar gerçekleştirilebilir. Bu hak 2024'te anayasaya dahil edilmiştir.$expl$, $choices$[{"id":"a","text":"Evet, yasayla güvence altına alınmış bir haktır"},{"id":"b","text":"Hayır, tamamen yasaktır"},{"id":"c","text":"Yalnızca anne için tehlike durumunda"},{"id":"d","text":"Yalnızca bir hakimin izniyle"}]$choices$),
  (227, 'en', $text$What does the Constitution contain?$text$, $expl$The Constitution contains the fundamental rules of organisation of the State, the distribution of powers and the fundamental rights and freedoms of citizens. It is the supreme legal norm in France.$expl$, $choices$[{"id":"a","text":"The rules of organisation of the State and the fundamental rights of citizens"},{"id":"b","text":"Only penal laws"},{"id":"c","text":"The rules of the Highway Code"},{"id":"d","text":"The list of taxes to pay"}]$choices$),
  (227, 'tr', $text$Anayasa neleri içerir?$text$, $expl$Anayasa, devletin örgütlenmesinin temel kurallarını, yetkilerin dağılımını ve vatandaşların temel hak ve özgürlüklerini içerir. Fransa'da en üst hukuki normdur.$expl$, $choices$[{"id":"a","text":"Devletin örgütlenme kuralları ve vatandaşların temel hakları"},{"id":"b","text":"Yalnızca ceza yasaları"},{"id":"c","text":"Karayolları Kanunu kuralları"},{"id":"d","text":"Ödenecek vergilerin listesi"}]$choices$),
  (228, 'en', $text$What does freedom of the press guarantee?$text$, $expl$Freedom of the press guarantees the right to inform and to be informed freely. It is enshrined in the law of 29 July 1881 and constitutes a pillar of French democracy.$expl$, $choices$[{"id":"a","text":"The right to inform and to be informed freely"},{"id":"b","text":"The right to publish fake news"},{"id":"c","text":"The right to defame any public person"},{"id":"d","text":"The right not to respect privacy"}]$choices$),
  (228, 'tr', $text$Basın özgürlüğü neyi güvence altına alır?$text$, $expl$Basın özgürlüğü, özgürce haber verme ve haber alma hakkını güvence altına alır. 29 Temmuz 1881 yasası ile öngörülmüş olup Fransız demokrasisinin bir sütununu oluşturur.$expl$, $choices$[{"id":"a","text":"Özgürce haber verme ve haber alma hakkı"},{"id":"b","text":"Yalan haber yayınlama hakkı"},{"id":"c","text":"Herhangi bir kamu kişisine iftira atma hakkı"},{"id":"d","text":"Özel hayata saygı göstermeme hakkı"}]$choices$),
  (229, 'en', $text$What does the Charter for the Environment provide?$text$, $expl$The Charter for the Environment, integrated into the bloc of constitutionality in 2005, provides that everyone has the right to live in a balanced environment respectful of health, and the duty to preserve the environment.$expl$, $choices$[{"id":"a","text":"The right to live in a healthy environment and the duty to preserve it"},{"id":"b","text":"The total prohibition of industry in France"},{"id":"c","text":"The right to pollute if one pays a tax"},{"id":"d","text":"The obligation to live in the countryside"}]$choices$),
  (229, 'tr', $text$Çevre Şartı ne öngörür?$text$, $expl$2005'te anayasallık bloğuna dahil edilen Çevre Şartı, herkesin sağlığa uygun ve dengeli bir çevrede yaşama hakkına ve çevreyi koruma görevine sahip olduğunu öngörür.$expl$, $choices$[{"id":"a","text":"Sağlıklı bir çevrede yaşama hakkı ve onu koruma görevi"},{"id":"b","text":"Fransa'da sanayinin tamamen yasaklanması"},{"id":"c","text":"Vergi ödendiğinde kirletme hakkı"},{"id":"d","text":"Kırsalda yaşama zorunluluğu"}]$choices$),
  (230, 'en', $text$What does human dignity mean?$text$, $expl$Human dignity means that every human being has an intrinsic value that must be respected. This principle forbids degrading, inhuman or cruel treatment and constitutes a fundamental right.$expl$, $choices$[{"id":"a","text":"That every human being has a value that must be respected and protected"},{"id":"b","text":"That only French citizens deserve respect"},{"id":"c","text":"That dignity depends on a person's wealth"},{"id":"d","text":"That dignity is a privilege granted by the State"}]$choices$),
  (230, 'tr', $text$İnsan onuru ne anlama gelir?$text$, $expl$İnsan onuru, her insanın saygı görmesi gereken içkin bir değere sahip olduğu anlamına gelir. Bu ilke aşağılayıcı, insanlık dışı veya zalim muameleyi yasaklar ve temel bir hak oluşturur.$expl$, $choices$[{"id":"a","text":"Her insanın saygı görmesi ve korunması gereken bir değere sahip olduğu"},{"id":"b","text":"Yalnızca Fransız vatandaşlarının saygıyı hak ettiği"},{"id":"c","text":"Onurun kişinin zenginliğine bağlı olduğu"},{"id":"d","text":"Onurun Devlet tarafından verilen bir ayrıcalık olduğu"}]$choices$),
  (231, 'en', $text$What does the right to demonstrate mean?$text$, $expl$The right to demonstrate allows citizens to gather peacefully in public space to express an opinion or demand a right. It is regulated by law and generally requires a prior declaration to the prefecture.$expl$, $choices$[{"id":"a","text":"The right to gather peacefully to express an opinion"},{"id":"b","text":"The right to block roads without authorisation"},{"id":"c","text":"The right to destroy public property"},{"id":"d","text":"The right to use violence to defend one's ideas"}]$choices$),
  (231, 'tr', $text$Gösteri yapma hakkı ne anlama gelir?$text$, $expl$Gösteri yapma hakkı, vatandaşların bir görüş ifade etmek veya bir hak talep etmek üzere kamusal alanda barışçıl biçimde toplanmasına olanak tanır. Yasayla düzenlenmiş olup genellikle valiliğe önceden bildirim yapılmasını gerektirir.$expl$, $choices$[{"id":"a","text":"Bir görüş ifade etmek için barışçıl biçimde toplanma hakkı"},{"id":"b","text":"İzinsiz yolları kapatma hakkı"},{"id":"c","text":"Kamu mallarına zarar verme hakkı"},{"id":"d","text":"Görüşlerini savunmak için şiddete başvurma hakkı"}]$choices$),
  (232, 'en', $text$What does PMA mean?$text$, $expl$PMA means Procréation Médicalement Assistée (Medically Assisted Procreation). It encompasses the medical techniques allowing conception of a child outside the natural process. Since 2021, PMA is open to all women in France.$expl$, $choices$[{"id":"a","text":"Procréation Médicalement Assistée (Medically Assisted Procreation)"},{"id":"b","text":"Advanced Medical Protection"},{"id":"c","text":"Automatic Monthly Benefit"},{"id":"d","text":"Medical Support Programme"}]$choices$),
  (232, 'tr', $text$PMA ne anlama gelir?$text$, $expl$PMA, Procréation Médicalement Assistée (Tıbbi Destekli Üreme) anlamına gelir. Bir çocuğun doğal süreç dışında doğmasına olanak tanıyan tıbbi teknikleri kapsar. 2021'den beri PMA, Fransa'da tüm kadınlara açıktır.$expl$, $choices$[{"id":"a","text":"Procréation Médicalement Assistée (Tıbbi Destekli Üreme)"},{"id":"b","text":"İleri Tıbbi Koruma"},{"id":"c","text":"Otomatik Aylık Ödenek"},{"id":"d","text":"Tıbbi Refakat Programı"}]$choices$),
  (233, 'en', $text$Which text is the most difficult to modify?$text$, $expl$The Constitution is the most difficult text to modify. Its revision requires either a vote of the Congress by a three-fifths majority, or a referendum. It is the supreme norm of the French legal order.$expl$, $choices$[{"id":"a","text":"The Constitution"},{"id":"b","text":"An ordinary law"},{"id":"c","text":"A decree"},{"id":"d","text":"A municipal order"}]$choices$),
  (233, 'tr', $text$Hangi metnin değiştirilmesi en zordur?$text$, $expl$Değiştirilmesi en zor metin Anayasadır. Değişikliği ya Kongre'nin beşte üç çoğunluğuyla oyuyla ya da bir referandumla olur. Fransız hukuk düzeninin en üst normudur.$expl$, $choices$[{"id":"a","text":"Anayasa"},{"id":"b","text":"Sıradan bir yasa"},{"id":"c","text":"Bir kararname"},{"id":"d","text":"Bir belediye kararı"}]$choices$),
  (234, 'en', $text$Which freedom allows a person to believe in the religion of their choice?$text$, $expl$Freedom of conscience and freedom of worship allow each person to believe in the religion of their choice or to believe in none. These freedoms are guaranteed by the 1905 law and the Constitution.$expl$, $choices$[{"id":"a","text":"Freedom of conscience and worship"},{"id":"b","text":"Freedom of the press"},{"id":"c","text":"Freedom of enterprise"},{"id":"d","text":"Freedom of movement"}]$choices$),
  (234, 'tr', $text$Hangi özgürlük bir kişinin seçtiği dine inanmasına olanak tanır?$text$, $expl$Vicdan özgürlüğü ve ibadet özgürlüğü, her kişinin seçtiği dine inanmasına veya hiçbir dine inanmamasına olanak tanır. Bu özgürlükler 1905 yasası ve Anayasa tarafından güvence altına alınmıştır.$expl$, $choices$[{"id":"a","text":"Vicdan ve ibadet özgürlüğü"},{"id":"b","text":"Basın özgürlüğü"},{"id":"c","text":"Girişim özgürlüğü"},{"id":"d","text":"Dolaşım özgürlüğü"}]$choices$),
  (235, 'en', $text$What is the right to strike?$text$, $expl$The right to strike is the right of employees to collectively stop work to defend their professional demands. It is recognised by the preamble of the 1946 Constitution, integrated into the bloc of constitutionality.$expl$, $choices$[{"id":"a","text":"The right to collectively stop work to defend one's professional demands"},{"id":"b","text":"The right to never work"},{"id":"c","text":"The right to destroy one's workplace"},{"id":"d","text":"The right to definitively leave one's job without notice"}]$choices$),
  (235, 'tr', $text$Grev hakkı nedir?$text$, $expl$Grev hakkı, çalışanların mesleki taleplerini savunmak amacıyla toplu olarak işi durdurma hakkıdır. Anayasallık bloğuna dahil olan 1946 Anayasası'nın başlangıcında tanınmıştır.$expl$, $choices$[{"id":"a","text":"Mesleki taleplerini savunmak için toplu olarak işi durdurma hakkı"},{"id":"b","text":"Hiçbir zaman çalışmama hakkı"},{"id":"c","text":"İşyerini tahrip etme hakkı"},{"id":"d","text":"Bildirimsiz olarak işten kesin olarak ayrılma hakkı"}]$choices$),
  (236, 'en', $text$What is the Constitution?$text$, $expl$The Constitution is the supreme legal text that organises the powers of the State and guarantees the fundamental rights of citizens. The current Constitution of France dates from 4 October 1958.$expl$, $choices$[{"id":"a","text":"The supreme legal text that organises the powers of the State"},{"id":"b","text":"A collection of penal laws"},{"id":"c","text":"The internal rules of the National Assembly"},{"id":"d","text":"An international treaty signed by France"}]$choices$),
  (236, 'tr', $text$Anayasa nedir?$text$, $expl$Anayasa, devletin yetkilerini düzenleyen ve vatandaşların temel haklarını güvence altına alan en üst hukuki metindir. Fransa'nın mevcut Anayasası 4 Ekim 1958'e tarihlenir.$expl$, $choices$[{"id":"a","text":"Devletin yetkilerini düzenleyen en üst hukuki metin"},{"id":"b","text":"Ceza yasaları derlemesi"},{"id":"c","text":"Ulusal Meclisin iç tüzüğü"},{"id":"d","text":"Fransa tarafından imzalanan uluslararası bir antlaşma"}]$choices$),
  (237, 'en', $text$Who can request an abortion?$text$, $expl$Any pregnant woman who does not wish to continue her pregnancy can request an abortion, within the time limits provided by law (14 weeks of pregnancy). Minors must be accompanied by an adult of their choice.$expl$, $choices$[{"id":"a","text":"Any pregnant woman, within the time limits provided by law"},{"id":"b","text":"Only married women"},{"id":"c","text":"Only women over 25"},{"id":"d","text":"Only on a judge's decision"}]$choices$),
  (237, 'tr', $text$Kim kürtaj talep edebilir?$text$, $expl$Gebeliğini sürdürmek istemeyen herhangi bir gebe kadın, yasada öngörülen süreler içinde (gebeliğin 14. haftası) kürtaj talep edebilir. Reşit olmayanlara kendi seçtikleri bir yetişkin eşlik etmelidir.$expl$, $choices$[{"id":"a","text":"Yasada öngörülen süreler içinde, her gebe kadın"},{"id":"b","text":"Yalnızca evli kadınlar"},{"id":"c","text":"Yalnızca 25 yaş üstü kadınlar"},{"id":"d","text":"Yalnızca bir hakim kararıyla"}]$choices$),
  (238, 'en', $text$Does an adult woman of French nationality have the right to vote in elections?$text$, $expl$Yes, every adult woman of French nationality has the right to vote. The right to vote for women was granted in 1944 in France. Suffrage is universal and makes no distinction of sex.$expl$, $choices$[{"id":"a","text":"Yes, all adult women of French nationality have the right to vote"},{"id":"b","text":"No, only men can vote"},{"id":"c","text":"Only in municipal elections"},{"id":"d","text":"Only if they have a job"}]$choices$),
  (238, 'tr', $text$Fransız vatandaşı ergin bir kadının seçimlerde oy hakkı var mıdır?$text$, $expl$Evet, her Fransız vatandaşı ergin kadın oy hakkına sahiptir. Kadınların oy hakkı Fransa'da 1944'te tanınmıştır. Seçim hakkı geneldir ve cinsiyet ayrımı gözetmez.$expl$, $choices$[{"id":"a","text":"Evet, tüm Fransız vatandaşı ergin kadınlar oy hakkına sahiptir"},{"id":"b","text":"Hayır, yalnızca erkekler oy verebilir"},{"id":"c","text":"Yalnızca belediye seçimlerinde"},{"id":"d","text":"Yalnızca bir işleri varsa"}]$choices$),
  (239, 'en', $text$Regarding the use of social media, which statement is correct?$text$, $expl$The use of social media is subject to compliance with the law. Racist, hateful, defamatory or violence-inciting remarks are forbidden online just as in real life.$expl$, $choices$[{"id":"a","text":"The law also applies on social media: hateful or defamatory remarks are forbidden"},{"id":"b","text":"One can say whatever one wants on social media without consequence"},{"id":"c","text":"Social media is not subject to French law"},{"id":"d","text":"Only certified accounts must comply with the law"}]$choices$),
  (239, 'tr', $text$Sosyal medya kullanımı konusunda hangi ifade doğrudur?$text$, $expl$Sosyal medya kullanımı yasaya uyulmasına tabidir. Irkçı, nefret içerikli, iftira niteliğinde veya şiddete teşvik eden ifadeler, çevrimiçi olarak da gerçek hayattaki gibi yasaktır.$expl$, $choices$[{"id":"a","text":"Yasa sosyal medyada da geçerlidir: nefret veya iftira içeren sözler yasaktır"},{"id":"b","text":"Sosyal medyada hiçbir sonuç olmaksızın istenildiği söylenebilir"},{"id":"c","text":"Sosyal medya Fransız yasalarına tabi değildir"},{"id":"d","text":"Yalnızca doğrulanmış hesaplar yasaya uymak zorundadır"}]$choices$),
  (240, 'en', $text$Throwing a cigarette butt on the ground is:$text$, $expl$Throwing a cigarette butt on the ground is an offence punishable by a fine of 135 euros. It is a polluting act that harms the environment and the cleanliness of public spaces.$expl$, $choices$[{"id":"a","text":"Forbidden and punishable by a fine"},{"id":"b","text":"Allowed in public spaces"},{"id":"c","text":"Tolerated if one is outside"},{"id":"d","text":"Forbidden only in parks"}]$choices$),
  (240, 'tr', $text$Yere sigara izmariti atmak:$text$, $expl$Yere sigara izmariti atmak 135 avro para cezasına tabi bir suçtur. Çevreye ve kamusal alanların temizliğine zarar veren kirletici bir davranıştır.$expl$, $choices$[{"id":"a","text":"Yasak ve para cezası gerektirir"},{"id":"b","text":"Kamusal alanlarda izin verilir"},{"id":"c","text":"Dışarıda hoş görülür"},{"id":"d","text":"Yalnızca parklarda yasaktır"}]$choices$),
  (241, 'en', $text$Can the State limit rights and freedoms?$text$, $expl$Yes, the State can limit rights and freedoms, but only under conditions provided for by law, for reasons of public order, security or to protect the rights of others. These limitations must be proportionate.$expl$, $choices$[{"id":"a","text":"Yes, under the conditions provided by law and in a proportionate manner"},{"id":"b","text":"No, never, freedoms are absolute"},{"id":"c","text":"Yes, without any limit"},{"id":"d","text":"Only in wartime"}]$choices$),
  (241, 'tr', $text$Devlet hak ve özgürlükleri sınırlayabilir mi?$text$, $expl$Evet, Devlet hak ve özgürlükleri sınırlayabilir, ancak yalnızca yasayla öngörülen koşullarda, kamu düzeni, güvenlik veya başkalarının haklarını korumak amacıyla. Bu sınırlamalar orantılı olmalıdır.$expl$, $choices$[{"id":"a","text":"Evet, yasada öngörülen koşullarda ve orantılı biçimde"},{"id":"b","text":"Hayır, asla, özgürlükler mutlaktır"},{"id":"c","text":"Evet, hiçbir sınır olmaksızın"},{"id":"d","text":"Yalnızca savaş döneminde"}]$choices$),
  (242, 'en', $text$Among these actions, which one allows adopting an environmentally respectful attitude?$text$, $expl$Sorting one's waste is a simple and concrete gesture that helps protect the environment. Selective sorting facilitates recycling and reduces the quantity of waste sent to landfill or incineration.$expl$, $choices$[{"id":"a","text":"Sorting one's waste"},{"id":"b","text":"Throwing one's waste in nature"},{"id":"c","text":"Letting water run permanently"},{"id":"d","text":"Using one's car for all trips"}]$choices$),
  (242, 'tr', $text$Aşağıdaki eylemlerden hangisi çevreye saygılı bir tutum benimsemeyi sağlar?$text$, $expl$Atıkları ayırmak, çevreyi korumayı sağlayan basit ve somut bir davranıştır. Seçici ayırma geri dönüşümü kolaylaştırır ve çöplüğe veya yakmaya gönderilen atık miktarını azaltır.$expl$, $choices$[{"id":"a","text":"Atıkları ayırmak"},{"id":"b","text":"Atıkları doğaya atmak"},{"id":"c","text":"Suyu sürekli açık bırakmak"},{"id":"d","text":"Tüm yolculuklarda araba kullanmak"}]$choices$),
  (243, 'en', $text$Which statement constitutes an obligation?$text$, $expl$Respect for the law is an obligation for every person residing in France, whatever their nationality. No one may ignore the law and everyone must comply with it.$expl$, $choices$[{"id":"a","text":"Respecting the law"},{"id":"b","text":"Voting in elections"},{"id":"c","text":"Joining a political party"},{"id":"d","text":"Doing volunteer work"}]$choices$),
  (243, 'tr', $text$Hangi ifade bir yükümlülük oluşturur?$text$, $expl$Yasaya uyma, milliyeti ne olursa olsun Fransa'da ikamet eden her kişi için bir yükümlülüktür. Hiç kimse yasayı bilmediğini iddia edemez ve herkes ona uymalıdır.$expl$, $choices$[{"id":"a","text":"Yasaya uymak"},{"id":"b","text":"Seçimlerde oy vermek"},{"id":"c","text":"Bir siyasi partiye katılmak"},{"id":"d","text":"Gönüllü çalışmak"}]$choices$),
  (244, 'en', $text$For what reason can freedom of expression be limited?$text$, $expl$Freedom of expression can be limited to prevent breaches of public order, to protect the reputation or rights of others, and to forbid hateful, racist or defamatory remarks.$expl$, $choices$[{"id":"a","text":"To protect public order and the rights of others"},{"id":"b","text":"To prevent any criticism of the government"},{"id":"c","text":"To forbid religious opinions"},{"id":"d","text":"Freedom of expression can never be limited"}]$choices$),
  (244, 'tr', $text$Hangi sebeple ifade özgürlüğü sınırlanabilir?$text$, $expl$İfade özgürlüğü; kamu düzenine zarar verilmesini önlemek, başkalarının itibarını veya haklarını korumak ve nefret içeren, ırkçı veya iftira içeren ifadeleri yasaklamak için sınırlanabilir.$expl$, $choices$[{"id":"a","text":"Kamu düzenini ve başkalarının haklarını korumak için"},{"id":"b","text":"Hükümete yönelik her türlü eleştiriyi engellemek için"},{"id":"c","text":"Dini görüşleri yasaklamak için"},{"id":"d","text":"İfade özgürlüğü asla sınırlanamaz"}]$choices$),
  (245, 'en', $text$Why must one sort one's waste?$text$, $expl$Sorting waste is necessary to enable recycling, reduce pollution and preserve natural resources. It is a citizen obligation that contributes to the protection of the environment.$expl$, $choices$[{"id":"a","text":"To enable recycling and protect the environment"},{"id":"b","text":"Only to avoid a fine"},{"id":"c","text":"It is not compulsory"},{"id":"d","text":"Only in large cities"}]$choices$),
  (245, 'tr', $text$Atıklar neden ayrılmalıdır?$text$, $expl$Atıkların ayrılması, geri dönüşümü sağlamak, kirliliği azaltmak ve doğal kaynakları korumak için gereklidir. Çevrenin korunmasına katkıda bulunan bir vatandaşlık yükümlülüğüdür.$expl$, $choices$[{"id":"a","text":"Geri dönüşümü sağlamak ve çevreyi korumak için"},{"id":"b","text":"Yalnızca para cezasından kaçınmak için"},{"id":"c","text":"Zorunlu değildir"},{"id":"d","text":"Yalnızca büyük şehirlerde"}]$choices$),
  (246, 'en', $text$What should one do when faced with orders from police officers or gendarmes?$text$, $expl$Every person must obey the lawful orders of police officers and gendarmes. Refusing to comply is a criminal offence. In case of disagreement, one can challenge this later by legal means.$expl$, $choices$[{"id":"a","text":"Obey their lawful orders"},{"id":"b","text":"Systematically ignore them"},{"id":"c","text":"Physically resist"},{"id":"d","text":"Flee without responding"}]$choices$),
  (246, 'tr', $text$Polis veya jandarmanın emirleri karşısında ne yapılmalıdır?$text$, $expl$Her kişi polis ve jandarmanın meşru emirlerine uymalıdır. Uymayı reddetmek bir suçtur. Anlaşmazlık durumunda daha sonra yasal yollarla itiraz edilebilir.$expl$, $choices$[{"id":"a","text":"Meşru emirlerine uymak"},{"id":"b","text":"Sistematik olarak yok saymak"},{"id":"c","text":"Fiziksel olarak direnmek"},{"id":"d","text":"Cevap vermeden kaçmak"}]$choices$),
  (247, 'en', $text$What is an example of assistance to a person in danger?$text$, $expl$Calling the emergency services when witnessing an accident is an example of assistance to a person in danger. In France, failure to assist a person in peril is an offence punished by law.$expl$, $choices$[{"id":"a","text":"Calling the emergency services when witnessing an accident"},{"id":"b","text":"Filming the scene without intervening"},{"id":"c","text":"Quickly leaving the area"},{"id":"d","text":"Waiting for the police to arrive on their own"}]$choices$),
  (247, 'tr', $text$Tehlikedeki bir kişiye yardımın bir örneği nedir?$text$, $expl$Bir kazaya tanık olunduğunda acil servisleri aramak, tehlikedeki bir kişiye yardımın bir örneğidir. Fransa'da tehlikedeki bir kişiye yardım etmemek yasayla cezalandırılan bir suçtur.$expl$, $choices$[{"id":"a","text":"Bir kazaya tanık olunduğunda acil servisleri aramak"},{"id":"b","text":"Müdahale etmeden olayı filme almak"},{"id":"c","text":"Olay yerinden hızla uzaklaşmak"},{"id":"d","text":"Polisin kendiliğinden gelmesini beklemek"}]$choices$),
  (248, 'en', $text$Which example illustrates a limitation of freedom to protect the general interest?$text$, $expl$The prohibition of smoking in enclosed public places is an example of a limitation of individual freedom to protect public health and the general interest. This measure protects non-smokers from passive smoking.$expl$, $choices$[{"id":"a","text":"The prohibition of smoking in enclosed public places"},{"id":"b","text":"The prohibition of voting"},{"id":"c","text":"The prohibition of speaking in public"},{"id":"d","text":"The prohibition of moving freely"}]$choices$),
  (248, 'tr', $text$Hangi örnek genel çıkarı korumak için özgürlüğün sınırlanmasını gösterir?$text$, $expl$Kapalı kamusal alanlarda sigara içme yasağı, halk sağlığını ve genel çıkarı korumak için bireysel özgürlüğün sınırlanmasının bir örneğidir. Bu önlem, sigara içmeyenleri pasif içicilikten korur.$expl$, $choices$[{"id":"a","text":"Kapalı kamusal alanlarda sigara içme yasağı"},{"id":"b","text":"Oy verme yasağı"},{"id":"c","text":"Halka açık konuşma yasağı"},{"id":"d","text":"Özgürce dolaşma yasağı"}]$choices$),
  (249, 'en', $text$What is the attitude to have when witnessing violence?$text$, $expl$When witnessing violence, one should alert the emergency services (police, fire brigade, SAMU) and, if possible, assist the victim without putting oneself in danger. Failure to act may constitute the offence of non-assistance to a person in danger.$expl$, $choices$[{"id":"a","text":"Alert the emergency services and, if possible, assist the victim"},{"id":"b","text":"Film the scene and post it on social media"},{"id":"c","text":"Do nothing because it does not concern us"},{"id":"d","text":"Leave immediately so as not to be involved"}]$choices$),
  (249, 'tr', $text$Şiddete tanık olunduğunda nasıl davranılmalıdır?$text$, $expl$Şiddete tanık olunduğunda acil servisler (polis, itfaiye, SAMU) uyarılmalı ve mümkünse kendini tehlikeye atmadan mağdura yardım edilmelidir. Müdahale etmemek tehlikedeki bir kişiye yardım etmeme suçunu oluşturabilir.$expl$, $choices$[{"id":"a","text":"Acil servisleri uyarmak ve mümkünse mağdura yardım etmek"},{"id":"b","text":"Olayı filme almak ve sosyal medyada yayınlamak"},{"id":"c","text":"Bizi ilgilendirmediği için hiçbir şey yapmamak"},{"id":"d","text":"Olaya karışmamak için derhal uzaklaşmak"}]$choices$),
  (250, 'en', $text$Which obligation concerns all persons residing in France whatever their nationality?$text$, $expl$Respect for French law is an obligation that concerns all persons residing in France, whatever their nationality. No one is deemed to be unaware of the law on French territory.$expl$, $choices$[{"id":"a","text":"Respect for French law"},{"id":"b","text":"Voting in presidential elections"},{"id":"c","text":"Military service"},{"id":"d","text":"Joining a trade union"}]$choices$),
  (250, 'tr', $text$Hangi yükümlülük, milliyeti ne olursa olsun Fransa'da ikamet eden tüm kişileri ilgilendirir?$text$, $expl$Fransız yasalarına saygı göstermek, milliyeti ne olursa olsun Fransa'da ikamet eden tüm kişileri ilgilendiren bir yükümlülüktür. Fransız topraklarında hiç kimsenin yasayı bilmediği varsayılmaz.$expl$, $choices$[{"id":"a","text":"Fransız yasalarına saygı"},{"id":"b","text":"Cumhurbaşkanlığı seçimlerinde oy vermek"},{"id":"c","text":"Askerlik hizmeti"},{"id":"d","text":"Bir sendikaya üye olmak"}]$choices$),
  (251, 'en', $text$Which statement represents an example of a crime (felony)?$text$, $expl$Murder is an example of a crime [felony], i.e. the most serious offence in French criminal law. Crimes are judged by the cour d'assises and punished by sentences of criminal imprisonment.$expl$, $choices$[{"id":"a","text":"Murder"},{"id":"b","text":"Speeding"},{"id":"c","text":"Noise disturbance at night"},{"id":"d","text":"Illegal parking"}]$choices$),
  (251, 'tr', $text$Hangi ifade bir ağır suç örneğidir?$text$, $expl$Cinayet, Fransız ceza hukukundaki en ağır suç türü olan ağır suça (crime) örnektir. Ağır suçlar cour d'assises (ağır ceza mahkemesi) tarafından yargılanır ve ağır hapis cezalarıyla cezalandırılır.$expl$, $choices$[{"id":"a","text":"Cinayet"},{"id":"b","text":"Hız aşımı"},{"id":"c","text":"Gece gürültüsü"},{"id":"d","text":"Yasak park"}]$choices$),
  (252, 'en', $text$Which statement represents an example of a délit (misdemeanour)?$text$, $expl$Theft is an example of a délit [misdemeanour]. A délit is an offence of intermediate seriousness, judged by the tribunal correctionnel. It is punished by fines and/or imprisonment up to 10 years.$expl$, $choices$[{"id":"a","text":"Theft"},{"id":"b","text":"Speeding by 5 km/h"},{"id":"c","text":"Noise disturbance at night"},{"id":"d","text":"Murder"}]$choices$),
  (252, 'tr', $text$Hangi ifade bir suç (délit) örneğidir?$text$, $expl$Hırsızlık bir suç (délit) örneğidir. Délit, orta düzeyde ciddi bir suçtur ve tribunal correctionnel (ceza mahkemesi) tarafından yargılanır. Para cezası ve/veya 10 yıla kadar hapis cezasıyla cezalandırılır.$expl$, $choices$[{"id":"a","text":"Hırsızlık"},{"id":"b","text":"5 km/sa hız aşımı"},{"id":"c","text":"Gece gürültüsü"},{"id":"d","text":"Cinayet"}]$choices$),
  (253, 'en', $text$Who watches over the maintenance of public order?$text$, $expl$The police and gendarmerie watch over the maintenance of public order in France. The police intervene mainly in urban areas and the gendarmerie in rural and peri-urban areas.$expl$, $choices$[{"id":"a","text":"The police and the gendarmerie"},{"id":"b","text":"Citizens themselves"},{"id":"c","text":"Mayors only"},{"id":"d","text":"Lawyers"}]$choices$),
  (253, 'tr', $text$Kamu düzeninin korunmasını kim gözetir?$text$, $expl$Fransa'da kamu düzeninin korunmasını polis ve jandarma gözetir. Polis ağırlıklı olarak kentsel alanlarda, jandarma ise kırsal ve şehir çeperi alanlarda görev yapar.$expl$, $choices$[{"id":"a","text":"Polis ve jandarma"},{"id":"b","text":"Vatandaşların kendileri"},{"id":"c","text":"Yalnızca belediye başkanları"},{"id":"d","text":"Avukatlar"}]$choices$),
  (254, 'en', $text$Regarding waste, which statement is correct?$text$, $expl$Sorting waste is a legal obligation in France. Every citizen must sort their waste according to the instructions of their commune in order to facilitate recycling and protect the environment.$expl$, $choices$[{"id":"a","text":"Sorting waste is an obligation to protect the environment"},{"id":"b","text":"One can throw all one's waste in the same bin"},{"id":"c","text":"Sorting waste is optional"},{"id":"d","text":"Only companies must sort their waste"}]$choices$),
  (254, 'tr', $text$Atıklar konusunda hangi ifade doğrudur?$text$, $expl$Atıkların ayrılması Fransa'da yasal bir yükümlülüktür. Her vatandaş, geri dönüşümü kolaylaştırmak ve çevreyi korumak amacıyla atıklarını belediyesinin talimatlarına göre ayırmalıdır.$expl$, $choices$[{"id":"a","text":"Atıkların ayrılması çevreyi korumak için bir yükümlülüktür"},{"id":"b","text":"Tüm atıklar aynı çöp kutusuna atılabilir"},{"id":"c","text":"Atıkların ayrılması isteğe bağlıdır"},{"id":"d","text":"Yalnızca şirketler atıklarını ayırmak zorundadır"}]$choices$),
  (255, 'en', $text$What is the purpose of the right to strike?$text$, $expl$The right to strike allows employees to collectively stop work to defend their professional demands (wages, working conditions, etc.). It is guaranteed by the preamble of the 1946 Constitution.$expl$, $choices$[{"id":"a","text":"To allow employees to collectively defend their professional demands"},{"id":"b","text":"To authorise employees never to work again"},{"id":"c","text":"To allow employers to dismiss dissatisfied employees"},{"id":"d","text":"To force the State to raise wages"}]$choices$),
  (255, 'tr', $text$Grev hakkı neye yarar?$text$, $expl$Grev hakkı, çalışanların mesleki taleplerini (ücretler, çalışma koşulları vb.) savunmak için toplu olarak işi durdurmasına olanak tanır. 1946 Anayasası'nın başlangıcı tarafından güvence altına alınmıştır.$expl$, $choices$[{"id":"a","text":"Çalışanların mesleki taleplerini toplu olarak savunmasına olanak tanır"},{"id":"b","text":"Çalışanların bir daha asla çalışmamasına izin verir"},{"id":"c","text":"İşverenlerin memnuniyetsiz çalışanları işten çıkarmasına olanak tanır"},{"id":"d","text":"Devleti ücretleri artırmaya zorlar"}]$choices$),
  (256, 'en', $text$Article 4 of the Déclaration des Droits de l'Homme et du Citoyen states that 'liberty consists in being able to do whatever does not harm others'. What does this mean?$text$, $expl$It means that everyone is free to act provided they do not infringe upon the rights and freedoms of others. Individual freedom ends where that of others begins.$expl$, $choices$[{"id":"a","text":"Everyone is free to act as long as it does not infringe upon the rights of others"},{"id":"b","text":"One can do absolutely whatever one wants"},{"id":"c","text":"Freedom does not exist in France"},{"id":"d","text":"Only the State can decide what is allowed"}]$choices$),
  (256, 'tr', $text$İnsan ve Vatandaş Hakları Bildirgesi'nin 4. maddesi, 'özgürlük başkasına zarar vermeyen her şeyi yapabilmektir' der. Bu ne anlama gelir?$text$, $expl$Bu, herkesin başkalarının hak ve özgürlüklerine zarar vermediği sürece eylemlerinde özgür olduğu anlamına gelir. Bireysel özgürlük, başkasının özgürlüğünün başladığı yerde sona erer.$expl$, $choices$[{"id":"a","text":"Başkalarının haklarına zarar vermediği sürece herkes eylemlerinde özgürdür"},{"id":"b","text":"Tamamen istenildiği yapılabilir"},{"id":"c","text":"Fransa'da özgürlük yoktur"},{"id":"d","text":"Neye izin verildiğine yalnızca Devlet karar verebilir"}]$choices$),
  (258, 'en', $text$What does freedom of movement allow?$text$, $expl$Freedom of movement allows every person to move freely on French territory and to leave it. It is guaranteed by the Constitution and by the European treaties for EU citizens.$expl$, $choices$[{"id":"a","text":"To move freely on French territory"},{"id":"b","text":"To drive without a licence"},{"id":"c","text":"Not to comply with the Highway Code"},{"id":"d","text":"To travel only within one's commune of residence"}]$choices$),
  (258, 'tr', $text$Dolaşım özgürlüğü neyi sağlar?$text$, $expl$Dolaşım özgürlüğü, her kişinin Fransız topraklarında özgürce dolaşmasını ve ülkeden ayrılmasını sağlar. Anayasa ve AB vatandaşları için Avrupa antlaşmaları tarafından güvence altına alınmıştır.$expl$, $choices$[{"id":"a","text":"Fransız topraklarında özgürce dolaşmak"},{"id":"b","text":"Ehliyetsiz araç kullanmak"},{"id":"c","text":"Karayolları Kanununa uymamak"},{"id":"d","text":"Yalnızca ikamet edilen belediye sınırları içinde dolaşmak"}]$choices$),
  (259, 'en', $text$What does it mean to be a citizen of a State?$text$, $expl$To be a citizen of a State means to have rights (vote, protection, freedoms) and duties (respect for the law, payment of taxes, defence of the country) towards that State. Citizenship is linked to nationality.$expl$, $choices$[{"id":"a","text":"To have rights and duties towards that State"},{"id":"b","text":"To have only rights without any duty"},{"id":"c","text":"To reside in the country without any obligation"},{"id":"d","text":"To be obliged to work for the State"}]$choices$),
  (259, 'tr', $text$Bir Devletin vatandaşı olmak ne anlama gelir?$text$, $expl$Bir Devletin vatandaşı olmak, o Devlete karşı haklara (oy, koruma, özgürlükler) ve görevlere (yasaya uyma, vergi ödeme, ülkenin savunması) sahip olmak demektir. Vatandaşlık milliyetle bağlantılıdır.$expl$, $choices$[{"id":"a","text":"O Devlete karşı hak ve görevlere sahip olmak"},{"id":"b","text":"Hiçbir görev olmaksızın yalnızca haklara sahip olmak"},{"id":"c","text":"Hiçbir yükümlülük olmadan ülkede ikamet etmek"},{"id":"d","text":"Devlet için çalışmak zorunda olmak"}]$choices$),
  (260, 'en', $text$What are fundamental rights?$text$, $expl$Fundamental rights are the essential rights guaranteed to every individual, such as liberty, equality, dignity and security. They are protected by the Constitution and international texts.$expl$, $choices$[{"id":"a","text":"The essential rights guaranteed to every individual, such as liberty and equality"},{"id":"b","text":"Rights reserved for civil servants"},{"id":"c","text":"Rights granted only by the President"},{"id":"d","text":"Rights that change at each election"}]$choices$),
  (260, 'tr', $text$Temel haklar nedir?$text$, $expl$Temel haklar, özgürlük, eşitlik, onur ve güvenlik gibi her bireye güvence altına alınan temel haklardır. Anayasa ve uluslararası metinlerle korunmaktadır.$expl$, $choices$[{"id":"a","text":"Her bireye güvence altına alınan, özgürlük ve eşitlik gibi temel haklar"},{"id":"b","text":"Yalnızca memurlar için ayrılmış haklar"},{"id":"c","text":"Yalnızca Cumhurbaşkanı tarafından verilen haklar"},{"id":"d","text":"Her seçimde değişen haklar"}]$choices$),
  (261, 'en', $text$Which right protects a person against arbitrary arrest?$text$, $expl$The right to security protects every person against arbitrary arrest and detention. It is guaranteed by the Déclaration des Droits de l'Homme et du Citoyen of 1789 and by the European Convention on Human Rights.$expl$, $choices$[{"id":"a","text":"The right to security"},{"id":"b","text":"The right to vote"},{"id":"c","text":"The right to strike"},{"id":"d","text":"The right to property"}]$choices$),
  (261, 'tr', $text$Hangi hak bir kişiyi keyfi tutuklamaya karşı korur?$text$, $expl$Güvenlik hakkı, her kişiyi keyfi tutuklama ve gözaltına karşı korur. 1789 İnsan ve Vatandaş Hakları Bildirgesi ve Avrupa İnsan Hakları Sözleşmesi tarafından güvence altına alınmıştır.$expl$, $choices$[{"id":"a","text":"Güvenlik hakkı"},{"id":"b","text":"Oy hakkı"},{"id":"c","text":"Grev hakkı"},{"id":"d","text":"Mülkiyet hakkı"}]$choices$),
  (262, 'en', $text$Which text affirms that all men are born free and equal in rights?$text$, $expl$The Déclaration des Droits de l'Homme et du Citoyen of 1789 affirms in its Article 1 that 'Men are born and remain free and equal in rights'. It is a founding text of human rights.$expl$, $choices$[{"id":"a","text":"The Déclaration des Droits de l'Homme et du Citoyen of 1789"},{"id":"b","text":"The Civil Code of 1804"},{"id":"c","text":"The Treaty of Rome of 1957"},{"id":"d","text":"The Charter of the United Nations of 1945"}]$choices$),
  (262, 'tr', $text$Hangi metin tüm insanların haklar bakımından özgür ve eşit doğduğunu beyan eder?$text$, $expl$1789 İnsan ve Vatandaş Hakları Bildirgesi'nin 1. maddesi, 'İnsanlar haklar bakımından özgür ve eşit doğar ve öyle kalır' der. İnsan haklarının kurucu bir metnidir.$expl$, $choices$[{"id":"a","text":"1789 İnsan ve Vatandaş Hakları Bildirgesi"},{"id":"b","text":"1804 Medeni Kanun"},{"id":"c","text":"1957 Roma Antlaşması"},{"id":"d","text":"1945 Birleşmiş Milletler Şartı"}]$choices$),
  (263, 'en', $text$Which situation is a violation of human dignity?$text$, $expl$Slavery, torture and inhuman or degrading treatment are violations of human dignity. Human dignity is a fundamental principle protected by the Constitution and international conventions.$expl$, $choices$[{"id":"a","text":"Slavery and torture"},{"id":"b","text":"The right to vote"},{"id":"c","text":"Salaried work"},{"id":"d","text":"Compulsory education"}]$choices$),
  (263, 'tr', $text$Hangi durum insan onuruna bir saldırıdır?$text$, $expl$Kölelik, işkence ve insanlık dışı veya aşağılayıcı muameleler insan onuruna saldırılardır. İnsan onuru Anayasa ve uluslararası sözleşmelerle korunan temel bir ilkedir.$expl$, $choices$[{"id":"a","text":"Kölelik ve işkence"},{"id":"b","text":"Oy hakkı"},{"id":"c","text":"Ücretli çalışma"},{"id":"d","text":"Zorunlu eğitim"}]$choices$),
  (264, 'en', $text$Following arrest by the police, it is possible to:$text$, $expl$Following arrest, it is possible to be placed in police custody (garde à vue) for an initial period of 24 hours. The person retains the right to consult a lawyer and to be informed of their rights.$expl$, $choices$[{"id":"a","text":"Be placed in police custody and consult a lawyer"},{"id":"b","text":"Be imprisoned immediately without trial"},{"id":"c","text":"Refuse to give one's identity"},{"id":"d","text":"Leave the police station freely at any time"}]$choices$),
  (264, 'tr', $text$Polis tarafından tutuklamadan sonra mümkün olan:$text$, $expl$Tutuklamadan sonra ilk 24 saat boyunca gözaltına (garde à vue) alınmak mümkündür. Kişi avukat görüşme hakkını ve haklarına ilişkin bilgilendirilme hakkını korur.$expl$, $choices$[{"id":"a","text":"Gözaltına alınmak ve avukatla görüşmek"},{"id":"b","text":"Yargılanmadan derhal hapse atılmak"},{"id":"c","text":"Kimliğini vermeyi reddetmek"},{"id":"d","text":"Karakoldan istediği zaman serbestçe ayrılmak"}]$choices$),
  (265, 'en', $text$Do all French citizens have a religion?$text$, $expl$No, not all French citizens necessarily have a religion. France is a secular State that guarantees freedom of conscience: everyone is free to believe or not to believe.$expl$, $choices$[{"id":"a","text":"No, everyone is free to believe or not to believe"},{"id":"b","text":"Yes, all French people must have a religion"},{"id":"c","text":"Yes, Catholicism is compulsory"},{"id":"d","text":"No, religion is forbidden in France"}]$choices$),
  (265, 'tr', $text$Tüm Fransız vatandaşlarının bir dini var mıdır?$text$, $expl$Hayır, tüm Fransız vatandaşlarının zorunlu olarak bir dini yoktur. Fransa, vicdan özgürlüğünü güvence altına alan laik bir Devlettir: herkes inanmakta veya inanmamakta özgürdür.$expl$, $choices$[{"id":"a","text":"Hayır, herkes inanmakta veya inanmamakta özgürdür"},{"id":"b","text":"Evet, tüm Fransızların bir dini olmalıdır"},{"id":"c","text":"Evet, Katoliklik zorunludur"},{"id":"d","text":"Hayır, Fransa'da din yasaktır"}]$choices$),
  (266, 'en', $text$At what age is digital majority in France?$text$, $expl$Digital majority in France is set at 15 years old. Below this age, registration on social media requires parental consent. This measure aims to protect minors online.$expl$, $choices$[{"id":"a","text":"15 years old"},{"id":"b","text":"13 years old"},{"id":"c","text":"16 years old"},{"id":"d","text":"18 years old"}]$choices$),
  (266, 'tr', $text$Fransa'da dijital reşitlik yaşı kaçtır?$text$, $expl$Fransa'da dijital reşitlik yaşı 15 olarak belirlenmiştir. Bu yaşın altında sosyal medyaya kayıt olmak ebeveyn iznini gerektirir. Bu önlem çevrimiçi olarak küçükleri korumayı amaçlar.$expl$, $choices$[{"id":"a","text":"15 yaşında"},{"id":"b","text":"13 yaşında"},{"id":"c","text":"16 yaşında"},{"id":"d","text":"18 yaşında"}]$choices$),
  (267, 'en', $text$In which of these places is one allowed to smoke?$text$, $expl$It is allowed to smoke in private spaces such as one's home. However, it is forbidden to smoke in enclosed and covered public places (restaurants, bars, train stations, etc.) since the 2007 law.$expl$, $choices$[{"id":"a","text":"At home, in a private space"},{"id":"b","text":"In a restaurant"},{"id":"c","text":"In a hospital"},{"id":"d","text":"In a school"}]$choices$),
  (267, 'tr', $text$Aşağıdaki mekanlardan hangisinde sigara içmeye izin verilir?$text$, $expl$Evde, özel alanda sigara içmeye izin verilir. Buna karşın, 2007 yasasından beri kapalı ve örtülü kamusal alanlarda (restoranlar, barlar, garlar vb.) sigara içmek yasaktır.$expl$, $choices$[{"id":"a","text":"Evde, özel alanda"},{"id":"b","text":"Bir restoranda"},{"id":"c","text":"Bir hastanede"},{"id":"d","text":"Bir okulda"}]$choices$),
  (268, 'en', $text$In France, riding a motorcycle without a licence is:$text$, $expl$Riding without a licence is a délit [misdemeanour] in France, punishable by one year of imprisonment and 15,000 euros in fines. A driving licence is compulsory to drive any motorised vehicle.$expl$, $choices$[{"id":"a","text":"A délit (misdemeanour) punishable by fine and imprisonment"},{"id":"b","text":"Allowed if the motorcycle has small engine capacity"},{"id":"c","text":"A simple contravention"},{"id":"d","text":"Allowed for short trips"}]$choices$),
  (268, 'tr', $text$Fransa'da ehliyetsiz motosiklet kullanmak:$text$, $expl$Ehliyetsiz araç kullanmak Fransa'da bir suçtur (délit), bir yıl hapis ve 15.000 avro para cezası gerektirir. Motorlu herhangi bir aracı kullanmak için ehliyet zorunludur.$expl$, $choices$[{"id":"a","text":"Para cezası ve hapis gerektiren bir suç (délit)"},{"id":"b","text":"Motosiklet düşük silindir hacmindeyse izin verilir"},{"id":"c","text":"Basit bir kabahat"},{"id":"d","text":"Kısa yolculuklar için izin verilir"}]$choices$),
  (269, 'en', $text$What does the duty of solidarity consist of?$text$, $expl$The duty of solidarity consists of contributing to social cohesion, in particular through the payment of taxes and social contributions that fund public services and social protection for all.$expl$, $choices$[{"id":"a","text":"Contributing to social cohesion, in particular through paying taxes and contributions"},{"id":"b","text":"Giving all one's money to associations"},{"id":"c","text":"Doing nothing and waiting for State aid"},{"id":"d","text":"Helping only members of one's family"}]$choices$),
  (269, 'tr', $text$Dayanışma görevi neyi içerir?$text$, $expl$Dayanışma görevi, özellikle kamu hizmetlerini ve herkes için sosyal korumayı finanse eden vergi ve sosyal güvenlik primlerinin ödenmesi yoluyla sosyal uyuma katkıda bulunmaktan oluşur.$expl$, $choices$[{"id":"a","text":"Özellikle vergi ve primlerin ödenmesi yoluyla sosyal uyuma katkıda bulunmak"},{"id":"b","text":"Tüm parasını derneklere vermek"},{"id":"c","text":"Hiçbir şey yapmamak ve Devletin yardımını beklemek"},{"id":"d","text":"Yalnızca kendi aile fertlerine yardım etmek"}]$choices$),
  (270, 'en', $text$Is it compulsory to declare one's taxes every year in France?$text$, $expl$Yes, every person residing in France with an income is required to declare their taxes each year to the tax authorities. It is a legal obligation, even if one does not pay any tax.$expl$, $choices$[{"id":"a","text":"Yes, it is a legal obligation for every person residing in France"},{"id":"b","text":"No, it is optional"},{"id":"c","text":"Only if one earns more than 50,000 euros per year"},{"id":"d","text":"Only for French citizens"}]$choices$),
  (270, 'tr', $text$Fransa'da her yıl vergi beyannamesi vermek zorunlu mudur?$text$, $expl$Evet, Fransa'da ikamet eden ve geliri olan herkes, her yıl vergi idaresine vergi beyannamesi vermekle yükümlüdür. Vergi ödenmese bile yasal bir yükümlülüktür.$expl$, $choices$[{"id":"a","text":"Evet, Fransa'da ikamet eden her kişi için yasal bir yükümlülüktür"},{"id":"b","text":"Hayır, isteğe bağlıdır"},{"id":"c","text":"Yalnızca yılda 50.000 avrodan fazla kazanılırsa"},{"id":"d","text":"Yalnızca Fransız vatandaşları için"}]$choices$),
  (271, 'en', $text$Is it compulsory to assist a person in danger?$text$, $expl$Yes, in France, failure to assist a person in peril is an offence provided for in Article 223-6 of the Penal Code. Any person witnessing a danger must act, at the very least by calling the emergency services.$expl$, $choices$[{"id":"a","text":"Yes, non-assistance to a person in danger is an offence"},{"id":"b","text":"No, it is a personal choice"},{"id":"c","text":"Only if one is a doctor"},{"id":"d","text":"Only if the person is of French nationality"}]$choices$),
  (271, 'tr', $text$Tehlikedeki bir kişiye yardım etmek zorunlu mudur?$text$, $expl$Evet, Fransa'da tehlikedeki bir kişiye yardım etmemek, Ceza Kanunu'nun 223-6. maddesi ile öngörülen bir suçtur. Bir tehlikeye tanık olan her kişi en azından acil servisleri arayarak harekete geçmelidir.$expl$, $choices$[{"id":"a","text":"Evet, tehlikedeki bir kişiye yardım etmemek bir suçtur"},{"id":"b","text":"Hayır, kişisel bir tercihtir"},{"id":"c","text":"Yalnızca doktor olunması durumunda"},{"id":"d","text":"Yalnızca kişi Fransız vatandaşıysa"}]$choices$),
  (272, 'en', $text$Being a juror in a cour d'assises (assize court) is:$text$, $expl$Being a juror in the cour d'assises is a compulsory civic duty. Jurors are drawn by lot from the electoral lists and participate in the judgement of the most serious crimes. Refusing without a legitimate reason is punishable by a fine.$expl$, $choices$[{"id":"a","text":"A compulsory civic duty"},{"id":"b","text":"A voluntary choice"},{"id":"c","text":"Reserved for lawyers"},{"id":"d","text":"Forbidden to women"}]$choices$),
  (272, 'tr', $text$Cour d'assises (ağır ceza mahkemesi) jürisi olmak:$text$, $expl$Cour d'assises jürisi olmak zorunlu bir vatandaşlık görevidir. Jüri üyeleri seçmen listelerinden kura ile seçilir ve en ağır suçların yargılanmasına katılır. Meşru bir gerekçe olmadan reddetmek para cezası gerektirir.$expl$, $choices$[{"id":"a","text":"Zorunlu bir vatandaşlık görevi"},{"id":"b","text":"Gönüllü bir tercih"},{"id":"c","text":"Avukatlara ayrılmış"},{"id":"d","text":"Kadınlara yasak"}]$choices$),
  (273, 'en', $text$The sale of alcohol in France is forbidden to persons under:$text$, $expl$The sale of alcohol is forbidden to minors under 18 in France. This measure aims to protect young people's health. Shopkeepers may ask for ID to verify age.$expl$, $choices$[{"id":"a","text":"18 years old"},{"id":"b","text":"16 years old"},{"id":"c","text":"21 years old"},{"id":"d","text":"14 years old"}]$choices$),
  (273, 'tr', $text$Fransa'da alkol satışı kaç yaşından küçüklere yasaktır?$text$, $expl$Alkol satışı Fransa'da 18 yaşından küçüklere yasaktır. Bu önlem gençlerin sağlığını korumayı amaçlar. Tüccarlar yaşı doğrulamak için kimlik belgesi isteyebilir.$expl$, $choices$[{"id":"a","text":"18 yaş"},{"id":"b","text":"16 yaş"},{"id":"c","text":"21 yaş"},{"id":"d","text":"14 yaş"}]$choices$),
  (274, 'en', $text$Failure to comply with the Highway Code is:$text$, $expl$Failure to comply with the Highway Code is an offence that may be a contravention or a délit depending on the seriousness. Penalties range from a fine to licence withdrawal, or even imprisonment.$expl$, $choices$[{"id":"a","text":"An offence punishable by sanctions"},{"id":"b","text":"Tolerated if one is careful"},{"id":"c","text":"Without legal consequence"},{"id":"d","text":"Allowed in case of personal emergency"}]$choices$),
  (274, 'tr', $text$Karayolları Kanununa uymamak:$text$, $expl$Karayolları Kanununa uymamak, ağırlığına göre bir kabahat veya bir suç (délit) olabilen bir suçtur. Yaptırımlar para cezasından ehliyet iptaline, hatta hapis cezasına kadar uzanır.$expl$, $choices$[{"id":"a","text":"Yaptırımlar gerektiren bir suç"},{"id":"b","text":"Dikkatli olunursa hoş görülür"},{"id":"c","text":"Hukuki sonucu yoktur"},{"id":"d","text":"Kişisel acil durumda izin verilir"}]$choices$),
  (275, 'en', $text$Which of these crimes or délits may lead to deprivation of civil and political rights by a judge?$text$, $expl$Certain serious crimes or délits, such as corruption or breaches of the fundamental interests of the nation, may lead to deprivation of civil and political rights (right to vote, eligibility) pronounced by a judge.$expl$, $choices$[{"id":"a","text":"Serious crimes and délits such as corruption"},{"id":"b","text":"Speeding"},{"id":"c","text":"Noise disturbance at night"},{"id":"d","text":"Illegal parking"}]$choices$),
  (275, 'tr', $text$Aşağıdaki suçlardan hangisi bir hakim tarafından medeni ve siyasi haklardan yoksun bırakmaya yol açabilir?$text$, $expl$Yolsuzluk veya ulusun temel çıkarlarına zarar verme gibi bazı ağır suçlar veya suçlar, bir hakim tarafından medeni ve siyasi haklardan (oy hakkı, seçilebilirlik) yoksun bırakmaya yol açabilir.$expl$, $choices$[{"id":"a","text":"Yolsuzluk gibi ağır suçlar ve suçlar"},{"id":"b","text":"Hız aşımı"},{"id":"c","text":"Gece gürültüsü"},{"id":"d","text":"Yasak park"}]$choices$),
  (276, 'en', $text$To obtain an identity card, one must:$text$, $expl$To obtain an identity card, one must provide proof of French nationality, proof of address, identity photographs and complete a form. The application is made at the town hall or online via a pre-application.$expl$, $choices$[{"id":"a","text":"Provide proof of nationality, proof of address and identity photographs"},{"id":"b","text":"Simply go to the town hall without any document"},{"id":"c","text":"Pay a sum of 500 euros"},{"id":"d","text":"Have a clean criminal record"}]$choices$),
  (276, 'tr', $text$Kimlik kartı almak için:$text$, $expl$Kimlik kartı almak için Fransız vatandaşlığı kanıtı, ikametgah belgesi, kimlik fotoğrafları sunmak ve bir form doldurmak gerekir. Başvuru belediyede veya çevrimiçi olarak ön başvuru yoluyla yapılır.$expl$, $choices$[{"id":"a","text":"Vatandaşlık kanıtı, ikametgah belgesi ve kimlik fotoğrafları sunmak gerekir"},{"id":"b","text":"Belgesiz olarak belediyeye başvurmak yeterlidir"},{"id":"c","text":"500 avro ödemek gerekir"},{"id":"d","text":"Temiz bir sabıka kaydına sahip olmak gerekir"}]$choices$),
  (277, 'en', $text$What must a citizen do if called to be a juror in a cour d'assises trial?$text$, $expl$A citizen called to be a juror in the cour d'assises must appear at the court. It is a compulsory civic duty. Refusing without a legitimate reason is punishable by a fine of 3,750 euros.$expl$, $choices$[{"id":"a","text":"Appear at the court because it is a compulsory civic duty"},{"id":"b","text":"Ignore the summons because it is optional"},{"id":"c","text":"Send someone else in their place"},{"id":"d","text":"Ask a lawyer to replace them"}]$choices$),
  (277, 'tr', $text$Bir vatandaş bir cour d'assises davasında jüri olarak çağrılırsa ne yapmalıdır?$text$, $expl$Cour d'assises jürisi olarak çağrılan bir vatandaş mahkemeye gitmek zorundadır. Zorunlu bir vatandaşlık görevidir. Meşru bir gerekçe olmadan reddetmek 3.750 avro para cezası gerektirir.$expl$, $choices$[{"id":"a","text":"Zorunlu bir vatandaşlık görevi olduğu için mahkemeye gitmek"},{"id":"b","text":"İsteğe bağlı olduğu için çağrıyı yok saymak"},{"id":"c","text":"Yerine başka birini göndermek"},{"id":"d","text":"Bir avukatın yerini almasını istemek"}]$choices$),
  (278, 'en', $text$What is the age of civil majority in France?$text$, $expl$Civil majority in France is set at 18 years old. At this age, a person acquires full legal capacity: they can vote, marry without parental authorisation, sign contracts, etc.$expl$, $choices$[{"id":"a","text":"18 years old"},{"id":"b","text":"16 years old"},{"id":"c","text":"21 years old"},{"id":"d","text":"15 years old"}]$choices$),
  (278, 'tr', $text$Fransa'da medeni reşitlik yaşı kaçtır?$text$, $expl$Fransa'da medeni reşitlik yaşı 18 olarak belirlenmiştir. Bu yaşta bir kişi tam ehliyet kazanır: oy verebilir, ebeveyn izni olmadan evlenebilir, sözleşme imzalayabilir vs.$expl$, $choices$[{"id":"a","text":"18 yaş"},{"id":"b","text":"16 yaş"},{"id":"c","text":"21 yaş"},{"id":"d","text":"15 yaş"}]$choices$),
  (279, 'en', $text$What is one of the main duties of a French citizen?$text$, $expl$Respect for the law is one of the main duties of a French citizen. Other duties include the payment of taxes, participation in the country's defence and the duty to vote.$expl$, $choices$[{"id":"a","text":"Respect the law and pay one's taxes"},{"id":"b","text":"Join a political party"},{"id":"c","text":"Attend all sessions of Parliament"},{"id":"d","text":"Wear a national uniform"}]$choices$),
  (279, 'tr', $text$Bir Fransız vatandaşının başlıca görevlerinden biri nedir?$text$, $expl$Yasaya saygı göstermek, bir Fransız vatandaşının başlıca görevlerinden biridir. Diğer görevler arasında vergi ödeme, ülkenin savunmasına katılma ve oy verme görevi yer alır.$expl$, $choices$[{"id":"a","text":"Yasaya uymak ve vergilerini ödemek"},{"id":"b","text":"Bir siyasi partiye katılmak"},{"id":"c","text":"Parlamentonun tüm oturumlarına katılmak"},{"id":"d","text":"Ulusal bir üniforma giymek"}]$choices$),
  (280, 'en', $text$What is digital citizenship?$text$, $expl$Digital citizenship refers to the set of rights and duties of individuals in the use of digital technologies. It involves responsible use of the Internet and social media, in compliance with the law.$expl$, $choices$[{"id":"a","text":"The set of rights and duties linked to responsible use of digital technology"},{"id":"b","text":"The right to hack websites"},{"id":"c","text":"The obligation to have a social media account"},{"id":"d","text":"The right to anonymously publish hateful remarks"}]$choices$),
  (280, 'tr', $text$Dijital vatandaşlık nedir?$text$, $expl$Dijital vatandaşlık, dijital teknolojilerin kullanımında bireylerin hak ve görevlerinin bütününü ifade eder. İnternet ve sosyal medyanın yasaya uygun olarak sorumlu kullanımını içerir.$expl$, $choices$[{"id":"a","text":"Dijitalin sorumlu kullanımına bağlı hak ve görevlerin bütünü"},{"id":"b","text":"İnternet sitelerini hack etme hakkı"},{"id":"c","text":"Sosyal medyada hesap sahibi olma zorunluluğu"},{"id":"d","text":"Anonim olarak nefret içerikli ifadeler yayınlama hakkı"}]$choices$),
  (281, 'en', $text$What is the duty of remembrance?$text$, $expl$The duty of remembrance is the moral obligation to remember the tragic events of history (wars, genocides, etc.) to prevent them from happening again. It is expressed through commemorations and the teaching of history.$expl$, $choices$[{"id":"a","text":"The moral obligation to remember the tragic events of history"},{"id":"b","text":"The obligation to memorise the Constitution"},{"id":"c","text":"The duty to know all presidents by heart"},{"id":"d","text":"The obligation to visit all museums in France"}]$choices$),
  (281, 'tr', $text$Anma görevi nedir?$text$, $expl$Anma görevi, tarihin trajik olaylarını (savaşlar, soykırımlar vb.) tekrar yaşanmasını önlemek için hatırlamanın ahlaki yükümlülüğüdür. Anma törenleri ve tarih eğitimi ile kendini gösterir.$expl$, $choices$[{"id":"a","text":"Tarihin trajik olaylarını hatırlamanın ahlaki yükümlülüğü"},{"id":"b","text":"Anayasayı ezberleme yükümlülüğü"},{"id":"c","text":"Tüm cumhurbaşkanlarını ezbere bilme görevi"},{"id":"d","text":"Fransa'daki tüm müzeleri ziyaret etme yükümlülüğü"}]$choices$),
  (282, 'en', $text$A person is deprived of their civil and political rights for 5 years following a conviction. Among these statements, which one is correct?$text$, $expl$When a person is deprived of their civil and political rights by court decision, they can no longer vote or stand for election during the period set by the judge.$expl$, $choices$[{"id":"a","text":"They cannot vote or stand for election for 5 years"},{"id":"b","text":"They can continue to vote normally"},{"id":"c","text":"They only lose their right to drive"},{"id":"d","text":"They must leave French territory"}]$choices$),
  (282, 'tr', $text$Bir kişi bir mahkumiyet sonrası 5 yıl boyunca medeni ve siyasi haklarından yoksun bırakılır. Aşağıdaki ifadelerden hangisi doğrudur?$text$, $expl$Bir kişi mahkeme kararıyla medeni ve siyasi haklarından yoksun bırakıldığında, hakim tarafından belirlenen süre boyunca artık oy veremez veya bir seçime aday olamaz.$expl$, $choices$[{"id":"a","text":"5 yıl boyunca oy veremez veya bir seçime aday olamaz"},{"id":"b","text":"Normal şekilde oy vermeye devam edebilir"},{"id":"c","text":"Yalnızca ehliyet hakkını kaybeder"},{"id":"d","text":"Fransız topraklarını terk etmek zorundadır"}]$choices$),
  (537, 'en', $text$You wish to enrol your 7-year-old child in the public school of your neighbourhood. The principal asks for your residence permit before accepting the enrolment. What do you do?$text$, $expl$In France, the right to education is guaranteed for all children residing on the territory, regardless of their parents' administrative status. The school cannot refuse to enrol a child on the grounds that their parents do not have a residence permit.$expl$, $choices$[{"id":"a","text":"You agree to return with your residence permit because it is compulsory"},{"id":"b","text":"You remind them that the right to education applies to all children and that a residence permit is not required for school enrolment"},{"id":"c","text":"You give up enrolling your child in this school"},{"id":"d","text":"You enrol your child in a private school instead"}]$choices$),
  (537, 'tr', $text$7 yaşındaki çocuğunuzu mahallenizdeki devlet okuluna kaydettirmek istiyorsunuz. Müdür kaydı kabul etmeden önce oturma izninizi soruyor. Ne yaparsınız?$text$, $expl$Fransa'da eğitim hakkı, ebeveynlerinin idari durumu ne olursa olsun ülkede ikamet eden tüm çocuklar için güvence altına alınmıştır. Okul, ebeveynlerinin oturma izni olmadığı gerekçesiyle bir çocuğun kaydını reddedemez.$expl$, $choices$[{"id":"a","text":"Zorunlu olduğu için oturma izninizle geri gelmeyi kabul edersiniz"},{"id":"b","text":"Eğitim hakkının tüm çocuklara uygulandığını ve okul kaydı için oturma izninin gerekli olmadığını hatırlatırsınız"},{"id":"c","text":"Çocuğunuzu bu okula kaydettirmekten vazgeçersiniz"},{"id":"d","text":"Bunun yerine çocuğunuzu özel bir okula kaydettirirsiniz"}]$choices$),
  (538, 'en', $text$Your neighbour regularly opens your mailbox and reads your mail. When you talk to him about it, he replies that it doesn't matter because there is nothing secret. What is the right reaction?$text$, $expl$The right to respect for private life is guaranteed by Article 9 of the Civil Code. Opening another person's mail is a criminal offence punished by Article 226-15 of the Penal Code, even if the content is not confidential.$expl$, $choices$[{"id":"a","text":"He is right, it does not matter if the mail contains nothing secret"},{"id":"b","text":"You simply ask him to stop but with no recourse"},{"id":"c","text":"You can file a complaint because opening another person's mail is an offence, whatever the content"},{"id":"d","text":"You change your mailbox because the law does not protect mail"}]$choices$),
  (538, 'tr', $text$Komşunuz düzenli olarak posta kutunuzu açıp mektuplarınızı okuyor. Bu konuda kendisiyle konuştuğunuzda, gizli bir şey olmadığı için önemli olmadığını söylüyor. Doğru tepki nedir?$text$, $expl$Özel hayata saygı hakkı Medeni Kanun'un 9. maddesi tarafından güvence altına alınmıştır. Başkasının mektubunu açmak, içerik gizli olmasa bile Ceza Kanunu'nun 226-15. maddesi tarafından cezalandırılan bir suçtur.$expl$, $choices$[{"id":"a","text":"Mektupta gizli bir şey yoksa haklı, önemli değil"},{"id":"b","text":"Sadece durmasını istersiniz ama başvurabileceğiniz bir yol yok"},{"id":"c","text":"Şikayette bulunabilirsiniz çünkü başkasının mektubunu açmak içerik ne olursa olsun bir suçtur"},{"id":"d","text":"Yasa mektupları korumadığı için posta kutunuzu değiştirirsiniz"}]$choices$),
  (539, 'en', $text$You are stopped by the police in the street. The officers ask you to present an identity document. You do not have one with you. What happens?$text$, $expl$In France, it is not compulsory to carry an identity document at all times. However, in case of a lawful identity check, the police may detain you for up to 4 hours to verify your identity if you cannot prove it on the spot.$expl$, $choices$[{"id":"a","text":"You are immediately arrested and placed in police custody"},{"id":"b","text":"The officers may detain you for up to 4 hours to verify your identity"},{"id":"c","text":"The check is illegal because you are in the street"},{"id":"d","text":"You automatically receive a fine for lack of identity papers"}]$choices$),
  (539, 'tr', $text$Sokakta polis tarafından durduruluyorsunuz. Görevliler kimlik belgesi göstermenizi istiyor. Yanınızda yok. Ne olur?$text$, $expl$Fransa'da her zaman kimlik belgesi taşımak zorunlu değildir. Ancak yasal bir kimlik kontrolü durumunda, kimliğinizi yerinde kanıtlayamazsanız güvenlik güçleri kimliğinizi doğrulamak için sizi 4 saate kadar tutabilir.$expl$, $choices$[{"id":"a","text":"Derhal tutuklanıp gözaltına alınırsınız"},{"id":"b","text":"Görevliler kimliğinizi doğrulamak için sizi 4 saate kadar tutabilir"},{"id":"c","text":"Sokakta olduğunuz için kontrol yasadışıdır"},{"id":"d","text":"Belgesizlik için otomatik olarak para cezası alırsınız"}]$choices$),
  (540, 'en', $text$Your employer forbids you from leaving French territory during your paid leave. Does he have the right to impose this restriction on you?$text$, $expl$The freedom of movement is a fundamental right guaranteed by the Constitution. An employer cannot restrict an employee's freedom of movement during their paid leave, except for a specific mobility clause linked to the exercise of the work.$expl$, $choices$[{"id":"a","text":"Yes, the employer can decide where his employees spend their holidays"},{"id":"b","text":"Yes, but only for foreign employees"},{"id":"c","text":"No, the freedom of movement is a fundamental right, including during paid leave"},{"id":"d","text":"Yes, if it is written in the company's internal regulations"}]$choices$),
  (540, 'tr', $text$İşvereniniz ücretli izniniz sırasında Fransız topraklarını terk etmenizi yasaklıyor. Size bu kısıtlamayı dayatma hakkı var mıdır?$text$, $expl$Dolaşım özgürlüğü Anayasa tarafından güvence altına alınmış temel bir haktır. Bir işveren, işin yerine getirilmesine bağlı belirli bir mobilite hükmü dışında, ücretli izni sırasında bir çalışanın dolaşım özgürlüğünü kısıtlayamaz.$expl$, $choices$[{"id":"a","text":"Evet, işveren çalışanlarının tatilini nerede geçireceğine karar verebilir"},{"id":"b","text":"Evet, ama yalnızca yabancı çalışanlar için"},{"id":"c","text":"Hayır, dolaşım özgürlüğü ücretli izin sırasında da geçerli olan temel bir haktır"},{"id":"d","text":"Evet, şirketin iç tüzüğünde yazılıysa"}]$choices$),
  (541, 'en', $text$Your 16-year-old son is suspected of theft in a shop. The shop manager states in front of other customers that your son is a thief. How do you react?$text$, $expl$In France, every person is presumed innocent until proven guilty by a court. The manager does not have the right to publicly affirm that your son is guilty. He can file a complaint, but the presumption of innocence must be respected.$expl$, $choices$[{"id":"a","text":"The manager has the right to say this since he is the victim of theft"},{"id":"b","text":"You accept the situation because your son is a minor"},{"id":"c","text":"You ask the manager not to call the police"},{"id":"d","text":"You remind the manager that your son benefits from the presumption of innocence and that he cannot accuse him publicly without trial"}]$choices$),
  (541, 'tr', $text$16 yaşındaki oğlunuz bir mağazada hırsızlık yapmaktan şüpheleniliyor. Mağaza müdürü diğer müşterilerin önünde oğlunuzun hırsız olduğunu söylüyor. Nasıl tepki verirsiniz?$text$, $expl$Fransa'da her kişi, bir mahkeme tarafından suçlu ilan edilene kadar masum kabul edilir. Müdürün oğlunuzun suçlu olduğunu alenen iddia etme hakkı yoktur. Şikayette bulunabilir, ancak masumiyet karinesine uyulmalıdır.$expl$, $choices$[{"id":"a","text":"Hırsızlığın mağduru olduğu için müdürün bunu söyleme hakkı vardır"},{"id":"b","text":"Oğlunuz reşit olmadığı için durumu kabullenirsiniz"},{"id":"c","text":"Müdürden polisi aramamasını istersiniz"},{"id":"d","text":"Müdüre oğlunuzun masumiyet karinesinden yararlandığını ve yargılanmadan onu alenen suçlayamayacağını hatırlatırsınız"}]$choices$),
  (542, 'en', $text$You discover that a website has published photos of you taken without your knowledge in a private place. What right can you invoke?$text$, $expl$The right to one's image is part of the right to respect for private life (Article 9 of the Civil Code). Anyone may oppose the publication of their image taken without their consent, especially in a private place. You can demand removal and claim damages.$expl$, $choices$[{"id":"a","text":"You invoke your right to your image and the right to respect for private life to demand the removal of the photos"},{"id":"b","text":"You can do nothing because the photos are already published on the internet"},{"id":"c","text":"You must first prove that the photos cause you harm"},{"id":"d","text":"It is only illegal if the photos are used for commercial purposes"}]$choices$),
  (542, 'tr', $text$Bir internet sitesinin sizin haberiniz olmadan özel bir yerde çekilmiş fotoğraflarınızı yayınladığını keşfediyorsunuz. Hangi hakkı ileri sürebilirsiniz?$text$, $expl$Görüntü hakkı, özel hayata saygı hakkının bir parçasıdır (Medeni Kanun'un 9. maddesi). Herkes, özellikle özel bir yerde rızası olmadan çekilmiş görüntüsünün yayılmasına karşı çıkabilir. Kaldırılmasını talep edebilir ve tazminat isteyebilirsiniz.$expl$, $choices$[{"id":"a","text":"Fotoğrafların kaldırılmasını talep etmek için görüntü hakkı ve özel hayata saygı hakkını ileri sürersiniz"},{"id":"b","text":"Fotoğraflar internette zaten yayınlandığı için hiçbir şey yapamazsınız"},{"id":"c","text":"Önce fotoğrafların size zarar verdiğini kanıtlamanız gerekir"},{"id":"d","text":"Yalnızca fotoğraflar ticari amaçla kullanılırsa yasadışıdır"}]$choices$),
  (543, 'en', $text$You wish to organise a public meeting in your neighbourhood to discuss a construction project. Do you need to obtain prior authorisation?$text$, $expl$In France, freedom of assembly is guaranteed. Public meetings are free and do not require prior authorisation, unlike demonstrations on public roads which must be declared at the prefecture.$expl$, $choices$[{"id":"a","text":"Yes, you must obtain authorisation from the mayor"},{"id":"b","text":"No, public meetings are free and do not require prior authorisation"},{"id":"c","text":"Yes, you must obtain authorisation from the prefecture"},{"id":"d","text":"No, but only if you are a French citizen"}]$choices$),
  (543, 'tr', $text$Bir inşaat projesini tartışmak için mahallenizde halka açık bir toplantı düzenlemek istiyorsunuz. Önceden izin almanız gerekiyor mu?$text$, $expl$Fransa'da toplantı özgürlüğü güvence altına alınmıştır. Halka açık toplantılar serbesttir ve önceden izin gerektirmez; valilikte bildirim gerektiren kamu yolu üzerindeki gösterilerin aksine.$expl$, $choices$[{"id":"a","text":"Evet, belediye başkanından izin almanız gerekir"},{"id":"b","text":"Hayır, halka açık toplantılar serbesttir ve önceden izin gerektirmez"},{"id":"c","text":"Evet, valilikten izin almanız gerekir"},{"id":"d","text":"Hayır, ama yalnızca Fransız vatandaşı iseniz"}]$choices$),
  (544, 'en', $text$Your landlord tells you that he wants to install a surveillance camera in the corridor of your flat for security reasons. What is your position?$text$, $expl$The home is inviolable and the right to respect for private life applies in the tenant's private space. The landlord cannot install a camera in the private parts of the dwelling without the tenant's consent, even for security reasons.$expl$, $choices$[{"id":"a","text":"You accept because the landlord has all rights over his property"},{"id":"b","text":"You accept on condition that the images are not stored"},{"id":"c","text":"You refuse because it infringes on your private life in your home"},{"id":"d","text":"You must accept if it is provided for in the lease"}]$choices$),
  (544, 'tr', $text$Ev sahibiniz güvenlik nedeniyle dairenizin koridoruna bir gözetim kamerası kurmak istediğini bildiriyor. Tutumunuz nedir?$text$, $expl$Konut dokunulmazdır ve özel hayata saygı hakkı kiracının özel alanında geçerlidir. Ev sahibi, güvenlik nedeniyle dahi olsa kiracının rızası olmadan konutun özel bölümlerine kamera kuramaz.$expl$, $choices$[{"id":"a","text":"Ev sahibinin malı üzerinde tüm haklara sahip olduğu için kabul edersiniz"},{"id":"b","text":"Görüntüler saklanmamak koşuluyla kabul edersiniz"},{"id":"c","text":"Evinizde özel hayatınıza saldırı olduğu için reddedersiniz"},{"id":"d","text":"Sözleşmede öngörülmüşse kabul etmek zorundasınız"}]$choices$),
  (545, 'en', $text$During a job interview, the recruiter asks a female candidate if she plans to have children soon. Is this question legal?$text$, $expl$Questions about family situation or motherhood plans are forbidden in a job interview. The Labour Code (Article L1132-1) prohibits any discrimination based on pregnancy or family situation.$expl$, $choices$[{"id":"a","text":"Yes, the recruiter has the right to ask any question he wishes"},{"id":"b","text":"No, this question constitutes discrimination forbidden by law"},{"id":"c","text":"Yes, but only for positions of responsibility"},{"id":"d","text":"Yes, if the company employs fewer than 50 staff"}]$choices$),
  (545, 'tr', $text$Bir iş görüşmesi sırasında, işe alım uzmanı bir kadın adaya yakın zamanda çocuk yapmayı planlayıp planlamadığını soruyor. Bu soru yasal mıdır?$text$, $expl$Aile durumuna veya annelik planlarına ilişkin sorular bir iş görüşmesinde yasaktır. İş Kanunu (madde L1132-1), gebelik veya aile durumuna dayalı her türlü ayrımcılığı yasaklar.$expl$, $choices$[{"id":"a","text":"Evet, işe alım uzmanı istediği soruyu sorma hakkına sahiptir"},{"id":"b","text":"Hayır, bu soru yasanın yasakladığı bir ayrımcılık oluşturur"},{"id":"c","text":"Evet, ama yalnızca sorumluluk pozisyonları için"},{"id":"d","text":"Evet, şirket 50'den az çalışana sahipse"}]$choices$),
  (546, 'en', $text$Your female colleague discovers that she is paid 15% less than a male colleague occupying the same position with the same seniority and the same qualifications. What can she do?$text$, $expl$The principle 'equal pay for equal work' is enshrined in the Labour Code (Article L3221-2). The employer is required to guarantee equal pay between women and men for the same work or work of equal value. The employee can bring the matter before the conseil de prud'hommes (labour court).$expl$, $choices$[{"id":"a","text":"She can do nothing because salaries are freely set by the employer"},{"id":"b","text":"She must first prove that she works more than her colleague"},{"id":"c","text":"She can only speak to her trade union without any legal recourse"},{"id":"d","text":"She can bring the matter before the conseil de prud'hommes (labour court) because the law requires equal pay for equal work"}]$choices$),
  (546, 'tr', $text$Kadın meslektaşınız, aynı kıdem ve aynı niteliklerle aynı pozisyonda çalışan bir erkek meslektaşından %15 daha az kazandığını keşfediyor. Ne yapabilir?$text$, $expl$'Eşit işe eşit ücret' ilkesi İş Kanunu'nun L3221-2. maddesinde yer almaktadır. İşveren, aynı iş veya eşit değerde iş için kadın ve erkekler arasında ücret eşitliğini sağlamak zorundadır. Çalışan conseil de prud'hommes (iş mahkemesi) önünde dava açabilir.$expl$, $choices$[{"id":"a","text":"Maaşlar işveren tarafından serbestçe belirlendiği için hiçbir şey yapamaz"},{"id":"b","text":"Önce meslektaşından daha fazla çalıştığını kanıtlaması gerekir"},{"id":"c","text":"Yalnızca yasal başvuru olmaksızın sendikasıyla konuşabilir"},{"id":"d","text":"Yasa eşit işe eşit ücret zorunlu kıldığı için conseil de prud'hommes (iş mahkemesi) önünde dava açabilir"}]$choices$),
  (547, 'en', $text$In your neighbourhood, a father refuses to send his daughter to secondary school because he believes that studies are not necessary for girls. Is this attitude acceptable in France?$text$, $expl$Education is compulsory for all children aged 3 to 16 in France, without distinction of sex. Refusing to send a child to school may lead to criminal prosecution. Equal access to education between girls and boys is a fundamental principle.$expl$, $choices$[{"id":"a","text":"Yes, parents are free to decide on the schooling of their children"},{"id":"b","text":"No, education is compulsory for all children, girls and boys, and this refusal is contrary to the law"},{"id":"c","text":"Yes, if it is consistent with the family's cultural beliefs"},{"id":"d","text":"No, but only if the girl is under 12"}]$choices$),
  (547, 'tr', $text$Mahallenizdeki bir baba, kızların okumasının gerekli olmadığını düşündüğü için kızını ortaokula göndermeyi reddediyor. Bu tutum Fransa'da kabul edilebilir mi?$text$, $expl$Fransa'da eğitim, cinsiyet ayrımı olmaksızın 3 ile 16 yaş arasındaki tüm çocuklar için zorunludur. Bir çocuğun okula gönderilmemesi cezai kovuşturmaya yol açabilir. Kız ve erkek çocuklar arasında eğitime eşit erişim temel bir ilkedir.$expl$, $choices$[{"id":"a","text":"Evet, ebeveynler çocuklarının eğitimi hakkında karar vermekte özgürdür"},{"id":"b","text":"Hayır, eğitim tüm çocuklar için, kız ve erkek, zorunludur ve bu ret yasaya aykırıdır"},{"id":"c","text":"Evet, ailenin kültürel inançlarına uygunsa"},{"id":"d","text":"Hayır, ama yalnızca kız 12 yaşından küçükse"}]$choices$),
  (548, 'en', $text$Your friend confides that her husband forbids her to work and controls all her expenses. What can you tell her?$text$, $expl$In France, each spouse has the right to exercise a profession freely, even without the other's consent (Article 223 of the Civil Code). Economic control exercised by a spouse may constitute domestic violence within the meaning of the law.$expl$, $choices$[{"id":"a","text":"It is normal, the husband is the head of the family in France"},{"id":"b","text":"She must obey as long as she lives under his roof"},{"id":"c","text":"In France, each spouse has the right to work freely and economic control may be considered domestic violence"},{"id":"d","text":"She must ask the judge for permission to work"}]$choices$),
  (548, 'tr', $text$Arkadaşınız kocasının çalışmasına izin vermediğini ve tüm harcamalarını kontrol ettiğini söylüyor. Ona ne söyleyebilirsiniz?$text$, $expl$Fransa'da her eş, diğerinin rızası olmasa bile serbestçe meslek icra etme hakkına sahiptir (Medeni Kanun'un 223. maddesi). Bir eş tarafından uygulanan ekonomik kontrol, yasa anlamında eş içi şiddet teşkil edebilir.$expl$, $choices$[{"id":"a","text":"Bu normaldir, Fransa'da koca aile reisidir"},{"id":"b","text":"Onun çatısı altında yaşadığı sürece itaat etmelidir"},{"id":"c","text":"Fransa'da her eş serbestçe çalışma hakkına sahiptir ve ekonomik kontrol eş içi şiddet olarak kabul edilebilir"},{"id":"d","text":"Çalışabilmek için hakimden izin istemesi gerekir"}]$choices$),
  (549, 'en', $text$At a parent-teacher meeting, a father states that boys should have priority for sports activities at school. What is the position of French law?$text$, $expl$The principle of equality between girls and boys is enshrined in the Education Code. The school must guarantee equal access to all activities, including sports, without discrimination based on sex.$expl$, $choices$[{"id":"a","text":"The law guarantees equal access to sports activities for girls and boys at school"},{"id":"b","text":"Boys do indeed have priority in competitive sports"},{"id":"c","text":"The school can freely decide on the distribution of sports activities"},{"id":"d","text":"It is up to parents to decide which activities are suitable for their children"}]$choices$),
  (549, 'tr', $text$Bir veli toplantısında bir baba, okuldaki sportif faaliyetlerde erkeklerin öncelikli olması gerektiğini söylüyor. Fransız yasasının tutumu nedir?$text$, $expl$Kız ve erkek çocuklar arasında eşitlik ilkesi Eğitim Kanunu'nda yer alır. Okul, cinsiyete dayalı ayrımcılık olmaksızın sportif olanlar dahil tüm faaliyetlere eşit erişimi sağlamak zorundadır.$expl$, $choices$[{"id":"a","text":"Yasa, okulda kız ve erkeklere sportif faaliyetlere eşit erişim güvencesi verir"},{"id":"b","text":"Yarışmacı sporlarda erkekler gerçekten önceliklidir"},{"id":"c","text":"Okul sportif faaliyetlerin dağılımına serbestçe karar verebilir"},{"id":"d","text":"Hangi faaliyetlerin çocuklarına uygun olduğuna ebeveynler karar verir"}]$choices$),
  (550, 'en', $text$A couple of your acquaintance wishes to marry. The future bride is 17 years old and her parents agree. Can the marriage take place in France?$text$, $expl$Since 2006, the legal minimum age of marriage is set at 18 for both women and men in France. An exceptional dispensation may be granted by the public prosecutor for serious reasons, but parental consent alone is not sufficient.$expl$, $choices$[{"id":"a","text":"Yes, because the parents give their consent"},{"id":"b","text":"No, the legal age of marriage is 18 for everyone, except by exceptional dispensation from the public prosecutor"},{"id":"c","text":"Yes, because the minimum age is 16 for girls in France"},{"id":"d","text":"Yes, if the future husband is over 18"}]$choices$),
  (550, 'tr', $text$Çevrenizden bir çift evlenmek istiyor. Müstakbel gelin 17 yaşında ve ebeveynleri buna razı. Evlilik Fransa'da gerçekleşebilir mi?$text$, $expl$2006'dan beri, Fransa'da yasal evlilik yaşı kadınlar ve erkekler için 18 olarak belirlenmiştir. Ciddi nedenlerle Cumhuriyet Savcısı tarafından istisnai bir muafiyet verilebilir, ancak yalnızca ebeveyn rızası yeterli değildir.$expl$, $choices$[{"id":"a","text":"Evet, çünkü ebeveynler rızasını veriyor"},{"id":"b","text":"Hayır, yasal evlilik yaşı herkes için 18'dir, Cumhuriyet Savcısı'nın istisnai muafiyeti hariç"},{"id":"c","text":"Evet, çünkü Fransa'da kızlar için asgari yaş 16'dır"},{"id":"d","text":"Evet, müstakbel koca 18 yaşından büyükse"}]$choices$),
  (551, 'en', $text$Your employer refuses to grant you paternity leave on the birth of your child, saying that 'it is leave for mothers'. Is he right?$text$, $expl$Paternity and childcare leave has been a right for all salaried fathers since 2002, extended to 25 days since 2021. The employer cannot refuse this leave. It is a right linked to equality between women and men in parenthood.$expl$, $choices$[{"id":"a","text":"Yes, only mothers are entitled to leave at birth"},{"id":"b","text":"No, paternity leave is a right for all salaried fathers and the employer cannot refuse it"},{"id":"c","text":"Paternity leave only exists in the public service"},{"id":"d","text":"Yes, unless the company has more than 250 employees"}]$choices$),
  (551, 'tr', $text$İşvereniniz çocuğunuzun doğumunda size babalık izni vermeyi 'bu annelere yönelik bir izindir' diyerek reddediyor. Haklı mıdır?$text$, $expl$Babalık ve çocuk karşılama izni 2002'den beri tüm ücretli babalar için bir haktır, 2021'den beri 25 güne uzatılmıştır. İşveren bu izni reddedemez. Bu, ebeveynlikte kadın ve erkek arasındaki eşitliğe bağlı bir haktır.$expl$, $choices$[{"id":"a","text":"Evet, yalnızca anneler doğumda izin hakkına sahiptir"},{"id":"b","text":"Hayır, babalık izni tüm ücretli babalar için bir haktır ve işveren reddedemez"},{"id":"c","text":"Babalık izni yalnızca kamu hizmetinde vardır"},{"id":"d","text":"Evet, şirket 250'den fazla çalışana sahip değilse"}]$choices$),
  (552, 'en', $text$You have been working in France for a year and have never declared your income to the tax authorities. A friend tells you that it is not compulsory for foreigners. Is he right?$text$, $expl$Every person residing in France and earning income must declare it to the tax authorities, whatever their nationality. The payment of tax is a duty that applies to all French tax residents.$expl$, $choices$[{"id":"a","text":"Yes, only French citizens must declare their income"},{"id":"b","text":"Yes, foreigners do not pay tax in France"},{"id":"c","text":"No, he is wrong: every person residing in France must declare their income, whatever their nationality"},{"id":"d","text":"Yes, unless you earn more than 30,000 euros per year"}]$choices$),
  (552, 'tr', $text$Bir yıldır Fransa'da çalışıyorsunuz ve hiç vergi beyannamesi vermediniz. Bir arkadaşınız yabancılar için zorunlu olmadığını söylüyor. Haklı mıdır?$text$, $expl$Fransa'da ikamet edip gelir elde eden herkes, milliyeti ne olursa olsun bunu vergi idaresine beyan etmek zorundadır. Vergi ödemek, tüm Fransız vergi mükelleflerine uygulanan bir görevdir.$expl$, $choices$[{"id":"a","text":"Evet, yalnızca Fransız vatandaşları gelirlerini beyan etmek zorundadır"},{"id":"b","text":"Evet, yabancılar Fransa'da vergi ödemez"},{"id":"c","text":"Hayır, yanılıyor: Fransa'da ikamet eden herkes milliyeti ne olursa olsun gelirini beyan etmelidir"},{"id":"d","text":"Evet, yılda 30.000 avrodan fazla kazanmıyorsanız"}]$choices$),
  (553, 'en', $text$You receive a summons to be a juror in a cour d'assises. You do not wish to participate because it disrupts your schedule. Can you refuse?$text$, $expl$Participation as a juror in the cour d'assises is a compulsory civic duty for any French citizen on the electoral lists. Refusing without a legitimate reason is punishable by a fine of 3,750 euros. Only certain reasons such as age (over 70) or serious illness allow exemption.$expl$, $choices$[{"id":"a","text":"Yes, participation in the jury is optional"},{"id":"b","text":"Yes, if your employer refuses to release you"},{"id":"c","text":"Yes, by paying a replacement contribution"},{"id":"d","text":"No, it is a compulsory civic duty and refusal without a legitimate reason is punishable by a fine"}]$choices$),
  (553, 'tr', $text$Cour d'assises jürisi olmak için bir çağrı alıyorsunuz. Programınızı bozduğu için katılmak istemiyorsunuz. Reddedebilir misiniz?$text$, $expl$Cour d'assises jürisine katılım, seçmen listelerinde kayıtlı her Fransız vatandaşı için zorunlu bir vatandaşlık görevidir. Meşru bir neden olmadan reddetmek 3.750 avro para cezası gerektirir. Yalnızca yaş (70 üzeri) veya ağır hastalık gibi belirli nedenler muafiyete olanak tanır.$expl$, $choices$[{"id":"a","text":"Evet, jüri katılımı isteğe bağlıdır"},{"id":"b","text":"Evet, işvereniniz sizi serbest bırakmayı reddederse"},{"id":"c","text":"Evet, bir vekalet ödeyerek"},{"id":"d","text":"Hayır, zorunlu bir vatandaşlık görevidir ve meşru bir neden olmadan reddetmek para cezası gerektirir"}]$choices$),
  (554, 'en', $text$You witness a road accident. The victim is injured and lying on the ground. What must you do as a priority?$text$, $expl$In France, every person witnessing an accident has a legal obligation to assist a person in danger (Article 223-6 of the Penal Code). Not assisting is the offence of non-assistance to a person in danger. You must at the very least call the emergency services (15, 18 or 112).$expl$, $choices$[{"id":"a","text":"You can continue on your way, it is not your responsibility"},{"id":"b","text":"You must call the emergency services and, if possible, assist the victim"},{"id":"c","text":"You must only alert the police, not the emergency services"},{"id":"d","text":"You wait for someone else to intervene"}]$choices$),
  (554, 'tr', $text$Bir trafik kazasına tanık oluyorsunuz. Mağdur yaralı ve yerde yatıyor. Öncelikli olarak ne yapmalısınız?$text$, $expl$Fransa'da bir kazaya tanık olan her kişinin tehlikedeki bir kişiye yardım etme yasal yükümlülüğü vardır (Ceza Kanunu'nun 223-6. maddesi). Yardım etmemek tehlikedeki bir kişiye yardım etmeme suçudur. En azından acil servisleri (15, 18 veya 112) aramanız gerekir.$expl$, $choices$[{"id":"a","text":"Yolunuza devam edebilirsiniz, sizin sorumluluğunuz değildir"},{"id":"b","text":"Acil servisleri aramalı ve mümkünse mağdura yardım etmelisiniz"},{"id":"c","text":"Yalnızca polisi uyarmalısınız, acil servisleri değil"},{"id":"d","text":"Başka birinin müdahale etmesini beklersiniz"}]$choices$),
  (555, 'en', $text$In your building, a neighbour systematically parks his car in front of the emergency exit, blocking access. What do you do?$text$, $expl$Respect for safety rules is a duty of every citizen. Blocking an emergency exit endangers the lives of the building's occupants. You can report this offence to the building manager, the town hall or the law enforcement authorities.$expl$, $choices$[{"id":"a","text":"You do nothing because it is a private problem between neighbours"},{"id":"b","text":"You move your neighbour's car yourself"},{"id":"c","text":"You report the situation to the building manager and, if necessary, to the competent authorities"},{"id":"d","text":"You also block the emergency exit with your vehicle in retaliation"}]$choices$),
  (555, 'tr', $text$Binanızda bir komşu arabasını sürekli olarak acil çıkışın önüne park ederek erişimi engelliyor. Ne yaparsınız?$text$, $expl$Güvenlik kurallarına uyma her vatandaşın görevidir. Bir acil çıkışı engellemek bina sakinlerinin hayatını tehlikeye atar. Bu suçu apartman yöneticisine, belediyeye veya güvenlik güçlerine bildirebilirsiniz.$expl$, $choices$[{"id":"a","text":"Komşular arası özel bir sorun olduğu için hiçbir şey yapmazsınız"},{"id":"b","text":"Komşunuzun arabasını kendiniz çekersiniz"},{"id":"c","text":"Durumu apartman yöneticisine ve gerekirse yetkili makamlara bildirirsiniz"},{"id":"d","text":"Misilleme olarak acil çıkışı kendi aracınızla da engellersiniz"}]$choices$),
  (556, 'en', $text$You discover that your employer makes undocumented people work in indecent conditions and without declaring them. What must you do?$text$, $expl$Undeclared work and exploitation of vulnerable persons are serious offences in France. Every citizen has a duty to report serious offences of which they are aware. You can alert the labour inspectorate, the police or the public prosecutor.$expl$, $choices$[{"id":"a","text":"You do nothing because it does not concern you directly"},{"id":"b","text":"You only talk about it to your colleagues"},{"id":"c","text":"You help your employer hide the situation"},{"id":"d","text":"You report the situation to the labour inspectorate or the competent authorities"}]$choices$),
  (556, 'tr', $text$İşvereninizin belgesiz kişileri insanlık dışı koşullarda ve onları beyan etmeden çalıştırdığını keşfediyorsunuz. Ne yapmalısınız?$text$, $expl$Kayıtdışı çalışma ve kırılgan kişilerin sömürülmesi Fransa'da ağır suçlardır. Her vatandaş bildiği ağır suçları bildirmekle yükümlüdür. İş müfettişliğini, polisi veya Cumhuriyet Savcısı'nı uyarabilirsiniz.$expl$, $choices$[{"id":"a","text":"Sizi doğrudan ilgilendirmediği için hiçbir şey yapmazsınız"},{"id":"b","text":"Yalnızca meslektaşlarınızla konuşursunuz"},{"id":"c","text":"İşvereninizin durumu gizlemesine yardım edersiniz"},{"id":"d","text":"Durumu iş müfettişliğine veya yetkili makamlara bildirirsiniz"}]$choices$),
  (557, 'en', $text$You are a French citizen and the municipal elections are approaching. You think that voting is useless. What is the reality concerning voting in France?$text$, $expl$In France, voting is not legally compulsory (unlike in some other countries), but it is considered a fundamental civic duty. It is the main means for citizens to participate in democratic life and to influence the decisions that concern them.$expl$, $choices$[{"id":"a","text":"Voting is compulsory and you risk a fine if you do not vote"},{"id":"b","text":"Voting is not compulsory in France but it is a civic duty essential to democracy"},{"id":"c","text":"Voting is reserved for people born in France"},{"id":"d","text":"Only presidential elections are important, municipal elections are optional"}]$choices$),
  (557, 'tr', $text$Fransız vatandaşısınız ve belediye seçimleri yaklaşıyor. Oy vermenin işe yaramadığını düşünüyorsunuz. Fransa'da oy verme konusundaki gerçek nedir?$text$, $expl$Fransa'da oy vermek yasal olarak zorunlu değildir (diğer bazı ülkelerin aksine), ancak temel bir vatandaşlık görevi olarak kabul edilir. Vatandaşların demokratik yaşama katılmaları ve kendilerini ilgilendiren kararları etkilemeleri için ana araçtır.$expl$, $choices$[{"id":"a","text":"Oy vermek zorunludur ve oy vermezseniz para cezası alırsınız"},{"id":"b","text":"Oy vermek Fransa'da zorunlu değildir ancak demokrasi için temel bir vatandaşlık görevidir"},{"id":"c","text":"Oy vermek Fransa'da doğmuş kişilere ayrılmıştır"},{"id":"d","text":"Yalnızca cumhurbaşkanlığı seçimleri önemlidir, belediye seçimleri isteğe bağlıdır"}]$choices$),
  (558, 'en', $text$Your 17-year-old son has been summoned for the JDC (Journée défense et citoyenneté, Defence and Citizenship Day). He tells you that he does not want to go. What do you reply?$text$, $expl$The JDC (Journée défense et citoyenneté, Defence and Citizenship Day) is compulsory for all young French citizens, girls and boys, aged between 16 and 25. The participation certificate is required to register for examinations and public competitive exams (baccalauréat, driving licence, etc.).$expl$, $choices$[{"id":"a","text":"He can refuse because military service no longer exists"},{"id":"b","text":"The JDC (Defence and Citizenship Day) is compulsory and the certificate is required to take examinations such as the baccalauréat or the driving licence"},{"id":"c","text":"The JDC is only compulsory for boys"},{"id":"d","text":"He can postpone it indefinitely without consequence"}]$choices$),
  (558, 'tr', $text$17 yaşındaki oğlunuz JDC (Journée défense et citoyenneté, Savunma ve Vatandaşlık Günü) için çağrılmıştır. Gitmek istemediğini söylüyor. Ne cevap verirsiniz?$text$, $expl$JDC (Journée défense et citoyenneté, Savunma ve Vatandaşlık Günü), 16 ile 25 yaş arasındaki tüm Fransız gençleri için, kız ve erkek, zorunludur. Katılım belgesi sınav ve kamu yarışmalarına (baccalauréat, ehliyet vb.) kayıt için gereklidir.$expl$, $choices$[{"id":"a","text":"Reddedebilir çünkü askerlik hizmeti artık yok"},{"id":"b","text":"JDC (Savunma ve Vatandaşlık Günü) zorunludur ve belge baccalauréat veya ehliyet gibi sınavlar için gereklidir"},{"id":"c","text":"JDC yalnızca erkekler için zorunludur"},{"id":"d","text":"Sonuç olmaksızın süresiz olarak erteleyebilir"}]$choices$),
  (559, 'en', $text$You notice that a child in your neighbourhood regularly shows marks of blows and seems frightened by his parents. What is your responsibility?$text$, $expl$In France, every person who is aware of mistreatment of a minor has a legal obligation to report it to the authorities (Article 434-3 of the Penal Code). You can call 119 (national number for child endangerment) or alert social services or the police.$expl$, $choices$[{"id":"a","text":"You do nothing because it is a family matter and you should not get involved"},{"id":"b","text":"You talk about it to other neighbours to get their opinion"},{"id":"c","text":"You have a legal obligation to report the situation to the authorities, for example by calling 119"},{"id":"d","text":"You wait until you have formal evidence before reacting"}]$choices$),
  (559, 'tr', $text$Mahallenizdeki bir çocuğun düzenli olarak darp izleri taşıdığını ve ebeveynlerinden korktuğunu fark ediyorsunuz. Sorumluluğunuz nedir?$text$, $expl$Fransa'da bir küçüğe kötü muamele yapıldığını bilen her kişinin bunu yetkililere bildirme yasal yükümlülüğü vardır (Ceza Kanunu'nun 434-3. maddesi). 119'u (tehlikedeki çocuk için ulusal numara) arayabilir veya sosyal hizmetleri veya polisi uyarabilirsiniz.$expl$, $choices$[{"id":"a","text":"Aile meselesi olduğu için ve karışmamanız gerektiği için hiçbir şey yapmazsınız"},{"id":"b","text":"Görüşlerini almak için diğer komşularla konuşursunuz"},{"id":"c","text":"Durumu yetkililere bildirme, örneğin 119'u arama yasal yükümlülüğünüz vardır"},{"id":"d","text":"Tepki vermeden önce kesin kanıtlarınızın olmasını beklersiniz"}]$choices$),
  (560, 'en', $text$During an online debate, an internet user publishes hateful remarks against a religious community, invoking freedom of expression. Is he right to defend himself in this way?$text$, $expl$Freedom of expression is a fundamental right but it has limits. Incitement to racial or religious hatred is an offence punished by law (law of 29 July 1881 and Article 24). Freedom of expression does not protect discriminatory, defamatory or hate-inciting remarks.$expl$, $choices$[{"id":"a","text":"Yes, freedom of expression is absolute in France and protects all remarks"},{"id":"b","text":"No, freedom of expression has limits and incitement to religious hatred is an offence"},{"id":"c","text":"Yes, because French laws do not apply on the internet"},{"id":"d","text":"Yes, provided no specific names are cited"}]$choices$),
  (560, 'tr', $text$Çevrimiçi bir tartışma sırasında, bir internet kullanıcısı ifade özgürlüğüne dayanarak bir dini topluluğa karşı nefret içerikli yorumlar yayınlıyor. Kendisini bu şekilde savunmakta haklı mıdır?$text$, $expl$İfade özgürlüğü temel bir haktır ancak sınırları vardır. Irksal veya dinsel nefrete teşvik, yasayla cezalandırılan bir suçtur (29 Temmuz 1881 yasası ve 24. madde). İfade özgürlüğü ayrımcı, iftira içeren veya nefrete teşvik eden ifadeleri korumaz.$expl$, $choices$[{"id":"a","text":"Evet, ifade özgürlüğü Fransa'da mutlaktır ve tüm sözleri korur"},{"id":"b","text":"Hayır, ifade özgürlüğünün sınırları vardır ve dinsel nefrete teşvik bir suçtur"},{"id":"c","text":"Evet, çünkü internette Fransız yasaları geçerli değildir"},{"id":"d","text":"Evet, belirli isimler söylenmediği sürece"}]$choices$),
  (561, 'en', $text$Your neighbour organises a party with very loud music every Saturday evening until 4 a.m. You ask him to turn down the volume, but he replies that he is at home and does whatever he wants. Is he right?$text$, $expl$The right of property and the freedom to enjoy one's home are not absolute. Excessive noise nuisance, especially at night (between 10 p.m. and 7 a.m.), constitutes an abnormal neighbourhood disturbance sanctioned by law. You can call the police, who may draw up a report.$expl$, $choices$[{"id":"a","text":"Yes, he is free to do whatever he wants at home at any time"},{"id":"b","text":"No, nocturnal noise nuisance is forbidden and you can call the police"},{"id":"c","text":"Yes, but only at weekends"},{"id":"d","text":"No, but only if the noise exceeds 100 decibels"}]$choices$),
  (561, 'tr', $text$Komşunuz her cumartesi akşamı sabah 4'e kadar çok yüksek sesle müzikle parti veriyor. Sesi kısmasını istiyorsunuz ama kendi evinde olduğunu ve istediğini yaptığını söylüyor. Haklı mıdır?$text$, $expl$Mülkiyet hakkı ve evden yararlanma özgürlüğü mutlak değildir. Özellikle gece (saat 22 ile 7 arasında) aşırı gürültü, yasayla cezalandırılan anormal bir komşuluk rahatsızlığı oluşturur. Polisi arayabilirsiniz, polis tutanak düzenleyebilir.$expl$, $choices$[{"id":"a","text":"Evet, evinde istediği saatte istediğini yapmakta özgürdür"},{"id":"b","text":"Hayır, gece gürültüsü yasaktır ve polisi arayabilirsiniz"},{"id":"c","text":"Evet, ama yalnızca hafta sonu"},{"id":"d","text":"Hayır, ama yalnızca gürültü 100 desibeli aşarsa"}]$choices$),
  (562, 'en', $text$The town hall wishes to build a road that would pass through your land. You are offered compensation but you refuse to sell. Can the town hall force you to do so?$text$, $expl$The right of property is a fundamental right, but it can be limited for reasons of public utility. The expropriation procedure allows the State or local authorities to force an owner to give up their property in exchange for a fair and prior indemnity, in accordance with the Déclaration des Droits de l'Homme (Article 17).$expl$, $choices$[{"id":"a","text":"No, the right of property is absolute and no one can force you to sell"},{"id":"b","text":"Yes, the town hall can take your land without any compensation"},{"id":"c","text":"Yes, through the expropriation procedure for public utility, with fair compensation"},{"id":"d","text":"No, except if you are a tenant and not an owner"}]$choices$),
  (562, 'tr', $text$Belediye, arazinizden geçecek bir yol inşa etmek istiyor. Size bir tazminat öneriliyor ancak satmayı reddediyorsunuz. Belediye sizi buna zorlayabilir mi?$text$, $expl$Mülkiyet hakkı temel bir haktır, ancak kamu yararı nedeniyle sınırlanabilir. Kamulaştırma prosedürü, Devlet veya yerel yönetimlerin İnsan Hakları Bildirgesi'ne (17. madde) uygun olarak adil ve önceden bir tazminat karşılığında bir maliki malını devretmeye zorlamasına olanak tanır.$expl$, $choices$[{"id":"a","text":"Hayır, mülkiyet hakkı mutlaktır ve kimse sizi satmaya zorlayamaz"},{"id":"b","text":"Evet, belediye arazinizi tazminat ödemeden alabilir"},{"id":"c","text":"Evet, kamu yararı için kamulaştırma prosedürüyle, adil bir tazminat karşılığında"},{"id":"d","text":"Hayır, kiracı olduğunuzda ve malik olmadığınızda hariç"}]$choices$),
  (563, 'en', $text$You wish to demonstrate in the street against a law you consider unjust. Can you organise this demonstration freely?$text$, $expl$The right to demonstrate is guaranteed in France, but it is regulated. Any demonstration on a public road must be the subject of a prior declaration to the prefecture at least 3 days in advance. The prefect may forbid it if he considers that it risks seriously disturbing public order.$expl$, $choices$[{"id":"a","text":"Yes, the right to demonstrate is totally free and without condition"},{"id":"b","text":"No, demonstrations are forbidden in France"},{"id":"c","text":"Yes, but you must make a prior declaration to the prefecture"},{"id":"d","text":"Yes, but only if you have French nationality"}]$choices$),
  (563, 'tr', $text$Adaletsiz bulduğunuz bir yasaya karşı sokakta gösteri yapmak istiyorsunuz. Bu gösteriyi serbestçe düzenleyebilir misiniz?$text$, $expl$Gösteri yapma hakkı Fransa'da güvence altına alınmıştır ancak düzenlenmiştir. Kamu yolu üzerindeki herhangi bir gösteri en az 3 gün önceden valiliğe önceden bildirim yapılmasını gerektirir. Vali, kamu düzenini ciddi şekilde bozma riski taşıdığına kanaat getirirse yasaklayabilir.$expl$, $choices$[{"id":"a","text":"Evet, gösteri yapma hakkı tamamen serbesttir ve koşulsuzdur"},{"id":"b","text":"Hayır, gösteriler Fransa'da yasaktır"},{"id":"c","text":"Evet, ama valiliğe önceden bildirim yapmanız gerekir"},{"id":"d","text":"Evet, ama yalnızca Fransız vatandaşıysanız"}]$choices$),
  (564, 'en', $text$You are the owner of a flat and you refuse to rent it to a family because of their ethnic origin. Your real estate agent supports you in this approach. What does the law say?$text$, $expl$Discrimination in housing based on ethnic origin is an offence punished by law (Article 225-1 of the Penal Code). Both the owner and the real estate agent are exposed to criminal prosecution, which can go up to 3 years of imprisonment and 45,000 euros in fines.$expl$, $choices$[{"id":"a","text":"The owner is free to choose his tenant according to whatever criteria he wishes"},{"id":"b","text":"It is legal if the real estate agent agrees"},{"id":"c","text":"It is illegal discrimination punishable by criminal prosecution for the owner and the real estate agent"},{"id":"d","text":"It is forbidden only for social housing"}]$choices$),
  (564, 'tr', $text$Bir dairenin sahibi sizsiniz ve bir aileyi etnik kökeni nedeniyle kiraya vermeyi reddediyorsunuz. Emlakçınız bu yaklaşımda size destek oluyor. Yasa ne diyor?$text$, $expl$Etnik kökene dayalı konut ayrımcılığı yasayla cezalandırılan bir suçtur (Ceza Kanunu'nun 225-1. maddesi). Hem malik hem de emlakçı, 3 yıla kadar hapis ve 45.000 avro para cezasına kadar varabilen cezai kovuşturmaya maruz kalır.$expl$, $choices$[{"id":"a","text":"Malik kiracısını istediği kriterlere göre seçmekte özgürdür"},{"id":"b","text":"Emlakçı kabul ederse yasaldır"},{"id":"c","text":"Malik ve emlakçı için cezai kovuşturma gerektiren yasadışı bir ayrımcılıktır"},{"id":"d","text":"Yalnızca sosyal konut için yasaktır"}]$choices$),
  (565, 'en', $text$You film a police officer during a check in the street and he asks you to stop, saying that it is forbidden. Is he right?$text$, $expl$In France, it is legal to film police officers in the exercise of their functions in public space, on condition of not hindering their action. The law for global security does not call this right into question. However, the dissemination of images with the aim of harming an officer's physical or psychological integrity is forbidden.$expl$, $choices$[{"id":"a","text":"Yes, it is totally forbidden to film the police in France"},{"id":"b","text":"No, you have the right to film police officers in public space as long as you do not hinder their action"},{"id":"c","text":"Yes, except if you are an accredited journalist"},{"id":"d","text":"No, but you must obtain their written authorisation before broadcasting the images"}]$choices$),
  (565, 'tr', $text$Sokakta bir kontrol sırasında bir polis memurunu filme alıyorsunuz ve yasak olduğunu söyleyerek durmanızı istiyor. Haklı mıdır?$text$, $expl$Fransa'da, polislerin görevlerini ifa ederken kamusal alanda filme alınması, eylemlerini engellememek koşuluyla yasaldır. Küresel güvenlik yasası bu hakkı sorgulamaz. Ancak bir görevlinin fiziksel veya psikolojik bütünlüğüne zarar verme amacıyla görüntülerin yayılması yasaktır.$expl$, $choices$[{"id":"a","text":"Evet, Fransa'da polisi filme almak tamamen yasaktır"},{"id":"b","text":"Hayır, eylemlerini engellemediğiniz sürece kamusal alandaki polisi filme alma hakkınız vardır"},{"id":"c","text":"Evet, akredite gazeteci değilseniz"},{"id":"d","text":"Hayır, ancak görüntüleri yayınlamadan önce yazılı izinlerini almanız gerekir"}]$choices$),
  (566, 'en', $text$Your religious association wishes to organise a prayer in a public park. The mayor opposes this, invoking secularism. Is this prohibition justified?$text$, $expl$Secularism (laïcité) requires the neutrality of the State, not the prohibition of all religious expression in public space. Citizens are free to practise their religion, including in public space, as long as they do not disturb public order. The mayor can only forbid a prayer in a park if it actually threatens public order.$expl$, $choices$[{"id":"a","text":"Yes, secularism forbids any religious expression in public space"},{"id":"b","text":"Yes, only churches can host prayers"},{"id":"c","text":"No, secularism imposes the neutrality of the State but does not forbid religious practice in public space, except in case of disturbance of public order"},{"id":"d","text":"No, but only if the association is officially recognised by the State"}]$choices$),
  (566, 'tr', $text$Dini derneğiniz halka açık bir parkta dua düzenlemek istiyor. Belediye başkanı laikliğe dayanarak buna karşı çıkıyor. Bu yasak haklı mıdır?$text$, $expl$Laiklik, kamusal alanda her türlü dini ifadenin yasaklanmasını değil, Devletin tarafsızlığını gerektirir. Vatandaşlar, kamu düzenini bozmadıkları sürece kamusal alanda da dahil olmak üzere dinlerini uygulamakta özgürdür. Belediye başkanı bir parktaki duayı yalnızca gerçekten kamu düzenini tehdit ediyorsa yasaklayabilir.$expl$, $choices$[{"id":"a","text":"Evet, laiklik kamusal alanda her türlü dini ifadeyi yasaklar"},{"id":"b","text":"Evet, yalnızca kiliseler dua barındırabilir"},{"id":"c","text":"Hayır, laiklik Devletin tarafsızlığını dayatır ama kamusal alanda dini pratiği yasaklamaz, kamu düzenini bozma durumu hariç"},{"id":"d","text":"Hayır, ancak yalnızca dernek Devlet tarafından resmi olarak tanınmışsa"}]$choices$)
INSERT INTO question_translations (question_id, lang, text, explanation, choices) VALUES
  (283, 'en', $text$In what year did the French Revolution begin?$text$, $expl$The French Revolution began in 1789 with the storming of the Bastille on 14 July. This event marks the end of the Ancien Régime and the beginning of an era of profound political and social changes in France.$expl$, $choices$[{"id":"a","text":"1789"},{"id":"b","text":"1799"},{"id":"c","text":"1776"},{"id":"d","text":"1815"}]$choices$),
  (283, 'tr', $text$Fransız Devrimi hangi yılda başladı?$text$, $expl$Fransız Devrimi, 14 Temmuz'da Bastille'in ele geçirilmesiyle 1789'da başladı. Bu olay, Ancien Régime'in (Eski Rejim) sonunu ve Fransa'da derin siyasi ve sosyal değişikliklerin başlangıcını işaret eder.$expl$, $choices$[{"id":"a","text":"1789"},{"id":"b","text":"1799"},{"id":"c","text":"1776"},{"id":"d","text":"1815"}]$choices$),
  (284, 'en', $text$Who was Napoleon I?$text$, $expl$Napoleon I was Emperor of the French from 1804 to 1814, then briefly in 1815. He modernised the French administration and established the Civil Code, still in force today.$expl$, $choices$[{"id":"a","text":"The first Emperor of the French"},{"id":"b","text":"The last king of France"},{"id":"c","text":"The founder of the Fifth Republic"},{"id":"d","text":"A general in the First World War"}]$choices$),
  (284, 'tr', $text$Napoléon Ier (I. Napolyon) kimdi?$text$, $expl$I. Napolyon, 1804'ten 1814'e kadar, ardından kısa bir süre 1815'te Fransızların İmparatoru'ydu. Fransız yönetimini modernleştirdi ve bugün hâlâ yürürlükte olan Medeni Kanun'u (Code civil) yürürlüğe koydu.$expl$, $choices$[{"id":"a","text":"Fransızların ilk İmparatoru"},{"id":"b","text":"Fransa'nın son kralı"},{"id":"c","text":"Beşinci Cumhuriyet'in kurucusu"},{"id":"d","text":"Birinci Dünya Savaşı generali"}]$choices$),
  (285, 'en', $text$Which of these historical figures is French?$text$, $expl$Jeanne d'Arc is an emblematic figure of French history. She led French armies against the English during the Hundred Years' War in the 15th century.$expl$, $choices$[{"id":"a","text":"Jeanne d'Arc"},{"id":"b","text":"Christopher Columbus"},{"id":"c","text":"Winston Churchill"},{"id":"d","text":"Leonardo da Vinci"}]$choices$),
  (285, 'tr', $text$Bu tarihi kişilerden hangisi Fransızdır?$text$, $expl$Jeanne d'Arc (Jan Dark), Fransız tarihinin sembolik bir figürüdür. 15. yüzyılda Yüzyıl Savaşı sırasında Fransız ordularını İngilizlere karşı yönetti.$expl$, $choices$[{"id":"a","text":"Jeanne d'Arc"},{"id":"b","text":"Kristof Kolomb"},{"id":"c","text":"Winston Churchill"},{"id":"d","text":"Leonardo da Vinci"}]$choices$),
  (286, 'en', $text$Which Republic are we in today?$text$, $expl$France is currently under the Fifth Republic, established in 1958 by General de Gaulle. It strengthened the power of the President of the Republic.$expl$, $choices$[{"id":"a","text":"The Fifth Republic"},{"id":"b","text":"The Fourth Republic"},{"id":"c","text":"The Third Republic"},{"id":"d","text":"The Sixth Republic"}]$choices$),
  (286, 'tr', $text$Bugün hangi Cumhuriyet'teyiz?$text$, $expl$Fransa şu anda 1958'de General de Gaulle tarafından kurulan Beşinci Cumhuriyet altındadır. Cumhurbaşkanının yetkisini güçlendirmiştir.$expl$, $choices$[{"id":"a","text":"Beşinci Cumhuriyet"},{"id":"b","text":"Dördüncü Cumhuriyet"},{"id":"c","text":"Üçüncü Cumhuriyet"},{"id":"d","text":"Altıncı Cumhuriyet"}]$choices$),
  (287, 'en', $text$What is the Shoah?$text$, $expl$The Shoah refers to the genocide of European Jews by Nazi Germany during the Second World War. About six million Jews were exterminated between 1941 and 1945.$expl$, $choices$[{"id":"a","text":"The genocide of Jews during the Second World War"},{"id":"b","text":"A battle of the First World War"},{"id":"c","text":"A European peace treaty"},{"id":"d","text":"The French Resistance against the occupation"}]$choices$),
  (287, 'tr', $text$Shoah (Holokost) nedir?$text$, $expl$Shoah, İkinci Dünya Savaşı sırasında Nazi Almanyası tarafından Avrupa Yahudilerinin soykırımını ifade eder. 1941 ile 1945 arasında yaklaşık altı milyon Yahudi yok edildi.$expl$, $choices$[{"id":"a","text":"İkinci Dünya Savaşı sırasında Yahudilerin soykırımı"},{"id":"b","text":"Birinci Dünya Savaşı muharebesi"},{"id":"c","text":"Bir Avrupa barış antlaşması"},{"id":"d","text":"İşgale karşı Fransız Direnişi"}]$choices$),
  (288, 'en', $text$Which country or region of the world was colonised by France?$text$, $expl$Algeria was colonised by France from 1830 to 1962. It was the most important French colony in North Africa, and its independence was obtained after a long war.$expl$, $choices$[{"id":"a","text":"Algeria"},{"id":"b","text":"Brazil"},{"id":"c","text":"India"},{"id":"d","text":"Australia"}]$choices$),
  (288, 'tr', $text$Dünyanın hangi ülkesi veya bölgesi Fransa tarafından sömürgeleştirildi?$text$, $expl$Cezayir, 1830'dan 1962'ye kadar Fransa tarafından sömürgeleştirildi. Kuzey Afrika'daki en önemli Fransız sömürgesiydi ve bağımsızlığı uzun bir savaştan sonra elde edildi.$expl$, $choices$[{"id":"a","text":"Cezayir"},{"id":"b","text":"Brezilya"},{"id":"c","text":"Hindistan"},{"id":"d","text":"Avustralya"}]$choices$),
  (289, 'en', $text$Who made schooling free, secular and compulsory?$text$, $expl$Jules Ferry, Minister of Public Instruction, had the laws of 1881-1882 passed, making primary schooling free, secular and compulsory. These laws are a pillar of the French Republic.$expl$, $choices$[{"id":"a","text":"Jules Ferry"},{"id":"b","text":"Victor Hugo"},{"id":"c","text":"Napoleon Bonaparte"},{"id":"d","text":"Charles de Gaulle"}]$choices$),
  (289, 'tr', $text$Okulu ücretsiz, laik ve zorunlu hale getiren kimdir?$text$, $expl$Halk Eğitim Bakanı Jules Ferry, ilkokulu ücretsiz, laik ve zorunlu kılan 1881-1882 yasalarını çıkarttı. Bu yasalar Fransız Cumhuriyeti'nin temel taşlarındandır.$expl$, $choices$[{"id":"a","text":"Jules Ferry"},{"id":"b","text":"Victor Hugo"},{"id":"c","text":"Napoléon Bonaparte"},{"id":"d","text":"Charles de Gaulle"}]$choices$),
  (290, 'en', $text$When did the Second World War take place?$text$, $expl$The Second World War took place from 1939 to 1945. This global conflict involved most nations and caused millions of casualties.$expl$, $choices$[{"id":"a","text":"1939-1945"},{"id":"b","text":"1914-1918"},{"id":"c","text":"1870-1871"},{"id":"d","text":"1950-1953"}]$choices$),
  (290, 'tr', $text$İkinci Dünya Savaşı ne zaman yaşandı?$text$, $expl$İkinci Dünya Savaşı 1939'dan 1945'e kadar sürdü. Bu küresel çatışma çoğu ulusu içine aldı ve milyonlarca kayba neden oldu.$expl$, $choices$[{"id":"a","text":"1939-1945"},{"id":"b","text":"1914-1918"},{"id":"c","text":"1870-1871"},{"id":"d","text":"1950-1953"}]$choices$),
  (291, 'en', $text$When did the First World War take place?$text$, $expl$The First World War took place from 1914 to 1918. This conflict mainly pitted the Triple Entente powers against the Central Empires.$expl$, $choices$[{"id":"a","text":"1914-1918"},{"id":"b","text":"1939-1945"},{"id":"c","text":"1870-1871"},{"id":"d","text":"1899-1902"}]$choices$),
  (291, 'tr', $text$Birinci Dünya Savaşı ne zaman yaşandı?$text$, $expl$Birinci Dünya Savaşı 1914'ten 1918'e kadar sürdü. Bu çatışma esas olarak Üçlü İtilaf güçlerini Merkezi İmparatorluklarla karşı karşıya getirdi.$expl$, $choices$[{"id":"a","text":"1914-1918"},{"id":"b","text":"1939-1945"},{"id":"c","text":"1870-1871"},{"id":"d","text":"1899-1902"}]$choices$),
  (292, 'en', $text$In what year was the European Economic Community (EEC) created?$text$, $expl$The EEC was created in 1957 by the Treaty of Rome, signed by six founding countries including France. It is the ancestor of today's European Union.$expl$, $choices$[{"id":"a","text":"1957"},{"id":"b","text":"1945"},{"id":"c","text":"1962"},{"id":"d","text":"1951"}]$choices$),
  (292, 'tr', $text$Avrupa Ekonomik Topluluğu (AET) hangi yılda kuruldu?$text$, $expl$AET, Fransa dahil altı kurucu ülke tarafından imzalanan Roma Antlaşması ile 1957'de kuruldu. Bugünkü Avrupa Birliği'nin atasıdır.$expl$, $choices$[{"id":"a","text":"1957"},{"id":"b","text":"1945"},{"id":"c","text":"1962"},{"id":"d","text":"1951"}]$choices$),
  (293, 'en', $text$11 November is a public holiday. What does this date correspond to?$text$, $expl$11 November 1918 marks the armistice of the First World War. This public holiday commemorates the end of the fighting and pays tribute to the soldiers who died for France.$expl$, $choices$[{"id":"a","text":"The armistice of the First World War"},{"id":"b","text":"The end of the Second World War"},{"id":"c","text":"The French national holiday"},{"id":"d","text":"The proclamation of the Republic"}]$choices$),
  (293, 'tr', $text$11 Kasım resmi tatildir. Bu tarih neye karşılık gelir?$text$, $expl$11 Kasım 1918, Birinci Dünya Savaşı'nın ateşkesini işaret eder. Bu resmi tatil, çatışmaların sonunu anar ve Fransa için ölen askerlere saygı duruşunda bulunur.$expl$, $choices$[{"id":"a","text":"Birinci Dünya Savaşı'nın ateşkesi"},{"id":"b","text":"İkinci Dünya Savaşı'nın sonu"},{"id":"c","text":"Fransız ulusal bayramı"},{"id":"d","text":"Cumhuriyet'in ilanı"}]$choices$),
  (294, 'en', $text$Who was the first President elected under the Fifth Republic?$text$, $expl$Charles de Gaulle was the first President of the Fifth Republic, elected in 1958. He is the founder of this regime and served two presidential terms.$expl$, $choices$[{"id":"a","text":"Charles de Gaulle"},{"id":"b","text":"François Mitterrand"},{"id":"c","text":"Georges Pompidou"},{"id":"d","text":"René Coty"}]$choices$),
  (294, 'tr', $text$Beşinci Cumhuriyet döneminde seçilen ilk Cumhurbaşkanı kimdi?$text$, $expl$Charles de Gaulle, 1958'de seçilen Beşinci Cumhuriyet'in ilk Cumhurbaşkanıdır. Bu rejimin kurucusudur ve iki cumhurbaşkanlığı dönemi görev yapmıştır.$expl$, $choices$[{"id":"a","text":"Charles de Gaulle"},{"id":"b","text":"François Mitterrand"},{"id":"c","text":"Georges Pompidou"},{"id":"d","text":"René Coty"}]$choices$),
  (295, 'en', $text$In what year was slavery definitively abolished in France?$text$, $expl$Slavery was definitively abolished in France in 1848, at the initiative of Victor Schœlcher. A first abolition decree had been issued in 1794, but Napoleon had reinstated slavery in 1802.$expl$, $choices$[{"id":"a","text":"1848"},{"id":"b","text":"1789"},{"id":"c","text":"1865"},{"id":"d","text":"1794"}]$choices$),
  (295, 'tr', $text$Fransa'da kölelik kesin olarak hangi yılda kaldırıldı?$text$, $expl$Kölelik, Victor Schœlcher'in girişimiyle 1848'de Fransa'da kesin olarak kaldırıldı. 1794'te ilk bir kaldırma kararnamesi çıkarılmıştı, ancak Napolyon 1802'de köleliği yeniden başlatmıştı.$expl$, $choices$[{"id":"a","text":"1848"},{"id":"b","text":"1789"},{"id":"c","text":"1865"},{"id":"d","text":"1794"}]$choices$),
  (296, 'en', $text$Since what year has public schooling been free?$text$, $expl$Public schooling has been free since 1881, thanks to the Jules Ferry laws. These laws also made primary education compulsory and secular.$expl$, $choices$[{"id":"a","text":"1881"},{"id":"b","text":"1789"},{"id":"c","text":"1905"},{"id":"d","text":"1848"}]$choices$),
  (296, 'tr', $text$Devlet okulu hangi yıldan beri ücretsizdir?$text$, $expl$Devlet okulu, Jules Ferry yasaları sayesinde 1881'den beri ücretsizdir. Bu yasalar ayrıca ilköğretimi zorunlu ve laik hale getirmiştir.$expl$, $choices$[{"id":"a","text":"1881"},{"id":"b","text":"1789"},{"id":"c","text":"1905"},{"id":"d","text":"1848"}]$choices$),
  (297, 'en', $text$How many republics has France had?$text$, $expl$France has had five republics. The First Republic was proclaimed in 1792 and the Fifth Republic, established in 1958, is the current regime.$expl$, $choices$[{"id":"a","text":"Five"},{"id":"b","text":"Three"},{"id":"c","text":"Four"},{"id":"d","text":"Six"}]$choices$),
  (297, 'tr', $text$Fransa'da kaç cumhuriyet olmuştur?$text$, $expl$Fransa beş cumhuriyet yaşamıştır. Birinci Cumhuriyet 1792'de ilan edilmiş ve 1958'de kurulan Beşinci Cumhuriyet mevcut rejimdir.$expl$, $choices$[{"id":"a","text":"Beş"},{"id":"b","text":"Üç"},{"id":"c","text":"Dört"},{"id":"d","text":"Altı"}]$choices$),
  (298, 'en', $text$Who was the king of France at the time of the French Revolution?$text$, $expl$Louis XVI was king of France during the French Revolution of 1789. He was overthrown and then guillotined in 1793.$expl$, $choices$[{"id":"a","text":"Louis XVI"},{"id":"b","text":"Louis XIV"},{"id":"c","text":"Louis XV"},{"id":"d","text":"Henry IV"}]$choices$),
  (298, 'tr', $text$Fransız Devrimi sırasında Fransa kralı kimdi?$text$, $expl$1789 Fransız Devrimi sırasında Fransa kralı Louis XVI (XVI. Lui) idi. Devrilip 1793'te giyotinle idam edildi.$expl$, $choices$[{"id":"a","text":"Louis XVI"},{"id":"b","text":"Louis XIV"},{"id":"c","text":"Louis XV"},{"id":"d","text":"Henri IV"}]$choices$),
  (299, 'en', $text$Who founded the Fifth Republic?$text$, $expl$General Charles de Gaulle founded the Fifth Republic in 1958. He was its first President and established a Constitution strengthening executive power.$expl$, $choices$[{"id":"a","text":"General de Gaulle"},{"id":"b","text":"François Mitterrand"},{"id":"c","text":"Napoleon III"},{"id":"d","text":"Léon Blum"}]$choices$),
  (299, 'tr', $text$Beşinci Cumhuriyet'i kim kurdu?$text$, $expl$General Charles de Gaulle, Beşinci Cumhuriyet'i 1958'de kurdu. İlk Cumhurbaşkanı oldu ve yürütme yetkisini güçlendiren bir Anayasa hazırladı.$expl$, $choices$[{"id":"a","text":"General de Gaulle"},{"id":"b","text":"François Mitterrand"},{"id":"c","text":"III. Napolyon"},{"id":"d","text":"Léon Blum"}]$choices$),
  (300, 'en', $text$What is celebrated on 14 July?$text$, $expl$14 July is the French national holiday. It commemorates the storming of the Bastille in 1789 and the Fête de la Fédération of 1790, symbols of liberty and national unity.$expl$, $choices$[{"id":"a","text":"The national holiday, anniversary of the storming of the Bastille"},{"id":"b","text":"The 1918 armistice"},{"id":"c","text":"The end of the Second World War"},{"id":"d","text":"The abolition of slavery"}]$choices$),
  (300, 'tr', $text$14 Temmuz'da ne kutlanır?$text$, $expl$14 Temmuz, Fransız ulusal bayramıdır. 1789'da Bastille'in ele geçirilmesini ve özgürlük ile ulusal birliğin sembolleri olan 1790 Fête de la Fédération'u anar.$expl$, $choices$[{"id":"a","text":"Ulusal bayram, Bastille'in ele geçirilişinin yıldönümü"},{"id":"b","text":"1918 ateşkesi"},{"id":"c","text":"İkinci Dünya Savaşı'nın sonu"},{"id":"d","text":"Köleliğin kaldırılması"}]$choices$),
  (301, 'en', $text$Which war took place between 1914 and 1918?$text$, $expl$The First World War took place from 1914 to 1918. It pitted the Allies against the Central Empires and caused millions of deaths.$expl$, $choices$[{"id":"a","text":"The First World War"},{"id":"b","text":"The Second World War"},{"id":"c","text":"The Franco-Prussian War"},{"id":"d","text":"The Algerian War"}]$choices$),
  (301, 'tr', $text$1914 ile 1918 arasında hangi savaş gerçekleşti?$text$, $expl$Birinci Dünya Savaşı 1914'ten 1918'e kadar sürdü. Müttefikleri Merkezi İmparatorluklarla karşı karşıya getirdi ve milyonlarca ölüme neden oldu.$expl$, $choices$[{"id":"a","text":"Birinci Dünya Savaşı"},{"id":"b","text":"İkinci Dünya Savaşı"},{"id":"c","text":"Fransa-Prusya Savaşı"},{"id":"d","text":"Cezayir Savaşı"}]$choices$),
  (302, 'en', $text$Why is the year 1958 important for France?$text$, $expl$The year 1958 marks the creation of the Fifth Republic by General de Gaulle. A new Constitution was adopted, establishing France's current political regime.$expl$, $choices$[{"id":"a","text":"It is the year the Fifth Republic was created"},{"id":"b","text":"It is the year the Second World War ended"},{"id":"c","text":"It is the year slavery was abolished"},{"id":"d","text":"It is the year of the French Revolution"}]$choices$),
  (302, 'tr', $text$Fransa için 1958 yılı neden önemlidir?$text$, $expl$1958 yılı, General de Gaulle tarafından Beşinci Cumhuriyet'in kuruluşunu işaret eder. Fransa'nın mevcut siyasi rejimini oluşturan yeni bir Anayasa kabul edilmiştir.$expl$, $choices$[{"id":"a","text":"Beşinci Cumhuriyet'in kurulduğu yıldır"},{"id":"b","text":"İkinci Dünya Savaşı'nın sona erdiği yıldır"},{"id":"c","text":"Köleliğin kaldırıldığı yıldır"},{"id":"d","text":"Fransız Devrimi yılıdır"}]$choices$),
  (303, 'en', $text$Which river flows through France?$text$, $expl$The Loire is the longest river in France, about 1,012 km. It crosses central France from the Massif Central to the Atlantic Ocean.$expl$, $choices$[{"id":"a","text":"The Loire"},{"id":"b","text":"The Danube"},{"id":"c","text":"The Nile"},{"id":"d","text":"The Amazon"}]$choices$),
  (303, 'tr', $text$Fransa'da hangi nehir akar?$text$, $expl$Loire, Fransa'nın yaklaşık 1.012 km ile en uzun nehridir. Fransa'nın merkezinden Massif Central'dan Atlas Okyanusu'na kadar geçer.$expl$, $choices$[{"id":"a","text":"Loire"},{"id":"b","text":"Tuna"},{"id":"c","text":"Nil"},{"id":"d","text":"Amazon"}]$choices$),
  (304, 'en', $text$Which city is French?$text$, $expl$Lyon is a major French city, capital of the Auvergne-Rhône-Alpes region. It is the third largest city in France after Paris and Marseille.$expl$, $choices$[{"id":"a","text":"Lyon"},{"id":"b","text":"Geneva"},{"id":"c","text":"Brussels"},{"id":"d","text":"Barcelona"}]$choices$),
  (304, 'tr', $text$Hangi şehir Fransız'dır?$text$, $expl$Lyon, Auvergne-Rhône-Alpes bölgesinin merkezi olan büyük bir Fransız şehridir. Paris ve Marsilya'dan sonra Fransa'nın üçüncü büyük şehridir.$expl$, $choices$[{"id":"a","text":"Lyon"},{"id":"b","text":"Cenevre"},{"id":"c","text":"Brüksel"},{"id":"d","text":"Barselona"}]$choices$),
  (305, 'en', $text$Which ocean borders the French west coast?$text$, $expl$The Atlantic Ocean borders the west coast of mainland France. From Brittany to the Basque Country, this maritime façade stretches for hundreds of kilometres.$expl$, $choices$[{"id":"a","text":"The Atlantic Ocean"},{"id":"b","text":"The Pacific Ocean"},{"id":"c","text":"The Indian Ocean"},{"id":"d","text":"The Arctic Ocean"}]$choices$),
  (305, 'tr', $text$Fransa'nın batı kıyısını hangi okyanus çevreler?$text$, $expl$Atlas Okyanusu, metropolitan Fransa'nın batı kıyısını çevreler. Brittany'den Bask Ülkesi'ne kadar bu deniz cephesi yüzlerce kilometre boyunca uzanır.$expl$, $choices$[{"id":"a","text":"Atlas Okyanusu"},{"id":"b","text":"Pasifik Okyanusu"},{"id":"c","text":"Hint Okyanusu"},{"id":"d","text":"Kuzey Buz Denizi"}]$choices$),
  (306, 'en', $text$What is Paris?$text$, $expl$Paris is the capital of France and its political, economic and cultural centre. It is also the most populous city in the country.$expl$, $choices$[{"id":"a","text":"The capital of France"},{"id":"b","text":"A region of France"},{"id":"c","text":"An overseas department"},{"id":"d","text":"The capital of Europe"}]$choices$),
  (306, 'tr', $text$Paris nedir?$text$, $expl$Paris, Fransa'nın başkenti ve siyasi, ekonomik ve kültürel merkezidir. Ayrıca ülkenin en kalabalık şehridir.$expl$, $choices$[{"id":"a","text":"Fransa'nın başkenti"},{"id":"b","text":"Fransa'nın bir bölgesi"},{"id":"c","text":"Bir denizaşırı il"},{"id":"d","text":"Avrupa'nın başkenti"}]$choices$),
  (307, 'en', $text$What is the capital of France?$text$, $expl$Paris has been the capital of France for centuries. It houses the main State institutions, including the Élysée Palace and the National Assembly.$expl$, $choices$[{"id":"a","text":"Paris"},{"id":"b","text":"Lyon"},{"id":"c","text":"Marseille"},{"id":"d","text":"Strasbourg"}]$choices$),
  (307, 'tr', $text$Fransa'nın başkenti neresidir?$text$, $expl$Paris yüzyıllardır Fransa'nın başkentidir. Élysée Sarayı ve Ulusal Meclis dahil ana Devlet kurumlarına ev sahipliği yapar.$expl$, $choices$[{"id":"a","text":"Paris"},{"id":"b","text":"Lyon"},{"id":"c","text":"Marsilya"},{"id":"d","text":"Strazburg"}]$choices$),
  (308, 'en', $text$On which continent is mainland France located?$text$, $expl$Mainland France is located on the European continent. It is bordered by the Atlantic Ocean to the west, the Mediterranean Sea to the south and the English Channel to the north.$expl$, $choices$[{"id":"a","text":"Europe"},{"id":"b","text":"Africa"},{"id":"c","text":"America"},{"id":"d","text":"Asia"}]$choices$),
  (308, 'tr', $text$Metropolitan Fransa hangi kıtada yer alır?$text$, $expl$Metropolitan Fransa, Avrupa kıtasında yer alır. Batıda Atlas Okyanusu, güneyde Akdeniz ve kuzeyde Manş Denizi ile çevrilidir.$expl$, $choices$[{"id":"a","text":"Avrupa"},{"id":"b","text":"Afrika"},{"id":"c","text":"Amerika"},{"id":"d","text":"Asya"}]$choices$),
  (309, 'en', $text$Which island is a French overseas department?$text$, $expl$Martinique is a French overseas department and region located in the Antilles. It is an integral part of the French Republic.$expl$, $choices$[{"id":"a","text":"Martinique"},{"id":"b","text":"Cuba"},{"id":"c","text":"Jamaica"},{"id":"d","text":"Haiti"}]$choices$),
  (309, 'tr', $text$Hangi ada bir Fransız denizaşırı ilidir?$text$, $expl$Martinik, Antiller'de yer alan bir Fransız denizaşırı il ve bölgesidir. Fransız Cumhuriyeti'nin ayrılmaz bir parçasıdır.$expl$, $choices$[{"id":"a","text":"Martinik"},{"id":"b","text":"Küba"},{"id":"c","text":"Jamaika"},{"id":"d","text":"Haiti"}]$choices$),
  (310, 'en', $text$How many regions are there in mainland France?$text$, $expl$Since the 2016 territorial reform, mainland France has 13 regions. This number was reduced from 22 to 13 to strengthen the efficiency of local authorities.$expl$, $choices$[{"id":"a","text":"13"},{"id":"b","text":"18"},{"id":"c","text":"22"},{"id":"d","text":"10"}]$choices$),
  (310, 'tr', $text$Metropolitan Fransa'da kaç bölge vardır?$text$, $expl$2016 toprak reformundan bu yana, metropolitan Fransa'nın 13 bölgesi vardır. Yerel otoritelerin verimliliğini güçlendirmek için bu sayı 22'den 13'e indirilmiştir.$expl$, $choices$[{"id":"a","text":"13"},{"id":"b","text":"18"},{"id":"c","text":"22"},{"id":"d","text":"10"}]$choices$),
  (311, 'en', $text$Which city is a major seaport?$text$, $expl$Marseille is the largest seaport in France and one of the most important in the Mediterranean. It is also the second largest city in France.$expl$, $choices$[{"id":"a","text":"Marseille"},{"id":"b","text":"Clermont-Ferrand"},{"id":"c","text":"Grenoble"},{"id":"d","text":"Limoges"}]$choices$),
  (311, 'tr', $text$Hangi şehir büyük bir deniz limanıdır?$text$, $expl$Marsilya, Fransa'nın en büyük deniz limanı ve Akdeniz'deki en önemli limanlardan biridir. Aynı zamanda Fransa'nın ikinci büyük şehridir.$expl$, $choices$[{"id":"a","text":"Marsilya"},{"id":"b","text":"Clermont-Ferrand"},{"id":"c","text":"Grenoble"},{"id":"d","text":"Limoges"}]$choices$),
  (312, 'en', $text$What is the sea south of mainland France?$text$, $expl$The Mediterranean Sea borders the south of mainland France. It stretches from the Spanish to the Italian border, along the Côte d'Azur and Languedoc.$expl$, $choices$[{"id":"a","text":"The Mediterranean Sea"},{"id":"b","text":"The North Sea"},{"id":"c","text":"The Baltic Sea"},{"id":"d","text":"The English Channel"}]$choices$),
  (312, 'tr', $text$Metropolitan Fransa'nın güneyindeki deniz nedir?$text$, $expl$Akdeniz, metropolitan Fransa'nın güneyini çevreler. İspanya sınırından İtalya sınırına kadar, Côte d'Azur ve Languedoc boyunca uzanır.$expl$, $choices$[{"id":"a","text":"Akdeniz"},{"id":"b","text":"Kuzey Denizi"},{"id":"c","text":"Baltık Denizi"},{"id":"d","text":"Manş Denizi"}]$choices$),
  (313, 'en', $text$Which city is located on the Mediterranean Sea?$text$, $expl$Nice is a city located on the Côte d'Azur, on the Mediterranean Sea. It is one of the main tourist destinations in southern France.$expl$, $choices$[{"id":"a","text":"Nice"},{"id":"b","text":"Lille"},{"id":"c","text":"Strasbourg"},{"id":"d","text":"Rennes"}]$choices$),
  (313, 'tr', $text$Hangi şehir Akdeniz kıyısında yer alır?$text$, $expl$Nice, Akdeniz kıyısındaki Côte d'Azur'da yer alan bir şehirdir. Güney Fransa'nın başlıca turistik yerlerinden biridir.$expl$, $choices$[{"id":"a","text":"Nice"},{"id":"b","text":"Lille"},{"id":"c","text":"Strazburg"},{"id":"d","text":"Rennes"}]$choices$),
  (314, 'en', $text$Where is Corsica located?$text$, $expl$Corsica is an island located in the Mediterranean Sea, southeast of mainland France. It is a unique territorial authority with a special status.$expl$, $choices$[{"id":"a","text":"In the Mediterranean Sea"},{"id":"b","text":"In the Atlantic Ocean"},{"id":"c","text":"In the English Channel"},{"id":"d","text":"In the North Sea"}]$choices$),
  (314, 'tr', $text$Korsika nerede yer alır?$text$, $expl$Korsika, Akdeniz'de, metropolitan Fransa'nın güneydoğusunda yer alan bir adadır. Özel bir statüye sahip benzersiz bir yerel yönetimdir.$expl$, $choices$[{"id":"a","text":"Akdeniz'de"},{"id":"b","text":"Atlas Okyanusu'nda"},{"id":"c","text":"Manş Denizi'nde"},{"id":"d","text":"Kuzey Denizi'nde"}]$choices$),
  (315, 'en', $text$Which mountain range is located between France and Italy?$text$, $expl$The Alps form a natural border between France and Italy. Mont Blanc, located in the Alps, is the highest summit in Western Europe at 4,809 metres.$expl$, $choices$[{"id":"a","text":"The Alps"},{"id":"b","text":"The Pyrenees"},{"id":"c","text":"The Jura"},{"id":"d","text":"The Vosges"}]$choices$),
  (315, 'tr', $text$Fransa ile İtalya arasında hangi dağ silsilesi yer alır?$text$, $expl$Alpler, Fransa ile İtalya arasında doğal bir sınır oluşturur. Alpler'de yer alan Mont Blanc, 4.809 metre ile Batı Avrupa'nın en yüksek zirvesidir.$expl$, $choices$[{"id":"a","text":"Alpler"},{"id":"b","text":"Pireneler"},{"id":"c","text":"Jura Dağları"},{"id":"d","text":"Vosges Dağları"}]$choices$),
  (316, 'en', $text$Who was Molière?$text$, $expl$Molière (1622-1673) was a 17th-century French playwright and actor. He is the author of famous comedies such as Le Malade imaginaire and Le Misanthrope.$expl$, $choices$[{"id":"a","text":"A 17th-century French playwright and actor"},{"id":"b","text":"A Renaissance painter"},{"id":"c","text":"A classical music composer"},{"id":"d","text":"An Enlightenment philosopher"}]$choices$),
  (316, 'tr', $text$Molière kimdi?$text$, $expl$Molière (1622-1673), 17. yüzyıl Fransız oyun yazarı ve oyuncusuydu. Le Malade imaginaire (Hastalık Hastası) ve Le Misanthrope gibi ünlü komedilerin yazarıdır.$expl$, $choices$[{"id":"a","text":"17. yüzyıl Fransız oyun yazarı ve oyuncusu"},{"id":"b","text":"Bir Rönesans ressamı"},{"id":"c","text":"Bir klasik müzik bestecisi"},{"id":"d","text":"Bir Aydınlanma filozofu"}]$choices$),
  (317, 'en', $text$Who was Charles Baudelaire?$text$, $expl$Charles Baudelaire (1821-1867) was a French poet, author of the famous collection Les Fleurs du mal (The Flowers of Evil). He is considered one of the precursors of modern poetry.$expl$, $choices$[{"id":"a","text":"A French poet, author of Les Fleurs du mal"},{"id":"b","text":"A novelist, author of Les Misérables"},{"id":"c","text":"A 19th-century sculptor"},{"id":"d","text":"A Romantic musician"}]$choices$),
  (317, 'tr', $text$Charles Baudelaire kimdi?$text$, $expl$Charles Baudelaire (1821-1867), ünlü Les Fleurs du mal (Kötülük Çiçekleri) derlemesinin yazarı olan bir Fransız şairdi. Modern şiirin öncülerinden biri sayılır.$expl$, $choices$[{"id":"a","text":"Les Fleurs du mal'in yazarı bir Fransız şair"},{"id":"b","text":"Les Misérables'ın yazarı bir romancı"},{"id":"c","text":"19. yüzyıl heykeltıraşı"},{"id":"d","text":"Bir Romantik müzisyen"}]$choices$),
  (318, 'en', $text$Who was George Sand?$text$, $expl$George Sand (1804-1876) was a 19th-century French novelist, whose real name was Amantine Lucile Aurore Dupin. She is known for her pastoral novels and her commitment to women's rights.$expl$, $choices$[{"id":"a","text":"A 19th-century French novelist"},{"id":"b","text":"A queen of France"},{"id":"c","text":"A Nobel Prize-winning scientist"},{"id":"d","text":"An opera singer"}]$choices$),
  (318, 'tr', $text$George Sand kimdi?$text$, $expl$George Sand (1804-1876), gerçek adı Amantine Lucile Aurore Dupin olan 19. yüzyıl Fransız romancısıydı. Kırsal romanları ve kadın haklarına olan bağlılığıyla tanınır.$expl$, $choices$[{"id":"a","text":"19. yüzyıl Fransız romancısı"},{"id":"b","text":"Bir Fransa kraliçesi"},{"id":"c","text":"Nobel ödüllü bir bilim insanı"},{"id":"d","text":"Bir opera sanatçısı"}]$choices$),
  (319, 'en', $text$Who was Simone de Beauvoir?$text$, $expl$Simone de Beauvoir (1908-1986) was a French philosopher and writer, a major figure of feminism. She is notably the author of Le Deuxième Sexe (The Second Sex), a founding work of modern feminism.$expl$, $choices$[{"id":"a","text":"A French feminist philosopher and writer"},{"id":"b","text":"A Resistance fighter of the Second World War"},{"id":"c","text":"A French physicist"},{"id":"d","text":"A French film actress"}]$choices$),
  (319, 'tr', $text$Simone de Beauvoir kimdi?$text$, $expl$Simone de Beauvoir (1908-1986), feminizmin önemli bir figürü olan Fransız filozof ve yazardı. Özellikle modern feminizmin kurucu eseri olan Le Deuxième Sexe'in (İkinci Cins) yazarıdır.$expl$, $choices$[{"id":"a","text":"Bir Fransız feminist filozof ve yazar"},{"id":"b","text":"İkinci Dünya Savaşı direnişçisi"},{"id":"c","text":"Bir Fransız fizikçi"},{"id":"d","text":"Bir Fransız sinema oyuncusu"}]$choices$),
  (320, 'en', $text$Who was Albert Camus?$text$, $expl$Albert Camus (1913-1960) was a French writer and philosopher, Nobel Prize winner in Literature in 1957. He is the author of L'Étranger (The Stranger) and La Peste (The Plague).$expl$, $choices$[{"id":"a","text":"A French writer and philosopher, Nobel Prize winner in Literature"},{"id":"b","text":"An Impressionist painter"},{"id":"c","text":"A politician of the Third Republic"},{"id":"d","text":"A classical music composer"}]$choices$),
  (320, 'tr', $text$Albert Camus kimdi?$text$, $expl$Albert Camus (1913-1960), 1957 Nobel Edebiyat Ödülü sahibi Fransız yazar ve filozoftu. L'Étranger (Yabancı) ve La Peste (Veba) eserlerinin yazarıdır.$expl$, $choices$[{"id":"a","text":"Nobel Edebiyat Ödülü sahibi Fransız yazar ve filozof"},{"id":"b","text":"Bir Empresyonist ressam"},{"id":"c","text":"Üçüncü Cumhuriyet'in bir siyasetçisi"},{"id":"d","text":"Bir klasik müzik bestecisi"}]$choices$),
  (321, 'en', $text$Who was Paul Cézanne?$text$, $expl$Paul Cézanne (1839-1906) was a French painter, considered the father of modern art. His works influenced Cubism and many artistic movements of the 20th century.$expl$, $choices$[{"id":"a","text":"A French painter, precursor of modern art"},{"id":"b","text":"A naturalist writer"},{"id":"c","text":"An 18th-century sculptor"},{"id":"d","text":"A Renaissance architect"}]$choices$),
  (321, 'tr', $text$Paul Cézanne kimdi?$text$, $expl$Paul Cézanne (1839-1906), modern sanatın babası sayılan bir Fransız ressamdı. Eserleri Kübizm'i ve 20. yüzyılın birçok sanat akımını etkilemiştir.$expl$, $choices$[{"id":"a","text":"Modern sanatın öncüsü bir Fransız ressam"},{"id":"b","text":"Bir natüralist yazar"},{"id":"c","text":"18. yüzyıl heykeltıraşı"},{"id":"d","text":"Bir Rönesans mimarı"}]$choices$),
  (322, 'en', $text$Who was Marc Chagall?$text$, $expl$Marc Chagall (1887-1985) was a painter and engraver of Russian origin who became a naturalised French citizen. He is famous for his colourful works mixing fantasy and symbolism, notably the stained glass windows of the Paris Opera.$expl$, $choices$[{"id":"a","text":"A painter of Russian origin naturalised French"},{"id":"b","text":"A French Enlightenment philosopher"},{"id":"c","text":"An Austrian classical musician"},{"id":"d","text":"An Italian film director"}]$choices$),
  (322, 'tr', $text$Marc Chagall kimdi?$text$, $expl$Marc Chagall (1887-1985), Fransız vatandaşlığına geçmiş Rus asıllı bir ressam ve gravürcüydü. Fantezi ve sembolizmi karıştıran renkli eserleriyle, özellikle Paris Operası'nın vitraylarıyla ünlüdür.$expl$, $choices$[{"id":"a","text":"Fransız vatandaşlığına geçmiş Rus asıllı bir ressam"},{"id":"b","text":"Bir Fransız Aydınlanma filozofu"},{"id":"c","text":"Avusturyalı klasik müzisyen"},{"id":"d","text":"Bir İtalyan film yönetmeni"}]$choices$),
  (323, 'en', $text$Who was Joséphine Baker?$text$, $expl$Joséphine Baker (1906-1975) was a Franco-American artist, singer and dancer, a Resistance fighter during the Second World War. She was admitted to the Panthéon in 2021 for her commitment.$expl$, $choices$[{"id":"a","text":"A Franco-American artist, singer, dancer and Resistance fighter"},{"id":"b","text":"A Franco-Polish scientist"},{"id":"c","text":"A French politician"},{"id":"d","text":"A 19th-century novelist"}]$choices$),
  (323, 'tr', $text$Joséphine Baker kimdi?$text$, $expl$Joséphine Baker (1906-1975), İkinci Dünya Savaşı sırasında direnişçi olan Fransız-Amerikalı bir sanatçı, şarkıcı ve dansçıydı. Kararlılığı nedeniyle 2021'de Panthéon'a kabul edildi.$expl$, $choices$[{"id":"a","text":"Fransız-Amerikalı bir sanatçı, şarkıcı, dansçı ve direnişçi"},{"id":"b","text":"Fransız-Polonyalı bir bilim insanı"},{"id":"c","text":"Bir Fransız siyasetçi"},{"id":"d","text":"19. yüzyıl romancısı"}]$choices$),
  (324, 'en', $text$Who was a famous French singer?$text$, $expl$Édith Piaf (1915-1963) is one of the most famous French singers in the world. She is known for songs such as La Vie en rose and Non, je ne regrette rien.$expl$, $choices$[{"id":"a","text":"Édith Piaf"},{"id":"b","text":"Madonna"},{"id":"c","text":"Beyoncé"},{"id":"d","text":"Adele"}]$choices$),
  (324, 'tr', $text$Ünlü bir Fransız şarkıcı kimdi?$text$, $expl$Édith Piaf (1915-1963), dünyada en ünlü Fransız şarkıcılardan biridir. La Vie en rose ve Non, je ne regrette rien gibi şarkılarla tanınır.$expl$, $choices$[{"id":"a","text":"Édith Piaf"},{"id":"b","text":"Madonna"},{"id":"c","text":"Beyoncé"},{"id":"d","text":"Adele"}]$choices$),
  (325, 'en', $text$What is the Louvre?$text$, $expl$The Louvre is the largest art museum in the world, located in Paris. A former royal palace, it houses famous works such as the Mona Lisa by Leonardo da Vinci.$expl$, $choices$[{"id":"a","text":"The largest art museum in the world, located in Paris"},{"id":"b","text":"A Loire Valley château"},{"id":"c","text":"A Gothic cathedral"},{"id":"d","text":"A national theatre"}]$choices$),
  (325, 'tr', $text$Louvre nedir?$text$, $expl$Louvre, Paris'te bulunan dünyanın en büyük sanat müzesidir. Eski bir kraliyet sarayı olan müze, Leonardo da Vinci'nin Mona Lisa'sı gibi ünlü eserlere ev sahipliği yapar.$expl$, $choices$[{"id":"a","text":"Paris'te bulunan dünyanın en büyük sanat müzesi"},{"id":"b","text":"Bir Loire Vadisi şatosu"},{"id":"c","text":"Bir Gotik katedral"},{"id":"d","text":"Bir ulusal tiyatro"}]$choices$),
  (326, 'en', $text$Who was Jean de la Fontaine?$text$, $expl$Jean de la Fontaine (1621-1695) was a French poet famous for his Fables. His works, such as The Crow and the Fox, are still taught in French schools.$expl$, $choices$[{"id":"a","text":"A French poet famous for his Fables"},{"id":"b","text":"A king of France"},{"id":"c","text":"A Renaissance painter"},{"id":"d","text":"An explorer of the New World"}]$choices$),
  (326, 'tr', $text$Jean de la Fontaine kimdi?$text$, $expl$Jean de la Fontaine (1621-1695), Fables (Masallar) ile ünlü Fransız bir şairdi. Le Corbeau et le Renard (Karga ile Tilki) gibi eserleri hâlâ Fransız okullarında okutulmaktadır.$expl$, $choices$[{"id":"a","text":"Fables ile ünlü bir Fransız şair"},{"id":"b","text":"Bir Fransa kralı"},{"id":"c","text":"Bir Rönesans ressamı"},{"id":"d","text":"Yeni Dünya kâşifi"}]$choices$),
  (327, 'en', $text$Which writer is French?$text$, $expl$Victor Hugo (1802-1885) is one of the greatest French writers. He is the author of masterpieces such as Les Misérables and Notre-Dame de Paris.$expl$, $choices$[{"id":"a","text":"Victor Hugo"},{"id":"b","text":"Charles Dickens"},{"id":"c","text":"Miguel de Cervantes"},{"id":"d","text":"William Shakespeare"}]$choices$),
  (327, 'tr', $text$Hangi yazar Fransızdır?$text$, $expl$Victor Hugo (1802-1885), en büyük Fransız yazarlardan biridir. Les Misérables (Sefiller) ve Notre-Dame de Paris gibi başyapıtların yazarıdır.$expl$, $choices$[{"id":"a","text":"Victor Hugo"},{"id":"b","text":"Charles Dickens"},{"id":"c","text":"Miguel de Cervantes"},{"id":"d","text":"William Shakespeare"}]$choices$),
  (328, 'en', $text$In which city is the Eiffel Tower located?$text$, $expl$The Eiffel Tower is located in Paris. Built by Gustave Eiffel for the 1889 Universal Exhibition, it has become the most emblematic symbol of France.$expl$, $choices$[{"id":"a","text":"Paris"},{"id":"b","text":"Lyon"},{"id":"c","text":"Marseille"},{"id":"d","text":"Bordeaux"}]$choices$),
  (328, 'tr', $text$Eyfel Kulesi hangi şehirdedir?$text$, $expl$Eyfel Kulesi Paris'tedir. Gustave Eiffel tarafından 1889 Evrensel Sergisi için inşa edilmiş ve Fransa'nın en sembolik simgesi haline gelmiştir.$expl$, $choices$[{"id":"a","text":"Paris"},{"id":"b","text":"Lyon"},{"id":"c","text":"Marsilya"},{"id":"d","text":"Bordeaux"}]$choices$),
  (329, 'en', $text$When is Christmas celebrated?$text$, $expl$Christmas is celebrated on 25 December. It is a public holiday in France, a Christian holiday that has also become a cultural tradition marked by family meals and gift exchanges.$expl$, $choices$[{"id":"a","text":"25 December"},{"id":"b","text":"1 January"},{"id":"c","text":"14 July"},{"id":"d","text":"1 November"}]$choices$),
  (329, 'tr', $text$Noel ne zaman kutlanır?$text$, $expl$Noel 25 Aralık'ta kutlanır. Fransa'da resmi tatildir; aile yemekleri ve hediye değişimleriyle kültürel bir geleneğe de dönüşmüş Hristiyan bayramıdır.$expl$, $choices$[{"id":"a","text":"25 Aralık"},{"id":"b","text":"1 Ocak"},{"id":"c","text":"14 Temmuz"},{"id":"d","text":"1 Kasım"}]$choices$),
  (330, 'en', $text$What was the nickname of Louis XIV?$text$, $expl$Louis XIV was nicknamed the Sun King. He reigned from 1643 to 1715, that is 72 years, the longest reign in French history, and had the Palace of Versailles built.$expl$, $choices$[{"id":"a","text":"The Sun King"},{"id":"b","text":"The King of Kings"},{"id":"c","text":"The Well-Beloved"},{"id":"d","text":"The Great"}]$choices$),
  (330, 'tr', $text$Louis XIV'in (XIV. Lui) lakabı neydi?$text$, $expl$Louis XIV'in lakabı Güneş Kral (Roi-Soleil) idi. 1643'ten 1715'e kadar 72 yıl saltanat sürerek Fransa tarihinin en uzun saltanatını gerçekleştirmiş ve Versay Sarayı'nı yaptırmıştır.$expl$, $choices$[{"id":"a","text":"Güneş Kral (Roi-Soleil)"},{"id":"b","text":"Krallar Kralı"},{"id":"c","text":"Sevgili"},{"id":"d","text":"Büyük"}]$choices$),
  (331, 'en', $text$Which king of France was executed during the French Revolution?$text$, $expl$Louis XVI was guillotined on 21 January 1793 at the Place de la Révolution in Paris. He had been tried and condemned to death by the National Convention for treason.$expl$, $choices$[{"id":"a","text":"Louis XVI"},{"id":"b","text":"Louis XIV"},{"id":"c","text":"Louis XV"},{"id":"d","text":"Charles X"}]$choices$),
  (331, 'tr', $text$Fransız Devrimi sırasında hangi Fransa kralı idam edildi?$text$, $expl$Louis XVI, 21 Ocak 1793'te Paris'teki Place de la Révolution'da giyotinle idam edildi. Ulusal Konvansiyon tarafından vatana ihanetten yargılanmış ve ölüme mahkûm edilmişti.$expl$, $choices$[{"id":"a","text":"Louis XVI"},{"id":"b","text":"Louis XIV"},{"id":"c","text":"Louis XV"},{"id":"d","text":"Charles X"}]$choices$),
  (332, 'en', $text$In what year did Napoleon I become emperor?$text$, $expl$Napoleon I became Emperor of the French in 1804. His coronation took place on 2 December 1804 at the Notre-Dame Cathedral in Paris.$expl$, $choices$[{"id":"a","text":"1804"},{"id":"b","text":"1789"},{"id":"c","text":"1799"},{"id":"d","text":"1815"}]$choices$),
  (332, 'tr', $text$I. Napolyon hangi yıl imparator oldu?$text$, $expl$I. Napolyon 1804'te Fransızların İmparatoru oldu. Taç giyme töreni 2 Aralık 1804'te Paris'teki Notre-Dame Katedrali'nde gerçekleşti.$expl$, $choices$[{"id":"a","text":"1804"},{"id":"b","text":"1789"},{"id":"c","text":"1799"},{"id":"d","text":"1815"}]$choices$),
  (333, 'en', $text$Which of these figures has a link with the French Republic?$text$, $expl$Marianne is the allegorical symbol of the French Republic. She represents the values of liberty, equality and fraternity, and her bust is present in every town hall.$expl$, $choices$[{"id":"a","text":"Marianne"},{"id":"b","text":"Britannia"},{"id":"c","text":"Uncle Sam"},{"id":"d","text":"John Bull"}]$choices$),
  (333, 'tr', $text$Bu figürlerden hangisinin Fransız Cumhuriyeti ile bağlantısı vardır?$text$, $expl$Marianne, Fransız Cumhuriyeti'nin alegorik sembolüdür. Özgürlük, eşitlik ve kardeşlik değerlerini temsil eder ve büstü tüm belediye binalarında bulunur.$expl$, $choices$[{"id":"a","text":"Marianne"},{"id":"b","text":"Britannia"},{"id":"c","text":"Uncle Sam (Sam Amca)"},{"id":"d","text":"John Bull"}]$choices$),
  (334, 'en', $text$From when does General de Gaulle's call to resistance date?$text$, $expl$General de Gaulle's appeal dates from 18 June 1940. From London, he called on the French to resist against the German occupation via the BBC.$expl$, $choices$[{"id":"a","text":"18 June 1940"},{"id":"b","text":"8 May 1945"},{"id":"c","text":"14 July 1940"},{"id":"d","text":"25 August 1944"}]$choices$),
  (334, 'tr', $text$General de Gaulle'ün direniş çağrısı hangi tarihe aittir?$text$, $expl$General de Gaulle'ün çağrısı 18 Haziran 1940 tarihine aittir. Londra'dan, BBC aracılığıyla Fransızları Alman işgaline karşı direnmeye çağırdı.$expl$, $choices$[{"id":"a","text":"18 Haziran 1940"},{"id":"b","text":"8 Mayıs 1945"},{"id":"c","text":"14 Temmuz 1940"},{"id":"d","text":"25 Ağustos 1944"}]$choices$),
  (335, 'en', $text$Why is the Shoah studied at school?$text$, $expl$The Shoah is studied at school to transmit the memory of this genocide and raise awareness among pupils about the duty of remembrance. This helps combat racism, antisemitism and all forms of discrimination.$expl$, $choices$[{"id":"a","text":"For the duty of remembrance and to fight against racism and antisemitism"},{"id":"b","text":"To prepare pupils for history exams"},{"id":"c","text":"To teach the geography of Europe"},{"id":"d","text":"To study the war economy"}]$choices$),
  (335, 'tr', $text$Shoah neden okulda işlenir?$text$, $expl$Shoah, bu soykırımın hafızasını aktarmak ve öğrencileri hatırlama görevi konusunda duyarlı kılmak için okulda öğretilir. Bu, ırkçılık, antisemitizm ve her türlü ayrımcılıkla mücadele etmeye yardımcı olur.$expl$, $choices$[{"id":"a","text":"Hatırlama görevi ve ırkçılık ile antisemitizmle mücadele için"},{"id":"b","text":"Öğrencileri tarih sınavlarına hazırlamak için"},{"id":"c","text":"Avrupa coğrafyasını öğretmek için"},{"id":"d","text":"Savaş ekonomisini incelemek için"}]$choices$),
  (336, 'en', $text$Which country was colonised by France?$text$, $expl$Senegal was a French West African colony. It gained independence in 1960, like many French-speaking African countries.$expl$, $choices$[{"id":"a","text":"Senegal"},{"id":"b","text":"Nigeria"},{"id":"c","text":"South Africa"},{"id":"d","text":"Ethiopia"}]$choices$),
  (336, 'tr', $text$Hangi ülke Fransa tarafından sömürgeleştirildi?$text$, $expl$Senegal, Batı Afrika'da bir Fransız sömürgesiydi. Birçok Frankofon Afrika ülkesi gibi 1960'ta bağımsızlığını kazandı.$expl$, $choices$[{"id":"a","text":"Senegal"},{"id":"b","text":"Nijerya"},{"id":"c","text":"Güney Afrika"},{"id":"d","text":"Etiyopya"}]$choices$),
  (337, 'en', $text$Since when have the French elected the President of the Republic by direct universal suffrage?$text$, $expl$Since 1962, the French have elected the President of the Republic by direct universal suffrage, following the referendum called for by General de Gaulle. Before that date, the President was elected by an electoral college.$expl$, $choices$[{"id":"a","text":"1962"},{"id":"b","text":"1958"},{"id":"c","text":"1945"},{"id":"d","text":"1981"}]$choices$),
  (337, 'tr', $text$Fransızlar Cumhurbaşkanını ne zamandan beri doğrudan genel oy ile seçiyor?$text$, $expl$1962'den beri, General de Gaulle tarafından istenen referandumun ardından Fransızlar Cumhurbaşkanını doğrudan genel oy ile seçmektedir. Bu tarihten önce, Cumhurbaşkanı bir seçici kurul tarafından seçiliyordu.$expl$, $choices$[{"id":"a","text":"1962"},{"id":"b","text":"1958"},{"id":"c","text":"1945"},{"id":"d","text":"1981"}]$choices$),
  (338, 'en', $text$What is the first step of European construction in 1951?$text$, $expl$The European Coal and Steel Community (ECSC), created in 1951, is the first step of European construction. It was founded by six countries to pool their coal and steel production.$expl$, $choices$[{"id":"a","text":"The creation of the European Coal and Steel Community (ECSC)"},{"id":"b","text":"The creation of the European Union"},{"id":"c","text":"The signing of the Maastricht Treaty"},{"id":"d","text":"The adoption of the euro"}]$choices$),
  (338, 'tr', $text$1951'de Avrupa inşasının ilk adımı nedir?$text$, $expl$1951'de kurulan Avrupa Kömür ve Çelik Topluluğu (AKÇT), Avrupa inşasının ilk adımıdır. Kömür ve çelik üretimlerini birleştirmek için altı ülke tarafından kurulmuştur.$expl$, $choices$[{"id":"a","text":"Avrupa Kömür ve Çelik Topluluğu (AKÇT) kurulması"},{"id":"b","text":"Avrupa Birliği kurulması"},{"id":"c","text":"Maastricht Antlaşması imzalanması"},{"id":"d","text":"Euro'nun kabulü"}]$choices$),
  (339, 'en', $text$During which president's mandate was the death penalty abolished?$text$, $expl$The death penalty was abolished in 1981 under the presidency of François Mitterrand, thanks to the action of Justice Minister Robert Badinter. France was one of the last Western European countries to abolish it.$expl$, $choices$[{"id":"a","text":"François Mitterrand"},{"id":"b","text":"Valéry Giscard d'Estaing"},{"id":"c","text":"Jacques Chirac"},{"id":"d","text":"Charles de Gaulle"}]$choices$),
  (339, 'tr', $text$Ölüm cezası hangi cumhurbaşkanının görev döneminde kaldırıldı?$text$, $expl$Ölüm cezası, Adalet Bakanı Robert Badinter'in çabaları sayesinde 1981'de François Mitterrand'ın cumhurbaşkanlığı döneminde kaldırıldı. Fransa, ölüm cezasını kaldıran son Batı Avrupa ülkelerinden biriydi.$expl$, $choices$[{"id":"a","text":"François Mitterrand"},{"id":"b","text":"Valéry Giscard d'Estaing"},{"id":"c","text":"Jacques Chirac"},{"id":"d","text":"Charles de Gaulle"}]$choices$),
  (340, 'en', $text$What political regime was put in place during the French Revolution in 1792?$text$, $expl$The First Republic was proclaimed on 21 September 1792, after the abolition of the monarchy. It is the first republican regime in French history.$expl$, $choices$[{"id":"a","text":"The Republic (First Republic)"},{"id":"b","text":"The Empire"},{"id":"c","text":"Constitutional monarchy"},{"id":"d","text":"Military dictatorship"}]$choices$),
  (340, 'tr', $text$1792'de Fransız Devrimi sırasında hangi siyasi rejim kuruldu?$text$, $expl$Birinci Cumhuriyet, monarşinin kaldırılmasının ardından 21 Eylül 1792'de ilan edildi. Fransız tarihindeki ilk cumhuriyet rejimidir.$expl$, $choices$[{"id":"a","text":"Cumhuriyet (Birinci Cumhuriyet)"},{"id":"b","text":"İmparatorluk"},{"id":"c","text":"Anayasal monarşi"},{"id":"d","text":"Askeri diktatörlük"}]$choices$),
  (341, 'en', $text$Who was a figure of the French Resistance during the Second World War?$text$, $expl$Jean Moulin (1899-1943) was a senior French civil servant and Resistance fighter. He unified the Resistance movements under the authority of General de Gaulle before being arrested and killed by the Gestapo.$expl$, $choices$[{"id":"a","text":"Jean Moulin"},{"id":"b","text":"Philippe Pétain"},{"id":"c","text":"Pierre Laval"},{"id":"d","text":"Adolphe Thiers"}]$choices$),
  (341, 'tr', $text$İkinci Dünya Savaşı sırasında Fransız Direnişi'nin bir figürü kimdi?$text$, $expl$Jean Moulin (1899-1943), Fransız üst düzey memur ve direnişçiydi. Gestapo tarafından tutuklanıp öldürülmeden önce Direniş hareketlerini General de Gaulle'ün otoritesi altında birleştirdi.$expl$, $choices$[{"id":"a","text":"Jean Moulin"},{"id":"b","text":"Philippe Pétain"},{"id":"c","text":"Pierre Laval"},{"id":"d","text":"Adolphe Thiers"}]$choices$),
  (342, 'en', $text$In 1944, what changed for women?$text$, $expl$In 1944, women obtained the right to vote in France. They voted for the first time in the municipal elections of 29 April 1945.$expl$, $choices$[{"id":"a","text":"They obtained the right to vote"},{"id":"b","text":"They obtained the right to work"},{"id":"c","text":"They obtained the right to divorce"},{"id":"d","text":"They obtained the right to open a bank account"}]$choices$),
  (342, 'tr', $text$1944'te kadınlar için ne değişti?$text$, $expl$1944'te kadınlar Fransa'da oy hakkı elde etti. İlk kez 29 Nisan 1945 belediye seçimlerinde oy kullandılar.$expl$, $choices$[{"id":"a","text":"Oy hakkı elde ettiler"},{"id":"b","text":"Çalışma hakkı elde ettiler"},{"id":"c","text":"Boşanma hakkı elde ettiler"},{"id":"d","text":"Banka hesabı açma hakkı elde ettiler"}]$choices$),
  (343, 'en', $text$Which international organisation was created in 1945 after the Second World War?$text$, $expl$The United Nations Organization (UN) was created in 1945 to maintain international peace and security. France is one of the five permanent members of the Security Council.$expl$, $choices$[{"id":"a","text":"The United Nations Organization (UN)"},{"id":"b","text":"The European Union"},{"id":"c","text":"NATO"},{"id":"d","text":"The Red Cross"}]$choices$),
  (343, 'tr', $text$İkinci Dünya Savaşı sonrası 1945'te hangi uluslararası örgüt kuruldu?$text$, $expl$Birleşmiş Milletler Örgütü (BM), uluslararası barışı ve güvenliği korumak için 1945'te kuruldu. Fransa, Güvenlik Konseyi'nin beş daimi üyesinden biridir.$expl$, $choices$[{"id":"a","text":"Birleşmiş Milletler Örgütü (BM)"},{"id":"b","text":"Avrupa Birliği"},{"id":"c","text":"NATO"},{"id":"d","text":"Kızılhaç"}]$choices$),
  (344, 'en', $text$Which penalty was abolished in 1981?$text$, $expl$The death penalty was abolished in France on 9 October 1981 by the law championed by Robert Badinter. France thus joined the European countries having abolished capital punishment.$expl$, $choices$[{"id":"a","text":"The death penalty"},{"id":"b","text":"Life imprisonment"},{"id":"c","text":"Hard labour"},{"id":"d","text":"Banishment"}]$choices$),
  (344, 'tr', $text$1981'de hangi ceza kaldırıldı?$text$, $expl$Ölüm cezası, Robert Badinter'in öncülük ettiği yasayla 9 Ekim 1981'de Fransa'da kaldırıldı. Fransa böylece idam cezasını kaldıran Avrupa ülkelerine katılmıştır.$expl$, $choices$[{"id":"a","text":"Ölüm cezası"},{"id":"b","text":"Müebbet hapis cezası"},{"id":"c","text":"Ağır iş cezası"},{"id":"d","text":"Sürgün"}]$choices$),
  (345, 'en', $text$In what year did the euro become the currency used in France?$text$, $expl$The euro became the currency used in France on 1 January 2002, replacing the French franc. The euro is today the common currency of 20 countries in the eurozone.$expl$, $choices$[{"id":"a","text":"2002"},{"id":"b","text":"1999"},{"id":"c","text":"1992"},{"id":"d","text":"2005"}]$choices$),
  (345, 'tr', $text$Euro hangi yıl Fransa'da kullanılan para birimi haline geldi?$text$, $expl$Euro, 1 Ocak 2002'de Fransız frangının yerini alarak Fransa'da kullanılan para birimi haline geldi. Euro bugün euro bölgesindeki 20 ülkenin ortak para birimidir.$expl$, $choices$[{"id":"a","text":"2002"},{"id":"b","text":"1999"},{"id":"c","text":"1992"},{"id":"d","text":"2005"}]$choices$),
  (346, 'en', $text$In what year did the First World War begin?$text$, $expl$The First World War began in 1914, triggered by the assassination of Archduke Franz Ferdinand of Austria. France entered the conflict from the start.$expl$, $choices$[{"id":"a","text":"1914"},{"id":"b","text":"1916"},{"id":"c","text":"1912"},{"id":"d","text":"1939"}]$choices$),
  (346, 'tr', $text$Birinci Dünya Savaşı hangi yılda başladı?$text$, $expl$Birinci Dünya Savaşı, Avusturya Arşidükü Franz Ferdinand'ın suikasti ile tetiklenerek 1914'te başladı. Fransa çatışmaya başından itibaren katıldı.$expl$, $choices$[{"id":"a","text":"1914"},{"id":"b","text":"1916"},{"id":"c","text":"1912"},{"id":"d","text":"1939"}]$choices$),
  (347, 'en', $text$Where did the landing take place in 1944?$text$, $expl$The landing of 6 June 1944 (D-Day) took place on the beaches of Normandy. This Allied military operation marked the beginning of the liberation of France from Nazi occupation.$expl$, $choices$[{"id":"a","text":"In Normandy"},{"id":"b","text":"In Brittany"},{"id":"c","text":"In Provence"},{"id":"d","text":"In Picardy"}]$choices$),
  (347, 'tr', $text$1944'te çıkarma nerede gerçekleşti?$text$, $expl$6 Haziran 1944 (D-Day) çıkarması Normandiya kıyılarında gerçekleşti. Bu Müttefik askeri operasyonu, Fransa'nın Nazi işgalinden kurtuluşunun başlangıcını işaret etti.$expl$, $choices$[{"id":"a","text":"Normandiya'da"},{"id":"b","text":"Brittany'de"},{"id":"c","text":"Provence'ta"},{"id":"d","text":"Picardy'de"}]$choices$),
  (348, 'en', $text$Which continent was most affected by French decolonisation after the Second World War?$text$, $expl$Africa was the continent most affected by French decolonisation. The majority of French African colonies gained independence in the 1960s.$expl$, $choices$[{"id":"a","text":"Africa"},{"id":"b","text":"Asia"},{"id":"c","text":"South America"},{"id":"d","text":"Oceania"}]$choices$),
  (348, 'tr', $text$İkinci Dünya Savaşı sonrası Fransız sömürgesizleşmesinden en çok hangi kıta etkilendi?$text$, $expl$Fransız sömürgesizleşmesinden en çok etkilenen kıta Afrika oldu. Fransız Afrika sömürgelerinin çoğu 1960'larda bağımsızlığını kazandı.$expl$, $choices$[{"id":"a","text":"Afrika"},{"id":"b","text":"Asya"},{"id":"c","text":"Güney Amerika"},{"id":"d","text":"Okyanusya"}]$choices$),
  (349, 'en', $text$What is celebrated on 8 May?$text$, $expl$8 May commemorates the end of the Second World War in Europe (victory of the Allies over Nazi Germany in 1945). It is a public holiday in France.$expl$, $choices$[{"id":"a","text":"The end of the Second World War in Europe"},{"id":"b","text":"Labour Day"},{"id":"c","text":"The armistice of the First World War"},{"id":"d","text":"The national holiday"}]$choices$),
  (349, 'tr', $text$8 Mayıs'ta ne kutlanır?$text$, $expl$8 Mayıs, Avrupa'da İkinci Dünya Savaşı'nın sona ermesini (Müttefiklerin 1945'te Nazi Almanyası karşısındaki zaferi) anar. Fransa'da resmi tatildir.$expl$, $choices$[{"id":"a","text":"Avrupa'da İkinci Dünya Savaşı'nın sonu"},{"id":"b","text":"İşçi Bayramı"},{"id":"c","text":"Birinci Dünya Savaşı ateşkesi"},{"id":"d","text":"Ulusal bayram"}]$choices$),
  (350, 'en', $text$Which sea or ocean borders mainland France?$text$, $expl$The Mediterranean Sea borders the south of mainland France. France is also bordered by the Atlantic Ocean to the west and the English Channel to the north.$expl$, $choices$[{"id":"a","text":"The Mediterranean Sea"},{"id":"b","text":"The Caspian Sea"},{"id":"c","text":"The Black Sea"},{"id":"d","text":"The Red Sea"}]$choices$),
  (350, 'tr', $text$Hangi deniz veya okyanus metropolitan Fransa'yı çevreler?$text$, $expl$Akdeniz, metropolitan Fransa'nın güneyini çevreler. Fransa ayrıca batıda Atlas Okyanusu ve kuzeyde Manş Denizi ile çevrilidir.$expl$, $choices$[{"id":"a","text":"Akdeniz"},{"id":"b","text":"Hazar Denizi"},{"id":"c","text":"Karadeniz"},{"id":"d","text":"Kızıldeniz"}]$choices$),
  (351, 'en', $text$Which country shares a land border with mainland France?$text$, $expl$Spain shares a land border with France to the south, along the Pyrenees. Mainland France also has borders with Belgium, Luxembourg, Germany, Switzerland, Italy and Monaco.$expl$, $choices$[{"id":"a","text":"Spain"},{"id":"b","text":"Portugal"},{"id":"c","text":"England"},{"id":"d","text":"Poland"}]$choices$),
  (351, 'tr', $text$Hangi ülke metropolitan Fransa ile kara sınırına sahiptir?$text$, $expl$İspanya, güneyde Pireneler boyunca Fransa ile bir kara sınırı paylaşır. Metropolitan Fransa ayrıca Belçika, Lüksemburg, Almanya, İsviçre, İtalya ve Monako ile sınırlara sahiptir.$expl$, $choices$[{"id":"a","text":"İspanya"},{"id":"b","text":"Portekiz"},{"id":"c","text":"İngiltere"},{"id":"d","text":"Polonya"}]$choices$),
  (352, 'en', $text$Which French city is a seaport?$text$, $expl$Le Havre is a major French seaport located in Normandy, at the mouth of the Seine. It is one of the most important commercial ports in France.$expl$, $choices$[{"id":"a","text":"Le Havre"},{"id":"b","text":"Toulouse"},{"id":"c","text":"Clermont-Ferrand"},{"id":"d","text":"Strasbourg"}]$choices$),
  (352, 'tr', $text$Hangi Fransız şehri bir deniz limanıdır?$text$, $expl$Le Havre, Normandiya'da, Seine'in ağzında yer alan büyük bir Fransız deniz limanıdır. Fransa'nın en önemli ticari limanlarından biridir.$expl$, $choices$[{"id":"a","text":"Le Havre"},{"id":"b","text":"Toulouse"},{"id":"c","text":"Clermont-Ferrand"},{"id":"d","text":"Strazburg"}]$choices$),
  (353, 'en', $text$Which sea lies between France and England?$text$, $expl$The English Channel separates France from England. It connects the Atlantic Ocean to the North Sea and has been crossed by the Channel Tunnel since 1994.$expl$, $choices$[{"id":"a","text":"The English Channel"},{"id":"b","text":"The North Sea"},{"id":"c","text":"The Mediterranean Sea"},{"id":"d","text":"The Baltic Sea"}]$choices$),
  (353, 'tr', $text$Fransa ile İngiltere arasında hangi deniz yer alır?$text$, $expl$Manş Denizi, Fransa'yı İngiltere'den ayırır. Atlas Okyanusu'nu Kuzey Denizi'ne bağlar ve 1994'ten beri Manş Tüneli ile geçilir.$expl$, $choices$[{"id":"a","text":"Manş Denizi"},{"id":"b","text":"Kuzey Denizi"},{"id":"c","text":"Akdeniz"},{"id":"d","text":"Baltık Denizi"}]$choices$),
  (354, 'en', $text$What is overseas France?$text$, $expl$Overseas France refers to all French territories located outside Europe. It includes departments (Guadeloupe, Martinique, French Guiana, Réunion, Mayotte) and overseas collectivities.$expl$, $choices$[{"id":"a","text":"All French territories located outside Europe"},{"id":"b","text":"The regions of southern France"},{"id":"c","text":"The former independent French colonies"},{"id":"d","text":"The French-speaking countries of Africa"}]$choices$),
  (354, 'tr', $text$Denizaşırı Fransa nedir?$text$, $expl$Denizaşırı Fransa, Avrupa dışında yer alan tüm Fransız topraklarını ifade eder. Departmanları (Guadeloupe, Martinik, Fransız Guyanası, Réunion, Mayotte) ve denizaşırı toplulukları içerir.$expl$, $choices$[{"id":"a","text":"Avrupa dışında yer alan tüm Fransız toprakları"},{"id":"b","text":"Güney Fransa bölgeleri"},{"id":"c","text":"Eski bağımsız Fransız sömürgeleri"},{"id":"d","text":"Afrika'nın Frankofon ülkeleri"}]$choices$),
  (355, 'en', $text$Which mountain range is located between France and Spain?$text$, $expl$The Pyrenees form a natural border between France and Spain over about 430 km. Their highest peak is the Aneto (3,404 m) on the Spanish side.$expl$, $choices$[{"id":"a","text":"The Pyrenees"},{"id":"b","text":"The Alps"},{"id":"c","text":"The Jura"},{"id":"d","text":"The Vosges"}]$choices$),
  (355, 'tr', $text$Fransa ile İspanya arasında hangi dağ silsilesi yer alır?$text$, $expl$Pireneler, Fransa ile İspanya arasında yaklaşık 430 km boyunca doğal bir sınır oluşturur. En yüksek zirvesi İspanya tarafındaki Aneto'dur (3.404 m).$expl$, $choices$[{"id":"a","text":"Pireneler"},{"id":"b","text":"Alpler"},{"id":"c","text":"Jura Dağları"},{"id":"d","text":"Vosges Dağları"}]$choices$),
  (356, 'en', $text$Which French island is located in the Indian Ocean?$text$, $expl$Réunion is a French overseas department located in the Indian Ocean, east of Madagascar. It is a volcanic island with about 900,000 inhabitants.$expl$, $choices$[{"id":"a","text":"Réunion"},{"id":"b","text":"Martinique"},{"id":"c","text":"Guadeloupe"},{"id":"d","text":"Corsica"}]$choices$),
  (356, 'tr', $text$Hangi Fransız adası Hint Okyanusu'nda yer alır?$text$, $expl$Réunion, Madagaskar'ın doğusunda Hint Okyanusu'nda yer alan bir Fransız denizaşırı ilidir. Yaklaşık 900.000 nüfuslu bir volkanik adadır.$expl$, $choices$[{"id":"a","text":"Réunion"},{"id":"b","text":"Martinik"},{"id":"c","text":"Guadeloupe"},{"id":"d","text":"Korsika"}]$choices$),
  (357, 'en', $text$What is the approximate population of France in 2025?$text$, $expl$France has approximately 68 million inhabitants in 2025, including overseas territories. It is the second most populous country in the European Union after Germany.$expl$, $choices$[{"id":"a","text":"68 million inhabitants"},{"id":"b","text":"50 million inhabitants"},{"id":"c","text":"80 million inhabitants"},{"id":"d","text":"45 million inhabitants"}]$choices$),
  (357, 'tr', $text$Fransa'nın 2025'teki yaklaşık nüfusu nedir?$text$, $expl$Fransa'nın 2025'te denizaşırı topraklar dahil yaklaşık 68 milyon nüfusu vardır. Almanya'dan sonra Avrupa Birliği'nin ikinci en kalabalık ülkesidir.$expl$, $choices$[{"id":"a","text":"68 milyon nüfus"},{"id":"b","text":"50 milyon nüfus"},{"id":"c","text":"80 milyon nüfus"},{"id":"d","text":"45 milyon nüfus"}]$choices$),
  (358, 'en', $text$Which river flows through Paris?$text$, $expl$The Seine flows through Paris from east to west. This 776 km river rises in Burgundy and flows into the English Channel at Le Havre.$expl$, $choices$[{"id":"a","text":"The Seine"},{"id":"b","text":"The Loire"},{"id":"c","text":"The Rhône"},{"id":"d","text":"The Garonne"}]$choices$),
  (358, 'tr', $text$Paris'i hangi nehir geçer?$text$, $expl$Seine, Paris'i doğudan batıya doğru geçer. 776 km'lik bu nehrin kaynağı Burgonya'dadır ve Le Havre'da Manş Denizi'ne dökülür.$expl$, $choices$[{"id":"a","text":"Seine"},{"id":"b","text":"Loire"},{"id":"c","text":"Rhône"},{"id":"d","text":"Garonne"}]$choices$),
  (359, 'en', $text$Which of these countries shares land borders with France?$text$, $expl$Belgium shares a land border with France to the north. The two countries are neighbours and partners within the European Union.$expl$, $choices$[{"id":"a","text":"Belgium"},{"id":"b","text":"The Netherlands"},{"id":"c","text":"The United Kingdom"},{"id":"d","text":"Denmark"}]$choices$),
  (359, 'tr', $text$Bu ülkelerden hangisi Fransa ile kara sınırları paylaşır?$text$, $expl$Belçika kuzeyde Fransa ile bir kara sınırı paylaşır. İki ülke komşu ve Avrupa Birliği içinde ortaktır.$expl$, $choices$[{"id":"a","text":"Belçika"},{"id":"b","text":"Hollanda"},{"id":"c","text":"Birleşik Krallık"},{"id":"d","text":"Danimarka"}]$choices$),
  (360, 'en', $text$Which country has a border with mainland France in the north-east?$text$, $expl$Germany shares a border with France in the north-east, along the Rhine. This border was the scene of many conflicts before becoming a symbol of Franco-German reconciliation.$expl$, $choices$[{"id":"a","text":"Germany"},{"id":"b","text":"Poland"},{"id":"c","text":"Austria"},{"id":"d","text":"The Czech Republic"}]$choices$),
  (360, 'tr', $text$Hangi ülke metropolitan Fransa ile kuzeydoğuda sınır komşusudur?$text$, $expl$Almanya, Ren Nehri boyunca kuzeydoğuda Fransa ile bir sınır paylaşır. Bu sınır, Fransız-Alman uzlaşmasının sembolü haline gelmeden önce birçok çatışmaya sahne olmuştur.$expl$, $choices$[{"id":"a","text":"Almanya"},{"id":"b","text":"Polonya"},{"id":"c","text":"Avusturya"},{"id":"d","text":"Çek Cumhuriyeti"}]$choices$),
  (361, 'en', $text$Where are the main economic activities located in France?$text$, $expl$The main economic activities in France are concentrated in the large metropolises, in particular the Paris region (Île-de-France). Lyon, Marseille and other major cities are also major economic hubs.$expl$, $choices$[{"id":"a","text":"In the large metropolises and the Paris region"},{"id":"b","text":"Only in the south of France"},{"id":"c","text":"Mainly in rural areas"},{"id":"d","text":"Exclusively on the coasts"}]$choices$),
  (361, 'tr', $text$Fransa'da başlıca ekonomik faaliyetler nerede yer alır?$text$, $expl$Fransa'daki başlıca ekonomik faaliyetler büyük şehirlerde, özellikle Paris bölgesinde (Île-de-France) yoğunlaşmıştır. Lyon, Marsilya ve diğer büyük şehirler de önemli ekonomik merkezlerdir.$expl$, $choices$[{"id":"a","text":"Büyük şehirlerde ve Paris bölgesinde"},{"id":"b","text":"Sadece Fransa'nın güneyinde"},{"id":"c","text":"Esas olarak kırsal bölgelerde"},{"id":"d","text":"Yalnızca kıyılarda"}]$choices$),
  (362, 'en', $text$Among these countries, which one attracts the most visitors each year?$text$, $expl$France is the world's leading tourist destination with about 90 million foreign visitors per year. Its cultural heritage, gastronomy and varied landscapes attract tourists from around the world.$expl$, $choices$[{"id":"a","text":"France"},{"id":"b","text":"Italy"},{"id":"c","text":"The United States"},{"id":"d","text":"Spain"}]$choices$),
  (362, 'tr', $text$Bu ülkelerden hangisi her yıl en çok ziyaretçi çeker?$text$, $expl$Fransa, yılda yaklaşık 90 milyon yabancı ziyaretçi ile dünyanın önde gelen turistik destinasyonudur. Kültürel mirası, gastronomisi ve çeşitli manzaraları dünyanın her yerinden turistleri çeker.$expl$, $choices$[{"id":"a","text":"Fransa"},{"id":"b","text":"İtalya"},{"id":"c","text":"Amerika Birleşik Devletleri"},{"id":"d","text":"İspanya"}]$choices$),
  (363, 'en', $text$Where does the majority of French people live?$text$, $expl$The majority of French people live in cities (about 80% of the population is urban). Large metropolitan areas such as Paris, Lyon and Marseille concentrate a significant share of the population.$expl$, $choices$[{"id":"a","text":"In cities"},{"id":"b","text":"In the countryside"},{"id":"c","text":"In the mountains"},{"id":"d","text":"On the coast"}]$choices$),
  (363, 'tr', $text$Fransızların çoğunluğu nerede yaşar?$text$, $expl$Fransızların çoğunluğu şehirlerde yaşar (nüfusun yaklaşık %80'i kentseldir). Paris, Lyon ve Marsilya gibi büyük metropoller nüfusun önemli bir kısmını barındırır.$expl$, $choices$[{"id":"a","text":"Şehirde"},{"id":"b","text":"Kırsalda"},{"id":"c","text":"Dağda"},{"id":"d","text":"Kıyıda"}]$choices$),
  (364, 'en', $text$Which region is the most populated?$text$, $expl$Île-de-France is the most populous region in France with about 12 million inhabitants. It includes Paris and its suburbs, concentrating one fifth of the French population.$expl$, $choices$[{"id":"a","text":"Île-de-France"},{"id":"b","text":"Provence-Alpes-Côte d'Azur"},{"id":"c","text":"Occitanie"},{"id":"d","text":"Nouvelle-Aquitaine"}]$choices$),
  (364, 'tr', $text$En kalabalık bölge hangisidir?$text$, $expl$Île-de-France, yaklaşık 12 milyon nüfusu ile Fransa'nın en kalabalık bölgesidir. Paris ve banliyölerini içerir ve Fransa nüfusunun beşte birini barındırır.$expl$, $choices$[{"id":"a","text":"Île-de-France"},{"id":"b","text":"Provence-Alpes-Côte d'Azur"},{"id":"c","text":"Occitanie"},{"id":"d","text":"Nouvelle-Aquitaine"}]$choices$),
  (365, 'en', $text$Which French city is among the country's 10 largest metropolises?$text$, $expl$Toulouse is among the 10 largest metropolises in France. It is the fourth largest city in France by population and a major hub for the aerospace industry.$expl$, $choices$[{"id":"a","text":"Toulouse"},{"id":"b","text":"Basel"},{"id":"c","text":"Lausanne"},{"id":"d","text":"Charleroi"}]$choices$),
  (365, 'tr', $text$Hangi Fransız şehri ülkenin en büyük 10 metropolü arasındadır?$text$, $expl$Toulouse, Fransa'nın en büyük 10 metropolü arasındadır. Nüfus bakımından Fransa'nın dördüncü büyük şehri ve havacılık endüstrisinin önemli bir merkezidir.$expl$, $choices$[{"id":"a","text":"Toulouse"},{"id":"b","text":"Basel"},{"id":"c","text":"Lozan"},{"id":"d","text":"Charleroi"}]$choices$),
  (366, 'en', $text$Which of these French departments is the most touristic?$text$, $expl$Paris (department 75) is the most touristic department in France. The capital attracts millions of visitors each year thanks to its monuments, museums and cultural life.$expl$, $choices$[{"id":"a","text":"Paris"},{"id":"b","text":"La Creuse"},{"id":"c","text":"Le Cantal"},{"id":"d","text":"La Lozère"}]$choices$),
  (366, 'tr', $text$Bu Fransız departmanlarından hangisi en turistik olanıdır?$text$, $expl$Paris (75. departman) Fransa'nın en turistik departmanıdır. Başkent, anıtları, müzeleri ve kültürel yaşamı sayesinde her yıl milyonlarca ziyaretçi çeker.$expl$, $choices$[{"id":"a","text":"Paris"},{"id":"b","text":"Creuse"},{"id":"c","text":"Cantal"},{"id":"d","text":"Lozère"}]$choices$),
  (367, 'en', $text$When can you visit cultural places for free in France?$text$, $expl$The European Heritage Days, organised each year in September, allow visitors to freely visit many cultural sites and historical monuments in France.$expl$, $choices$[{"id":"a","text":"During the European Heritage Days"},{"id":"b","text":"Only on 14 July"},{"id":"c","text":"Every Sunday of the year"},{"id":"d","text":"During school holidays"}]$choices$),
  (367, 'tr', $text$Fransa'da kültürel mekânları ne zaman ücretsiz ziyaret edebilirsiniz?$text$, $expl$Her yıl eylül ayında düzenlenen Avrupa Miras Günleri, Fransa'daki birçok kültürel mekân ve tarihi anıtın ücretsiz ziyaret edilmesini sağlar.$expl$, $choices$[{"id":"a","text":"Avrupa Miras Günleri sırasında"},{"id":"b","text":"Sadece 14 Temmuz'da"},{"id":"c","text":"Yılın her pazarı"},{"id":"d","text":"Okul tatilleri sırasında"}]$choices$),
  (368, 'en', $text$How many people speak French in the world?$text$, $expl$About 300 million people speak French in the world. French is the fifth most spoken language and is the official language in 29 countries.$expl$, $choices$[{"id":"a","text":"About 300 million"},{"id":"b","text":"About 100 million"},{"id":"c","text":"About 500 million"},{"id":"d","text":"About 50 million"}]$choices$),
  (368, 'tr', $text$Dünyada kaç kişi Fransızca konuşur?$text$, $expl$Dünyada yaklaşık 300 milyon kişi Fransızca konuşur. Fransızca, en çok konuşulan beşinci dildir ve 29 ülkede resmi dildir.$expl$, $choices$[{"id":"a","text":"Yaklaşık 300 milyon"},{"id":"b","text":"Yaklaşık 100 milyon"},{"id":"c","text":"Yaklaşık 500 milyon"},{"id":"d","text":"Yaklaşık 50 milyon"}]$choices$),
  (369, 'en', $text$Who was Marguerite Yourcenar?$text$, $expl$Marguerite Yourcenar (1903-1987) was a French writer, the first woman elected to the Académie française in 1980. She is known for her historical novels such as Mémoires d'Hadrien (Memoirs of Hadrian).$expl$, $choices$[{"id":"a","text":"The first woman elected to the Académie française"},{"id":"b","text":"A Nobel Prize-winning physicist"},{"id":"c","text":"A 19th-century explorer"},{"id":"d","text":"A composer of Baroque music"}]$choices$),
  (369, 'tr', $text$Marguerite Yourcenar kimdi?$text$, $expl$Marguerite Yourcenar (1903-1987), 1980'de Académie française'e seçilen ilk kadın olan Fransız yazardı. Mémoires d'Hadrien (Hadrianus'un Anıları) gibi tarihi romanlarıyla tanınır.$expl$, $choices$[{"id":"a","text":"Académie française'e seçilen ilk kadın"},{"id":"b","text":"Nobel ödüllü bir fizikçi"},{"id":"c","text":"19. yüzyıl kâşifi"},{"id":"d","text":"Bir Barok müzik bestecisi"}]$choices$),
  (370, 'en', $text$Which painter is French?$text$, $expl$Claude Monet (1840-1926) was a French painter, founder of the Impressionist movement. He is famous for his series of paintings of Water Lilies and the Rouen Cathedral.$expl$, $choices$[{"id":"a","text":"Claude Monet"},{"id":"b","text":"Pablo Picasso"},{"id":"c","text":"Vincent van Gogh"},{"id":"d","text":"Salvador Dalí"}]$choices$),
  (370, 'tr', $text$Hangi ressam Fransızdır?$text$, $expl$Claude Monet (1840-1926), Empresyonist hareketin kurucusu olan bir Fransız ressamdı. Nilüfer Çiçekleri ve Rouen Katedrali tablo serileriyle ünlüdür.$expl$, $choices$[{"id":"a","text":"Claude Monet"},{"id":"b","text":"Pablo Picasso"},{"id":"c","text":"Vincent van Gogh"},{"id":"d","text":"Salvador Dalí"}]$choices$),
  (371, 'en', $text$Which museum is located in Paris?$text$, $expl$The Musée d'Orsay is located in Paris, in a former railway station. It houses the largest collection of Impressionist and Post-Impressionist art in the world.$expl$, $choices$[{"id":"a","text":"The Musée d'Orsay"},{"id":"b","text":"The British Museum"},{"id":"c","text":"The Prado Museum"},{"id":"d","text":"The Metropolitan Museum"}]$choices$),
  (371, 'tr', $text$Hangi müze Paris'tedir?$text$, $expl$Musée d'Orsay (Orsay Müzesi) eski bir tren istasyonunda yer alan Paris'tedir. Dünyanın en büyük Empresyonist ve Post-Empresyonist sanat koleksiyonunu barındırır.$expl$, $choices$[{"id":"a","text":"Musée d'Orsay"},{"id":"b","text":"British Museum"},{"id":"c","text":"Prado Müzesi"},{"id":"d","text":"Metropolitan Müzesi"}]$choices$),
  (372, 'en', $text$Who was Auguste Rodin?$text$, $expl$Auguste Rodin (1840-1917) was a French sculptor, considered the father of modern sculpture. He is the author of The Thinker and The Burghers of Calais.$expl$, $choices$[{"id":"a","text":"A French sculptor, author of The Thinker"},{"id":"b","text":"An Impressionist painter"},{"id":"c","text":"An architect of the Eiffel Tower"},{"id":"d","text":"A Romantic writer"}]$choices$),
  (372, 'tr', $text$Auguste Rodin kimdi?$text$, $expl$Auguste Rodin (1840-1917), modern heykeltıraşlığın babası sayılan Fransız bir heykeltıraştı. Düşünen Adam ve Calais Burjuvaları eserlerinin yazarıdır.$expl$, $choices$[{"id":"a","text":"Düşünen Adam'ın yazarı bir Fransız heykeltıraş"},{"id":"b","text":"Bir Empresyonist ressam"},{"id":"c","text":"Eyfel Kulesi'nin mimarı"},{"id":"d","text":"Bir Romantik yazar"}]$choices$),
  (373, 'en', $text$What is the ranking of the French language among the most spoken languages in the world?$text$, $expl$French is the fifth most spoken language in the world. It is the official language in 29 countries and is spoken on all five continents.$expl$, $choices$[{"id":"a","text":"5th most spoken language"},{"id":"b","text":"2nd most spoken language"},{"id":"c","text":"10th most spoken language"},{"id":"d","text":"1st most spoken language"}]$choices$),
  (373, 'tr', $text$Fransızcanın dünyada en çok konuşulan diller arasındaki sırası nedir?$text$, $expl$Fransızca, dünyada en çok konuşulan beşinci dildir. 29 ülkede resmi dildir ve beş kıtada konuşulur.$expl$, $choices$[{"id":"a","text":"5. en çok konuşulan dil"},{"id":"b","text":"2. en çok konuşulan dil"},{"id":"c","text":"10. en çok konuşulan dil"},{"id":"d","text":"1. en çok konuşulan dil"}]$choices$),
  (374, 'en', $text$Which famous cathedral was partially destroyed by fire in 2019?$text$, $expl$Notre-Dame de Paris cathedral was seriously damaged by a fire on 15 April 2019. Its spire and part of the roof collapsed. It was restored and reopened in December 2024.$expl$, $choices$[{"id":"a","text":"Notre-Dame de Paris"},{"id":"b","text":"Reims Cathedral"},{"id":"c","text":"Chartres Cathedral"},{"id":"d","text":"Strasbourg Cathedral"}]$choices$),
  (374, 'tr', $text$Hangi ünlü katedral 2019'da çıkan yangında kısmen tahrip oldu?$text$, $expl$Notre-Dame de Paris Katedrali, 15 Nisan 2019'da çıkan bir yangında ciddi şekilde hasar gördü. Kulesi ve çatısının bir kısmı çöktü. Restore edilerek Aralık 2024'te yeniden açıldı.$expl$, $choices$[{"id":"a","text":"Notre-Dame de Paris"},{"id":"b","text":"Reims Katedrali"},{"id":"c","text":"Chartres Katedrali"},{"id":"d","text":"Strazburg Katedrali"}]$choices$),
  (375, 'en', $text$Who was a famous French woman writer?$text$, $expl$Colette (1873-1954) was a famous French novelist, author of many novels such as the Claudine series. She was the second woman to receive a state funeral in France.$expl$, $choices$[{"id":"a","text":"Colette"},{"id":"b","text":"Jane Austen"},{"id":"c","text":"Virginia Woolf"},{"id":"d","text":"Agatha Christie"}]$choices$),
  (375, 'tr', $text$Hangi ünlü bir Fransız kadın yazardı?$text$, $expl$Colette (1873-1954), Claudine serisi gibi birçok romanın yazarı olan ünlü bir Fransız romancıydı. Fransa'da devlet töreniyle defnedilen ikinci kadındı.$expl$, $choices$[{"id":"a","text":"Colette"},{"id":"b","text":"Jane Austen"},{"id":"c","text":"Virginia Woolf"},{"id":"d","text":"Agatha Christie"}]$choices$),
  (376, 'en', $text$Who was a famous French musician?$text$, $expl$Claude Debussy (1862-1918) was a French composer, a major figure of Impressionist music. He is notably known for Clair de lune and La Mer.$expl$, $choices$[{"id":"a","text":"Claude Debussy"},{"id":"b","text":"Ludwig van Beethoven"},{"id":"c","text":"Wolfgang Amadeus Mozart"},{"id":"d","text":"Johann Sebastian Bach"}]$choices$),
  (376, 'tr', $text$Ünlü bir Fransız müzisyen kimdi?$text$, $expl$Claude Debussy (1862-1918), Empresyonist müziğin önemli bir figürü olan Fransız besteciydi. Özellikle Clair de lune (Ay Işığı) ve La Mer (Deniz) eserleriyle tanınır.$expl$, $choices$[{"id":"a","text":"Claude Debussy"},{"id":"b","text":"Ludwig van Beethoven"},{"id":"c","text":"Wolfgang Amadeus Mozart"},{"id":"d","text":"Johann Sebastian Bach"}]$choices$),
  (377, 'en', $text$Who was Auguste Renoir?$text$, $expl$Auguste Renoir (1841-1919) was a French painter, one of the great masters of Impressionism. He is famous for his scenes of everyday life and his luminous portraits.$expl$, $choices$[{"id":"a","text":"A French Impressionist painter"},{"id":"b","text":"An 18th-century sculptor"},{"id":"c","text":"A Realist writer"},{"id":"d","text":"A Renaissance architect"}]$choices$),
  (377, 'tr', $text$Auguste Renoir kimdi?$text$, $expl$Auguste Renoir (1841-1919), Empresyonizmin büyük ustalarından biri olan Fransız bir ressamdı. Günlük yaşam sahneleri ve ışıltılı portreleriyle ünlüdür.$expl$, $choices$[{"id":"a","text":"Bir Fransız Empresyonist ressam"},{"id":"b","text":"18. yüzyıl heykeltıraşı"},{"id":"c","text":"Bir Realist yazar"},{"id":"d","text":"Bir Rönesans mimarı"}]$choices$),
  (378, 'en', $text$Which festival is French?$text$, $expl$The Fête de la Musique, celebrated on 21 June, is a festival of French origin created in 1982 by Jack Lang. It is now celebrated in many countries around the world.$expl$, $choices$[{"id":"a","text":"The Fête de la Musique"},{"id":"b","text":"Thanksgiving"},{"id":"c","text":"Halloween"},{"id":"d","text":"Saint Patrick's Day"}]$choices$),
  (378, 'tr', $text$Hangi bayram Fransızdır?$text$, $expl$21 Haziran'da kutlanan Fête de la Musique (Müzik Bayramı), 1982'de Jack Lang tarafından kurulan Fransız kökenli bir bayramdır. Bugün dünyanın birçok ülkesinde kutlanmaktadır.$expl$, $choices$[{"id":"a","text":"Fête de la Musique (Müzik Bayramı)"},{"id":"b","text":"Şükran Günü"},{"id":"c","text":"Cadılar Bayramı"},{"id":"d","text":"Aziz Patrick Günü"}]$choices$),
  (379, 'en', $text$Among these texts, which one was adopted under Napoleon I?$text$, $expl$The Civil Code was adopted in 1804 under Napoleon I. Also called the Napoleonic Code, it unified French law and remains the foundation of civil law in France.$expl$, $choices$[{"id":"a","text":"The Civil Code"},{"id":"b","text":"The Declaration of the Rights of Man and of the Citizen"},{"id":"c","text":"The law on the separation of Church and State"},{"id":"d","text":"The Constitution of the Fifth Republic"}]$choices$),
  (379, 'tr', $text$Bu metinlerden hangisi I. Napolyon döneminde kabul edildi?$text$, $expl$Medeni Kanun (Code civil), I. Napolyon döneminde 1804'te kabul edildi. Napolyon Kanunu olarak da bilinen bu yasa, Fransız hukukunu birleştirmiştir ve Fransa'da medeni hukukun temeli olmaya devam etmektedir.$expl$, $choices$[{"id":"a","text":"Medeni Kanun (Code civil)"},{"id":"b","text":"İnsan ve Yurttaş Hakları Bildirgesi"},{"id":"c","text":"Kilise ve Devlet'in ayrılması yasası"},{"id":"d","text":"Beşinci Cumhuriyet Anayasası"}]$choices$),
  (380, 'en', $text$Who was President of the Fifth Republic?$text$, $expl$Jacques Chirac was President of the Fifth Republic from 1995 to 2007. He was the fifth President of the Fifth Republic, preceded by François Mitterrand.$expl$, $choices$[{"id":"a","text":"Jacques Chirac"},{"id":"b","text":"Winston Churchill"},{"id":"c","text":"Konrad Adenauer"},{"id":"d","text":"Benito Mussolini"}]$choices$),
  (380, 'tr', $text$Beşinci Cumhuriyet'in cumhurbaşkanı kimdi?$text$, $expl$Jacques Chirac, 1995'ten 2007'ye kadar Beşinci Cumhuriyet'in Cumhurbaşkanıydı. François Mitterrand'dan sonra gelen Beşinci Cumhuriyet'in beşinci Cumhurbaşkanıydı.$expl$, $choices$[{"id":"a","text":"Jacques Chirac"},{"id":"b","text":"Winston Churchill"},{"id":"c","text":"Konrad Adenauer"},{"id":"d","text":"Benito Mussolini"}]$choices$),
  (381, 'en', $text$What does the date of 14 July mean for the French?$text$, $expl$14 July is the French national holiday. It commemorates the storming of the Bastille in 1789, symbol of the end of absolutism, and the Fête de la Fédération of 1790.$expl$, $choices$[{"id":"a","text":"It is the national holiday, commemorating the storming of the Bastille"},{"id":"b","text":"It is the anniversary of the Constitution"},{"id":"c","text":"It is Europe Day"},{"id":"d","text":"It is Armistice Day"}]$choices$),
  (381, 'tr', $text$14 Temmuz tarihi Fransızlar için ne anlama gelir?$text$, $expl$14 Temmuz, Fransız ulusal bayramıdır. 1789'da Bastille'in ele geçirilmesini, mutlakiyetçiliğin sonunun sembolünü ve 1790 Fête de la Fédération'unu anar.$expl$, $choices$[{"id":"a","text":"Bastille'in ele geçirilmesini anan ulusal bayramdır"},{"id":"b","text":"Anayasanın yıldönümüdür"},{"id":"c","text":"Avrupa Günü'dür"},{"id":"d","text":"Ateşkes Günü'dür"}]$choices$),
  (382, 'en', $text$Which of these countries is a founding country of the European Union?$text$, $expl$France is one of the six founding countries of European construction, along with Germany, Italy, Belgium, the Netherlands and Luxembourg. The ECSC was created in 1951.$expl$, $choices$[{"id":"a","text":"France"},{"id":"b","text":"The United Kingdom"},{"id":"c","text":"Spain"},{"id":"d","text":"Poland"}]$choices$),
  (382, 'tr', $text$Bu ülkelerden hangisi Avrupa Birliği'nin kurucu üyesidir?$text$, $expl$Fransa, Almanya, İtalya, Belçika, Hollanda ve Lüksemburg ile birlikte Avrupa inşasının altı kurucu ülkesinden biridir. AKÇT 1951'de kurulmuştur.$expl$, $choices$[{"id":"a","text":"Fransa"},{"id":"b","text":"Birleşik Krallık"},{"id":"c","text":"İspanya"},{"id":"d","text":"Polonya"}]$choices$),
  (383, 'en', $text$In which region are some of the D-Day landing beaches located?$text$, $expl$The D-Day landing beaches of 6 June 1944 are located in Normandy. The five beaches (Utah, Omaha, Gold, Juno, Sword) are major places of remembrance.$expl$, $choices$[{"id":"a","text":"Normandy"},{"id":"b","text":"Brittany"},{"id":"c","text":"Picardy"},{"id":"d","text":"Aquitaine"}]$choices$),
  (383, 'tr', $text$Çıkarma plajlarının bir kısmı hangi bölgededir?$text$, $expl$6 Haziran 1944 çıkarma plajları Normandiya'da yer alır. Beş plaj (Utah, Omaha, Gold, Juno, Sword) önemli anma yerleridir.$expl$, $choices$[{"id":"a","text":"Normandiya"},{"id":"b","text":"Brittany"},{"id":"c","text":"Picardy"},{"id":"d","text":"Aquitaine"}]$choices$),
  (384, 'en', $text$In which city were the kings of France crowned?$text$, $expl$The kings of France were traditionally crowned in the cathedral of Reims. This tradition dates back to the baptism of Clovis around 496 and continued for centuries.$expl$, $choices$[{"id":"a","text":"Reims"},{"id":"b","text":"Paris"},{"id":"c","text":"Versailles"},{"id":"d","text":"Orléans"}]$choices$),
  (384, 'tr', $text$Fransa kralları hangi şehirde taç giyerdi?$text$, $expl$Fransa kralları geleneksel olarak Reims katedralinde taç giyerdi. Bu gelenek Clovis'in yaklaşık 496'daki vaftizine dayanır ve yüzyıllarca sürmüştür.$expl$, $choices$[{"id":"a","text":"Reims"},{"id":"b","text":"Paris"},{"id":"c","text":"Versay"},{"id":"d","text":"Orléans"}]$choices$),
  (385, 'en', $text$In what year was the European Union founded?$text$, $expl$The European Union was founded in 1992 by the Maastricht Treaty. This treaty transformed the European Economic Community into the European Union and laid the foundations of the single currency.$expl$, $choices$[{"id":"a","text":"1992"},{"id":"b","text":"1957"},{"id":"c","text":"2002"},{"id":"d","text":"1951"}]$choices$),
  (385, 'tr', $text$Avrupa Birliği hangi yılda kuruldu?$text$, $expl$Avrupa Birliği, Maastricht Antlaşması ile 1992'de kuruldu. Bu antlaşma Avrupa Ekonomik Topluluğu'nu Avrupa Birliği'ne dönüştürdü ve tek para biriminin temellerini attı.$expl$, $choices$[{"id":"a","text":"1992"},{"id":"b","text":"1957"},{"id":"c","text":"2002"},{"id":"d","text":"1951"}]$choices$),
  (386, 'en', $text$Who abolished slavery in France?$text$, $expl$Victor Schœlcher is the origin of the decree of definitive abolition of slavery in France on 27 April 1848. He was then under-secretary of State for the colonies under the Second Republic.$expl$, $choices$[{"id":"a","text":"Victor Schœlcher"},{"id":"b","text":"Napoleon Bonaparte"},{"id":"c","text":"Jules Ferry"},{"id":"d","text":"Léon Gambetta"}]$choices$),
  (386, 'tr', $text$Fransa'da köleliği kim kaldırdı?$text$, $expl$Victor Schœlcher, Fransa'da köleliğin kesin olarak kaldırılması kararnamesinin (27 Nisan 1848) kökeninde yer alır. O dönemde İkinci Cumhuriyet altında Sömürgeler için Devlet alt sekreteriydi.$expl$, $choices$[{"id":"a","text":"Victor Schœlcher"},{"id":"b","text":"Napoléon Bonaparte"},{"id":"c","text":"Jules Ferry"},{"id":"d","text":"Léon Gambetta"}]$choices$),
  (387, 'en', $text$During the Second World War, on what date was Paris liberated?$text$, $expl$Paris was liberated on 25 August 1944 after a popular uprising and the arrival of General Leclerc's 2nd Armoured Division. This event marks a turning point in the liberation of France.$expl$, $choices$[{"id":"a","text":"25 August 1944"},{"id":"b","text":"6 June 1944"},{"id":"c","text":"8 May 1945"},{"id":"d","text":"18 June 1940"}]$choices$),
  (387, 'tr', $text$İkinci Dünya Savaşı sırasında Paris hangi tarihte kurtarıldı?$text$, $expl$Paris, halk ayaklanması ve General Leclerc'in 2. Zırhlı Tümeni'nin gelişinin ardından 25 Ağustos 1944'te kurtarıldı. Bu olay Fransa'nın kurtuluşunda bir dönüm noktasıdır.$expl$, $choices$[{"id":"a","text":"25 Ağustos 1944"},{"id":"b","text":"6 Haziran 1944"},{"id":"c","text":"8 Mayıs 1945"},{"id":"d","text":"18 Haziran 1940"}]$choices$),
  (388, 'en', $text$What was the main French port involved in the slave trade in the 18th century?$text$, $expl$Nantes was the main French port involved in the slave trade in the 18th century. The city organised the largest number of French slave expeditions and today has a memorial for the abolition of slavery.$expl$, $choices$[{"id":"a","text":"Nantes"},{"id":"b","text":"Marseille"},{"id":"c","text":"Le Havre"},{"id":"d","text":"Brest"}]$choices$),
  (388, 'tr', $text$18. yüzyılda köle ticaretine dahil olan ana Fransız limanı hangisiydi?$text$, $expl$Nantes, 18. yüzyılda köle ticaretine dahil olan ana Fransız limanıydı. Şehir en çok sayıda Fransız köle seferi düzenlemiş ve bugün köleliğin kaldırılması için bir anıta sahiptir.$expl$, $choices$[{"id":"a","text":"Nantes"},{"id":"b","text":"Marsilya"},{"id":"c","text":"Le Havre"},{"id":"d","text":"Brest"}]$choices$),
  (389, 'en', $text$Which famous Enlightenment philosopher denounced slavery?$text$, $expl$Voltaire (1694-1778) was an Enlightenment philosopher who denounced slavery, notably in Candide. The Enlightenment philosophers played a major role in challenging this practice.$expl$, $choices$[{"id":"a","text":"Voltaire"},{"id":"b","text":"Napoleon Bonaparte"},{"id":"c","text":"Louis XIV"},{"id":"d","text":"Richelieu"}]$choices$),
  (389, 'tr', $text$Hangi ünlü Aydınlanma (les Lumières) filozofu köleliği kınamıştır?$text$, $expl$Voltaire (1694-1778), özellikle Candide'de köleliği kınayan bir Aydınlanma filozofuydu. Aydınlanma filozofları bu uygulamayı sorgulamada önemli bir rol oynamıştır.$expl$, $choices$[{"id":"a","text":"Voltaire"},{"id":"b","text":"Napoléon Bonaparte"},{"id":"c","text":"Louis XIV"},{"id":"d","text":"Richelieu"}]$choices$),
  (390, 'en', $text$Which dish is a French culinary speciality?$text$, $expl$Coq au vin is a traditional French dish, made of chicken simmered in red wine with bacon and mushrooms. French gastronomy is on the UNESCO intangible heritage list.$expl$, $choices$[{"id":"a","text":"Coq au vin"},{"id":"b","text":"Paella"},{"id":"c","text":"Sushi"},{"id":"d","text":"Fish and chips"}]$choices$),
  (390, 'tr', $text$Hangi yemek bir Fransız mutfağı uzmanlık alanıdır?$text$, $expl$Coq au vin, jambon ve mantarlarla kırmızı şarapta pişirilmiş tavuktan yapılan geleneksel bir Fransız yemeğidir. Fransız gastronomisi UNESCO somut olmayan kültürel mirasına dahildir.$expl$, $choices$[{"id":"a","text":"Coq au vin"},{"id":"b","text":"Paella"},{"id":"c","text":"Suşi"},{"id":"d","text":"Fish and chips"}]$choices$),
  (391, 'en', $text$Who was Marie Curie?$text$, $expl$Marie Curie (1867-1934) was a Franco-Polish physicist and chemist, the first woman to receive a Nobel Prize. She obtained two Nobel Prizes (Physics in 1903 and Chemistry in 1911) for her work on radioactivity.$expl$, $choices$[{"id":"a","text":"A Franco-Polish physicist, double Nobel Prize winner"},{"id":"b","text":"A 19th-century French novelist"},{"id":"c","text":"A Resistance fighter of the Second World War"},{"id":"d","text":"A queen of France"}]$choices$),
  (391, 'tr', $text$Marie Curie kimdi?$text$, $expl$Marie Curie (1867-1934), Nobel Ödülü alan ilk kadın olan Fransız-Polonyalı bir fizikçi ve kimyagerdi. Radyoaktivite üzerine çalışmaları için iki Nobel Ödülü (1903'te Fizik ve 1911'de Kimya) almıştır.$expl$, $choices$[{"id":"a","text":"Fransız-Polonyalı bir fizikçi, çift Nobel ödüllü"},{"id":"b","text":"19. yüzyıl Fransız romancısı"},{"id":"c","text":"İkinci Dünya Savaşı direnişçisi"},{"id":"d","text":"Bir Fransa kraliçesi"}]$choices$),
  (392, 'en', $text$Who painted Liberty Leading the People?$text$, $expl$Eugène Delacroix painted Liberty Leading the People in 1830. This famous painting depicts the July Revolution of 1830 and is exhibited at the Louvre Museum.$expl$, $choices$[{"id":"a","text":"Eugène Delacroix"},{"id":"b","text":"Claude Monet"},{"id":"c","text":"Paul Cézanne"},{"id":"d","text":"Auguste Renoir"}]$choices$),
  (392, 'tr', $text$« Halka Yol Gösteren Özgürlük »ü kim çizmiştir?$text$, $expl$Eugène Delacroix, La Liberté guidant le peuple'ü (Halka Yol Gösteren Özgürlük) 1830'da çizdi. Bu ünlü tablo 1830 Temmuz Devrimi'ni tasvir eder ve Louvre Müzesi'nde sergilenir.$expl$, $choices$[{"id":"a","text":"Eugène Delacroix"},{"id":"b","text":"Claude Monet"},{"id":"c","text":"Paul Cézanne"},{"id":"d","text":"Auguste Renoir"}]$choices$),
  (393, 'en', $text$In which major Parisian museum is the Mona Lisa exhibited?$text$, $expl$The Mona Lisa (or La Joconde) by Leonardo da Vinci is exhibited at the Louvre Museum in Paris. It is the most famous painting in the world and one of the jewels of the museum's collection.$expl$, $choices$[{"id":"a","text":"The Louvre Museum"},{"id":"b","text":"The Musée d'Orsay"},{"id":"c","text":"The Pompidou Centre"},{"id":"d","text":"The Rodin Museum"}]$choices$),
  (393, 'tr', $text$Mona Lisa hangi büyük Paris müzesinde sergilenir?$text$, $expl$Leonardo da Vinci'nin Mona Lisa'sı (La Joconde) Paris'teki Louvre Müzesi'nde sergilenir. Dünyanın en ünlü tablosu ve müze koleksiyonunun mücevherlerinden biridir.$expl$, $choices$[{"id":"a","text":"Louvre Müzesi"},{"id":"b","text":"Musée d'Orsay"},{"id":"c","text":"Pompidou Merkezi"},{"id":"d","text":"Rodin Müzesi"}]$choices$),
  (394, 'en', $text$Which famous château is located near Paris and symbolises the royal power of Louis XIV?$text$, $expl$The Palace of Versailles was the main residence of the kings of France from Louis XIV to Louis XVI. Built in the 17th century, it symbolises the power of the absolute monarchy.$expl$, $choices$[{"id":"a","text":"The Palace of Versailles"},{"id":"b","text":"The Château de Chambord"},{"id":"c","text":"The Château de Fontainebleau"},{"id":"d","text":"The Château de Chenonceau"}]$choices$),
  (394, 'tr', $text$Hangi ünlü şato Paris yakınlarındadır ve Louis XIV'in kraliyet gücünü simgeler?$text$, $expl$Versay Sarayı, Louis XIV'den Louis XVI'ya kadar Fransa krallarının ana ikametgâhıydı. 17. yüzyılda inşa edilen saray, mutlak monarşinin gücünü simgeler.$expl$, $choices$[{"id":"a","text":"Versay Sarayı"},{"id":"b","text":"Chambord Şatosu"},{"id":"c","text":"Fontainebleau Şatosu"},{"id":"d","text":"Chenonceau Şatosu"}]$choices$),
  (395, 'en', $text$Where can you see prehistoric paintings in France?$text$, $expl$The Lascaux cave, in Dordogne, contains prehistoric paintings dating back about 17,000 years. Discovered in 1940, it is nicknamed the "Sistine Chapel of Prehistory".$expl$, $choices$[{"id":"a","text":"In the Lascaux cave"},{"id":"b","text":"At the Palace of Versailles"},{"id":"c","text":"At the Louvre Museum"},{"id":"d","text":"In the Chartres Cathedral"}]$choices$),
  (395, 'tr', $text$Fransa'da tarih öncesi tabloları nerede görebilirsiniz?$text$, $expl$Dordogne'daki Lascaux mağarası, yaklaşık 17.000 yıl öncesine ait tarih öncesi tablolara ev sahipliği yapar. 1940'ta keşfedilen mağara, « Tarih Öncesi'nin Sistine Şapeli » olarak adlandırılır.$expl$, $choices$[{"id":"a","text":"Lascaux mağarasında"},{"id":"b","text":"Versay Sarayı'nda"},{"id":"c","text":"Louvre Müzesi'nde"},{"id":"d","text":"Chartres Katedrali'nde"}]$choices$),
  (396, 'en', $text$Which famous painter painted the Water Lilies?$text$, $expl$Claude Monet painted the famous Water Lilies series in his garden at Giverny. These Impressionist paintings, painted between 1895 and 1926, are exhibited at the Musée de l'Orangerie in Paris.$expl$, $choices$[{"id":"a","text":"Claude Monet"},{"id":"b","text":"Edgar Degas"},{"id":"c","text":"Paul Gauguin"},{"id":"d","text":"Édouard Manet"}]$choices$),
  (396, 'tr', $text$Hangi ünlü ressam Nilüfer Çiçekleri'ni (Nymphéas) çizdi?$text$, $expl$Claude Monet, ünlü Nilüfer Çiçekleri serisini Giverny'deki bahçesinde çizdi. 1895 ile 1926 arasında çizilen bu Empresyonist tablolar Paris'teki Musée de l'Orangerie'de sergilenmektedir.$expl$, $choices$[{"id":"a","text":"Claude Monet"},{"id":"b","text":"Edgar Degas"},{"id":"c","text":"Paul Gauguin"},{"id":"d","text":"Édouard Manet"}]$choices$),
  (397, 'en', $text$What does 1 May symbolise?$text$, $expl$1 May is Labour Day in France, a public holiday since 1947. It is a day of celebration of workers' rights, traditionally marked by the offering of lily of the valley sprigs.$expl$, $choices$[{"id":"a","text":"Labour Day"},{"id":"b","text":"The national holiday"},{"id":"c","text":"The Music Day"},{"id":"d","text":"The Victory Day"}]$choices$),
  (397, 'tr', $text$1 Mayıs neyi simgeler?$text$, $expl$1 Mayıs Fransa'da İşçi Bayramı'dır, 1947'den beri resmi tatildir. İşçi haklarının kutlandığı bir gün olup geleneksel olarak vadi zambağı dalları sunularak işaretlenir.$expl$, $choices$[{"id":"a","text":"İşçi Bayramı"},{"id":"b","text":"Ulusal bayram"},{"id":"c","text":"Müzik Bayramı"},{"id":"d","text":"Zafer Bayramı"}]$choices$),
  (398, 'en', $text$Who was Monsieur Rouget de Lisle?$text$, $expl$Claude Joseph Rouget de Lisle (1760-1836) was a French officer and composer, author of La Marseillaise in 1792. This patriotic song became the French national anthem.$expl$, $choices$[{"id":"a","text":"The composer of La Marseillaise"},{"id":"b","text":"The founder of the Fifth Republic"},{"id":"c","text":"A general of Napoleon"},{"id":"d","text":"An Enlightenment philosopher"}]$choices$),
  (398, 'tr', $text$Bay Rouget de Lisle kimdi?$text$, $expl$Claude Joseph Rouget de Lisle (1760-1836), 1792'de La Marseillaise'in yazarı olan Fransız bir subay ve besteciydi. Bu vatansever şarkı Fransa'nın ulusal marşı haline geldi.$expl$, $choices$[{"id":"a","text":"La Marseillaise'in bestecisi"},{"id":"b","text":"Beşinci Cumhuriyet'in kurucusu"},{"id":"c","text":"Napolyon'un bir generali"},{"id":"d","text":"Bir Aydınlanma filozofu"}]$choices$),
  (399, 'en', $text$On what occasion was the Eiffel Tower built?$text$, $expl$The Eiffel Tower was built for the 1889 Universal Exhibition, which celebrated the centenary of the French Revolution. Designed by Gustave Eiffel, it was to be dismantled after the exhibition.$expl$, $choices$[{"id":"a","text":"The 1889 Universal Exhibition"},{"id":"b","text":"The 1900 Olympic Games"},{"id":"c","text":"The 1918 victory"},{"id":"d","text":"The coronation of Napoleon"}]$choices$),
  (399, 'tr', $text$Eyfel Kulesi hangi vesileyle inşa edildi?$text$, $expl$Eyfel Kulesi, Fransız Devrimi'nin yüzüncü yıldönümünü kutlayan 1889 Evrensel Sergisi için inşa edildi. Gustave Eiffel tarafından tasarlanan kule, serginin ardından sökülmesi planlanmıştı.$expl$, $choices$[{"id":"a","text":"1889 Evrensel Sergisi"},{"id":"b","text":"1900 Olimpiyat Oyunları"},{"id":"c","text":"1918 zaferi"},{"id":"d","text":"Napolyon'un taç giyme töreni"}]$choices$),
  (400, 'en', $text$Who was a famous French composer?$text$, $expl$Maurice Ravel (1875-1937) was a French composer, author of the famous Boléro. He is one of the greatest French composers of the 20th century, along with Claude Debussy.$expl$, $choices$[{"id":"a","text":"Maurice Ravel"},{"id":"b","text":"Giuseppe Verdi"},{"id":"c","text":"Richard Wagner"},{"id":"d","text":"Pyotr Tchaikovsky"}]$choices$),
  (400, 'tr', $text$Ünlü bir Fransız besteci kimdi?$text$, $expl$Maurice Ravel (1875-1937), ünlü Boléro'nun yazarı olan Fransız bir besteciydi. Claude Debussy ile birlikte 20. yüzyılın en büyük Fransız bestecilerinden biridir.$expl$, $choices$[{"id":"a","text":"Maurice Ravel"},{"id":"b","text":"Giuseppe Verdi"},{"id":"c","text":"Richard Wagner"},{"id":"d","text":"Pyotr Çaykovski"}]$choices$),
  (401, 'en', $text$Which historic monument is located on an island in Normandy?$text$, $expl$Mont-Saint-Michel is a medieval abbey located on a rocky islet in Normandy. It is one of the most visited sites in France and is a UNESCO World Heritage Site.$expl$, $choices$[{"id":"a","text":"Mont-Saint-Michel"},{"id":"b","text":"The Château de Chambord"},{"id":"c","text":"The Pont du Gard"},{"id":"d","text":"The Cité de Carcassonne"}]$choices$),
  (401, 'tr', $text$Hangi tarihi anıt Normandiya'da bir ada üzerindedir?$text$, $expl$Mont-Saint-Michel, Normandiya'da kayalık bir adacık üzerinde yer alan ortaçağ bir manastırdır. Fransa'nın en çok ziyaret edilen yerlerinden biri olup UNESCO Dünya Mirası Listesi'ndedir.$expl$, $choices$[{"id":"a","text":"Mont-Saint-Michel"},{"id":"b","text":"Chambord Şatosu"},{"id":"c","text":"Pont du Gard"},{"id":"d","text":"Carcassonne Surlu Kenti"}]$choices$),
  (402, 'en', $text$Which island is part of the French Antilles?$text$, $expl$Guadeloupe is part of the French Antilles, in the Caribbean Sea. It is a French overseas department and region made up of several islands.$expl$, $choices$[{"id":"a","text":"Guadeloupe"},{"id":"b","text":"Cuba"},{"id":"c","text":"Jamaica"},{"id":"d","text":"Puerto Rico"}]$choices$),
  (402, 'tr', $text$Hangi ada Fransız Antilleri'nin bir parçasıdır?$text$, $expl$Guadeloupe, Karayip Denizi'ndeki Fransız Antilleri'nin bir parçasıdır. Birkaç adadan oluşan Fransız denizaşırı il ve bölgesidir.$expl$, $choices$[{"id":"a","text":"Guadeloupe"},{"id":"b","text":"Küba"},{"id":"c","text":"Jamaika"},{"id":"d","text":"Porto Riko"}]$choices$),
  (403, 'en', $text$Which island is French?$text$, $expl$New Caledonia is a French territory located in the Pacific Ocean. It is a sui generis collectivity of France with a special status within the Republic.$expl$, $choices$[{"id":"a","text":"New Caledonia"},{"id":"b","text":"The Bahamas"},{"id":"c","text":"The Maldives"},{"id":"d","text":"Borneo"}]$choices$),
  (403, 'tr', $text$Hangi ada Fransızdır?$text$, $expl$Yeni Kaledonya, Pasifik Okyanusu'nda yer alan bir Fransız bölgesidir. Cumhuriyet içinde özel statüye sahip bir Fransız kendine özgü (sui generis) topluluğudur.$expl$, $choices$[{"id":"a","text":"Yeni Kaledonya"},{"id":"b","text":"Bahamalar"},{"id":"c","text":"Maldivler"},{"id":"d","text":"Borneo"}]$choices$),
  (404, 'en', $text$What is the highest mountain in France?$text$, $expl$Mont Blanc, peaking at 4,809 metres, is the highest mountain in France and Western Europe. It is located in the Alps, on the border between France and Italy.$expl$, $choices$[{"id":"a","text":"Mont Blanc"},{"id":"b","text":"The Puy de Dôme"},{"id":"c","text":"The Pic du Midi"},{"id":"d","text":"Mont Ventoux"}]$choices$),
  (404, 'tr', $text$Fransa'nın en yüksek dağı hangisidir?$text$, $expl$4.809 metre zirvesi ile Mont Blanc, Fransa ve Batı Avrupa'nın en yüksek dağıdır. Fransa ile İtalya sınırında, Alpler'de yer alır.$expl$, $choices$[{"id":"a","text":"Mont Blanc"},{"id":"b","text":"Puy de Dôme"},{"id":"c","text":"Pic du Midi"},{"id":"d","text":"Mont Ventoux"}]$choices$),
  (405, 'en', $text$Which French island is located southeast of the African continent?$text$, $expl$Mayotte is a French island located in the Indian Ocean, southeast of the African continent. It became the 101st French department in 2011.$expl$, $choices$[{"id":"a","text":"Mayotte"},{"id":"b","text":"Martinique"},{"id":"c","text":"Guadeloupe"},{"id":"d","text":"Saint-Pierre and Miquelon"}]$choices$),
  (405, 'tr', $text$Hangi Fransız adası Afrika kıtasının güneydoğusundadır?$text$, $expl$Mayotte, Hint Okyanusu'nda Afrika kıtasının güneydoğusunda yer alan bir Fransız adasıdır. 2011'de 101. Fransız departmanı olmuştur.$expl$, $choices$[{"id":"a","text":"Mayotte"},{"id":"b","text":"Martinik"},{"id":"c","text":"Guadeloupe"},{"id":"d","text":"Saint-Pierre ve Miquelon"}]$choices$),
  (406, 'en', $text$Which French department has a border with Brazil?$text$, $expl$French Guiana is an overseas department located in South America, sharing a border with Brazil. It is the largest French department by area.$expl$, $choices$[{"id":"a","text":"French Guiana"},{"id":"b","text":"Martinique"},{"id":"c","text":"Réunion"},{"id":"d","text":"Mayotte"}]$choices$),
  (406, 'tr', $text$Hangi Fransız departmanı Brezilya ile sınır komşusudur?$text$, $expl$Fransız Guyanası, Güney Amerika'da yer alan ve Brezilya ile sınır paylaşan bir denizaşırı ildir. Yüzölçümü itibarıyla en büyük Fransız departmanıdır.$expl$, $choices$[{"id":"a","text":"Fransız Guyanası"},{"id":"b","text":"Martinik"},{"id":"c","text":"Réunion"},{"id":"d","text":"Mayotte"}]$choices$),
  (407, 'en', $text$From which French city does the Ariane rocket take off?$text$, $expl$The Ariane rocket takes off from Kourou, in French Guiana. The Guiana Space Centre has been the launch base of the European Space Agency (ESA) since 1968.$expl$, $choices$[{"id":"a","text":"Kourou"},{"id":"b","text":"Toulouse"},{"id":"c","text":"Bordeaux"},{"id":"d","text":"Marseille"}]$choices$),
  (407, 'tr', $text$Ariane roketi hangi Fransız şehrinden kalkar?$text$, $expl$Ariane roketi, Fransız Guyanası'nda Kourou'dan kalkar. Guyana Uzay Merkezi, 1968'den beri Avrupa Uzay Ajansı'nın (ESA) fırlatma üssüdür.$expl$, $choices$[{"id":"a","text":"Kourou"},{"id":"b","text":"Toulouse"},{"id":"c","text":"Bordeaux"},{"id":"d","text":"Marsilya"}]$choices$),
  (408, 'en', $text$What is the main seaport of France?$text$, $expl$Marseille is the main seaport of France and the leading port of the Mediterranean. The Grand Port Maritime of Marseille handles millions of tonnes of goods each year.$expl$, $choices$[{"id":"a","text":"Marseille"},{"id":"b","text":"Nantes"},{"id":"c","text":"Brest"},{"id":"d","text":"Bordeaux"}]$choices$),
  (408, 'tr', $text$Fransa'nın ana deniz limanı hangisidir?$text$, $expl$Marsilya, Fransa'nın ana deniz limanı ve Akdeniz'in önde gelen limanıdır. Marsilya Grand Port Maritime her yıl milyonlarca ton mal işler.$expl$, $choices$[{"id":"a","text":"Marsilya"},{"id":"b","text":"Nantes"},{"id":"c","text":"Brest"},{"id":"d","text":"Bordeaux"}]$choices$),
  (409, 'en', $text$What is the capital of the Auvergne-Rhône-Alpes region?$text$, $expl$Lyon is the capital of the Auvergne-Rhône-Alpes region. It is the third largest city in France and an important economic and cultural centre.$expl$, $choices$[{"id":"a","text":"Lyon"},{"id":"b","text":"Clermont-Ferrand"},{"id":"c","text":"Grenoble"},{"id":"d","text":"Saint-Étienne"}]$choices$),
  (409, 'tr', $text$Auvergne-Rhône-Alpes bölgesinin merkezi neresidir?$text$, $expl$Lyon, Auvergne-Rhône-Alpes bölgesinin merkezidir. Fransa'nın üçüncü büyük şehri ve önemli bir ekonomik ve kültürel merkezdir.$expl$, $choices$[{"id":"a","text":"Lyon"},{"id":"b","text":"Clermont-Ferrand"},{"id":"c","text":"Grenoble"},{"id":"d","text":"Saint-Étienne"}]$choices$),
  (410, 'en', $text$What is the capital of the Brittany region?$text$, $expl$Rennes is the capital of the Brittany region. It is a dynamic university city located in western France.$expl$, $choices$[{"id":"a","text":"Rennes"},{"id":"b","text":"Brest"},{"id":"c","text":"Nantes"},{"id":"d","text":"Quimper"}]$choices$),
  (410, 'tr', $text$Brittany bölgesinin merkezi neresidir?$text$, $expl$Rennes, Brittany bölgesinin merkezidir. Batı Fransa'da yer alan dinamik bir üniversite şehridir.$expl$, $choices$[{"id":"a","text":"Rennes"},{"id":"b","text":"Brest"},{"id":"c","text":"Nantes"},{"id":"d","text":"Quimper"}]$choices$),
  (411, 'en', $text$What is the capital of the Provence-Alpes-Côte d'Azur region?$text$, $expl$Marseille is the capital of the Provence-Alpes-Côte d'Azur region (PACA). It is the second largest city in France and a major Mediterranean port.$expl$, $choices$[{"id":"a","text":"Marseille"},{"id":"b","text":"Nice"},{"id":"c","text":"Toulon"},{"id":"d","text":"Aix-en-Provence"}]$choices$),
  (411, 'tr', $text$Provence-Alpes-Côte d'Azur bölgesinin merkezi neresidir?$text$, $expl$Marsilya, Provence-Alpes-Côte d'Azur (PACA) bölgesinin merkezidir. Fransa'nın ikinci büyük şehri ve Akdeniz'in önemli bir limanıdır.$expl$, $choices$[{"id":"a","text":"Marsilya"},{"id":"b","text":"Nice"},{"id":"c","text":"Toulon"},{"id":"d","text":"Aix-en-Provence"}]$choices$),
  (412, 'en', $text$What is the 101st French department since 2011?$text$, $expl$Mayotte became the 101st French department on 31 March 2011, following the 2009 referendum. It is the most recent overseas department to have joined the French Republic.$expl$, $choices$[{"id":"a","text":"Mayotte"},{"id":"b","text":"French Guiana"},{"id":"c","text":"New Caledonia"},{"id":"d","text":"Saint-Martin"}]$choices$),
  (412, 'tr', $text$2011'den beri 101. Fransız departmanı hangisidir?$text$, $expl$Mayotte, 2009 referandumunun ardından 31 Mart 2011'de 101. Fransız departmanı oldu. Fransız Cumhuriyeti'ne katılan en son denizaşırı departmandır.$expl$, $choices$[{"id":"a","text":"Mayotte"},{"id":"b","text":"Fransız Guyanası"},{"id":"c","text":"Yeni Kaledonya"},{"id":"d","text":"Saint-Martin"}]$choices$),
  (413, 'en', $text$Which French region is known for its ski resorts?$text$, $expl$The Auvergne-Rhône-Alpes region is the most renowned for its ski resorts in France. It is home to many famous Alpine resorts such as Chamonix, Les Deux Alpes and Val-d'Isère.$expl$, $choices$[{"id":"a","text":"Auvergne-Rhône-Alpes"},{"id":"b","text":"Île-de-France"},{"id":"c","text":"Nouvelle-Aquitaine"},{"id":"d","text":"Brittany"}]$choices$),
  (413, 'tr', $text$Hangi Fransız bölgesi kayak merkezleriyle ünlüdür?$text$, $expl$Auvergne-Rhône-Alpes bölgesi, kayak merkezleriyle Fransa'nın en ünlü bölgesidir. Chamonix, Les Deux Alpes ve Val-d'Isère gibi birçok ünlü Alp kayak merkezine ev sahipliği yapar.$expl$, $choices$[{"id":"a","text":"Auvergne-Rhône-Alpes"},{"id":"b","text":"Île-de-France"},{"id":"c","text":"Nouvelle-Aquitaine"},{"id":"d","text":"Brittany"}]$choices$),
  (567, 'en', $text$You have just arrived in France and your neighbour invites you to watch a military parade and fireworks on 14 July. What is celebrated on that day?$text$, $expl$14 July is the French national holiday. It commemorates the storming of the Bastille in 1789, a symbol of the end of royal absolutism and the beginning of the French Revolution. Military parades, popular dances and fireworks are organised throughout France.$expl$, $choices$[{"id":"a","text":"The national holiday, commemorating the storming of the Bastille"},{"id":"b","text":"The end of the Second World War"},{"id":"c","text":"The anniversary of the Constitution of the Fifth Republic"},{"id":"d","text":"Europe Day"}]$choices$),
  (567, 'tr', $text$Fransa'ya yeni geldiniz ve komşunuz sizi 14 Temmuz'da bir askeri geçit ve havai fişek gösterisi izlemeye davet ediyor. O gün ne kutlanır?$text$, $expl$14 Temmuz, Fransız ulusal bayramıdır. 1789'da Bastille'in ele geçirilmesini, kraliyet mutlakiyetçiliğinin sonunun ve Fransız Devrimi'nin başlangıcının sembolünü anar. Askeri geçit törenleri, halk balosu ve havai fişek gösterileri Fransa'nın her yerinde düzenlenir.$expl$, $choices$[{"id":"a","text":"Bastille'in ele geçirilişini anan ulusal bayram"},{"id":"b","text":"İkinci Dünya Savaşı'nın sonu"},{"id":"c","text":"Beşinci Cumhuriyet Anayasası'nın yıldönümü"},{"id":"d","text":"Avrupa Günü"}]$choices$),
  (568, 'en', $text$On 11 November, your employer tells you that the company is closed. Ceremonies take place in front of the war memorial in your commune. What does this day commemorate?$text$, $expl$11 November is a public holiday commemorating the 1918 armistice, marking the end of the First World War. Ceremonies are organised in front of war memorials to pay tribute to soldiers who fell in combat.$expl$, $choices$[{"id":"a","text":"The end of the Second World War"},{"id":"b","text":"International Day of Peace"},{"id":"c","text":"The armistice of the First World War"},{"id":"d","text":"National Day of Remembrance"}]$choices$),
  (568, 'tr', $text$11 Kasım'da işvereniniz şirketin kapalı olduğunu bildiriyor. Belediyenizin savaş anıtının önünde törenler yapılıyor. Bu gün neyi anar?$text$, $expl$11 Kasım, Birinci Dünya Savaşı'nın sonunu işaret eden 1918 ateşkesini anan bir resmi tatildir. Çatışmada düşen askerlere saygı duruşunda bulunmak için savaş anıtlarının önünde törenler düzenlenir.$expl$, $choices$[{"id":"a","text":"İkinci Dünya Savaşı'nın sonu"},{"id":"b","text":"Uluslararası Barış Günü"},{"id":"c","text":"Birinci Dünya Savaşı ateşkesi"},{"id":"d","text":"Ulusal Hatırlama Günü"}]$choices$),
  (569, 'en', $text$You pass in front of your town hall and notice a blue, white, red flag hanging on the façade. Your child asks you what it represents. What do you reply?$text$, $expl$The blue, white, red tricolour flag is the national emblem of France, enshrined in the Constitution. Blue and red represent the colours of Paris, and white the monarchy. It symbolises the values of the French Republic.$expl$, $choices$[{"id":"a","text":"It is the national flag of France, symbol of the Republic"},{"id":"b","text":"It is a decorative flag for the village festival"},{"id":"c","text":"It is the regional flag"},{"id":"d","text":"It is the flag of the European Union"}]$choices$),
  (569, 'tr', $text$Belediyenizin önünden geçerken cepheye asılı mavi, beyaz, kırmızı bir bayrak fark ediyorsunuz. Çocuğunuz size onun neyi temsil ettiğini soruyor. Ne cevap verirsiniz?$text$, $expl$Mavi, beyaz, kırmızı üç renkli bayrak, Anayasa'da yer alan Fransa'nın ulusal sembolüdür. Mavi ve kırmızı Paris'in renklerini, beyaz ise monarşiyi temsil eder. Fransız Cumhuriyeti'nin değerlerini simgeler.$expl$, $choices$[{"id":"a","text":"Cumhuriyet'in sembolü, Fransa'nın ulusal bayrağıdır"},{"id":"b","text":"Köy şenliği için dekoratif bir bayraktır"},{"id":"c","text":"Bölgenin bayrağıdır"},{"id":"d","text":"Avrupa Birliği'nin bayrağıdır"}]$choices$),
  (570, 'en', $text$On 8 May, you notice that shops are closed and that wreaths are laid at the foot of the war memorial. A neighbour invites you to the ceremony. What does 8 May commemorate?$text$, $expl$8 May 1945 marks the end of the Second World War in Europe, with the capitulation of Nazi Germany. This public holiday is an opportunity to pay tribute to all those who fought and suffered during this conflict.$expl$, $choices$[{"id":"a","text":"The 1945 victory and the end of the Second World War in Europe"},{"id":"b","text":"The signing of the Treaty of Rome"},{"id":"c","text":"Europe Day"},{"id":"d","text":"The anniversary of the Liberation of Paris"}]$choices$),
  (570, 'tr', $text$8 Mayıs'ta, mağazaların kapalı olduğunu ve savaş anıtının dibine çelenkler bırakıldığını görüyorsunuz. Bir komşu sizi törene davet ediyor. 8 Mayıs neyi anar?$text$, $expl$8 Mayıs 1945, Nazi Almanyası'nın teslim olmasıyla Avrupa'da İkinci Dünya Savaşı'nın sonunu işaret eder. Bu resmi tatil, bu çatışma sırasında savaşan ve acı çeken herkese saygı duruşunda bulunma fırsatıdır.$expl$, $choices$[{"id":"a","text":"1945 zaferi ve Avrupa'da İkinci Dünya Savaşı'nın sonu"},{"id":"b","text":"Roma Antlaşması'nın imzalanması"},{"id":"c","text":"Avrupa Günü"},{"id":"d","text":"Paris'in Kurtuluşu yıldönümü"}]$choices$),
  (571, 'en', $text$During an official ceremony at your town hall, everyone stands up when a hymn is played. You are told it is La Marseillaise. What is the status of this song?$text$, $expl$La Marseillaise is the national anthem of France, enshrined in the Constitution (article 2). Composed by Rouget de Lisle in 1792, it is played at official ceremonies, international sporting events and commemorations.$expl$, $choices$[{"id":"a","text":"It is a popular regional song"},{"id":"b","text":"It is a military song reserved for the army"},{"id":"c","text":"It is the anthem of the European Union"},{"id":"d","text":"It is the national anthem of France, enshrined in the Constitution"}]$choices$),
  (571, 'tr', $text$Belediyenizdeki resmi bir törende, bir marş çalındığında herkes ayağa kalkıyor. Size bunun La Marseillaise olduğu açıklanıyor. Bu şarkının statüsü nedir?$text$, $expl$La Marseillaise, Anayasa'da (2. madde) yer alan Fransa'nın ulusal marşıdır. 1792'de Rouget de Lisle tarafından bestelenmiş olup resmi törenlerde, uluslararası spor etkinliklerinde ve anma törenlerinde çalınır.$expl$, $choices$[{"id":"a","text":"Popüler bir bölgesel şarkıdır"},{"id":"b","text":"Orduya ayrılmış askeri bir şarkıdır"},{"id":"c","text":"Avrupa Birliği'nin marşıdır"},{"id":"d","text":"Anayasa'da yer alan Fransa'nın ulusal marşıdır"}]$choices$),
  (572, 'en', $text$You wish to visit a national museum in Paris but you have a limited budget. A friend tells you that on certain days entry is free. Which information is correct?$text$, $expl$National museums in France, such as the Louvre or the Musée d'Orsay, are free on the first Sunday of each month. In addition, entry is generally free for people under 26 residing in the European Union.$expl$, $choices$[{"id":"a","text":"National museums are free on the first Sunday of the month"},{"id":"b","text":"Museums are always paying, without exception"},{"id":"c","text":"Only French citizens can enter for free"},{"id":"d","text":"Museums are only free on 14 July"}]$choices$),
  (572, 'tr', $text$Paris'te bir ulusal müzeyi ziyaret etmek istiyorsunuz ancak bütçeniz sınırlı. Bir arkadaşınız bazı günler girişin ücretsiz olduğunu söylüyor. Hangi bilgi doğrudur?$text$, $expl$Louvre veya Musée d'Orsay gibi Fransa'daki ulusal müzeler her ayın ilk pazarı ücretsizdir. Ayrıca, Avrupa Birliği'nde ikamet eden 26 yaş altı kişiler için giriş genellikle ücretsizdir.$expl$, $choices$[{"id":"a","text":"Ulusal müzeler ayın ilk pazarı ücretsizdir"},{"id":"b","text":"Müzeler istisnasız her zaman ücretlidir"},{"id":"c","text":"Sadece Fransız vatandaşları ücretsiz girebilir"},{"id":"d","text":"Müzeler yalnızca 14 Temmuz'da ücretsizdir"}]$choices$),
  (573, 'en', $text$You visit Mont-Saint-Michel with friends and you see a sign indicating that it is a UNESCO World Heritage Site. What does this distinction mean?$text$, $expl$The UNESCO World Heritage classification recognises the outstanding universal value of a cultural or natural site. France has more than 50 listed sites. This distinction implies enhanced protection and preservation of the site.$expl$, $choices$[{"id":"a","text":"The site is recognised for its outstanding universal value and benefits from special protection"},{"id":"b","text":"The site belongs to the United Nations Organization"},{"id":"c","text":"The site is reserved for foreign tourists"},{"id":"d","text":"The site is closed to the public for preservation"}]$choices$),
  (573, 'tr', $text$Arkadaşlarınızla Mont-Saint-Michel'i ziyaret ediyorsunuz ve buranın UNESCO Dünya Mirası Listesi'nde olduğunu belirten bir tabela görüyorsunuz. Bu ayrım ne anlama gelir?$text$, $expl$UNESCO Dünya Mirası sınıflandırması, kültürel veya doğal bir alanın olağanüstü evrensel değerini tanır. Fransa'nın listede 50'den fazla alanı bulunmaktadır. Bu ayrım, alanın güçlendirilmiş korunması ve muhafazasını ima eder.$expl$, $choices$[{"id":"a","text":"Alan, olağanüstü evrensel değeri için tanınır ve özel koruma altındadır"},{"id":"b","text":"Alan, Birleşmiş Milletler Örgütü'ne aittir"},{"id":"c","text":"Alan, yabancı turistlere ayrılmıştır"},{"id":"d","text":"Alan, korunması için halka kapalıdır"}]$choices$),
  (574, 'en', $text$You are invited to dinner at French neighbours who offer you a typical meal with starter, main course, cheese and dessert. Which statement is true about French gastronomy?$text$, $expl$The gastronomic meal of the French has been on the UNESCO intangible cultural heritage list since 2010. The tradition of the structured meal (aperitif, starter, main course, cheese, dessert) is an important element of culture and social bond in France.$expl$, $choices$[{"id":"a","text":"French gastronomy has no international recognition"},{"id":"b","text":"French cuisine is solely a Parisian tradition"},{"id":"c","text":"The traditional French meal consists of only one dish"},{"id":"d","text":"The gastronomic meal of the French is on the UNESCO intangible heritage list"}]$choices$),
  (574, 'tr', $text$Fransız komşulara akşam yemeğine davet edilirsiniz; size ön yemek, ana yemek, peynir ve tatlıdan oluşan tipik bir öğün sunarlar. Fransız gastronomisi hakkında hangi ifade doğrudur?$text$, $expl$Fransız gastronomik öğünü, 2010'dan beri UNESCO somut olmayan kültürel mirası listesindedir. Yapılandırılmış öğün geleneği (aperatif, ön yemek, ana yemek, peynir, tatlı) Fransa'da kültürün ve sosyal bağın önemli bir unsurudur.$expl$, $choices$[{"id":"a","text":"Fransız gastronomisinin hiçbir uluslararası tanınırlığı yoktur"},{"id":"b","text":"Fransız mutfağı sadece Parisli bir gelenektir"},{"id":"c","text":"Geleneksel Fransız öğünü yalnızca tek bir yemekten oluşur"},{"id":"d","text":"Fransız gastronomik öğünü UNESCO somut olmayan kültürel mirası listesindedir"}]$choices$),
  (575, 'en', $text$In September, you see posters announcing the European Heritage Days. Buildings usually closed to the public open their doors. What is this about?$text$, $expl$The European Heritage Days take place every year in September. They allow the free visit of places usually closed to the public: ministries, palaces, historical buildings. It is a major cultural event in France and Europe.$expl$, $choices$[{"id":"a","text":"A commercial event to sell regional products"},{"id":"b","text":"A European religious festival"},{"id":"c","text":"An annual event allowing free visits of heritage places usually closed"},{"id":"d","text":"A renovation day for public buildings"}]$choices$),
  (575, 'tr', $text$Eylül'de Avrupa Miras Günleri'ni duyuran afişler görürsünüz. Genellikle halka kapalı olan binalar kapılarını açar. Bu nedir?$text$, $expl$Avrupa Miras Günleri her yıl eylül ayında gerçekleşir. Genellikle halka kapalı yerlerin (bakanlıklar, saraylar, tarihi binalar) ücretsiz ziyaret edilmesini sağlar. Bu, Fransa ve Avrupa'da önemli bir kültürel etkinliktir.$expl$, $choices$[{"id":"a","text":"Bölgesel ürünlerin satıldığı ticari bir etkinlik"},{"id":"b","text":"Bir Avrupa dini bayramı"},{"id":"c","text":"Genellikle kapalı olan miras yerlerinin ücretsiz ziyaret edilmesini sağlayan yıllık bir etkinlik"},{"id":"d","text":"Kamu binaları için bir yenileme günü"}]$choices$),
  (576, 'en', $text$Your child comes back from school telling you about a school trip organised to the museum and a music education class. Why does the French school include these cultural activities?$text$, $expl$Artistic and cultural education is a fundamental mission of school in France. It aims to allow all pupils, whatever their social background, to access culture and develop their artistic sensibility. It is a pillar of republican equality.$expl$, $choices$[{"id":"a","text":"Artistic and cultural education is a school mission to guarantee everyone's access to culture"},{"id":"b","text":"It is solely to entertain children"},{"id":"c","text":"It is a paying activity reserved for wealthy families"},{"id":"d","text":"These activities are optional and depend on the teacher's goodwill"}]$choices$),
  (576, 'tr', $text$Çocuğunuz okuldan dönerek müzeye düzenlenen bir okul gezisinden ve müzik eğitimi dersinden bahsediyor. Fransız okulu neden bu kültürel etkinlikleri içerir?$text$, $expl$Sanatsal ve kültürel eğitim, Fransa'da okulun temel bir görevidir. Sosyal kökenleri ne olursa olsun tüm öğrencilerin kültüre erişmesini ve sanatsal duyarlılıklarını geliştirmesini sağlamayı amaçlar. Cumhuriyetçi eşitliğin bir temel taşıdır.$expl$, $choices$[{"id":"a","text":"Sanatsal ve kültürel eğitim, herkesin kültüre erişimini güvence altına almak için bir okul görevidir"},{"id":"b","text":"Sadece çocukları eğlendirmek içindir"},{"id":"c","text":"Varlıklı ailelere ayrılmış ücretli bir etkinliktir"},{"id":"d","text":"Bu etkinlikler isteğe bağlıdır ve öğretmenin iradesine bağlıdır"}]$choices$),
  (577, 'en', $text$You are looking for a job and you check offers in different regions of France. How many metropolitan regions does France have since the 2015 reform?$text$, $expl$Since the 2015 territorial reform, mainland France has 13 regions (instead of 22 previously). The regions are led by an elected regional council. They notably manage regional transport, high schools and economic development.$expl$, $choices$[{"id":"a","text":"22 regions"},{"id":"b","text":"13 regions"},{"id":"c","text":"18 regions"},{"id":"d","text":"26 regions"}]$choices$),
  (577, 'tr', $text$Bir iş arıyorsunuz ve Fransa'nın farklı bölgelerindeki teklifleri inceliyorsunuz. 2015 reformundan bu yana Fransa'nın kaç metropolitan bölgesi vardır?$text$, $expl$2015 toprak reformundan bu yana, metropolitan Fransa'nın 13 bölgesi vardır (önceden 22 idi). Bölgeler seçilen bir bölge konseyi tarafından yönetilir. Özellikle bölgesel taşımacılık, liseler ve ekonomik kalkınma ile ilgilenirler.$expl$, $choices$[{"id":"a","text":"22 bölge"},{"id":"b","text":"13 bölge"},{"id":"c","text":"18 bölge"},{"id":"d","text":"26 bölge"}]$choices$),
  (578, 'en', $text$A colleague originally from Guadeloupe explains to you that he is French. You are surprised because Guadeloupe is far from mainland France. What is the legal situation of overseas territories?$text$, $expl$Overseas departments and regions (DROM) such as Guadeloupe, Martinique, French Guiana, Réunion and Mayotte are an integral part of the French Republic. Their inhabitants are full French citizens, with the same rights and duties.$expl$, $choices$[{"id":"a","text":"They are independent countries allied with France"},{"id":"b","text":"Their inhabitants are not French citizens"},{"id":"c","text":"They are territories of the French Republic whose inhabitants are French citizens"},{"id":"d","text":"They are colonies without political rights"}]$choices$),
  (578, 'tr', $text$Guadeloupe'tan gelen bir meslektaşınız size Fransız olduğunu açıklıyor. Guadeloupe'un anavatandan uzak olması sizi şaşırtıyor. Denizaşırı bölgelerin yasal durumu nedir?$text$, $expl$Guadeloupe, Martinik, Fransız Guyanası, Réunion ve Mayotte gibi denizaşırı il ve bölgeler (DROM), Fransız Cumhuriyeti'nin ayrılmaz bir parçasıdır. Sakinleri aynı haklara ve görevlere sahip tam Fransız vatandaşlarıdır.$expl$, $choices$[{"id":"a","text":"Fransa ile müttefik bağımsız ülkelerdir"},{"id":"b","text":"Sakinleri Fransız vatandaşı değildir"},{"id":"c","text":"Sakinleri Fransız vatandaşı olan Fransız Cumhuriyeti topraklarıdır"},{"id":"d","text":"Siyasi hakları olmayan sömürgelerdir"}]$choices$),
  (579, 'en', $text$You wish to travel to Spain for the holidays. A friend tells you that you do not need a passport if you have a French residence permit. Why is this possible?$text$, $expl$France is a member of the European Union and the Schengen area, which allows the free circulation of people between member countries without internal border controls. A valid French residence permit allows you to travel in the Schengen area.$expl$, $choices$[{"id":"a","text":"Spain and France have a special bilateral agreement"},{"id":"b","text":"Thanks to the Schengen area which allows free circulation between member countries"},{"id":"c","text":"There is never any border control in Europe"},{"id":"d","text":"It is not true, a passport is always compulsory"}]$choices$),
  (579, 'tr', $text$Tatil için İspanya'ya seyahat etmek istiyorsunuz. Bir arkadaşınız size Fransız oturma izniniz varsa pasaport gerekmediğini söylüyor. Bu neden mümkündür?$text$, $expl$Fransa, üye ülkeler arasında iç sınır kontrolü olmadan kişilerin serbest dolaşımına izin veren Avrupa Birliği ve Schengen alanı üyesidir. Geçerli bir Fransız oturma izni Schengen alanında seyahat etmenize olanak tanır.$expl$, $choices$[{"id":"a","text":"İspanya ve Fransa'nın özel ikili bir anlaşması var"},{"id":"b","text":"Üye ülkeler arasında serbest dolaşıma izin veren Schengen alanı sayesinde"},{"id":"c","text":"Avrupa'da hiçbir zaman sınır kontrolü yoktur"},{"id":"d","text":"Doğru değil, pasaport her zaman zorunludur"}]$choices$),
  (580, 'en', $text$You have just arrived in France and you have to change your money. What is the currency used in France and since when?$text$, $expl$France has used the euro (€) as its currency since 1 January 2002 (introduction of coins and banknotes). The euro is the common currency of the eurozone, which includes 20 European Union countries. It replaced the French franc.$expl$, $choices$[{"id":"a","text":"The French franc, since forever"},{"id":"b","text":"The European dollar, since 2010"},{"id":"c","text":"The euro, in circulation since 2002"},{"id":"d","text":"The pound, since Brexit"}]$choices$),
  (580, 'tr', $text$Fransa'ya yeni geldiniz ve paranızı değiştirmeniz gerekiyor. Fransa'da kullanılan para birimi nedir ve ne zamandan beri?$text$, $expl$Fransa, 1 Ocak 2002'den beri (madeni paraların ve banknotların dolaşıma sokulması) para birimi olarak euro (€) kullanmaktadır. Euro, Avrupa Birliği'nin 20 ülkesini içeren euro bölgesinin ortak para birimidir. Fransız frangının yerini almıştır.$expl$, $choices$[{"id":"a","text":"Fransız frangı, her zamandan beri"},{"id":"b","text":"Avrupa doları, 2010'dan beri"},{"id":"c","text":"Euro, 2002'den beri dolaşımda"},{"id":"d","text":"Sterlin, Brexit'ten beri"}]$choices$),
  (581, 'en', $text$You receive an official letter that mentions your commune and your department. You do not understand the difference between these two administrative levels. Which explanation is correct?$text$, $expl$France is organised into three levels of territorial authorities: the commune (managed by the mayor), the department (managed by the departmental council) and the region (managed by the regional council). The commune is the level closest to citizens.$expl$, $choices$[{"id":"a","text":"The commune and the department are the same thing"},{"id":"b","text":"The department is a grouping of several communes, it is a higher administrative level"},{"id":"c","text":"The department no longer exists since the 2015 reform"},{"id":"d","text":"The commune is larger than the department"}]$choices$),
  (581, 'tr', $text$Belediyenizi ve departmanınızı belirten resmi bir yazı alıyorsunuz. Bu iki yönetim seviyesi arasındaki farkı anlamıyorsunuz. Hangi açıklama doğrudur?$text$, $expl$Fransa, üç seviyeli yerel yönetim olarak örgütlenmiştir: belediye (belediye başkanı tarafından yönetilir), departman (departman konseyi tarafından yönetilir) ve bölge (bölge konseyi tarafından yönetilir). Belediye, vatandaşlara en yakın seviyedir.$expl$, $choices$[{"id":"a","text":"Belediye ve departman aynı şeydir"},{"id":"b","text":"Departman birkaç belediyenin bir araya gelmesidir, daha üst bir yönetim seviyesidir"},{"id":"c","text":"Departman 2015 reformundan beri artık yoktur"},{"id":"d","text":"Belediye, departmandan daha büyüktür"}]$choices$)
INSERT INTO question_translations (question_id, lang, text, explanation, choices) VALUES
(414, 'en', $text$Which emergency number is used to call the SAMU (medical emergencies)?$text$, $expl$15 is the emergency number for the SAMU (Service d'Aide Médicale Urgente, the emergency medical service). It connects you to a regulating doctor who assesses the situation and dispatches the appropriate help.$expl$, $choices$[{"id":"a","text":"15"},{"id":"b","text":"17"},{"id":"c","text":"18"},{"id":"d","text":"112"}]$choices$),
(414, 'tr', $text$SAMU'yu (tıbbi acil durumlar) aramak için hangi acil numarası kullanılır?$text$, $expl$15, SAMU'nun (Service d'Aide Médicale Urgente, acil tıbbi yardım servisi) acil numarasıdır. Durumu değerlendiren ve uygun yardımı gönderen bir düzenleyici doktora ulaşmayı sağlar.$expl$, $choices$[{"id":"a","text":"15"},{"id":"b","text":"17"},{"id":"c","text":"18"},{"id":"d","text":"112"}]$choices$),
(415, 'en', $text$Which emergency number is used to call the Pompiers (fire brigade)?$text$, $expl$18 is the number for the Pompiers (sapeurs-pompiers, fire brigade). It is used to report a fire, an accident, or any situation requiring an emergency response.$expl$, $choices$[{"id":"a","text":"18"},{"id":"b","text":"15"},{"id":"c","text":"17"},{"id":"d","text":"114"}]$choices$),
(415, 'tr', $text$Pompiers'yi (itfaiye) aramak için hangi acil numarası kullanılır?$text$, $expl$18, Pompiers'in (sapeurs-pompiers, itfaiye) numarasıdır. Yangın, kaza veya acil müdahale gerektiren herhangi bir durumu bildirmek için kullanılır.$expl$, $choices$[{"id":"a","text":"18"},{"id":"b","text":"15"},{"id":"c","text":"17"},{"id":"d","text":"114"}]$choices$),
(416, 'en', $text$After obtaining a driving licence, what must be done to be able to drive one's car?$text$, $expl$To drive legally, you must insure your vehicle with an insurance company. Car insurance is mandatory in France to cover damage caused to third parties.$expl$, $choices$[{"id":"a","text":"Insure the vehicle with an insurance company"},{"id":"b","text":"Register at the prefecture of police"},{"id":"c","text":"Undergo a mandatory medical examination"},{"id":"d","text":"Obtain a special authorization from the mairie (town hall)"}]$choices$),
(416, 'tr', $text$Sürücü belgesi aldıktan sonra arabayı kullanabilmek için ne yapılmalıdır?$text$, $expl$Yasal olarak araç kullanabilmek için aracı bir sigorta şirketine sigortalatmak gereklidir. Fransa'da araç sigortası, üçüncü şahıslara verilen zararları karşılamak için zorunludur.$expl$, $choices$[{"id":"a","text":"Aracı bir sigorta şirketine sigortalatmak"},{"id":"b","text":"Polis valiliğine kayıt yaptırmak"},{"id":"c","text":"Zorunlu sağlık muayenesinden geçmek"},{"id":"d","text":"Belediyeden (mairie) özel izin almak"}]$choices$),
(417, 'en', $text$Under what conditions is a marriage legally recognized?$text$, $expl$In France, only civil marriage celebrated at the mairie (town hall) is legally recognized. A religious marriage has no legal value if it is not preceded by a civil marriage.$expl$, $choices$[{"id":"a","text":"If it is celebrated at the mairie (town hall, civil marriage)"},{"id":"b","text":"If it is celebrated in a place of worship"},{"id":"c","text":"If it is recognized by the spouses' families"},{"id":"d","text":"If it is organized by a notary"}]$choices$),
(417, 'tr', $text$Bir evlilik hangi koşullarda hukuken tanınır?$text$, $expl$Fransa'da yalnızca belediyede (mairie) yapılan medeni nikâh hukuken tanınır. Dini nikâh, medeni nikâhtan önce gelmediği sürece hiçbir yasal değere sahip değildir.$expl$, $choices$[{"id":"a","text":"Belediyede (mairie) yapılırsa (medeni nikâh)"},{"id":"b","text":"Bir ibadethanede yapılırsa"},{"id":"c","text":"Eşlerin aileleri tarafından tanınırsa"},{"id":"d","text":"Bir noter tarafından düzenlenirse"}]$choices$),
(418, 'en', $text$When must a child be declared to the civil registry service of the mairie (town hall)?$text$, $expl$The birth declaration must be made within 5 days following the birth, at the mairie (town hall) of the place of birth. This deadline is set by law.$expl$, $choices$[{"id":"a","text":"Within 5 days following the birth"},{"id":"b","text":"Within 30 days following the birth"},{"id":"c","text":"Within 3 months following the birth"},{"id":"d","text":"Before leaving the hospital"}]$choices$),
(418, 'tr', $text$Bir çocuk belediyenin (mairie) nüfus müdürlüğüne ne zaman bildirilmelidir?$text$, $expl$Doğum bildirimi, doğum yerinin belediyesine (mairie) doğumu takip eden 5 gün içinde yapılmalıdır. Bu süre yasayla belirlenmiştir.$expl$, $choices$[{"id":"a","text":"Doğumu takip eden 5 gün içinde"},{"id":"b","text":"Doğumu takip eden 30 gün içinde"},{"id":"c","text":"Doğumu takip eden 3 ay içinde"},{"id":"d","text":"Hastaneden çıkmadan önce"}]$choices$),
(419, 'en', $text$Undeclared work is:$text$, $expl$Undeclared work (travail au noir) is prohibited by law. It deprives the employee of social protection and exposes both employer and employee to criminal and financial penalties.$expl$, $choices$[{"id":"a","text":"Prohibited by law"},{"id":"b","text":"Permitted for small jobs"},{"id":"c","text":"Tolerated if the employee agrees"},{"id":"d","text":"Permitted for foreign workers"}]$choices$),
(419, 'tr', $text$Kayıt dışı çalışma:$text$, $expl$Kayıt dışı çalışma (travail au noir) yasayla yasaklanmıştır. Çalışanı sosyal güvenceden mahrum bırakır ve hem işvereni hem de çalışanı cezai ve mali yaptırımlara maruz bırakır.$expl$, $choices$[{"id":"a","text":"Yasayla yasaklanmıştır"},{"id":"b","text":"Küçük işler için izin verilmiştir"},{"id":"c","text":"Çalışan kabul ederse tolere edilir"},{"id":"d","text":"Yabancı işçiler için izin verilmiştir"}]$choices$),
(420, 'en', $text$What must an employer do to set a salary?$text$, $expl$The employer must respect the SMIC (Salaire Minimum Interprofessionnel de Croissance, the statutory minimum wage) and the applicable collective agreements. They cannot set a salary lower than the legal minimum.$expl$, $choices$[{"id":"a","text":"Respect at minimum the SMIC (statutory minimum wage) and the applicable collective agreement"},{"id":"b","text":"Freely set the amount without any constraint"},{"id":"c","text":"Request authorization from the mairie (town hall)"},{"id":"d","text":"Consult other employers in the neighborhood"}]$choices$),
(420, 'tr', $text$Bir işveren bir maaş belirlemek için ne yapmalıdır?$text$, $expl$İşveren, SMIC'e (Salaire Minimum Interprofessionnel de Croissance, yasal asgari ücret) ve geçerli toplu iş sözleşmelerine uymak zorundadır. Yasal asgari ücretin altında bir maaş belirleyemez.$expl$, $choices$[{"id":"a","text":"En azından SMIC'e (yasal asgari ücret) ve geçerli toplu iş sözleşmesine uymak"},{"id":"b","text":"Hiçbir kısıtlama olmaksızın tutarı serbestçe belirlemek"},{"id":"c","text":"Belediyeden (mairie) izin istemek"},{"id":"d","text":"Mahallenin diğer işverenlerine danışmak"}]$choices$),
(421, 'en', $text$What is the SMIC (statutory minimum wage)?$text$, $expl$The SMIC is the Salaire Minimum Interprofessionnel de Croissance. It is the legal minimum hourly wage below which no employee can be paid in France.$expl$, $choices$[{"id":"a","text":"The legal minimum wage below which an employee cannot be paid"},{"id":"b","text":"The average salary of French people"},{"id":"c","text":"Financial aid paid by the State to the unemployed"},{"id":"d","text":"The maximum salary authorized by law"}]$choices$),
(421, 'tr', $text$SMIC (yasal asgari ücret) nedir?$text$, $expl$SMIC, Salaire Minimum Interprofessionnel de Croissance'tır. Fransa'da hiçbir çalışana altında ücret ödenemeyecek yasal asgari saatlik ücrettir.$expl$, $choices$[{"id":"a","text":"Bir çalışanın altında ücret alamayacağı yasal asgari ücret"},{"id":"b","text":"Fransızların ortalama maaşı"},{"id":"c","text":"Devlet tarafından işsizlere ödenen mali yardım"},{"id":"d","text":"Yasayla izin verilen azami maaş"}]$choices$),
(422, 'en', $text$What is the first step to take when looking for a job?$text$, $expl$The first step to look for a job is to register with France Travail (formerly Pôle emploi). This agency supports jobseekers in their search and can pay them benefits.$expl$, $choices$[{"id":"a","text":"Register with France Travail (formerly Pôle emploi, the public employment agency)"},{"id":"b","text":"Write directly to the President of the Republic"},{"id":"c","text":"Register at the mairie (town hall) of one's residence"},{"id":"d","text":"Publish an advertisement in a newspaper"}]$choices$),
(422, 'tr', $text$İş aramaya başlamak için yapılacak ilk adım nedir?$text$, $expl$İş aramak için ilk adım France Travail'a (eski adıyla Pôle emploi) kayıt olmaktır. Bu kurum, iş arayanlara aramalarında destek sağlar ve onlara işsizlik yardımı ödeyebilir.$expl$, $choices$[{"id":"a","text":"France Travail'a (eski adıyla Pôle emploi, kamu istihdam ajansı) kayıt olmak"},{"id":"b","text":"Doğrudan Cumhurbaşkanı'na yazmak"},{"id":"c","text":"İkamet edilen belediyeye (mairie) kayıt olmak"},{"id":"d","text":"Bir gazeteye ilan vermek"}]$choices$),
(423, 'en', $text$What is the legal weekly working time?$text$, $expl$The legal working time in France is 35 hours per week. Beyond that, overtime hours entitle the employee to a salary increase or compensatory rest.$expl$, $choices$[{"id":"a","text":"35 hours"},{"id":"b","text":"39 hours"},{"id":"c","text":"40 hours"},{"id":"d","text":"32 hours"}]$choices$),
(423, 'tr', $text$Yasal haftalık çalışma süresi nedir?$text$, $expl$Fransa'da yasal çalışma süresi haftada 35 saattir. Bunun ötesinde, fazla mesai saatleri ücret artışı veya telafi izni hakkı doğurur.$expl$, $choices$[{"id":"a","text":"35 saat"},{"id":"b","text":"39 saat"},{"id":"c","text":"40 saat"},{"id":"d","text":"32 saat"}]$choices$),
(424, 'en', $text$Who is assisted by France Travail (formerly Pôle emploi, the public employment agency)?$text$, $expl$France Travail (formerly Pôle emploi) helps people looking for a job. It offers personalized support, training, and the payment of unemployment benefits.$expl$, $choices$[{"id":"a","text":"People looking for a job"},{"id":"b","text":"Retired people only"},{"id":"c","text":"Employers exclusively"},{"id":"d","text":"Students in initial training"}]$choices$),
(424, 'tr', $text$France Travail (eski adıyla Pôle emploi, kamu istihdam ajansı) kime yardım eder?$text$, $expl$France Travail (eski adıyla Pôle emploi) iş arayanlara yardım eder. Kişiselleştirilmiş destek, eğitim ve işsizlik yardımı ödemesi sunar.$expl$, $choices$[{"id":"a","text":"İş arayan kişilere"},{"id":"b","text":"Yalnızca emeklilere"},{"id":"c","text":"Yalnızca işverenlere"},{"id":"d","text":"İlk eğitimdeki öğrencilere"}]$choices$),
(425, 'en', $text$A foreign person legally residing in France can create their business:$text$, $expl$In France, a foreign person legally residing has the right to create their business, just like any French citizen. There is no nationality restriction for entrepreneurship if the titre de séjour (residence permit) allows it.$expl$, $choices$[{"id":"a","text":"Yes, like any other person"},{"id":"b","text":"No, only French citizens can"},{"id":"c","text":"Only with special authorization from the prefect"},{"id":"d","text":"Only after 10 years of residence in France"}]$choices$),
(425, 'tr', $text$Yasal olarak ikamet eden yabancı bir kişi kendi işini kurabilir mi?$text$, $expl$Fransa'da yasal olarak ikamet eden yabancı bir kişi, herhangi bir Fransız vatandaşı gibi kendi işini kurma hakkına sahiptir. Titre de séjour (oturma izni) izin veriyorsa, girişimcilik için hiçbir uyrukluk kısıtlaması yoktur.$expl$, $choices$[{"id":"a","text":"Evet, her insan gibi"},{"id":"b","text":"Hayır, yalnızca Fransızlar kurabilir"},{"id":"c","text":"Yalnızca valinin özel izniyle"},{"id":"d","text":"Yalnızca Fransa'da 10 yıl ikametten sonra"}]$choices$),
(426, 'en', $text$Can a woman create her own business?$text$, $expl$Yes, a woman can create her own business in France. Equality between women and men is a fundamental principle of the Republic, including in the economic and professional sphere.$expl$, $choices$[{"id":"a","text":"Yes, on the same conditions as a man"},{"id":"b","text":"No, she must obtain her husband's consent"},{"id":"c","text":"Only in certain sectors of activity"},{"id":"d","text":"Only if she has French nationality"}]$choices$),
(426, 'tr', $text$Bir kadın kendi işini kurabilir mi?$text$, $expl$Evet, bir kadın Fransa'da kendi işini kurabilir. Kadın-erkek eşitliği, ekonomik ve mesleki alan dahil, Cumhuriyet'in temel ilkelerinden biridir.$expl$, $choices$[{"id":"a","text":"Evet, bir erkekle aynı koşullarda"},{"id":"b","text":"Hayır, kocasının rızasını almak zorundadır"},{"id":"c","text":"Yalnızca belirli faaliyet sektörlerinde"},{"id":"d","text":"Yalnızca Fransız uyruğuna sahipse"}]$choices$),
(427, 'en', $text$From what age can a minor work?$text$, $expl$In France, a minor can work from the age of 16, with parental authorization. Exceptions exist for apprenticeships from age 15 under certain conditions.$expl$, $choices$[{"id":"a","text":"16 years old"},{"id":"b","text":"14 years old"},{"id":"c","text":"18 years old"},{"id":"d","text":"12 years old"}]$choices$),
(427, 'tr', $text$Bir çocuk hangi yaştan itibaren çalışabilir?$text$, $expl$Fransa'da bir çocuk, ebeveyn izniyle 16 yaşından itibaren çalışabilir. Belirli koşullar altında 15 yaşından itibaren çıraklık için istisnalar vardır.$expl$, $choices$[{"id":"a","text":"16 yaş"},{"id":"b","text":"14 yaş"},{"id":"c","text":"18 yaş"},{"id":"d","text":"12 yaş"}]$choices$),
(428, 'en', $text$Which body should be asked for the reimbursement of healthcare costs?$text$, $expl$It is from the Sécurité sociale (Assurance maladie / CPAM) that you must request the reimbursement of healthcare costs. It covers part of the medical expenses.$expl$, $choices$[{"id":"a","text":"The Sécurité sociale (the French social security system / Assurance maladie, public health insurance)"},{"id":"b","text":"The mairie (town hall)"},{"id":"c","text":"France Travail (formerly Pôle emploi)"},{"id":"d","text":"The Banque de France"}]$choices$),
(428, 'tr', $text$Sağlık masraflarının geri ödenmesi için hangi kuruma başvurulmalıdır?$text$, $expl$Sağlık masraflarının geri ödenmesini talep etmek için Sécurité sociale'a (Assurance maladie / CPAM) başvurulmalıdır. Tıbbi masrafların bir kısmını karşılar.$expl$, $choices$[{"id":"a","text":"Sécurité sociale (Fransız sosyal güvenlik sistemi / Assurance maladie, kamu sağlık sigortası)"},{"id":"b","text":"Belediye (mairie)"},{"id":"c","text":"France Travail (eski adıyla Pôle emploi)"},{"id":"d","text":"Banque de France"}]$choices$),
(429, 'en', $text$What is an emergency number?$text$, $expl$An emergency number is a free telephone number, accessible 24 hours a day, which makes it possible to reach the emergency services (SAMU, Pompiers, police) in an emergency situation.$expl$, $choices$[{"id":"a","text":"A free number to reach emergency services at any time"},{"id":"b","text":"A paid number reserved for doctors"},{"id":"c","text":"A number available only during daytime"},{"id":"d","text":"A number to contact your supplementary health insurance"}]$choices$),
(429, 'tr', $text$Acil numara nedir?$text$, $expl$Acil numara, 7/24 erişilebilen, acil bir durumda acil servislere (SAMU, Pompiers, polis) ulaşmayı sağlayan ücretsiz bir telefon numarasıdır.$expl$, $choices$[{"id":"a","text":"Acil servislere her zaman ulaşmayı sağlayan ücretsiz bir numara"},{"id":"b","text":"Yalnızca doktorlara ayrılmış ücretli bir numara"},{"id":"c","text":"Yalnızca gündüz erişilebilen bir numara"},{"id":"d","text":"Tamamlayıcı sağlık sigortasına ulaşmak için bir numara"}]$choices$),
(430, 'en', $text$Regarding access to healthcare, which statement is correct?$text$, $expl$In France, everyone has the right to be cared for, regardless of nationality or financial situation. Access to healthcare is a fundamental right guaranteed by law.$expl$, $choices$[{"id":"a","text":"Every person has the right to be cared for"},{"id":"b","text":"Only French citizens have access to healthcare"},{"id":"c","text":"Access to healthcare depends on income level"},{"id":"d","text":"A prefectoral authorization is required to consult a doctor"}]$choices$),
(430, 'tr', $text$Sağlık hizmetlerine erişim konusunda hangi ifade doğrudur?$text$, $expl$Fransa'da uyruğu veya mali durumu ne olursa olsun herkesin tedavi görme hakkı vardır. Sağlık hizmetlerine erişim yasayla güvence altına alınmış temel bir haktır.$expl$, $choices$[{"id":"a","text":"Herkesin tedavi görme hakkı vardır"},{"id":"b","text":"Yalnızca Fransız vatandaşlarının sağlık hizmetlerine erişimi vardır"},{"id":"c","text":"Sağlık hizmetlerine erişim gelir düzeyine bağlıdır"},{"id":"d","text":"Bir doktora başvurmak için valilik izni gereklidir"}]$choices$),
(431, 'en', $text$For a non-urgent health problem, who should be consulted first?$text$, $expl$For a non-urgent health problem, you should first consult your médecin traitant (referring doctor). They coordinate care and refer you to a specialist if necessary. This avoids overcrowding hospital emergency departments.$expl$, $choices$[{"id":"a","text":"One's médecin traitant (general practitioner / referring doctor)"},{"id":"b","text":"The hospital emergency department"},{"id":"c","text":"The pharmacy"},{"id":"d","text":"The SAMU by calling 15"}]$choices$),
(431, 'tr', $text$Acil olmayan bir sağlık sorunu durumunda önce kime başvurulmalıdır?$text$, $expl$Acil olmayan bir sağlık sorunu durumunda önce aile hekiminize (médecin traitant) başvurmanız gerekir. Tedaviyi koordine eder ve gerekirse sizi bir uzmana yönlendirir. Bu, hastane acil servislerinin yoğunluğunu önler.$expl$, $choices$[{"id":"a","text":"Aile hekimine (médecin traitant)"},{"id":"b","text":"Hastanenin acil servisine"},{"id":"c","text":"Eczaneye"},{"id":"d","text":"15'i arayarak SAMU'ya"}]$choices$),
(432, 'en', $text$What is the role of the médecin traitant (referring doctor)?$text$, $expl$The médecin traitant (referring doctor) ensures the overall medical follow-up of the patient. They coordinate care, refer to specialists if needed, and keep the medical record up to date. They are the first point of contact for health matters.$expl$, $choices$[{"id":"a","text":"To ensure medical follow-up and coordinate the patient's care"},{"id":"b","text":"To prescribe only generic medicines"},{"id":"c","text":"To manage hospital emergencies"},{"id":"d","text":"To reimburse healthcare costs"}]$choices$),
(432, 'tr', $text$Aile hekiminin (médecin traitant) rolü nedir?$text$, $expl$Aile hekimi (médecin traitant) hastanın genel tıbbi takibini sağlar. Tedaviyi koordine eder, gerekirse uzmanlara yönlendirir ve tıbbi dosyayı günceller. Sağlık sorunları için ilk muhataptır.$expl$, $choices$[{"id":"a","text":"Tıbbi takibi sağlamak ve hastanın tedavisini koordine etmek"},{"id":"b","text":"Yalnızca jenerik ilaçlar reçete etmek"},{"id":"c","text":"Hastane acil servislerini yönetmek"},{"id":"d","text":"Sağlık masraflarını geri ödemek"}]$choices$),
(433, 'en', $text$In which situations should one go to the hospital emergency department?$text$, $expl$Hospital emergency departments are reserved for serious situations requiring immediate care: serious accident, intense pain, breathing difficulty, etc. For non-urgent problems, you should consult your médecin traitant (referring doctor).$expl$, $choices$[{"id":"a","text":"In case of a serious accident or a life-threatening situation"},{"id":"b","text":"For a simple cold or a mild flu"},{"id":"c","text":"To renew a prescription"},{"id":"d","text":"To obtain a medical certificate for sports"}]$choices$),
(433, 'tr', $text$Hangi durumlarda hastane acil servisine gidilmelidir?$text$, $expl$Hastane acil servisleri, derhal bakım gerektiren ciddi durumlara ayrılmıştır: ciddi kaza, şiddetli ağrı, nefes alma güçlüğü vb. Acil olmayan sorunlar için aile hekiminize (médecin traitant) başvurmanız gerekir.$expl$, $choices$[{"id":"a","text":"Ciddi bir kaza veya hayati tehlike içeren bir durumda"},{"id":"b","text":"Basit bir nezle veya hafif bir grip için"},{"id":"c","text":"Bir reçeteyi yenilemek için"},{"id":"d","text":"Spor için tıbbi rapor almak için"}]$choices$),
(434, 'en', $text$What is the objective of mandatory vaccinations?$text$, $expl$Mandatory vaccinations aim to protect everyone's health and the health of the community by preventing the spread of serious diseases. This is the principle of collective protection.$expl$, $choices$[{"id":"a","text":"To protect individual and collective health against serious diseases"},{"id":"b","text":"To allow pharmaceutical companies to make profits"},{"id":"c","text":"To control the population"},{"id":"d","text":"To replace doctor's consultations"}]$choices$),
(434, 'tr', $text$Zorunlu aşıların amacı nedir?$text$, $expl$Zorunlu aşılar, ciddi hastalıkların yayılmasını önleyerek herkesin ve toplumun sağlığını korumayı amaçlar. Bu, toplu koruma ilkesidir.$expl$, $choices$[{"id":"a","text":"Bireysel ve toplumsal sağlığı ciddi hastalıklara karşı korumak"},{"id":"b","text":"İlaç şirketlerinin kâr etmesine olanak sağlamak"},{"id":"c","text":"Nüfusu kontrol etmek"},{"id":"d","text":"Doktor muayenelerinin yerini almak"}]$choices$),
(435, 'en', $text$What is the carte Vitale (the French health insurance card) for?$text$, $expl$The carte Vitale is the health insurance card. It enables faster reimbursement of healthcare costs by the Sécurité sociale. It contains the administrative information of the insured person.$expl$, $choices$[{"id":"a","text":"To be reimbursed for healthcare costs by the Sécurité sociale (the French social security system)"},{"id":"b","text":"To get discounts at pharmacies"},{"id":"c","text":"To prove one's identity"},{"id":"d","text":"To pay one's taxes"}]$choices$),
(435, 'tr', $text$Carte Vitale (Fransız sağlık sigortası kartı) ne işe yarar?$text$, $expl$Carte Vitale sağlık sigortası kartıdır. Sécurité sociale tarafından sağlık masraflarının daha hızlı geri ödenmesini sağlar. Sigortalı kişinin idari bilgilerini içerir.$expl$, $choices$[{"id":"a","text":"Sécurité sociale (Fransız sosyal güvenlik sistemi) tarafından sağlık masraflarının geri ödenmesini sağlamak"},{"id":"b","text":"Eczanelerde indirim almak"},{"id":"c","text":"Kimliği kanıtlamak"},{"id":"d","text":"Vergileri ödemek"}]$choices$),
(436, 'en', $text$What is a mutuelle santé (supplementary health insurance) for?$text$, $expl$A mutuelle santé (supplementary health insurance / complémentaire santé) supplements the reimbursements of the Sécurité sociale. It covers all or part of the healthcare costs remaining at the insured person's expense.$expl$, $choices$[{"id":"a","text":"To complement reimbursements from the Sécurité sociale (the French social security system)"},{"id":"b","text":"To replace the Sécurité sociale"},{"id":"c","text":"To obtain a job"},{"id":"d","text":"To finance one's retirement"}]$choices$),
(436, 'tr', $text$Mutuelle santé (tamamlayıcı sağlık sigortası) ne işe yarar?$text$, $expl$Mutuelle santé (tamamlayıcı sağlık sigortası / complémentaire santé) Sécurité sociale'ın geri ödemelerini tamamlar. Sigortalının üzerinde kalan sağlık masraflarının tamamını veya bir kısmını karşılar.$expl$, $choices$[{"id":"a","text":"Sécurité sociale'ın (Fransız sosyal güvenlik sistemi) geri ödemelerini tamamlamak"},{"id":"b","text":"Sécurité sociale'ın yerini almak"},{"id":"c","text":"İş bulmak"},{"id":"d","text":"Emekliliği finanse etmek"}]$choices$),
(437, 'en', $text$Up to what age is school compulsory?$text$, $expl$Education is compulsory in France for all children from 3 to 16 years old. Since the 2019 law, compulsory instruction begins at age 3 and continues until age 16.$expl$, $choices$[{"id":"a","text":"16 years old"},{"id":"b","text":"14 years old"},{"id":"c","text":"18 years old"},{"id":"d","text":"12 years old"}]$choices$),
(437, 'tr', $text$Okul hangi yaşa kadar zorunludur?$text$, $expl$Fransa'da eğitim, 3 ila 16 yaş arasındaki tüm çocuklar için zorunludur. 2019 yasasından bu yana, zorunlu eğitim 3 yaşında başlar ve 16 yaşına kadar devam eder.$expl$, $choices$[{"id":"a","text":"16 yaş"},{"id":"b","text":"14 yaş"},{"id":"c","text":"18 yaş"},{"id":"d","text":"12 yaş"}]$choices$),
(438, 'en', $text$Parental authority entails the obligation:$text$, $expl$Parental authority entails the obligation to protect the child, ensure their education, and enable their development. Parents must look after their health, safety, and moral upbringing.$expl$, $choices$[{"id":"a","text":"To protect, educate, and ensure the development of the child"},{"id":"b","text":"To let the child decide alone about their future from the age of 10"},{"id":"c","text":"To entrust the child to the State from birth"},{"id":"d","text":"To enroll the child in a private school"}]$choices$),
(438, 'tr', $text$Ebeveyn otoritesi şu yükümlülüğü içerir:$text$, $expl$Ebeveyn otoritesi, çocuğu koruma, eğitimini sağlama ve gelişimine olanak tanıma yükümlülüğünü içerir. Ebeveynler çocuğun sağlığını, güvenliğini ve ahlakını gözetmelidir.$expl$, $choices$[{"id":"a","text":"Çocuğu korumak, eğitmek ve gelişimini sağlamak"},{"id":"b","text":"Çocuğun 10 yaşından itibaren geleceği hakkında tek başına karar vermesine izin vermek"},{"id":"c","text":"Çocuğu doğumdan itibaren Devlet'e teslim etmek"},{"id":"d","text":"Çocuğu özel bir okula kaydettirmek"}]$choices$),
(439, 'en', $text$For whom is school compulsory?$text$, $expl$School (instruction) is compulsory for all children residing in France, from 3 to 16 years old, regardless of their nationality or administrative status.$expl$, $choices$[{"id":"a","text":"For all children residing in France, from 3 to 16 years old"},{"id":"b","text":"Only for children of French nationality"},{"id":"c","text":"Only for boys"},{"id":"d","text":"For children from 6 to 18 years old"}]$choices$),
(439, 'tr', $text$Okul kimler için zorunludur?$text$, $expl$Okul (eğitim), uyruğu veya idari durumu ne olursa olsun, Fransa'da ikamet eden 3 ila 16 yaş arasındaki tüm çocuklar için zorunludur.$expl$, $choices$[{"id":"a","text":"Fransa'da ikamet eden 3 ila 16 yaş arasındaki tüm çocuklar için"},{"id":"b","text":"Yalnızca Fransız uyruklu çocuklar için"},{"id":"c","text":"Yalnızca erkek çocuklar için"},{"id":"d","text":"6 ila 18 yaş arasındaki çocuklar için"}]$choices$),
(440, 'en', $text$Which diploma is obtained at the end of lycée (high school)?$text$, $expl$The baccalauréat (le bac) is the diploma obtained at the end of lycée (high school). It marks the completion of secondary education and gives access to higher education.$expl$, $choices$[{"id":"a","text":"The baccalauréat (high school diploma)"},{"id":"b","text":"The brevet des collèges (middle school diploma)"},{"id":"c","text":"The CAP (vocational training certificate)"},{"id":"d","text":"The licence (bachelor's degree)"}]$choices$),
(440, 'tr', $text$Lise (lycée) sonunda hangi diploma alınır?$text$, $expl$Baccalauréat (le bac), lise sonunda alınan diplomadır. Orta öğretimin sonunu işaretler ve yükseköğretime erişim sağlar.$expl$, $choices$[{"id":"a","text":"Baccalauréat (lise bitirme diploması)"},{"id":"b","text":"Brevet des collèges (ortaokul bitirme diploması)"},{"id":"c","text":"CAP (meslek eğitimi sertifikası)"},{"id":"d","text":"Licence (lisans diploması)"}]$choices$),
(441, 'en', $text$In which school establishment do pupils go after primary school?$text$, $expl$After primary school (école élémentaire), pupils go to collège (middle school). Collège welcomes pupils from the 6th to the 3rd grade, generally from 11 to 15 years old.$expl$, $choices$[{"id":"a","text":"To collège (middle school)"},{"id":"b","text":"To lycée (high school)"},{"id":"c","text":"To university"},{"id":"d","text":"To école maternelle (preschool)"}]$choices$),
(441, 'tr', $text$Öğrenciler ilkokuldan sonra hangi okula gider?$text$, $expl$İlkokuldan (école élémentaire) sonra öğrenciler collège'e (ortaokul) gider. Collège, genellikle 11 ila 15 yaşları arasındaki 6. sınıftan 3. sınıfa kadar olan öğrencileri kabul eder.$expl$, $choices$[{"id":"a","text":"Collège'e (ortaokul)"},{"id":"b","text":"Lycée'ye (lise)"},{"id":"c","text":"Üniversiteye"},{"id":"d","text":"École maternelle'ye (anaokulu)"}]$choices$),
(442, 'en', $text$A child enrolled in school:$text$, $expl$A child enrolled in school must attend regularly. School attendance is a legal obligation. Unjustified absences may lead to sanctions against the parents.$expl$, $choices$[{"id":"a","text":"Must attend school regularly (attendance obligation)"},{"id":"b","text":"May be absent whenever they want"},{"id":"c","text":"Is not required to attend all classes"},{"id":"d","text":"May leave school at any time of the day"}]$choices$),
(442, 'tr', $text$Okula kayıtlı bir çocuk:$text$, $expl$Okula kayıtlı bir çocuk okula düzenli olarak devam etmelidir. Okul devamı yasal bir zorunluluktur. Mazeretsiz devamsızlıklar ebeveynlere yaptırım uygulanmasına yol açabilir.$expl$, $choices$[{"id":"a","text":"Okula düzenli olarak devam etmelidir (devam zorunluluğu)"},{"id":"b","text":"İstediği zaman okula gelmeyebilir"},{"id":"c","text":"Tüm derslere katılmak zorunda değildir"},{"id":"d","text":"Günün herhangi bir saatinde okuldan ayrılabilir"}]$choices$),
(443, 'en', $text$Children who do not speak French:$text$, $expl$Children who do not speak French benefit from adapted teaching to learn French. Specific programs (UPE2A) exist in schools to support them in learning the language.$expl$, $choices$[{"id":"a","text":"Benefit from adapted teaching to learn French at school"},{"id":"b","text":"Cannot be enrolled in public school"},{"id":"c","text":"Must first learn French before going to school"},{"id":"d","text":"Are directed to special private schools"}]$choices$),
(443, 'tr', $text$Fransızca konuşmayan çocuklar:$text$, $expl$Fransızca konuşmayan çocuklar, Fransızca öğrenmek için uyarlanmış eğitimden yararlanır. Onlara dil öğreniminde destek olmak için okullarda belirli programlar (UPE2A) bulunmaktadır.$expl$, $choices$[{"id":"a","text":"Okulda Fransızca öğrenmek için uyarlanmış eğitimden yararlanır"},{"id":"b","text":"Devlet okuluna kayıt olamaz"},{"id":"c","text":"Okula gitmeden önce Fransızca öğrenmelidir"},{"id":"d","text":"Özel okullara yönlendirilir"}]$choices$),
(444, 'en', $text$Which marriage is recognized by the State?$text$, $expl$Only the civil marriage, celebrated at the mairie (town hall) before a civil registrar, is recognized by the French State. Religious marriage has no legal value in France.$expl$, $choices$[{"id":"a","text":"The civil marriage celebrated at the mairie (town hall)"},{"id":"b","text":"The religious marriage celebrated in a place of worship"},{"id":"c","text":"The customary marriage celebrated within the family"},{"id":"d","text":"Every type of marriage is recognized by the State"}]$choices$),
(444, 'tr', $text$Hangi evlilik Devlet tarafından tanınır?$text$, $expl$Yalnızca belediyede (mairie) bir nüfus memuru huzurunda yapılan medeni nikâh Fransız Devleti tarafından tanınır. Dini nikâhın Fransa'da hiçbir yasal değeri yoktur.$expl$, $choices$[{"id":"a","text":"Belediyede (mairie) yapılan medeni nikâh"},{"id":"b","text":"Bir ibadethanede yapılan dini nikâh"},{"id":"c","text":"Aile içinde yapılan geleneksel evlilik"},{"id":"d","text":"Her tür evlilik Devlet tarafından tanınır"}]$choices$),
(445, 'en', $text$At which institution can parents enroll their child in public school?$text$, $expl$Parents must enroll their child in public school at the mairie (town hall) of their commune of residence. The mairie indicates the catchment school based on their place of residence.$expl$, $choices$[{"id":"a","text":"The mairie (town hall) of their commune"},{"id":"b","text":"The préfecture (the prefecture, central state office)"},{"id":"c","text":"The rectorat (regional education authority)"},{"id":"d","text":"The Ministry of National Education"}]$choices$),
(445, 'tr', $text$Ebeveynler çocuklarını hangi kuruma devlet okuluna kaydettirebilir?$text$, $expl$Ebeveynler çocuklarını ikamet ettikleri belediyenin (mairie) devlet okuluna kaydettirmelidir. Belediye, ikamet yerine bağlı olarak ilgili okulu belirtir.$expl$, $choices$[{"id":"a","text":"Yaşadıkları belediyeye (mairie)"},{"id":"b","text":"Valiliğe (préfecture)"},{"id":"c","text":"Rectorat'a (bölgesel eğitim makamı)"},{"id":"d","text":"Milli Eğitim Bakanlığı'na"}]$choices$),
(446, 'en', $text$In case of divorce, who exercises parental authority?$text$, $expl$In case of divorce, both parents continue to exercise parental authority jointly, unless decided otherwise by a judge. The child's best interests take precedence in all decisions.$expl$, $choices$[{"id":"a","text":"Both parents jointly"},{"id":"b","text":"Only the mother"},{"id":"c","text":"Only the father"},{"id":"d","text":"The State takes charge of the child"}]$choices$),
(446, 'tr', $text$Boşanma durumunda ebeveyn otoritesini kim kullanır?$text$, $expl$Boşanma durumunda, hâkimin aksi karar vermesi durumu hariç, her iki ebeveyn ebeveyn otoritesini birlikte kullanmaya devam eder. Tüm kararlarda çocuğun yararı önceliklidir.$expl$, $choices$[{"id":"a","text":"Her iki ebeveyn birlikte"},{"id":"b","text":"Yalnızca anne"},{"id":"c","text":"Yalnızca baba"},{"id":"d","text":"Devlet çocuğu üstlenir"}]$choices$),
(447, 'en', $text$Which aid enables people with financial difficulties to have a lawyer?$text$, $expl$Aide juridictionnelle (legal aid) enables people with low income to have a lawyer paid for in whole or in part by the State. It guarantees access to justice for all.$expl$, $choices$[{"id":"a","text":"Aide juridictionnelle (legal aid)"},{"id":"b","text":"RSA (Revenu de Solidarité Active, active solidarity income)"},{"id":"c","text":"Allocation logement (housing benefit)"},{"id":"d","text":"CMU (Couverture Maladie Universelle, universal health coverage)"}]$choices$),
(447, 'tr', $text$Maddi zorluk yaşayan kişilerin avukat tutmasına hangi yardım imkân sağlar?$text$, $expl$Aide juridictionnelle (adli yardım), düşük gelirli kişilerin masrafları kısmen veya tamamen Devlet tarafından karşılanan bir avukattan yararlanmasını sağlar. Herkes için adalete erişimi güvence altına alır.$expl$, $choices$[{"id":"a","text":"Aide juridictionnelle (adli yardım)"},{"id":"b","text":"RSA (Revenu de Solidarité Active, aktif dayanışma geliri)"},{"id":"c","text":"Allocation logement (konut yardımı)"},{"id":"d","text":"CMU (Couverture Maladie Universelle, evrensel sağlık güvencesi)"}]$choices$),
(448, 'en', $text$Where must a child's birth be declared?$text$, $expl$A child's birth must be declared at the mairie (town hall) of the place of birth, within 5 days following the delivery. The civil registrar then issues the birth certificate.$expl$, $choices$[{"id":"a","text":"At the mairie (town hall) of the place of birth"},{"id":"b","text":"At the préfecture of the département"},{"id":"c","text":"At the police station"},{"id":"d","text":"At the judicial court"}]$choices$),
(448, 'tr', $text$Bir çocuğun doğumu nerede bildirilmelidir?$text$, $expl$Bir çocuğun doğumu, doğumu takip eden 5 gün içinde doğum yerinin belediyesine (mairie) bildirilmelidir. Nüfus memuru daha sonra doğum belgesini düzenler.$expl$, $choices$[{"id":"a","text":"Doğum yerinin belediyesine (mairie)"},{"id":"b","text":"Département'ın valiliğine (préfecture)"},{"id":"c","text":"Polis karakoluna"},{"id":"d","text":"Adliyeye"}]$choices$),
(449, 'en', $text$What is one of the conditions for taking the driving licence exam?$text$, $expl$To take the driving licence exam in France, you must be at least 17 years old (or 15 for accompanied driving). You must also have passed the highway code (code de la route).$expl$, $choices$[{"id":"a","text":"Being at least 17 years old"},{"id":"b","text":"Being at least 21 years old"},{"id":"c","text":"Being of French nationality"},{"id":"d","text":"Owning one's own vehicle"}]$choices$),
(449, 'tr', $text$Sürücü belgesi sınavına girmenin koşullarından biri nedir?$text$, $expl$Fransa'da sürücü belgesi sınavına girmek için en az 17 yaşında olmak gerekir (eşlikli sürüş için 15 yaş). Ayrıca trafik kuralları sınavını (code de la route) geçmiş olmak gerekir.$expl$, $choices$[{"id":"a","text":"En az 17 yaşında olmak"},{"id":"b","text":"En az 21 yaşında olmak"},{"id":"c","text":"Fransız uyruklu olmak"},{"id":"d","text":"Kendi aracına sahip olmak"}]$choices$),
(450, 'en', $text$A rental lease is valid if it is:$text$, $expl$A rental lease (rental contract) is valid if it is signed by the landlord and the tenant. It must be in writing and contain certain mandatory mentions such as the description of the dwelling, the amount of rent, and the duration.$expl$, $choices$[{"id":"a","text":"Signed by the landlord and the tenant"},{"id":"b","text":"Validated by the mairie (town hall)"},{"id":"c","text":"Registered with the court"},{"id":"d","text":"Approved by a notary, mandatorily"}]$choices$),
(450, 'tr', $text$Bir kira sözleşmesi hangi durumda geçerlidir?$text$, $expl$Bir kira sözleşmesi, ev sahibi ve kiracı tarafından imzalandığında geçerlidir. Yazılı olmalı ve konutun tanımı, kira tutarı ve süre gibi belirli zorunlu unsurları içermelidir.$expl$, $choices$[{"id":"a","text":"Ev sahibi ve kiracı tarafından imzalanmış olması"},{"id":"b","text":"Belediye (mairie) tarafından onaylanmış olması"},{"id":"c","text":"Mahkemeye kaydedilmiş olması"},{"id":"d","text":"Zorunlu olarak bir noter tarafından onaylanmış olması"}]$choices$),
(451, 'en', $text$Where can a broken dishwasher be disposed of?$text$, $expl$A broken dishwasher is waste electrical and electronic equipment (DEEE). It can be taken to a déchetterie (recycling centre) or taken back free of charge by the store when buying an equivalent new appliance.$expl$, $choices$[{"id":"a","text":"At the déchetterie (recycling centre) or by having it taken back by a store"},{"id":"b","text":"On the sidewalk in front of one's home"},{"id":"c","text":"In the household waste bin"},{"id":"d","text":"In a glass recycling container"}]$choices$),
(451, 'tr', $text$Bozuk bir bulaşık makinesi nereye atılabilir?$text$, $expl$Bozuk bir bulaşık makinesi, elektrikli ve elektronik atık ekipmanıdır (DEEE). Déchetterie'ye (geri dönüşüm merkezine) götürülebilir veya eşdeğer yeni bir cihaz satın alınırken mağaza tarafından ücretsiz olarak geri alınabilir.$expl$, $choices$[{"id":"a","text":"Déchetterie'ye (geri dönüşüm merkezine) veya bir mağazaya geri alınması için"},{"id":"b","text":"Evin önündeki kaldırıma"},{"id":"c","text":"Ev çöpü kutusuna"},{"id":"d","text":"Cam geri dönüşüm konteynerine"}]$choices$),
(452, 'en', $text$Which emergency number is used to call the police?$text$, $expl$17 is the emergency number for reaching the police or the Gendarmerie (rural police). It is used to report an emergency situation requiring the intervention of law enforcement.$expl$, $choices$[{"id":"a","text":"17"},{"id":"b","text":"15"},{"id":"c","text":"18"},{"id":"d","text":"119"}]$choices$),
(452, 'tr', $text$Polisi aramak için hangi acil numarası kullanılır?$text$, $expl$17, polis veya Gendarmerie'ye (kırsal polis) ulaşmak için acil numarasıdır. Kolluk kuvvetlerinin müdahalesini gerektiren acil bir durumu bildirmek için kullanılır.$expl$, $choices$[{"id":"a","text":"17"},{"id":"b","text":"15"},{"id":"c","text":"18"},{"id":"d","text":"119"}]$choices$),
(453, 'en', $text$To whom is contraception accessible?$text$, $expl$Contraception is accessible to any person, including minors. Minors can obtain contraception free of charge and confidentially, without parental authorization.$expl$, $choices$[{"id":"a","text":"To any person, including minors"},{"id":"b","text":"Only to adults"},{"id":"c","text":"Only to married women"},{"id":"d","text":"Only with a specialist's prescription"}]$choices$),
(453, 'tr', $text$Doğum kontrolü kimin için erişilebilirdir?$text$, $expl$Doğum kontrolü, reşit olmayanlar dahil her kişi için erişilebilirdir. Reşit olmayanlar ebeveyn izni olmaksızın ücretsiz ve gizli olarak doğum kontrolü alabilir.$expl$, $choices$[{"id":"a","text":"Reşit olmayanlar dahil her kişi için"},{"id":"b","text":"Yalnızca yetişkinler için"},{"id":"c","text":"Yalnızca evli kadınlar için"},{"id":"d","text":"Yalnızca bir uzmanın reçetesiyle"}]$choices$),
(454, 'en', $text$What is the principle of confidentiality in the field of health?$text$, $expl$The principle of confidentiality (medical secrecy) means that the doctor cannot disclose information about their patient's health to third parties without their consent. It is a fundamental right of the patient.$expl$, $choices$[{"id":"a","text":"The doctor cannot disclose the patient's medical information without their consent"},{"id":"b","text":"The patient cannot know their own diagnosis"},{"id":"c","text":"Medical results are published for research"},{"id":"d","text":"The employer has access to the employee's medical record"}]$choices$),
(454, 'tr', $text$Sağlık alanında gizlilik ilkesi nedir?$text$, $expl$Gizlilik ilkesi (tıbbi sır), doktorun hastasının sağlığı hakkındaki bilgileri onayı olmadan üçüncü taraflara açıklayamayacağı anlamına gelir. Hastanın temel bir hakkıdır.$expl$, $choices$[{"id":"a","text":"Doktor, hastanın tıbbi bilgilerini onayı olmadan ifşa edemez"},{"id":"b","text":"Hasta kendi teşhisini öğrenemez"},{"id":"c","text":"Tıbbi sonuçlar araştırma için yayımlanır"},{"id":"d","text":"İşveren, çalışanın tıbbi dosyasına erişebilir"}]$choices$),
(455, 'en', $text$Registration with Assurance maladie (public health insurance) is:$text$, $expl$Registration with Assurance maladie is mandatory. Anyone who works or resides in France in a stable and regular manner is entitled to have their healthcare costs covered.$expl$, $choices$[{"id":"a","text":"Mandatory"},{"id":"b","text":"Optional"},{"id":"c","text":"Reserved for salaried employees"},{"id":"d","text":"Paid and optional"}]$choices$),
(455, 'tr', $text$Assurance maladie'ye (kamu sağlık sigortası) kayıt:$text$, $expl$Assurance maladie'ye kayıt zorunludur. Fransa'da istikrarlı ve düzenli olarak çalışan veya ikamet eden herkes sağlık masraflarının karşılanmasından yararlanma hakkına sahiptir.$expl$, $choices$[{"id":"a","text":"Zorunludur"},{"id":"b","text":"İsteğe bağlıdır"},{"id":"c","text":"Yalnızca maaşlı çalışanlara mahsustur"},{"id":"d","text":"Ücretli ve isteğe bağlıdır"}]$choices$),
(456, 'en', $text$Who can request parental leave (congé parental d'éducation)?$text$, $expl$Parental leave (congé parental d'éducation) can be requested by the father or the mother, without distinction. It allows one to stop or reduce one's professional activity in order to take care of the child.$expl$, $choices$[{"id":"a","text":"The father or the mother"},{"id":"b","text":"Only the mother"},{"id":"c","text":"Only the father"},{"id":"d","text":"Neither of them, it is automatic"}]$choices$),
(456, 'tr', $text$Ebeveyn iznini (congé parental d'éducation) kim talep edebilir?$text$, $expl$Ebeveyn izni (congé parental d'éducation), ayrım gözetmeksizin baba veya anne tarafından talep edilebilir. Çocukla ilgilenmek için mesleki faaliyeti durdurmaya veya azaltmaya olanak tanır.$expl$, $choices$[{"id":"a","text":"Baba veya anne"},{"id":"b","text":"Yalnızca anne"},{"id":"c","text":"Yalnızca baba"},{"id":"d","text":"Hiçbiri, otomatiktir"}]$choices$),
(457, 'en', $text$What matters are handled by the conseil de prud'hommes (labour tribunal)?$text$, $expl$The conseil de prud'hommes (labour tribunal) handles disputes between employees and employers related to the employment contract: wrongful dismissal, non-payment of salary, workplace harassment, etc.$expl$, $choices$[{"id":"a","text":"Disputes between employees and employers related to the employment contract"},{"id":"b","text":"Divorce cases"},{"id":"c","text":"Criminal offenses"},{"id":"d","text":"Disputes between neighbors"}]$choices$),
(457, 'tr', $text$Conseil de prud'hommes (iş mahkemesi) hangi davalara bakar?$text$, $expl$Conseil de prud'hommes (iş mahkemesi), çalışan ve işveren arasında iş sözleşmesiyle ilgili uyuşmazlıklara bakar: haksız işten çıkarma, maaşın ödenmemesi, işyerinde taciz vb.$expl$, $choices$[{"id":"a","text":"Çalışan ve işveren arasındaki iş sözleşmesine ilişkin uyuşmazlıklara"},{"id":"b","text":"Boşanma davalarına"},{"id":"c","text":"Cezai suçlara"},{"id":"d","text":"Komşular arasındaki uyuşmazlıklara"}]$choices$),
(458, 'en', $text$When an employer wants an employee to work longer than the duration set out in the employment contract:$text$, $expl$Overtime hours must be paid with a salary increase or compensated by rest time. The employer cannot impose overtime without respecting the legal rules.$expl$, $choices$[{"id":"a","text":"The employer must pay overtime with an increase in pay"},{"id":"b","text":"The employer can require it without compensation"},{"id":"c","text":"The employee must always refuse"},{"id":"d","text":"It is illegal in all cases"}]$choices$),
(458, 'tr', $text$Bir işveren, çalışanın iş sözleşmesinde öngörülen süreden daha uzun çalışmasını istediğinde:$text$, $expl$Fazla mesai saatleri zamlı bir ücretle ödenmeli veya dinlenme süresiyle telafi edilmelidir. İşveren, yasal kurallara uymadan fazla mesai dayatamaz.$expl$, $choices$[{"id":"a","text":"Fazla mesaiyi zamlı bir ücretle ödemek zorundadır"},{"id":"b","text":"Tazminat ödemeden bunu talep edebilir"},{"id":"c","text":"Çalışan her zaman reddetmelidir"},{"id":"d","text":"Her durumda yasadışıdır"}]$choices$),
(459, 'en', $text$What is the mission of France Travail (formerly Pôle emploi, the public employment agency)?$text$, $expl$France Travail (formerly Pôle emploi) is tasked with supporting jobseekers in their search for work, compensating the unemployed, and helping companies in their recruitment.$expl$, $choices$[{"id":"a","text":"To support jobseekers and to compensate the unemployed"},{"id":"b","text":"To set wages in companies"},{"id":"c","text":"To monitor working conditions in companies"},{"id":"d","text":"To manage the retirement of employees"}]$choices$),
(459, 'tr', $text$France Travail'ın (eski adıyla Pôle emploi, kamu istihdam ajansı) görevi nedir?$text$, $expl$France Travail (eski adıyla Pôle emploi), iş arayanlara iş aramalarında destek olmak, işsizlere tazminat ödemek ve şirketlere işe alımlarında yardımcı olmakla görevlidir.$expl$, $choices$[{"id":"a","text":"İş arayanlara destek olmak ve işsizlere tazminat ödemek"},{"id":"b","text":"Şirketlerdeki maaşları belirlemek"},{"id":"c","text":"Şirketlerdeki çalışma koşullarını denetlemek"},{"id":"d","text":"Çalışanların emekliliğini yönetmek"}]$choices$),
(460, 'en', $text$In a company, trade union rights allow:$text$, $expl$Trade union rights allow employees to come together to defend their professional interests. Trade unions negotiate working conditions and wages with the employer.$expl$, $choices$[{"id":"a","text":"Employees to come together to defend their professional interests"},{"id":"b","text":"The employer to dismiss freely"},{"id":"c","text":"Employees not to work whenever they want"},{"id":"d","text":"The State to control the company"}]$choices$),
(460, 'tr', $text$Bir şirkette sendika hakkı şuna olanak tanır:$text$, $expl$Sendika hakkı, çalışanların mesleki çıkarlarını savunmak için bir araya gelmesine olanak tanır. Sendikalar, işverenle çalışma koşullarını ve ücretleri müzakere eder.$expl$, $choices$[{"id":"a","text":"Çalışanların mesleki çıkarlarını savunmak için bir araya gelmesine"},{"id":"b","text":"İşverenin serbestçe işten çıkarmasına"},{"id":"c","text":"Çalışanların istedikleri zaman çalışmamasına"},{"id":"d","text":"Devlet'in şirketi denetlemesine"}]$choices$),
(461, 'en', $text$In a company, the right to strike authorizes:$text$, $expl$The right to strike, recognized by the Constitution, authorizes employees to collectively stop work to defend their professional demands. It is a fundamental right in France.$expl$, $choices$[{"id":"a","text":"Employees to collectively stop work to defend their demands"},{"id":"b","text":"The employer to close the company without notice"},{"id":"c","text":"Employees to destroy the company's equipment"},{"id":"d","text":"Employees to never come back to work again"}]$choices$),
(461, 'tr', $text$Bir şirkette grev hakkı şuna izin verir:$text$, $expl$Anayasa tarafından tanınan grev hakkı, çalışanların mesleki taleplerini savunmak için toplu olarak işi bırakmasına izin verir. Fransa'da temel bir haktır.$expl$, $choices$[{"id":"a","text":"Çalışanların taleplerini savunmak için toplu olarak işi bırakmasına"},{"id":"b","text":"İşverenin önceden bildirimde bulunmaksızın şirketi kapatmasına"},{"id":"c","text":"Çalışanların şirketin malzemelerini tahrip etmesine"},{"id":"d","text":"Çalışanların bir daha asla işe dönmemesine"}]$choices$),
(462, 'en', $text$What are the conditions for receiving unemployment benefits?$text$, $expl$To receive unemployment benefits, you must have worked long enough (at least 6 months over the last 24 months), be registered with France Travail, and actively seek employment.$expl$, $choices$[{"id":"a","text":"Having worked sufficiently, being registered with France Travail, and actively seeking employment"},{"id":"b","text":"It is enough not to have a job"},{"id":"c","text":"Having French nationality"},{"id":"d","text":"Being over 25 years old"}]$choices$),
(462, 'tr', $text$İşsizlik yardımı almanın koşulları nelerdir?$text$, $expl$İşsizlik yardımı almak için yeterince uzun süre çalışmış (son 24 ayda en az 6 ay), France Travail'a kayıtlı olmak ve aktif olarak iş aramak gerekir.$expl$, $choices$[{"id":"a","text":"Yeterince çalışmış olmak, France Travail'a kayıtlı olmak ve aktif olarak iş aramak"},{"id":"b","text":"İşin olmaması yeterlidir"},{"id":"c","text":"Fransız uyruğuna sahip olmak"},{"id":"d","text":"25 yaşından büyük olmak"}]$choices$),
(463, 'en', $text$What is école maternelle (preschool)?$text$, $expl$École maternelle (preschool) welcomes children from 3 to 6 years old. It is the first stage of schooling and prepares children for the fundamental learning of école élémentaire (primary school).$expl$, $choices$[{"id":"a","text":"The school that welcomes children from 3 to 6 years old"},{"id":"b","text":"A school reserved for girls"},{"id":"c","text":"An establishment for children from 6 to 11 years old"},{"id":"d","text":"A daycare run by the State"}]$choices$),
(463, 'tr', $text$École maternelle (anaokulu) nedir?$text$, $expl$École maternelle (anaokulu) 3 ila 6 yaş arasındaki çocukları kabul eder. Okul yaşamının ilk aşamasıdır ve çocukları école élémentaire'in (ilkokul) temel öğrenmelerine hazırlar.$expl$, $choices$[{"id":"a","text":"3 ila 6 yaş arasındaki çocukları kabul eden okul"},{"id":"b","text":"Yalnızca kızlar için ayrılmış bir okul"},{"id":"c","text":"6 ila 11 yaş arasındaki çocuklar için bir kurum"},{"id":"d","text":"Devlet tarafından yönetilen bir kreş"}]$choices$),
(464, 'en', $text$What is the name of the diploma taken by pupils at the end of collège (middle school)?$text$, $expl$The diplôme national du brevet (DNB), commonly called brevet des collèges, is taken at the end of the 3rd grade (last year of collège). It assesses the knowledge acquired during schooling at collège.$expl$, $choices$[{"id":"a","text":"The diplôme national du brevet (brevet des collèges, middle school diploma)"},{"id":"b","text":"The baccalauréat (high school diploma)"},{"id":"c","text":"The certificat d'études primaires"},{"id":"d","text":"The CAP (vocational training certificate)"}]$choices$),
(464, 'tr', $text$Öğrencilerin collège (ortaokul) sonunda aldıkları diplomanın adı nedir?$text$, $expl$Diplôme national du brevet (DNB), yaygın olarak brevet des collèges olarak adlandırılır, 3. sınıfın (collège'in son yılı) sonunda alınır. Collège'deki öğretim sırasında edinilen bilgileri değerlendirir.$expl$, $choices$[{"id":"a","text":"Diplôme national du brevet (brevet des collèges, ortaokul diploması)"},{"id":"b","text":"Baccalauréat (lise diploması)"},{"id":"c","text":"Certificat d'études primaires"},{"id":"d","text":"CAP (meslek eğitimi sertifikası)"}]$choices$),
(465, 'en', $text$Parents of pupils have the right to:$text$, $expl$Parents of pupils have the right to participate in school life, in particular by electing parent representatives and participating in school or class councils.$expl$, $choices$[{"id":"a","text":"Participate in school life and elect parent representatives"},{"id":"b","text":"Choose their child's teachers"},{"id":"c","text":"Modify the school curriculum"},{"id":"d","text":"Decide on class schedules"}]$choices$),
(465, 'tr', $text$Öğrenci velilerinin hakları nelerdir?$text$, $expl$Öğrenci velileri, özellikle veli temsilcileri seçerek ve okul veya sınıf konseylerine katılarak okul yaşamına katılma hakkına sahiptir.$expl$, $choices$[{"id":"a","text":"Okul yaşamına katılmak ve veli temsilcileri seçmek"},{"id":"b","text":"Çocuklarının öğretmenlerini seçmek"},{"id":"c","text":"Okul müfredatını değiştirmek"},{"id":"d","text":"Ders saatlerine karar vermek"}]$choices$),
(466, 'en', $text$Who can eat at the school cantine (canteen)?$text$, $expl$All pupils enrolled in the establishment can eat at the school cantine. Access to school catering is a right for all schooled children, without discrimination.$expl$, $choices$[{"id":"a","text":"All pupils enrolled in the establishment"},{"id":"b","text":"Only pupils whose parents work"},{"id":"c","text":"Only pupils who live far from the school"},{"id":"d","text":"Only pupils receiving a scholarship"}]$choices$),
(466, 'tr', $text$Okul yemekhanesinde (cantine) kim yemek yiyebilir?$text$, $expl$Kuruma kayıtlı tüm öğrenciler okul yemekhanesinde yemek yiyebilir. Okul yemeğine erişim, ayrım gözetmeksizin tüm okula giden çocuklar için bir haktır.$expl$, $choices$[{"id":"a","text":"Kuruma kayıtlı tüm öğrenciler"},{"id":"b","text":"Yalnızca ebeveynleri çalışan öğrenciler"},{"id":"c","text":"Yalnızca okuldan uzakta yaşayan öğrenciler"},{"id":"d","text":"Yalnızca burslu öğrenciler"}]$choices$),
(467, 'en', $text$At what age does compulsory instruction for children begin?$text$, $expl$Since the law of 26 July 2019, instruction is compulsory in France from the age of 3. This corresponds to entry into école maternelle (preschool).$expl$, $choices$[{"id":"a","text":"3 years old"},{"id":"b","text":"5 years old"},{"id":"c","text":"6 years old"},{"id":"d","text":"4 years old"}]$choices$),
(467, 'tr', $text$Çocuklar için zorunlu eğitim hangi yaşta başlar?$text$, $expl$26 Temmuz 2019 yasasından bu yana, Fransa'da eğitim 3 yaşından itibaren zorunludur. Bu, école maternelle'ye (anaokulu) girişe denk gelir.$expl$, $choices$[{"id":"a","text":"3 yaş"},{"id":"b","text":"5 yaş"},{"id":"c","text":"6 yaş"},{"id":"d","text":"4 yaş"}]$choices$),
(468, 'en', $text$What is the age of majority?$text$, $expl$The age of majority in France is 18. At this age, a person acquires full legal capacity: they can vote, sign contracts, marry without parental authorization, etc.$expl$, $choices$[{"id":"a","text":"18 years old"},{"id":"b","text":"16 years old"},{"id":"c","text":"21 years old"},{"id":"d","text":"17 years old"}]$choices$),
(468, 'tr', $text$Reşit olma yaşı nedir?$text$, $expl$Fransa'da reşit olma yaşı 18'dir. Bu yaşta bir kişi tam hukuki ehliyet kazanır: oy verebilir, sözleşme imzalayabilir, ebeveyn izni olmaksızın evlenebilir vb.$expl$, $choices$[{"id":"a","text":"18 yaş"},{"id":"b","text":"16 yaş"},{"id":"c","text":"21 yaş"},{"id":"d","text":"17 yaş"}]$choices$),
(469, 'en', $text$At school, parents are forbidden to:$text$, $expl$At school, parents cannot object to the teaching of certain compulsory subjects in the school curriculum. The educational content is defined by the Éducation nationale (National Education) and applies to all.$expl$, $choices$[{"id":"a","text":"Object to the teaching of certain compulsory subjects"},{"id":"b","text":"Participate in parent-teacher meetings"},{"id":"c","text":"Consult their child's textbook log"},{"id":"d","text":"Meet their child's teachers"}]$choices$),
(469, 'tr', $text$Okulda velilere şu yasaktır:$text$, $expl$Okulda veliler, okul müfredatındaki bazı zorunlu derslerin öğretimine karşı çıkamaz. Pedagojik içerik, Éducation nationale (Milli Eğitim) tarafından belirlenir ve herkes için bağlayıcıdır.$expl$, $choices$[{"id":"a","text":"Bazı zorunlu derslerin öğretimine karşı çıkmak"},{"id":"b","text":"Veli-öğretmen toplantılarına katılmak"},{"id":"c","text":"Çocuklarının ödev defterine bakmak"},{"id":"d","text":"Çocuklarının öğretmenleriyle görüşmek"}]$choices$),
(470, 'en', $text$Which reason for absence is accepted by the school?$text$, $expl$The child's illness (with a medical certificate) is a legitimate reason for absence accepted by the school. Other accepted reasons include imperative family obligations or religious holidays.$expl$, $choices$[{"id":"a","text":"The child's illness"},{"id":"b","text":"A family vacation trip"},{"id":"c","text":"Sales at the stores"},{"id":"d","text":"The child's tiredness"}]$choices$),
(470, 'tr', $text$Okul tarafından hangi devamsızlık mazereti kabul edilir?$text$, $expl$Çocuğun hastalığı (sağlık raporu ile) okul tarafından kabul edilen meşru bir devamsızlık mazeretidir. Diğer kabul edilen mazeretler arasında zorunlu aile yükümlülükleri veya dini bayramlar yer alır.$expl$, $choices$[{"id":"a","text":"Çocuğun hastalığı"},{"id":"b","text":"Aile ile tatil seyahati"},{"id":"c","text":"Mağazalardaki indirimler"},{"id":"d","text":"Çocuğun yorgunluğu"}]$choices$),
(471, 'en', $text$Parents do not respect the compulsory instruction obligation for their children. What maximum sanction do they incur?$text$, $expl$Parents who do not respect the compulsory instruction obligation for their children incur up to 2 years' imprisonment and a 30,000 euro fine. Instruction is a legal obligation in France.$expl$, $choices$[{"id":"a","text":"2 years' imprisonment and a 30,000 euro fine"},{"id":"b","text":"A simple warning from the mairie (town hall)"},{"id":"c","text":"A 150 euro fine"},{"id":"d","text":"No sanction is provided for"}]$choices$),
(471, 'tr', $text$Çocukları için zorunlu eğitim yükümlülüğüne uymayan ebeveynler hangi azami yaptırımla karşılaşır?$text$, $expl$Çocukları için zorunlu eğitim yükümlülüğüne uymayan ebeveynler 2 yıla kadar hapis ve 30.000 euro para cezasıyla karşılaşır. Fransa'da eğitim yasal bir yükümlülüktür.$expl$, $choices$[{"id":"a","text":"2 yıl hapis ve 30.000 euro para cezası"},{"id":"b","text":"Belediyeden (mairie) basit bir uyarı"},{"id":"c","text":"150 euro para cezası"},{"id":"d","text":"Hiçbir yaptırım öngörülmemiştir"}]$choices$),
(472, 'en', $text$When do the Christmas school holidays take place?$text$, $expl$The Christmas school holidays take place in December-January, generally for two weeks around 25 December and 1 January. They are common to all school zones.$expl$, $choices$[{"id":"a","text":"In December-January, for approximately two weeks"},{"id":"b","text":"In November, for one week"},{"id":"c","text":"In February, for two weeks"},{"id":"d","text":"In October, for one week"}]$choices$),
(472, 'tr', $text$Okulların Noel tatili ne zaman olur?$text$, $expl$Okulların Noel tatili Aralık-Ocak aylarında, genellikle 25 Aralık ve 1 Ocak çevresinde iki hafta süreyle olur. Tüm okul bölgeleri için ortaktır.$expl$, $choices$[{"id":"a","text":"Aralık-Ocak'ta, yaklaşık iki hafta süreyle"},{"id":"b","text":"Kasım'da, bir hafta süreyle"},{"id":"c","text":"Şubat'ta, iki hafta süreyle"},{"id":"d","text":"Ekim'de, bir hafta süreyle"}]$choices$),
(473, 'en', $text$At school, a child with a disability:$text$, $expl$In France, a child with a disability has the right to be enrolled in the school closest to their home. Inclusive education is a fundamental principle: every child has the right to suitable schooling.$expl$, $choices$[{"id":"a","text":"Has the right to be enrolled in the school closest to their home"},{"id":"b","text":"Must necessarily go to a specialized establishment"},{"id":"c","text":"Cannot be schooled"},{"id":"d","text":"Must stay at home with a private teacher"}]$choices$),
(473, 'tr', $text$Okulda engelli bir çocuk:$text$, $expl$Fransa'da engelli bir çocuk, evine en yakın okula kaydolma hakkına sahiptir. Kapsayıcı eğitim temel bir ilkedir: her çocuk uygun bir okul eğitimi alma hakkına sahiptir.$expl$, $choices$[{"id":"a","text":"Evine en yakın okula kaydolma hakkına sahiptir"},{"id":"b","text":"Mutlaka uzman bir kuruma gitmek zorundadır"},{"id":"c","text":"Okula gönderilemez"},{"id":"d","text":"Özel bir öğretmenle evde kalmalıdır"}]$choices$),
(474, 'en', $text$Which action can the tenant of a dwelling carry out without the landlord's authorization?$text$, $expl$The tenant can carry out small adjustments (decoration, painting, minor works) without asking for the landlord's authorization, provided that the dwelling is not transformed structurally.$expl$, $choices$[{"id":"a","text":"Make small adjustments such as painting walls or installing shelves"},{"id":"b","text":"Knock down a partition wall"},{"id":"c","text":"Sublet the dwelling to another person"},{"id":"d","text":"Change the windows and the front door"}]$choices$),
(474, 'tr', $text$Bir konutun kiracısı, ev sahibinin izni olmadan hangi işlemi yapabilir?$text$, $expl$Kiracı, konutu yapısal olarak değiştirmemek kaydıyla, ev sahibinden izin istemeden küçük düzenlemeler (dekorasyon, boyama, küçük işler) yapabilir.$expl$, $choices$[{"id":"a","text":"Duvarları boyamak veya raf takmak gibi küçük düzenlemeler yapmak"},{"id":"b","text":"Bir bölme duvarını yıkmak"},{"id":"c","text":"Konutu başka bir kişiye kiraya vermek"},{"id":"d","text":"Pencereleri ve ön kapıyı değiştirmek"}]$choices$),
(475, 'en', $text$Parking in a space reserved for people with disabilities:$text$, $expl$Parking in a space reserved for people with disabilities is forbidden without the carte mobilité inclusion (CMI). Offenders face a 135 euro fine and the impounding of their vehicle.$expl$, $choices$[{"id":"a","text":"Is forbidden without a carte mobilité inclusion (mobility inclusion card) and punishable by a fine"},{"id":"b","text":"Is allowed for everyone on Sundays"},{"id":"c","text":"Is allowed if it is for a short duration"},{"id":"d","text":"Is not regulated by law"}]$choices$),
(475, 'tr', $text$Engelli kişilere ayrılmış bir park yerine park etmek:$text$, $expl$Engelli kişilere ayrılmış bir park yerine park etmek, carte mobilité inclusion (CMI) olmaksızın yasaktır. İhlal edenler 135 euro para cezası ve aracının çekilmesiyle karşı karşıya kalır.$expl$, $choices$[{"id":"a","text":"Carte mobilité inclusion (engelli erişim kartı) olmaksızın yasaktır ve para cezasıyla cezalandırılır"},{"id":"b","text":"Pazar günleri herkes için izinlidir"},{"id":"c","text":"Kısa süreli ise izinlidir"},{"id":"d","text":"Yasayla düzenlenmemiştir"}]$choices$),
(476, 'en', $text$If a washing machine is broken, it is possible to:$text$, $expl$A broken household appliance can be taken to the déchetterie (recycling centre) or taken back by the store when purchasing a new appliance (one-for-one take-back obligation). It must not be thrown out with household waste.$expl$, $choices$[{"id":"a","text":"Take it to the déchetterie (recycling centre) or have it taken back by a store"},{"id":"b","text":"Throw it in the household waste bin"},{"id":"c","text":"Leave it on the sidewalk"},{"id":"d","text":"Throw it in a recycling container"}]$choices$),
(476, 'tr', $text$Bir çamaşır makinesi bozulduğunda şunu yapmak mümkündür:$text$, $expl$Bozuk bir beyaz eşya, déchetterie'ye (geri dönüşüm merkezi) götürülebilir veya yeni bir cihaz satın alınırken mağaza tarafından geri alınabilir (birebir geri alma yükümlülüğü). Ev çöpüyle birlikte atılmamalıdır.$expl$, $choices$[{"id":"a","text":"Déchetterie'ye (geri dönüşüm merkezi) götürmek veya bir mağaza tarafından geri alınmasını sağlamak"},{"id":"b","text":"Ev çöpü kutusuna atmak"},{"id":"c","text":"Kaldırıma bırakmak"},{"id":"d","text":"Bir geri dönüşüm konteynerine atmak"}]$choices$),
(477, 'en', $text$In which case must one declare one's child to the civil registry service?$text$, $expl$One must declare one's child to the civil registry service of the mairie (town hall) at each birth. This declaration is mandatory within 5 days following the birth and is used to establish the birth certificate.$expl$, $choices$[{"id":"a","text":"At each birth of a child"},{"id":"b","text":"Only for the first child"},{"id":"c","text":"When the child starts school"},{"id":"d","text":"When the child reaches the age of 18"}]$choices$),
(477, 'tr', $text$Bir çocuğu nüfus müdürlüğüne hangi durumda bildirmek gerekir?$text$, $expl$Çocuğu, her doğumda belediyenin (mairie) nüfus müdürlüğüne bildirmek gerekir. Bu bildirim, doğumu takip eden 5 gün içinde zorunludur ve doğum belgesinin düzenlenmesini sağlar.$expl$, $choices$[{"id":"a","text":"Her çocuğun doğumunda"},{"id":"b","text":"Yalnızca ilk çocuk için"},{"id":"c","text":"Çocuk okula başladığında"},{"id":"d","text":"Çocuk 18 yaşına ulaştığında"}]$choices$),
(478, 'en', $text$Who can request the divorce of married persons?$text$, $expl$Divorce can be requested by one of the spouses or by both spouses together (divorce by mutual consent). The request for divorce is a right granted to each spouse.$expl$, $choices$[{"id":"a","text":"One of the spouses, or both together"},{"id":"b","text":"Only the husband"},{"id":"c","text":"Only the spouses' families"},{"id":"d","text":"The mayor of the commune"}]$choices$),
(478, 'tr', $text$Evli kişilerin boşanmasını kim talep edebilir?$text$, $expl$Boşanma, eşlerden biri tarafından veya her iki eş birlikte (anlaşmalı boşanma) talep edilebilir. Boşanma talebi her iki eşe de tanınan bir haktır.$expl$, $choices$[{"id":"a","text":"Eşlerden biri veya ikisi birlikte"},{"id":"b","text":"Yalnızca koca"},{"id":"c","text":"Yalnızca eşlerin aileleri"},{"id":"d","text":"Belediye başkanı"}]$choices$),
(479, 'en', $text$Contraception:$text$, $expl$Contraception is a right in France. It is accessible to all, including minors, and can be obtained free of charge for those under 26. The choice of contraception is free.$expl$, $choices$[{"id":"a","text":"Is a right accessible to all, including minors"},{"id":"b","text":"Is forbidden in France"},{"id":"c","text":"Requires the consent of one's spouse"},{"id":"d","text":"Is reserved for married persons"}]$choices$),
(479, 'tr', $text$Doğum kontrolü:$text$, $expl$Doğum kontrolü Fransa'da bir haktır. Reşit olmayanlar dahil herkes için erişilebilirdir ve 26 yaşın altındakiler için ücretsiz olarak alınabilir. Doğum kontrolü seçimi serbesttir.$expl$, $choices$[{"id":"a","text":"Reşit olmayanlar dahil herkes için erişilebilir bir haktır"},{"id":"b","text":"Fransa'da yasaktır"},{"id":"c","text":"Eşin onayını gerektirir"},{"id":"d","text":"Yalnızca evli kişilere mahsustur"}]$choices$),
(480, 'en', $text$What is the tiers payant (third-party payment system)?$text$, $expl$The tiers payant is a system that exempts the patient from paying healthcare costs upfront. The healthcare professional is paid directly by Assurance maladie (public health insurance) and/or the mutuelle (supplementary health insurance).$expl$, $choices$[{"id":"a","text":"A system that exempts the patient from paying healthcare costs upfront"},{"id":"b","text":"A tax on medicines"},{"id":"c","text":"A surcharge to pay at a consultation"},{"id":"d","text":"A mandatory insurance for doctors"}]$choices$),
(480, 'tr', $text$Tiers payant (üçüncü taraf ödeme sistemi) nedir?$text$, $expl$Tiers payant, hastayı sağlık masraflarını peşin ödemekten muaf tutan bir sistemdir. Sağlık çalışanına doğrudan Assurance maladie (kamu sağlık sigortası) ve/veya mutuelle (tamamlayıcı sağlık sigortası) tarafından ödeme yapılır.$expl$, $choices$[{"id":"a","text":"Hastayı sağlık masraflarını peşin ödemekten muaf tutan bir sistem"},{"id":"b","text":"İlaçlara uygulanan bir vergi"},{"id":"c","text":"Muayenede ödenecek ek bir ücret"},{"id":"d","text":"Doktorlar için zorunlu bir sigorta"}]$choices$),
(481, 'en', $text$Is abortion possible in France?$text$, $expl$Yes, abortion (IVG - Interruption Volontaire de Grossesse) is legal in France. Since 2022, it can be performed up to 14 weeks of pregnancy. It has been a constitutional right since 2024.$expl$, $choices$[{"id":"a","text":"Yes, it is a right guaranteed by law"},{"id":"b","text":"No, it is totally forbidden"},{"id":"c","text":"Only in case of danger to the mother"},{"id":"d","text":"Only with the spouse's consent"}]$choices$),
(481, 'tr', $text$Fransa'da kürtaj mümkün müdür?$text$, $expl$Evet, kürtaj (IVG - Interruption Volontaire de Grossesse) Fransa'da yasaldır. 2022'den bu yana, gebeliğin 14. haftasına kadar yapılabilir. 2024'ten bu yana anayasal bir haktır.$expl$, $choices$[{"id":"a","text":"Evet, yasayla güvence altına alınmış bir haktır"},{"id":"b","text":"Hayır, tamamen yasaktır"},{"id":"c","text":"Yalnızca anne için tehlike durumunda"},{"id":"d","text":"Yalnızca eşin onayıyla"}]$choices$),
(482, 'en', $text$Which texts define the rules at work?$text$, $expl$Workplace rules are defined by the Code du travail (Labour Code), collective agreements, and the employment contract. The Labour Code sets the minimum legal framework that every employer must respect.$expl$, $choices$[{"id":"a","text":"The Code du travail (Labour Code), collective agreements, and the employment contract"},{"id":"b","text":"Only the company's internal regulations"},{"id":"c","text":"The decisions of the mayor of the commune"},{"id":"d","text":"Verbal agreements between colleagues"}]$choices$),
(482, 'tr', $text$İşyerindeki kuralları hangi metinler tanımlar?$text$, $expl$İşyerindeki kurallar, Code du travail (İş Kanunu), toplu iş sözleşmeleri ve iş sözleşmesi ile tanımlanır. İş Kanunu, her işverenin uyması gereken asgari yasal çerçeveyi belirler.$expl$, $choices$[{"id":"a","text":"Code du travail (İş Kanunu), toplu iş sözleşmeleri ve iş sözleşmesi"},{"id":"b","text":"Yalnızca şirketin iç yönetmeliği"},{"id":"c","text":"Belediye başkanının kararları"},{"id":"d","text":"Meslektaşlar arasındaki sözlü anlaşmalar"}]$choices$),
(483, 'en', $text$Who has the right to unionize?$text$, $expl$Any employee has the right to unionize, regardless of nationality. Freedom of association is a fundamental right recognized by the French Constitution and international conventions.$expl$, $choices$[{"id":"a","text":"Any employee, regardless of nationality"},{"id":"b","text":"Only French employees"},{"id":"c","text":"Only executives"},{"id":"d","text":"Only civil servants"}]$choices$),
(483, 'tr', $text$Sendikaya üye olma hakkı kimde vardır?$text$, $expl$Uyruğu ne olursa olsun her çalışan sendikaya üye olma hakkına sahiptir. Sendika özgürlüğü, Fransız Anayasası ve uluslararası sözleşmeler tarafından tanınan temel bir haktır.$expl$, $choices$[{"id":"a","text":"Uyruğu ne olursa olsun her çalışan"},{"id":"b","text":"Yalnızca Fransız çalışanlar"},{"id":"c","text":"Yalnızca yöneticiler"},{"id":"d","text":"Yalnızca memurlar"}]$choices$),
(484, 'en', $text$Is it possible to dismiss a pregnant woman or a woman on maternity leave because of her pregnancy?$text$, $expl$No, it is forbidden to dismiss a woman because of her pregnancy or during her maternity leave. The law protects pregnant women from any discrimination linked to motherhood.$expl$, $choices$[{"id":"a","text":"No, it is forbidden by law"},{"id":"b","text":"Yes, the employer is free to dismiss whoever they want"},{"id":"c","text":"Yes, but with a 3-month notice period"},{"id":"d","text":"Yes, if the company is experiencing economic difficulties"}]$choices$),
(484, 'tr', $text$Hamile bir kadını veya doğum izninde olan bir kadını hamileliği nedeniyle işten çıkarmak mümkün müdür?$text$, $expl$Hayır, bir kadını hamileliği nedeniyle veya doğum izni sırasında işten çıkarmak yasaktır. Yasa, hamile kadınları annelikle bağlantılı her türlü ayrımcılığa karşı korur.$expl$, $choices$[{"id":"a","text":"Hayır, yasayla yasaktır"},{"id":"b","text":"Evet, işveren istediği kişiyi işten çıkarmakta serbesttir"},{"id":"c","text":"Evet, ancak 3 ay önceden bildirimle"},{"id":"d","text":"Evet, şirket ekonomik zorluklar yaşıyorsa"}]$choices$),
(485, 'en', $text$Compulsory instruction for children is from:$text$, $expl$Compulsory instruction for children in France is from 3 to 16 years old. This obligation applies to all children residing on French territory, regardless of their nationality.$expl$, $choices$[{"id":"a","text":"3 to 16 years old"},{"id":"b","text":"6 to 16 years old"},{"id":"c","text":"3 to 18 years old"},{"id":"d","text":"5 to 14 years old"}]$choices$),
(485, 'tr', $text$Çocuklar için zorunlu eğitim şu yaşlar arasındadır:$text$, $expl$Fransa'da çocuklar için zorunlu eğitim 3 ila 16 yaş arasındadır. Bu yükümlülük, uyruğu ne olursa olsun Fransız topraklarında ikamet eden tüm çocuklara uygulanır.$expl$, $choices$[{"id":"a","text":"3 ila 16 yaş"},{"id":"b","text":"6 ila 16 yaş"},{"id":"c","text":"3 ila 18 yaş"},{"id":"d","text":"5 ila 14 yaş"}]$choices$),
(486, 'en', $text$What is the definition of parental authority?$text$, $expl$Parental authority is the set of rights and duties of parents towards their minor child. Its purpose is the child's best interests: their protection, health, safety, education, and development.$expl$, $choices$[{"id":"a","text":"The set of rights and duties of parents to protect and educate their child"},{"id":"b","text":"The right of parents to punish their child freely"},{"id":"c","text":"The power of the State over families"},{"id":"d","text":"The right of grandparents over their grandchildren"}]$choices$),
(486, 'tr', $text$Ebeveyn otoritesinin tanımı nedir?$text$, $expl$Ebeveyn otoritesi, ebeveynlerin reşit olmayan çocuklarına yönelik tüm hak ve görevlerinin bütünüdür. Amacı çocuğun yararıdır: korunması, sağlığı, güvenliği, eğitimi ve gelişimi.$expl$, $choices$[{"id":"a","text":"Ebeveynlerin çocuklarını korumak ve eğitmek için sahip olduğu hak ve görevlerin tamamı"},{"id":"b","text":"Ebeveynlerin çocuklarını serbestçe cezalandırma hakkı"},{"id":"c","text":"Devlet'in aileler üzerindeki yetkisi"},{"id":"d","text":"Büyükebeveynlerin torunları üzerindeki hakkı"}]$choices$),
(487, 'en', $text$As a parent of a pupil, it is possible to:$text$, $expl$As a parent of a pupil, it is possible to participate in the school's bodies (school council, class council) and to be elected as a parent representative to make one's voice heard.$expl$, $choices$[{"id":"a","text":"Participate in the school's bodies and be elected as a parent representative"},{"id":"b","text":"Choose the subjects taught to one's child"},{"id":"c","text":"Decide whether one's child moves up to a higher class"},{"id":"d","text":"Replace an absent teacher"}]$choices$),
(487, 'tr', $text$Bir öğrenci velisi olarak şunlar mümkündür:$text$, $expl$Bir öğrenci velisi olarak okulun kurullarına (okul konseyi, sınıf konseyi) katılmak ve sesini duyurmak için veli temsilcisi olarak seçilmek mümkündür.$expl$, $choices$[{"id":"a","text":"Okulun kurullarına katılmak ve veli temsilcisi olarak seçilmek"},{"id":"b","text":"Çocuğa öğretilen dersleri seçmek"},{"id":"c","text":"Çocuğun bir üst sınıfa geçişine karar vermek"},{"id":"d","text":"Bulunmayan bir öğretmenin yerine geçmek"}]$choices$),
(488, 'en', $text$What instruction is provided for children who do not speak French?$text$, $expl$Allophone children (those who do not speak French) benefit from specific French language teaching in pedagogical units (UPE2A) while being enrolled in a regular class corresponding to their age.$expl$, $choices$[{"id":"a","text":"A specific teaching of French (UPE2A) alongside a regular class"},{"id":"b","text":"None, they must learn on their own"},{"id":"c","text":"They are sent back to their country of origin"},{"id":"d","text":"They are placed in separate specialized schools"}]$choices$),
(488, 'tr', $text$Fransızca konuşmayan çocuklar için hangi eğitim öngörülmüştür?$text$, $expl$Allofon çocuklar (Fransızca konuşmayanlar), yaşlarına uygun sıradan bir sınıfa kayıtlı olurken pedagojik birimlerde (UPE2A) belirli Fransızca öğretiminden yararlanırlar.$expl$, $choices$[{"id":"a","text":"Sıradan bir sınıfla paralel olarak Fransızca için belirli bir eğitim (UPE2A)"},{"id":"b","text":"Hiçbiri, kendi başlarına öğrenmek zorundadırlar"},{"id":"c","text":"Köken ülkelerine geri gönderilirler"},{"id":"d","text":"Ayrı uzman okullara yerleştirilirler"}]$choices$),
(489, 'en', $text$Regarding the reception of children with disabilities at school, which of the following statements is true?$text$, $expl$Inclusive education is a right in France. Every child with a disability can be schooled in their neighborhood school with suitable accommodations (AESH, specialized equipment, etc.).$expl$, $choices$[{"id":"a","text":"Every child with a disability has the right to be schooled in a regular environment with accommodations"},{"id":"b","text":"Children with disabilities cannot go to school"},{"id":"c","text":"Only children with mild disabilities can go to school"},{"id":"d","text":"Children with disabilities must go to another département"}]$choices$),
(489, 'tr', $text$Engelli çocukların okulda kabulü konusunda aşağıdaki ifadelerden hangisi doğrudur?$text$, $expl$Kapsayıcı eğitim Fransa'da bir haktır. Her engelli çocuk, uygun düzenlemelerle (AESH, uzman ekipman vb.) mahallesindeki okulda eğitim görebilir.$expl$, $choices$[{"id":"a","text":"Her engelli çocuğun düzenlemelerle birlikte normal bir ortamda okutulma hakkı vardır"},{"id":"b","text":"Engelli çocuklar okula gidemez"},{"id":"c","text":"Yalnızca hafif engelli çocuklar okula gidebilir"},{"id":"d","text":"Engelli çocuklar başka bir département'a gitmek zorundadır"}]$choices$),
(490, 'en', $text$Since 1 July 2021, what is the duration of paternity leave?$text$, $expl$Since 1 July 2021, paternity leave is 25 calendar days (32 days in case of multiple births). This reform doubled the previous duration of 11 days.$expl$, $choices$[{"id":"a","text":"25 calendar days"},{"id":"b","text":"11 calendar days"},{"id":"c","text":"14 calendar days"},{"id":"d","text":"30 calendar days"}]$choices$),
(490, 'tr', $text$1 Temmuz 2021'den bu yana babalık izninin süresi nedir?$text$, $expl$1 Temmuz 2021'den bu yana babalık izni 25 takvim günüdür (çoğul doğum durumunda 32 gün). Bu reform, önceki 11 günlük süreyi iki katına çıkarmıştır.$expl$, $choices$[{"id":"a","text":"25 takvim günü"},{"id":"b","text":"11 takvim günü"},{"id":"c","text":"14 takvim günü"},{"id":"d","text":"30 takvim günü"}]$choices$),
(491, 'en', $text$Is it possible to physically punish one's children?$text$, $expl$No, physical violence against children is forbidden in France. Since the law of 10 July 2019, any ordinary educational violence (smacking, slapping, etc.) is prohibited. Parental authority is exercised without violence.$expl$, $choices$[{"id":"a","text":"No, any physical violence against children is forbidden"},{"id":"b","text":"Yes, if it is for educational reasons"},{"id":"c","text":"Yes, as long as it leaves no marks"},{"id":"d","text":"Yes, it is a parental right"}]$choices$),
(491, 'tr', $text$Çocuklarını fiziksel olarak cezalandırmak mümkün müdür?$text$, $expl$Hayır, Fransa'da çocuklara karşı fiziksel şiddet yasaktır. 10 Temmuz 2019 yasasından bu yana, her türlü sıradan eğitimsel şiddet (şaplak, tokat vb.) yasaktır. Ebeveyn otoritesi şiddet olmaksızın kullanılır.$expl$, $choices$[{"id":"a","text":"Hayır, çocuklara karşı her türlü fiziksel şiddet yasaktır"},{"id":"b","text":"Evet, eğitim amaçlıysa"},{"id":"c","text":"Evet, iz bırakmadığı sürece"},{"id":"d","text":"Evet, bu ebeveynlerin hakkıdır"}]$choices$),
(582, 'en', $text$Your wife has just given birth at the hospital. You are told that you must declare the birth. Where and within what timeframe must you do it?$text$, $expl$The birth declaration must be made at the mairie (town hall) of the place of birth within 5 days following the delivery. It is mandatory and allows the birth certificate of the child to be issued, which is essential for all administrative procedures.$expl$, $choices$[{"id":"a","text":"At the mairie (town hall) of the place of birth, within 5 days"},{"id":"b","text":"At the préfecture, within 30 days"},{"id":"c","text":"At the hospital, on the same day"},{"id":"d","text":"At the consulate, within 15 days"}]$choices$),
(582, 'tr', $text$Eşiniz hastanede yeni doğum yaptı. Doğumu bildirmeniz gerektiği söyleniyor. Nerede ve hangi süre içinde yapmalısınız?$text$, $expl$Doğum bildirimi, doğum yerinin belediyesine (mairie) doğumu takip eden 5 gün içinde yapılmalıdır. Zorunludur ve tüm idari işlemler için vazgeçilmez olan çocuğun doğum belgesinin düzenlenmesini sağlar.$expl$, $choices$[{"id":"a","text":"Doğum yerinin belediyesine (mairie), 5 gün içinde"},{"id":"b","text":"Valiliğe (préfecture), 30 gün içinde"},{"id":"c","text":"Hastaneye, aynı gün"},{"id":"d","text":"Konsolosluğa, 15 gün içinde"}]$choices$),
(583, 'en', $text$You have just arrived in France and you are starting to work. Your employer asks if you have a carte Vitale. What is this card for?$text$, $expl$The carte Vitale is the health insurance card of the Sécurité sociale (the French social security system). It enables the reimbursement of medical care. It must be presented at the doctor, the pharmacy, and the hospital so that the costs are covered.$expl$, $choices$[{"id":"a","text":"It is a public transport card"},{"id":"b","text":"It is a professional identity card"},{"id":"c","text":"It is a bank card for civil servants"},{"id":"d","text":"It is the health insurance card that enables the reimbursement of care"}]$choices$),
(583, 'tr', $text$Yeni Fransa'ya geldiniz ve çalışmaya başlıyorsunuz. İşvereniniz size carte Vitale'iniz olup olmadığını soruyor. Bu kart ne işe yarar?$text$, $expl$Carte Vitale, Sécurité sociale'ın (Fransız sosyal güvenlik sistemi) sağlık sigortası kartıdır. Tıbbi bakımın geri ödenmesini sağlar. Masrafların karşılanması için doktorda, eczanede ve hastanede gösterilmelidir.$expl$, $choices$[{"id":"a","text":"Bir toplu taşıma kartıdır"},{"id":"b","text":"Mesleki bir kimlik kartıdır"},{"id":"c","text":"Memurlar için bir banka kartıdır"},{"id":"d","text":"Bakımın geri ödenmesini sağlayan sağlık sigortası kartıdır"}]$choices$),
(584, 'en', $text$You have just obtained French nationality and you wish to vote in the next elections. What step must you take?$text$, $expl$To vote in France, you must be registered on the electoral lists of your commune. Registration can be done at the mairie (town hall), online at service-public.fr, or by post. Newly naturalized citizens are normally registered automatically, but it is recommended to check.$expl$, $choices$[{"id":"a","text":"Go to the préfecture on voting day"},{"id":"b","text":"No step needed, foreigners in a regular situation can vote"},{"id":"c","text":"Check your registration on the electoral lists at your mairie (town hall)"},{"id":"d","text":"Request a special authorization from the court"}]$choices$),
(584, 'tr', $text$Yeni Fransız vatandaşlığını aldınız ve bir sonraki seçimlerde oy kullanmak istiyorsunuz. Hangi adımı atmanız gerekir?$text$, $expl$Fransa'da oy kullanmak için belediyenizin seçmen listesine kayıtlı olmak gerekir. Kayıt belediyede (mairie), service-public.fr üzerinden çevrimiçi veya posta yoluyla yapılabilir. Yeni vatandaşlık alanlar normalde otomatik olarak kaydedilir, ancak kontrol etmek tavsiye edilir.$expl$, $choices$[{"id":"a","text":"Oy günü valiliğe (préfecture) gitmek"},{"id":"b","text":"Hiçbir adım gerekmiyor, düzenli durumda olan yabancılar oy kullanabilir"},{"id":"c","text":"Belediyenizde (mairie) seçmen listesindeki kaydınızı kontrol etmek"},{"id":"d","text":"Mahkemeden özel izin istemek"}]$choices$),
(585, 'en', $text$Your titre de séjour (residence permit) expires in three months. What must you do to renew it?$text$, $expl$The renewal of a titre de séjour (residence permit) must be requested 2 to 4 months before its expiration, at the préfecture or sous-préfecture of your residence. The application is generally made online on the ANEF website (Administration Numérique pour les Étrangers en France).$expl$, $choices$[{"id":"a","text":"Wait for the permit to expire before applying"},{"id":"b","text":"Contact the French embassy in your country of origin"},{"id":"c","text":"Ask your employer to handle it"},{"id":"d","text":"Submit the renewal application at the préfecture before the expiration date"}]$choices$),
(585, 'tr', $text$Titre de séjour'ünüz (oturma izni) üç ay içinde sona eriyor. Yenilemek için ne yapmalısınız?$text$, $expl$Titre de séjour'ün (oturma izni) yenilenmesi, sona ermesinden 2 ila 4 ay önce, ikamet ettiğiniz yerin valiliği (préfecture) veya alt valiliğine talep edilmelidir. Başvuru genellikle ANEF (Administration Numérique pour les Étrangers en France) sitesi üzerinden çevrimiçi yapılır.$expl$, $choices$[{"id":"a","text":"Başvurmadan önce iznin sona ermesini beklemek"},{"id":"b","text":"Köken ülkenizdeki Fransa büyükelçiliği ile iletişime geçmek"},{"id":"c","text":"İşvereninizden bu işle ilgilenmesini istemek"},{"id":"d","text":"Sona erme tarihinden önce valiliğe (préfecture) yenileme başvurusu yapmak"}]$choices$),
(586, 'en', $text$You receive a letter from the préfecture asking you to provide additional documents for your file. What must you do?$text$, $expl$When the préfecture requests additional documents, it is imperative to respond within the indicated deadlines. Not responding may result in the rejection of your application. In case of difficulty, you can contact the préfecture or get help from an association.$expl$, $choices$[{"id":"a","text":"Ignore the letter, the préfecture will get back to you"},{"id":"b","text":"File a complaint because the préfecture is harassing you"},{"id":"c","text":"Provide the requested documents within the indicated deadlines"},{"id":"d","text":"Wait until you have a lawyer to respond"}]$choices$),
(586, 'tr', $text$Valilikten (préfecture), dosyanız için ek belgeler sağlamanızı isteyen bir mektup alıyorsunuz. Ne yapmalısınız?$text$, $expl$Valilik ek belgeler istediğinde, belirtilen süreler içinde yanıt vermek zorunludur. Yanıt vermemek başvurunuzun reddedilmesine yol açabilir. Zorluk durumunda valilikle iletişime geçebilir veya bir dernekten yardım alabilirsiniz.$expl$, $choices$[{"id":"a","text":"Mektubu görmezden gelmek, valilik tekrar size dönecektir"},{"id":"b","text":"Valilik size taciz ettiği için şikâyette bulunmak"},{"id":"c","text":"İstenen belgeleri belirtilen süre içinde sağlamak"},{"id":"d","text":"Yanıt vermek için bir avukatınız olmasını beklemek"}]$choices$),
(587, 'en', $text$You have just moved to a new city. Which organizations must you notify of your change of address?$text$, $expl$When moving, you must notify many organizations: the préfecture (if you have a titre de séjour), the Sécurité sociale (CPAM, the primary health insurance fund), the CAF (Caisse d'allocations familiales, family allowances fund), the tax office, your bank, and La Poste for mail forwarding. The service-public.fr website offers an online change-of-address service.$expl$, $choices$[{"id":"a","text":"Only La Poste for mail forwarding"},{"id":"b","text":"No organization, the change is automatic"},{"id":"c","text":"Only the mairie (town hall) of your new city"},{"id":"d","text":"The préfecture, the Sécurité sociale (the French social security system), the CAF (the family allowances fund), the tax office, and your bank, among others"}]$choices$),
(587, 'tr', $text$Yeni bir şehre taşındınız. Adres değişikliğinizi hangi kurumlara bildirmeniz gerekir?$text$, $expl$Bir taşınma sırasında birçok kurumu bilgilendirmeniz gerekir: valilik (titre de séjour'ünüz varsa), Sécurité sociale (CPAM, birincil sağlık sigortası fonu), CAF (Caisse d'allocations familiales, aile yardımları fonu), vergi dairesi, bankanız ve posta takibi için La Poste. service-public.fr sitesi çevrimiçi bir adres değişikliği hizmeti sunar.$expl$, $choices$[{"id":"a","text":"Yalnızca posta takibi için La Poste'a"},{"id":"b","text":"Hiçbir kuruma, değişiklik otomatiktir"},{"id":"c","text":"Yalnızca yeni şehrinizin belediyesine (mairie)"},{"id":"d","text":"Diğerlerinin yanı sıra valilik (préfecture), Sécurité sociale (Fransız sosyal güvenlik sistemi), CAF (aile yardımları fonu), vergi dairesi ve bankanız"}]$choices$),
(588, 'en', $text$You need to carry out an administrative procedure but you don't know where to inquire. A friend recommends an official government website. Which one?$text$, $expl$The service-public.fr website is the official site of the French administration. It gathers all the information on administrative procedures, the rights and obligations of users. It also allows certain procedures to be carried out online.$expl$, $choices$[{"id":"a","text":"www.google.fr"},{"id":"b","text":"www.facebook.com"},{"id":"c","text":"www.service-public.fr"},{"id":"d","text":"www.wikipedia.org"}]$choices$),
(588, 'tr', $text$Bir idari işlem yapmanız gerekiyor ancak nereden bilgi alacağınızı bilmiyorsunuz. Bir arkadaşınız size resmi bir hükümet sitesi öneriyor. Hangisi?$text$, $expl$service-public.fr sitesi, Fransız idaresinin resmi sitesidir. İdari işlemler ile kullanıcıların hak ve yükümlülükleri hakkında tüm bilgileri bir araya getirir. Ayrıca bazı işlemlerin çevrimiçi olarak yapılmasına da olanak tanır.$expl$, $choices$[{"id":"a","text":"www.google.fr"},{"id":"b","text":"www.facebook.com"},{"id":"c","text":"www.service-public.fr"},{"id":"d","text":"www.wikipedia.org"}]$choices$),
(589, 'en', $text$You wish to get married in France and the mairie asks you for a birth certificate less than 3 months old. You were born abroad. Where must you request this document?$text$, $expl$If you were born abroad and your birth was transcribed in the French registers, you can request your birth certificate from the Service central d'état civil in Nantes (SCEC). Otherwise, you will need to provide the foreign birth certificate translated and legalized or apostilled.$expl$, $choices$[{"id":"a","text":"At the mairie (town hall) of your residence in France"},{"id":"b","text":"At the préfecture of police"},{"id":"c","text":"At the high court"},{"id":"d","text":"At the Service central d'état civil in Nantes or from the authorities of your country of origin"}]$choices$),
(589, 'tr', $text$Fransa'da evlenmek istiyorsunuz ve belediye (mairie) sizden 3 aydan eski olmayan bir doğum belgesi istiyor. Yurt dışında doğdunuz. Bu belgeyi nereden talep etmeniz gerekir?$text$, $expl$Yurt dışında doğduysanız ve doğumunuz Fransız sicillerine işlenmişse, doğum belgenizi Nantes'taki Service central d'état civil'den (SCEC) talep edebilirsiniz. Aksi takdirde, çevrilmiş ve onaylanmış veya apostilli yabancı doğum belgesini sağlamanız gerekir.$expl$, $choices$[{"id":"a","text":"Fransa'daki ikamet belediyenizden (mairie)"},{"id":"b","text":"Polis valiliğinden"},{"id":"c","text":"Asliye hukuk mahkemesinden"},{"id":"d","text":"Nantes'taki Service central d'état civil'den veya köken ülkenizin makamlarından"}]$choices$),
(590, 'en', $text$Your elderly neighbor is complaining of severe chest pain and has difficulty breathing. You think he is having a heart attack. Which number should you call in an emergency?$text$, $expl$15 is the number for the SAMU (Service d'Aide Médicale Urgente, emergency medical service). It must be called for any serious medical emergency: heart attack, stroke, serious accident. The SAMU sends a medical team on site and can trigger the intervention of the Pompiers (fire brigade).$expl$, $choices$[{"id":"a","text":"17 (police)"},{"id":"b","text":"15 (SAMU)"},{"id":"c","text":"18 (Pompiers, fire brigade)"},{"id":"d","text":"3114 (suicide prevention)"}]$choices$),
(590, 'tr', $text$Yaşlı komşunuz şiddetli göğüs ağrısından şikâyet ediyor ve nefes almakta zorlanıyor. Kalp krizi geçirdiğini düşünüyorsunuz. Acil durumda hangi numarayı aramalısınız?$text$, $expl$15, SAMU'nun (Service d'Aide Médicale Urgente, acil tıbbi yardım servisi) numarasıdır. Her ciddi tıbbi acil durum için aranmalıdır: kalp krizi, felç, ciddi kaza. SAMU yerine bir tıbbi ekip gönderir ve Pompiers'in (itfaiye) müdahalesini tetikleyebilir.$expl$, $choices$[{"id":"a","text":"17 (polis)"},{"id":"b","text":"15 (SAMU)"},{"id":"c","text":"18 (Pompiers, itfaiye)"},{"id":"d","text":"3114 (intiharı önleme)"}]$choices$),
(591, 'en', $text$On returning home in the evening, you notice that the door of your apartment has been forced open and that objects have disappeared. Which number must you call?$text$, $expl$17 is the number for police secours (or Gendarmerie in rural areas). It must be called in case of an ongoing or recent offense: burglary, assault, violence. You must not touch anything at the scene and wait for the arrival of law enforcement.$expl$, $choices$[{"id":"a","text":"15 (SAMU)"},{"id":"b","text":"17 (police secours)"},{"id":"c","text":"18 (Pompiers, fire brigade)"},{"id":"d","text":"12 (telephone information)"}]$choices$),
(591, 'tr', $text$Akşam eve döndüğünüzde, dairenizin kapısının zorla açıldığını ve eşyaların kaybolduğunu fark ediyorsunuz. Hangi numarayı aramalısınız?$text$, $expl$17, police secours'un (veya kırsal bölgelerde Gendarmerie'nin) numarasıdır. Devam eden veya yakın zamanda işlenmiş bir suç durumunda aranmalıdır: hırsızlık, saldırı, şiddet. Olay yerinde hiçbir şeye dokunmamalı ve kolluk kuvvetlerinin gelmesini beklemelisiniz.$expl$, $choices$[{"id":"a","text":"15 (SAMU)"},{"id":"b","text":"17 (police secours, acil polis)"},{"id":"c","text":"18 (Pompiers, itfaiye)"},{"id":"d","text":"12 (telefon bilgi servisi)"}]$choices$),
(592, 'en', $text$You smell a strong odor of smoke in your building and you see smoke coming out of a neighboring apartment. Which number do you call first?$text$, $expl$18 is the number for the Pompiers (sapeurs-pompiers, fire brigade). It must be called in case of fire, road accident, flooding, or any situation requiring rescue. In case of doubt, the 112 (European emergency number) also works.$expl$, $choices$[{"id":"a","text":"18 (Pompiers, fire brigade)"},{"id":"b","text":"15 (SAMU)"},{"id":"c","text":"17 (police)"},{"id":"d","text":"The building manager (syndic)"}]$choices$),
(592, 'tr', $text$Binanızda yoğun bir duman kokusu alıyorsunuz ve komşu daireden duman çıktığını görüyorsunuz. Önce hangi numarayı ararsınız?$text$, $expl$18, Pompiers'in (sapeurs-pompiers, itfaiye) numarasıdır. Yangın, trafik kazası, su baskını veya kurtarma gerektiren herhangi bir durumda aranmalıdır. Şüphe durumunda 112 (Avrupa acil numarası) da çalışır.$expl$, $choices$[{"id":"a","text":"18 (Pompiers, itfaiye)"},{"id":"b","text":"15 (SAMU)"},{"id":"c","text":"17 (polis)"},{"id":"d","text":"Bina yöneticisi (syndic)"}]$choices$),
(593, 'en', $text$You witness a road accident in France but you no longer remember the French emergency numbers. Which single number can you call that works throughout Europe?$text$, $expl$112 is the European emergency number. It works in all European Union countries, free of charge and 24/7. It allows you to reach the emergency services (Pompiers, SAMU, police) from any telephone, even without a SIM card.$expl$, $choices$[{"id":"a","text":"911"},{"id":"b","text":"112"},{"id":"c","text":"999"},{"id":"d","text":"114"}]$choices$),
(593, 'tr', $text$Fransa'da bir trafik kazasına tanık oluyorsunuz ama Fransız acil numaralarını hatırlamıyorsunuz. Tüm Avrupa'da çalışan tek numara hangisidir?$text$, $expl$112, Avrupa acil numarasıdır. Tüm Avrupa Birliği ülkelerinde ücretsiz olarak 7/24 çalışır. SIM kart olmadan bile herhangi bir telefondan acil servislere (Pompiers, SAMU, polis) ulaşmanızı sağlar.$expl$, $choices$[{"id":"a","text":"911"},{"id":"b","text":"112"},{"id":"c","text":"999"},{"id":"d","text":"114"}]$choices$),
(594, 'en', $text$You register with the Sécurité sociale (the French social security system) and you are asked to choose a médecin traitant (referring doctor). Why is it important?$text$, $expl$The médecin traitant (referring doctor) is the doctor you consult first for any health problem. They coordinate your care pathway and refer you to specialists if necessary. Without a declared médecin traitant, the reimbursement of care by the Sécurité sociale is reduced.$expl$, $choices$[{"id":"a","text":"It is mandatory only for children"},{"id":"b","text":"It is optional and has no impact on reimbursements"},{"id":"c","text":"The médecin traitant is only a specialist"},{"id":"d","text":"The médecin traitant coordinates your care and enables better reimbursement"}]$choices$),
(594, 'tr', $text$Sécurité sociale'a (Fransız sosyal güvenlik sistemi) kayıt oluyorsunuz ve bir médecin traitant (aile hekimi) seçmeniz isteniyor. Bu neden önemlidir?$text$, $expl$Médecin traitant (aile hekimi), herhangi bir sağlık sorunu için ilk başvurduğunuz doktordur. Tedavi yolculuğunuzu koordine eder ve gerekirse sizi uzmanlara yönlendirir. Bildirilmiş bir médecin traitant olmadan, Sécurité sociale tarafından bakımın geri ödenmesi azaltılır.$expl$, $choices$[{"id":"a","text":"Yalnızca çocuklar için zorunludur"},{"id":"b","text":"İsteğe bağlıdır ve geri ödemeler üzerinde hiçbir etkisi yoktur"},{"id":"c","text":"Médecin traitant yalnızca bir uzmandır"},{"id":"d","text":"Médecin traitant tedavinizi koordine eder ve daha iyi geri ödeme sağlar"}]$choices$),
(595, 'en', $text$Your child breaks his arm falling in a park on a Sunday. Your médecin traitant does not work on Sundays. Where should you take him?$text$, $expl$In case of medical emergency when the médecin traitant is not available, you can go to the emergency department of the nearest hospital. In France, hospital emergency departments operate 24/7. You can also call 15 (SAMU) for medical advice.$expl$, $choices$[{"id":"a","text":"Wait until Monday to see the médecin traitant"},{"id":"b","text":"Go directly to the emergency department of the nearest hospital"},{"id":"c","text":"Call the mairie (town hall) to get an appointment"},{"id":"d","text":"Go to the pharmacy to ask for a plaster cast"}]$choices$),
(595, 'tr', $text$Çocuğunuz bir pazar günü parkta düşerken kolunu kırıyor. Aile hekiminiz (médecin traitant) pazar günleri çalışmıyor. Onu nereye götürmelisiniz?$text$, $expl$Aile hekimi (médecin traitant) uygun olmadığında tıbbi acil durumda en yakın hastanenin acil servisine gidebilirsiniz. Fransa'da hastane acil servisleri 7/24 çalışır. Tıbbi tavsiye için 15'i (SAMU) de arayabilirsiniz.$expl$, $choices$[{"id":"a","text":"Aile hekimini görmek için pazartesiyi beklemek"},{"id":"b","text":"Doğrudan en yakın hastanenin acil servisine gitmek"},{"id":"c","text":"Randevu almak için belediyeyi (mairie) aramak"},{"id":"d","text":"Bir alçı istemek için eczaneye gitmek"}]$choices$),
(596, 'en', $text$It is 11 pm and you need an urgent medicine prescribed by the doctor. All the pharmacies in your neighborhood are closed. What can you do?$text$, $expl$In France, a system of pharmacies de garde (on-duty pharmacies) ensures the dispensing of medicines at night, on Sundays, and on public holidays. To find the nearest on-duty pharmacy, you can call 3237 or consult the website of the Ordre des pharmaciens.$expl$, $choices$[{"id":"a","text":"Wait until the next morning"},{"id":"b","text":"Order the medicine online"},{"id":"c","text":"Find the pharmacie de garde (on-duty pharmacy) by calling 3237"},{"id":"d","text":"Go to the emergency department to get the medicine"}]$choices$),
(596, 'tr', $text$Saat 23:00 ve doktorun yazdığı acil bir ilaca ihtiyacınız var. Mahallenizdeki tüm eczaneler kapalı. Ne yapabilirsiniz?$text$, $expl$Fransa'da, geceleri, pazar günleri ve resmi tatillerde nöbetçi eczaneler (pharmacies de garde) sistemi ilaç teminini sağlar. En yakın nöbetçi eczaneyi bulmak için 3237'yi arayabilir veya Ordre des pharmaciens'in web sitesine bakabilirsiniz.$expl$, $choices$[{"id":"a","text":"Ertesi sabahı beklemek"},{"id":"b","text":"İlacı internetten sipariş etmek"},{"id":"c","text":"3237'yi arayarak nöbetçi eczaneyi (pharmacie de garde) bulmak"},{"id":"d","text":"İlacı almak için acil servise gitmek"}]$choices$),
(597, 'en', $text$You have just arrived in France with your 7-year-old child. You wish to enroll him in school. Where must you go first?$text$, $expl$To enroll a child in primary school, you must first go to the mairie (town hall) of your residence to obtain a certificate of enrollment, then present yourself at the school with this certificate. School is compulsory in France from 3 to 16, regardless of the child's nationality.$expl$, $choices$[{"id":"a","text":"At the mairie (town hall) of your residence to obtain a certificate of enrollment"},{"id":"b","text":"Directly at the nearest school"},{"id":"c","text":"At the préfecture to request authorization"},{"id":"d","text":"At the rectorat of the académie"}]$choices$),
(597, 'tr', $text$7 yaşındaki çocuğunuzla yeni Fransa'ya geldiniz. Onu okula kaydettirmek istiyorsunuz. Önce nereye gitmelisiniz?$text$, $expl$Bir çocuğu ilkokula kaydettirmek için önce ikamet ettiğiniz belediyeye (mairie) gidip kayıt belgesi almanız, ardından bu belgeyle okula gitmeniz gerekir. Çocuğun uyruğu ne olursa olsun, Fransa'da okul 3 ila 16 yaş arasında zorunludur.$expl$, $choices$[{"id":"a","text":"Kayıt belgesi almak için ikamet ettiğiniz belediyeye (mairie)"},{"id":"b","text":"Doğrudan en yakın okula"},{"id":"c","text":"İzin istemek için valiliğe (préfecture)"},{"id":"d","text":"Académie'nin rectorat'ına"}]$choices$),
(598, 'en', $text$Your neighbor tells you that his 4-year-old child does not need to go to school because he is too young. Is he right?$text$, $expl$No. Since 2019, instruction is compulsory in France from the age of 3 (and until 16). This means that any child residing in France, regardless of nationality, must be enrolled in a school establishment or receive home instruction.$expl$, $choices$[{"id":"a","text":"Yes, school is compulsory only from age 6"},{"id":"b","text":"Yes, school is compulsory only from age 5"},{"id":"c","text":"No, instruction is compulsory from age 3 in France"},{"id":"d","text":"No, instruction is compulsory from age 2 in France"}]$choices$),
(598, 'tr', $text$Komşunuz, 4 yaşındaki çocuğunun çok küçük olduğu için okula gitmesi gerekmediğini söylüyor. Haklı mı?$text$, $expl$Hayır. 2019'dan bu yana, Fransa'da eğitim 3 yaşından itibaren (ve 16 yaşına kadar) zorunludur. Bu, uyruğu ne olursa olsun, Fransa'da ikamet eden her çocuğun bir okul kurumuna kayıt olması veya evde eğitim alması gerektiği anlamına gelir.$expl$, $choices$[{"id":"a","text":"Evet, okul yalnızca 6 yaşından itibaren zorunludur"},{"id":"b","text":"Evet, okul yalnızca 5 yaşından itibaren zorunludur"},{"id":"c","text":"Hayır, Fransa'da eğitim 3 yaşından itibaren zorunludur"},{"id":"d","text":"Hayır, Fransa'da eğitim 2 yaşından itibaren zorunludur"}]$choices$),
(599, 'en', $text$Your 14-year-old daughter wants to wear a visible religious sign at the public school. The establishment tells her that this is not allowed. Is this legal?$text$, $expl$Yes, it is legal. The law of 15 March 2004 forbids the wearing of signs or attire ostentatiously manifesting religious affiliation in public schools, colleges, and high schools. This law applies to all religions and aims to preserve laïcité (secularism) in the school space.$expl$, $choices$[{"id":"a","text":"No, it is religious discrimination"},{"id":"b","text":"Yes, the law forbids ostentatious religious signs in public schools"},{"id":"c","text":"It depends on the religion concerned"},{"id":"d","text":"It only concerns teachers, not pupils"}]$choices$),
(599, 'tr', $text$14 yaşındaki kızınız devlet okulunda görünür bir dini sembol takmak istiyor. Kurum bunun izin verilmediğini söylüyor. Bu yasal mı?$text$, $expl$Evet, yasaldır. 15 Mart 2004 yasası, devlet okullarında, ortaokullarda ve liselerde dini aidiyeti belirgin biçimde sergileyen sembol veya kıyafetlerin giyilmesini yasaklar. Bu yasa tüm dinler için geçerlidir ve okul alanında laïcité'yi (laiklik) korumayı amaçlar.$expl$, $choices$[{"id":"a","text":"Hayır, bu dini ayrımcılıktır"},{"id":"b","text":"Evet, yasa devlet okullarında belirgin dini sembolleri yasaklar"},{"id":"c","text":"İlgili dine göre değişir"},{"id":"d","text":"Yalnızca öğretmenleri ilgilendirir, öğrencileri değil"}]$choices$),
(600, 'en', $text$Your child's school invites you to a parent-teacher meeting. You don't speak French well and you hesitate to go. What should you do?$text$, $expl$It is important to attend parent-teacher meetings to follow your child's schooling. If you don't master French, you can be accompanied by a relative who translates, or ask the school whether an interpreting service exists.$expl$, $choices$[{"id":"a","text":"Not go because you won't understand anything"},{"id":"b","text":"Go accompanied by someone who can translate for you"},{"id":"c","text":"Send a letter to explain that you can't come"},{"id":"d","text":"Wait for your child to pass on the information"}]$choices$),
(600, 'tr', $text$Çocuğunuzun okulu sizi bir veli-öğretmen toplantısına davet ediyor. Fransızcayı iyi konuşmuyorsunuz ve gitmekte tereddüt ediyorsunuz. Ne yapmalısınız?$text$, $expl$Çocuğunuzun okul yaşamını takip etmek için veli-öğretmen toplantılarına katılmak önemlidir. Fransızcaya hâkim değilseniz, çeviri yapan bir yakınınız size eşlik edebilir veya okula bir tercümanlık hizmetinin olup olmadığını sorabilirsiniz.$expl$, $choices$[{"id":"a","text":"Hiçbir şey anlamayacağınız için gitmemek"},{"id":"b","text":"Sizin için çeviri yapabilecek bir kişiyle birlikte gitmek"},{"id":"c","text":"Gelemeyeceğinizi açıklayan bir mektup göndermek"},{"id":"d","text":"Çocuğunuzun bilgileri iletmesini beklemek"}]$choices$),
(601, 'en', $text$Your child comes back from school crying and tells you that classmates regularly hit and insult him. What must you do?$text$, $expl$School bullying is an offense in France. You must speak about it with the school director or the head of the establishment. You can also call 3020 (the national number against school bullying). The school has the obligation to protect pupils and take measures.$expl$, $choices$[{"id":"a","text":"Tell your child to defend himself alone"},{"id":"b","text":"Contact the parents of the children concerned to settle the issue"},{"id":"c","text":"Report the situation to the school director and call 3020 if necessary"},{"id":"d","text":"Change your child's school without saying anything"}]$choices$),
(601, 'tr', $text$Çocuğunuz ağlayarak okuldan dönüyor ve sınıf arkadaşlarının kendisini düzenli olarak dövdüğünü ve hakaret ettiğini söylüyor. Ne yapmalısınız?$text$, $expl$Okul zorbalığı Fransa'da bir suçtur. Bunu okul müdürü veya kurum yöneticisiyle konuşmanız gerekir. Ayrıca 3020'yi (okul zorbalığına karşı ulusal numara) arayabilirsiniz. Okul, öğrencileri koruma ve önlem alma yükümlülüğüne sahiptir.$expl$, $choices$[{"id":"a","text":"Çocuğunuza kendini tek başına savunmasını söylemek"},{"id":"b","text":"Sorunu çözmek için ilgili çocukların velileriyle iletişime geçmek"},{"id":"c","text":"Durumu okul müdürüne bildirmek ve gerekirse 3020'yi aramak"},{"id":"d","text":"Hiçbir şey söylemeden çocuğunuzun okulunu değiştirmek"}]$choices$),
(602, 'en', $text$You want to enroll your child in the school cantine (canteen) but you have a modest income. How is the price calculated?$text$, $expl$In most communes, the price of the school cantine is calculated according to the family's income (quotient familial). Families with the most modest incomes pay the lowest price. No child can be excluded from the cantine for financial reasons.$expl$, $choices$[{"id":"a","text":"The price is the same for everyone, without exception"},{"id":"b","text":"The cantine is always free in France"},{"id":"c","text":"The price is calculated according to the family's income"},{"id":"d","text":"Only children of French nationality can access it"}]$choices$),
(602, 'tr', $text$Çocuğunuzu okul yemekhanesine (cantine) kaydettirmek istiyorsunuz ama mütevazı gelirleriniz var. Ücret nasıl hesaplanır?$text$, $expl$Çoğu belediyede okul yemekhanesi ücreti ailenin gelirine göre (quotient familial) hesaplanır. En düşük gelirli aileler en düşük ücreti öder. Hiçbir çocuk maddi nedenlerle yemekhaneden hariç tutulamaz.$expl$, $choices$[{"id":"a","text":"Ücret istisnasız herkes için aynıdır"},{"id":"b","text":"Fransa'da yemekhane her zaman ücretsizdir"},{"id":"c","text":"Ücret ailenin gelirine göre hesaplanır"},{"id":"d","text":"Yalnızca Fransız uyruklu çocuklar yararlanabilir"}]$choices$),
(603, 'en', $text$Your child is sick and cannot go to school for several days. What is your obligation as a parent?$text$, $expl$Parents must inform the school from the first day of absence and provide a justification (medical certificate, written excuse). Repeated unjustified absences can lead to a referral to the authorities, as instruction is compulsory in France.$expl$, $choices$[{"id":"a","text":"Nothing, the school will understand"},{"id":"b","text":"Inform the school from the first day and provide a justification"},{"id":"c","text":"Send a letter to the académie"},{"id":"d","text":"Wait for the school to contact you"}]$choices$),
(603, 'tr', $text$Çocuğunuz hasta ve birkaç gün boyunca okula gidemez. Bir veli olarak yükümlülüğünüz nedir?$text$, $expl$Veliler, devamsızlığın ilk gününden itibaren okula haber vermeli ve bir mazeret (sağlık raporu, mazeret mektubu) sunmalıdır. Tekrarlanan mazeretsiz devamsızlıklar, Fransa'da eğitim zorunlu olduğundan, makamlara bildirime yol açabilir.$expl$, $choices$[{"id":"a","text":"Hiçbir şey, okul anlayışla karşılayacaktır"},{"id":"b","text":"İlk günden itibaren okula haber vermek ve mazeret belgesi sunmak"},{"id":"c","text":"Académie'ye bir mektup göndermek"},{"id":"d","text":"Okulun sizinle iletişime geçmesini beklemek"}]$choices$),
(604, 'en', $text$You have just arrived in France and you wonder if enrolling your child in public school is paid. What is the rule in France?$text$, $expl$Education in public schools is free in France, from preschool to high school. It is a fundamental principle of the republican school. Textbooks are generally provided. However, some school supplies remain at the families' expense.$expl$, $choices$[{"id":"a","text":"Public school is free for all children residing in France"},{"id":"b","text":"Public school is paid for foreign families"},{"id":"c","text":"School is free only from collège (middle school)"},{"id":"d","text":"Tuition fees depend on nationality"}]$choices$),
(604, 'tr', $text$Yeni Fransa'ya geldiniz ve çocuğunuzu devlet okuluna kaydettirmenin ücretli olup olmadığını merak ediyorsunuz. Fransa'daki kural nedir?$text$, $expl$Fransa'da devlet okullarında eğitim, anaokulundan liseye kadar ücretsizdir. Cumhuriyetçi okulun temel bir ilkesidir. Ders kitapları genellikle sağlanır. Ancak bazı okul malzemeleri ailelerin sorumluluğunda kalır.$expl$, $choices$[{"id":"a","text":"Devlet okulu Fransa'da ikamet eden tüm çocuklar için ücretsizdir"},{"id":"b","text":"Devlet okulu yabancı aileler için ücretlidir"},{"id":"c","text":"Okul yalnızca collège'den (ortaokul) itibaren ücretsizdir"},{"id":"d","text":"Eğitim ücretleri uyruğa bağlıdır"}]$choices$),
(605, 'en', $text$You have just lost your job in France. A friend advises you to register with France Travail (formerly Pôle emploi). Why is it important?$text$, $expl$France Travail is the public employment service in France. Registration enables support in the job search, access to training, and possibly an unemployment benefit (ARE) if you have contributed enough.$expl$, $choices$[{"id":"a","text":"It is mandatory only for French citizens"},{"id":"b","text":"Registration enables support in the job search and the receipt of unemployment benefits"},{"id":"c","text":"France Travail is a private temp agency"},{"id":"d","text":"Registration is only useful if you are looking for a job in the public service"}]$choices$),
(605, 'tr', $text$Fransa'da işinizi yeni kaybettiniz. Bir arkadaşınız size France Travail'a (eski adıyla Pôle emploi) kayıt olmanızı tavsiye ediyor. Bu neden önemlidir?$text$, $expl$France Travail, Fransa'daki kamu istihdam hizmetidir. Kayıt, iş aramada destek, eğitim olanakları ve yeterince prim ödediyseniz olası bir işsizlik yardımı (ARE) sağlar.$expl$, $choices$[{"id":"a","text":"Yalnızca Fransız vatandaşları için zorunludur"},{"id":"b","text":"Kayıt, iş aramada destek almayı ve işsizlik yardımı almayı sağlar"},{"id":"c","text":"France Travail özel bir geçici işçi ajansıdır"},{"id":"d","text":"Kayıt yalnızca kamu hizmetinde iş arıyorsanız faydalıdır"}]$choices$),
(606, 'en', $text$You are offered a full-time job but the proposed salary seems very low to you. Is there a minimum wage in France?$text$, $expl$Yes, the SMIC (Salaire Minimum Interprofessionnel de Croissance) is the legal minimum hourly wage in France. No adult employee can be paid below the SMIC. It is revalued each year. In case of doubt, you can check the current amount on service-public.fr.$expl$, $choices$[{"id":"a","text":"No, there is no minimum wage in France"},{"id":"b","text":"The minimum wage exists but only applies to French people"},{"id":"c","text":"Yes, the SMIC (statutory minimum wage) is the legal minimum wage applicable to all employees"},{"id":"d","text":"The minimum wage is set by each company"}]$choices$),
(606, 'tr', $text$Size tam zamanlı bir iş teklif ediliyor, ancak önerilen maaş size çok düşük geliyor. Fransa'da bir asgari ücret var mı?$text$, $expl$Evet, SMIC (Salaire Minimum Interprofessionnel de Croissance) Fransa'da yasal asgari saatlik ücrettir. Yetişkin hiçbir çalışana SMIC'in altında ücret ödenemez. Her yıl yeniden değerlenir. Şüphe durumunda, güncel tutarı service-public.fr'de kontrol edebilirsiniz.$expl$, $choices$[{"id":"a","text":"Hayır, Fransa'da asgari ücret yoktur"},{"id":"b","text":"Asgari ücret vardır ama yalnızca Fransızlara uygulanır"},{"id":"c","text":"Evet, SMIC (yasal asgari ücret) tüm çalışanlara uygulanan yasal asgari ücrettir"},{"id":"d","text":"Asgari ücret her şirket tarafından belirlenir"}]$choices$),
(607, 'en', $text$You are starting a new job and your employer gives you an employment contract. Which essential elements must it contain?$text$, $expl$An employment contract must contain at minimum: the identity of the parties, the position held, the working hours, the remuneration, the place of work, the start date, and the applicable collective agreement. For a CDD (fixed-term employment contract), the duration and reason for the contract must also be specified.$expl$, $choices$[{"id":"a","text":"Only the salary and working hours"},{"id":"b","text":"The employment contract is not mandatory in France"},{"id":"c","text":"Only the company's name and your signature"},{"id":"d","text":"The position, duration, salary, place of work, and collective agreement, among others"}]$choices$),
(607, 'tr', $text$Yeni bir işe başlıyorsunuz ve işvereniniz size bir iş sözleşmesi veriyor. Hangi temel unsurları içermelidir?$text$, $expl$Bir iş sözleşmesi en azından şunları içermelidir: tarafların kimliği, üstlenilen pozisyon, çalışma süresi, ücret, çalışma yeri, başlangıç tarihi ve geçerli toplu iş sözleşmesi. CDD (belirli süreli iş sözleşmesi) için süre ve sözleşmeye başvurma gerekçesi de belirtilmelidir.$expl$, $choices$[{"id":"a","text":"Yalnızca maaş ve çalışma saatleri"},{"id":"b","text":"İş sözleşmesi Fransa'da zorunlu değildir"},{"id":"c","text":"Yalnızca şirketin adı ve sizin imzanız"},{"id":"d","text":"Diğerlerinin yanı sıra pozisyon, süre, maaş, çalışma yeri ve toplu iş sözleşmesi"}]$choices$),
(608, 'en', $text$At work, your superior refuses to grant you a promotion because of your origin. What can you do?$text$, $expl$Discrimination based on origin is forbidden by law in France (Code du travail and Code pénal). You can refer the matter to the Défenseur des droits, file a complaint with the police or the public prosecutor, contact the staff representatives or a trade union, and refer the matter to the conseil de prud'hommes (labour tribunal).$expl$, $choices$[{"id":"a","text":"Accept the situation because the employer is always right"},{"id":"b","text":"Resign immediately"},{"id":"c","text":"Do nothing because the law does not protect against this kind of discrimination"},{"id":"d","text":"Refer the matter to the Défenseur des droits (Defender of Rights), file a complaint, or contact a trade union"}]$choices$),
(608, 'tr', $text$İşte üstünüz kökeniniz nedeniyle size bir terfi vermeyi reddediyor. Ne yapabilirsiniz?$text$, $expl$Kökene dayalı ayrımcılık Fransa'da yasayla yasaktır (Code du travail ve Code pénal). Défenseur des droits'a başvurabilir, polise veya savcıya şikâyette bulunabilir, personel temsilcileri veya bir sendikayla iletişime geçebilir ve conseil de prud'hommes'a (iş mahkemesi) başvurabilirsiniz.$expl$, $choices$[{"id":"a","text":"Durumu kabul etmek çünkü işveren her zaman haklıdır"},{"id":"b","text":"Hemen istifa etmek"},{"id":"c","text":"Hiçbir şey yapmamak çünkü yasa bu tür ayrımcılığa karşı korumaz"},{"id":"d","text":"Défenseur des droits'a (Haklar Savunucusu) başvurmak, şikâyette bulunmak veya bir sendikayla iletişime geçmek"}]$choices$),
(609, 'en', $text$You have been working in a company for a year and you wish to take a vacation. Are you entitled to paid leave?$text$, $expl$In France, every employee is entitled to 5 weeks of paid leave per year (i.e., 2.5 working days per month worked). This right is guaranteed by the Code du travail (Labour Code). The employer cannot refuse paid leave, even if they can set the dates according to service needs.$expl$, $choices$[{"id":"a","text":"Yes, every employee is entitled to 5 weeks of paid leave per year"},{"id":"b","text":"No, paid leave is only granted after 5 years of seniority"},{"id":"c","text":"Paid leave is reserved for executives"},{"id":"d","text":"Paid leave only exists in the public service"}]$choices$),
(609, 'tr', $text$Bir şirkette bir yıldır çalışıyorsunuz ve tatil yapmak istiyorsunuz. Ücretli izne hakkınız var mı?$text$, $expl$Fransa'da her çalışanın yılda 5 hafta ücretli izin hakkı vardır (yani çalışılan her ay için 2,5 iş günü). Bu hak Code du travail (İş Kanunu) tarafından güvence altına alınmıştır. İşveren, hizmet gereklilikleri doğrultusunda tarihleri belirleyebilse de ücretli izni reddedemez.$expl$, $choices$[{"id":"a","text":"Evet, her çalışanın yılda 5 hafta ücretli izin hakkı vardır"},{"id":"b","text":"Hayır, ücretli izin yalnızca 5 yıllık kıdemden sonra verilir"},{"id":"c","text":"Ücretli izin yöneticilere mahsustur"},{"id":"d","text":"Ücretli izin yalnızca kamu hizmetinde vardır"}]$choices$),
(610, 'en', $text$A colleague talks to you about trade unions and offers you to join. Can your employer forbid you from joining a trade union?$text$, $expl$No. Freedom of association is a fundamental right enshrined in the French Constitution and the Code du travail (Labour Code). Every employee is free to join a trade union or not. The employer cannot sanction or discriminate against an employee on the basis of their trade union membership.$expl$, $choices$[{"id":"a","text":"Yes, the employer can forbid any trade union activity"},{"id":"b","text":"Trade unions are reserved for employees of French nationality"},{"id":"c","text":"No, freedom of association is a constitutional right, the employer cannot forbid it"},{"id":"d","text":"Only civil servants have the right to join a trade union"}]$choices$),
(610, 'tr', $text$Bir meslektaşınız sizinle sendikalardan bahsediyor ve üye olmanızı öneriyor. İşvereniniz size bir sendikaya üye olmanızı yasaklayabilir mi?$text$, $expl$Hayır. Sendika özgürlüğü, Fransız Anayasası ve Code du travail (İş Kanunu) tarafından güvence altına alınan temel bir haktır. Her çalışan bir sendikaya üye olmakta veya olmamakta serbesttir. İşveren, bir çalışanı sendika üyeliği nedeniyle cezalandıramaz veya ayrımcılık yapamaz.$expl$, $choices$[{"id":"a","text":"Evet, işveren her türlü sendika faaliyetini yasaklayabilir"},{"id":"b","text":"Sendikalar Fransız uyruklu çalışanlara mahsustur"},{"id":"c","text":"Hayır, sendika özgürlüğü anayasal bir haktır, işveren yasaklayamaz"},{"id":"d","text":"Yalnızca memurların sendikaya üye olma hakkı vardır"}]$choices$),
(611, 'en', $text$Colleagues tell you that they are going on strike to demand a salary increase. You wonder if it is legal in France. What does the law say?$text$, $expl$The right to strike is a constitutional right in France, recognized by the preamble of the 1946 Constitution. Any employee can participate in a strike to defend their professional interests. The employer cannot dismiss an employee for having gone on strike.$expl$, $choices$[{"id":"a","text":"Strikes are illegal in France"},{"id":"b","text":"Strikes are only allowed in the public sector"},{"id":"c","text":"Only trade unions can decide on a strike"},{"id":"d","text":"The right to strike is a constitutional right for all employees"}]$choices$),
(611, 'tr', $text$Meslektaşlarınız maaş artışı talep etmek için grev yapacaklarını söylüyor. Fransa'da bunun yasal olup olmadığını merak ediyorsunuz. Yasa ne diyor?$text$, $expl$Grev hakkı Fransa'da anayasal bir haktır ve 1946 Anayasası'nın önsözüyle tanınmıştır. Her çalışan mesleki çıkarlarını savunmak için bir greve katılabilir. İşveren, grev yaptığı için bir çalışanı işten çıkaramaz.$expl$, $choices$[{"id":"a","text":"Grev Fransa'da yasadışıdır"},{"id":"b","text":"Grev yalnızca kamu sektöründe izinlidir"},{"id":"c","text":"Yalnızca sendikalar bir greve karar verebilir"},{"id":"d","text":"Grev hakkı tüm çalışanlar için anayasal bir haktır"}]$choices$)
